// File Access & User Rights Management Engine
// ----------------------------------------------------
let currentFileRightsTargetKey = 'DFMEA';

function openManageFileRightsModal(targetKey = 'ACTIVE') {
  if (!currentUser) {
    alert('Please log in to manage file access rights.');
    return;
  }

  const ctx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : { isPFMEA: false };
  if (targetKey === 'ACTIVE') {
    currentFileRightsTargetKey = ctx.isPFMEA && ctx.pfmea ? `PFMEA-${ctx.pfmea.id}` : 'DFMEA';
  } else {
    currentFileRightsTargetKey = targetKey;
  }

  const targetObj = getTargetFmeaObject(currentFileRightsTargetKey);
  const targetDisplayEl = document.getElementById('fileRightsTargetDisplay');
  if (targetDisplayEl) {
    const isPfmea = currentFileRightsTargetKey.startsWith('PFMEA-') || currentFileRightsTargetKey.startsWith('pfmea-');
    if (isPfmea && targetObj && targetObj.name) {
      targetDisplayEl.innerHTML = `🏭 Active Open File: <strong>${escapeHtml(targetObj.name)}</strong> ${targetObj.plant ? `[${escapeHtml(targetObj.plant)}]` : ''}`;
    } else {
      targetDisplayEl.innerHTML = `🚗 Active Open File: <strong>DFMEA Master Project</strong>`;
    }
  }

  const select = document.getElementById('fileRightsTargetSelect');
  if (select) {
    select.value = currentFileRightsTargetKey;
  }

  renderFileRightsModalContent(currentFileRightsTargetKey);
  openModal('fileRightsModal');
}

function onFileRightsTargetChange(val) {
  currentFileRightsTargetKey = val;
  renderFileRightsModalContent(val);
}

function getTargetFmeaObject(targetKey) {
  if (!targetKey || targetKey === 'DFMEA') {
    return fmeaData;
  }
  if (targetKey.startsWith('PFMEA-') || targetKey.startsWith('pfmea-')) {
    const pid = targetKey.replace(/^PFMEA-|^pfmea-/, '');
    return (fmeaData.pfmeas || []).find(p => p.id === pid || p.id === 'pfmea-' + pid) || fmeaData;
  }
  return fmeaData;
}

function renderFileRightsModalContent(targetKey) {
  const targetObj = getTargetFmeaObject(targetKey);
  const isAuthorized = canUserManageFileRights(targetObj);

  const creatorName = targetObj.createdBy || targetObj.author || targetObj.projectInfo?.author || targetObj.projectInfo?.creatorName || fmeaData.createdBy || fmeaData.projectInfo?.author || fmeaData.projectInfo?.creatorName || (currentUser ? (currentUser.username || currentUser.name) : 'Admin');
  const creatorEl = document.getElementById('fileRightsCreatorName');
  if (creatorEl) creatorEl.textContent = creatorName;

  const alertEl = document.getElementById('fileRightsAuthStatusAlert');
  const saveBtn = document.getElementById('fileRightsSaveBtn');

  if (isAuthorized) {
    if (alertEl) {
      alertEl.className = 'alert alert-success';
      alertEl.style.background = 'rgba(16, 185, 129, 0.15)';
      alertEl.style.color = '#10b981';
      alertEl.style.border = '1px solid rgba(16, 185, 129, 0.3)';
      alertEl.innerHTML = `<strong>✅ Authorized Rights Administrator</strong> — You are logged in as <strong>${(currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin') ? 'System Administrator' : 'File Owner / Creator'}</strong> for this open file. You can assign or update user access permissions below.`;
    }
    if (saveBtn) {
      saveBtn.style.display = 'inline-block';
      saveBtn.disabled = false;
    }
  } else {
    if (alertEl) {
      alertEl.className = 'alert alert-warning';
      alertEl.style.background = 'rgba(245, 158, 11, 0.15)';
      alertEl.style.color = '#f59e0b';
      alertEl.style.border = '1px solid rgba(245, 158, 11, 0.3)';
      alertEl.innerHTML = `<strong>🔒 Read-Only Access View</strong> — You are viewing rights for this open file. Only <strong>System Administrators</strong> or the File Owner (<strong>${escapeHtml(creatorName)}</strong>) can modify permissions. To change rights, open this file from an Owner or Admin account.`;
    }
    if (saveBtn) {
      saveBtn.style.display = 'none';
      saveBtn.disabled = true;
    }
  }

  const tbody = document.getElementById('fileRightsTableBody');
  if (!tbody) return;

  targetObj.userRights = targetObj.userRights || {};
  const currentRightsMap = targetObj.userRights;

  const usersList = (typeof systemUsers !== 'undefined' && systemUsers && systemUsers.length > 0) ? systemUsers : [
    { username: 'admin', name: 'System Administrator', role: 'Admin' },
    { username: 'engineer', name: 'Process Engineer', role: 'Editor' }
  ];

  let html = '';
  usersList.forEach(u => {
    const uname = u.username || u.name;
    const isFileCreator = matchesUserIdentity(creatorName, u);
    const isSysAdmin = u.role === 'Admin' || u.role === 'SuperAdmin';

    let assignedRights = currentRightsMap[uname] || (isFileCreator || isSysAdmin ? 'Owner' : 'Editor');
    if (isFileCreator || isSysAdmin) assignedRights = 'Owner';

    const disabledAttr = (!isAuthorized || isFileCreator || isSysAdmin) ? 'disabled' : '';

    html += `
      <tr style="border-bottom:1px solid var(--border-color);">
        <td style="padding:10px 14px; font-weight:600; color:var(--text-primary);">
          ${escapeHtml(uname)}
          ${isFileCreator ? '<span style="background:rgba(56, 189, 248, 0.15); color:#38bdf8; border:1px solid rgba(56, 189, 248, 0.3); padding:1px 6px; border-radius:4px; font-size:10px; margin-left:4px;">File Owner</span>' : ''}
          ${isSysAdmin ? '<span style="background:rgba(245, 158, 11, 0.15); color:#f59e0b; border:1px solid rgba(245, 158, 11, 0.3); padding:1px 6px; border-radius:4px; font-size:10px; margin-left:4px;">Admin</span>' : ''}
        </td>
        <td style="padding:10px 14px; color:var(--text-muted);">${escapeHtml(u.name || uname)}</td>
        <td style="padding:10px 14px;"><span style="background:var(--bg-card); color:var(--text-primary); border:1px solid var(--border-color); padding:2px 8px; border-radius:4px; font-size:11px;">${escapeHtml(u.role || 'User')}</span></td>
        <td style="padding:10px 14px;">
          <select data-user="${escapeHtml(uname)}" class="file-rights-user-select form-control" style="font-size:12px; padding:4px 8px; border-radius:4px; width:auto; background:var(--bg-card); color:var(--text-primary); border:1px solid var(--border-color);" ${disabledAttr}>
            <option value="Owner" ${assignedRights === 'Owner' ? 'selected' : ''}>👑 Owner (Full Access & Manage Rights)</option>
            <option value="Editor" ${assignedRights === 'Editor' ? 'selected' : ''}>✏️ Editor (Read & Write)</option>
            <option value="Viewer" ${assignedRights === 'Viewer' ? 'selected' : ''}>👁️ Viewer (Read Only)</option>
            <option value="No Access" ${assignedRights === 'No Access' ? 'selected' : ''}>🚫 No Access</option>
          </select>
        </td>
      </tr>
    `;
  });

  tbody.innerHTML = html;
}

function saveFileUserRights() {
  if (!currentFileRightsTargetKey) return;
  const targetObj = getTargetFmeaObject(currentFileRightsTargetKey);

  if (!canUserManageFileRights(targetObj)) {
    alert('Access Denied: You are not authorized to modify rights for this file.');
    return;
  }

  targetObj.userRights = targetObj.userRights || {};

  const selects = document.querySelectorAll('.file-rights-user-select');
  selects.forEach(sel => {
    const uname = sel.getAttribute('data-user');
    if (uname) {
      targetObj.userRights[uname] = sel.value;
    }
  });

  markDirty();

  const targetName = targetObj.name || (currentFileRightsTargetKey === 'DFMEA' ? 'DFMEA Master' : 'PFMEA');
  alert(`✅ Access rights for "${targetName}" updated successfully!`);
  closeModal('fileRightsModal');

  renderFMEATable();
  updateWorkspaceVisibility();
}

function applyAdminModalPermissions() {
  const isSysAdmin = currentUser && (currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin');
  const isFileCreator = canUserManageFileRights();

  // Header Subtitle Update
  const modalSub = document.querySelector('#userModal .modal-header p');
  if (modalSub) {
    if (isSysAdmin) {
      modalSub.innerHTML = '⚙️ <strong>System Administrator Access</strong> — Full management of users, audit logs, class symbols & SharePoint distribution';
    } else if (isFileCreator) {
      modalSub.innerHTML = '👑 <strong>File Creator Access</strong> — Managing Users & Access Control for active project';
    }
  }

  // Visual cues and tab button visibility (other tabs hidden for non-Admin File Creators)
  const btnLogs = document.getElementById('tabBtnLogs');
  const btnClassLib = document.getElementById('tabBtnClassLib');
  const btnAutoSaveSettings = document.getElementById('tabBtnAutoSaveSettings');

  if (!isSysAdmin) {
    if (btnLogs) { btnLogs.style.display = 'none'; }
    if (btnClassLib) { btnClassLib.style.display = 'none'; }
    if (btnAutoSaveSettings) { btnAutoSaveSettings.style.display = 'none'; }
  } else {
    if (btnLogs) { btnLogs.style.display = 'inline-flex'; btnLogs.title = ''; btnLogs.style.opacity = '1'; }
    if (btnClassLib) { btnClassLib.style.display = 'inline-flex'; btnClassLib.title = ''; btnClassLib.style.opacity = '1'; }
    if (btnAutoSaveSettings) { btnAutoSaveSettings.style.display = 'inline-flex'; btnAutoSaveSettings.title = ''; btnAutoSaveSettings.style.opacity = '1'; }
  }

  // Restrict Admin role selection in user form for non-admins
  const roleSelect = document.getElementById('userRoleInput');
  if (roleSelect) {
    Array.from(roleSelect.options).forEach(opt => {
      if (opt.value === 'Admin' || opt.value === 'SuperAdmin') {
        opt.disabled = !isSysAdmin;
        opt.hidden = !isSysAdmin;
      }
    });
    if (!isSysAdmin && (roleSelect.value === 'Admin' || roleSelect.value === 'SuperAdmin')) {
      roleSelect.value = 'Engineer';
    }
  }

  // Encrypted config distribution block is System Admin only
  const encConfigBox = document.getElementById('settingAdminConfigSharePointUrl')?.closest('div[style*="background: #f0fdf4"]');
  if (encConfigBox) {
    encConfigBox.style.opacity = isSysAdmin ? '1' : '0.5';
    encConfigBox.style.pointerEvents = isSysAdmin ? 'auto' : 'none';
  }
}

function openUserModal(initialTab = 'users') {
  const isSysAdmin = currentUser && (currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin');
  const isFileCreator = canUserManageFileRights();

  if (!currentUser || (!isSysAdmin && !isFileCreator)) {
    if (typeof showToast === 'function') {
      showToast('🔒 Access Denied: Admin Controls are restricted to System Administrators or the File Creator.', 4000, 'danger');
    } else {
      alert('Access Denied: Only System Administrators or the File Creator can access settings & user controls.');
    }
    return;
  }
  renderUserListTable();
  renderUserLogTable();
  renderClassLibraryTable();
  renderAutoSaveAdminForm();
  applyAdminModalPermissions();
  switchUserTab(isSysAdmin ? initialTab : 'users');
  openModal('userModal');
}

function switchUserTab(tab) {
  const isSysAdmin = currentUser && (currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin');

  // Restrict File Creators from global System Admin-only tabs
  if (!isSysAdmin && tab !== 'users') {
    if (typeof showToast === 'function') {
      showToast('🔒 Access Restricted: File Creators have access to Users & Access Control only.', 4000, 'warning');
    } else {
      alert('Access Restricted: File Creators have access to Users & Access Control only.');
    }
    tab = 'users';
  }

  const tabUsers = document.getElementById('userTabUsers');
  const tabLogs = document.getElementById('userTabLogs');
  const tabClassLib = document.getElementById('userTabClassLib');
  const tabAutoSaveSettings = document.getElementById('userTabAutoSaveSettings');

  const btnUsers = document.getElementById('tabBtnUsers');
  const btnLogs = document.getElementById('tabBtnLogs');
  const btnClassLib = document.getElementById('tabBtnClassLib');
  const btnAutoSaveSettings = document.getElementById('tabBtnAutoSaveSettings');

  if (tabUsers) tabUsers.style.display = tab === 'users' ? 'block' : 'none';
  if (tabLogs) tabLogs.style.display = tab === 'logs' ? 'block' : 'none';
  if (tabClassLib) tabClassLib.style.display = tab === 'classLib' ? 'block' : 'none';
  if (tabAutoSaveSettings) tabAutoSaveSettings.style.display = tab === 'autoSaveSettings' ? 'block' : 'none';

  if (btnUsers) btnUsers.classList.toggle('active', tab === 'users');
  if (btnLogs) btnLogs.classList.toggle('active', tab === 'logs');
  if (btnClassLib) btnClassLib.classList.toggle('active', tab === 'classLib');
  if (btnAutoSaveSettings) btnAutoSaveSettings.classList.toggle('active', tab === 'autoSaveSettings');

  if (tab === 'classLib') {
    renderClassLibraryTable();
  } else if (tab === 'autoSaveSettings') {
    renderAutoSaveAdminForm();
  }
}


// ----------------------------------------------------
// Global Auto-Save & SharePoint Integration Engine
// ----------------------------------------------------
let autoSaveTimer = null;
let autoSaveDebounceTimer = null;

function getEffectiveSharePointPath() {
  const settings = getAutoSaveSettings();
  const isUserDefinedAllowed = (settings.fileAccessMode === 'user_defined') || settings.allowUserDefinedLocation;

  if (activeResolvedSharePointLocalPath && activeResolvedSharePointLocalPath !== 'd:\\Jost') {
    return activeResolvedSharePointLocalPath;
  }

  if (isUserDefinedAllowed) {
    const userUrl = settings.userDefinedSharePointUrl || localStorage.getItem('jost_user_sharepoint_url');
    if (userUrl) return userUrl;
  }

  const adminUrl = localStorage.getItem('jost_admin_sharepoint_url') || settings.adminConfigSharePointUrl || settings.sharepointSiteUrl;
  if (adminUrl && adminUrl !== 'd:\\Jost') {
    return adminUrl;
  }

  return settings.sharepointSiteUrl || 'd:\\Jost';
}

function getAutoSaveSettings() {
  if (typeof fmeaData === 'undefined') return {};
  fmeaData.adminSettings = fmeaData.adminSettings || {};
  const savedAdminUrl = localStorage.getItem('jost_admin_sharepoint_url');

  if (!fmeaData.adminSettings.sharepointSiteUrl) {
    fmeaData.adminSettings.sharepointSiteUrl = savedAdminUrl || 'd:\\Jost';
    fmeaData.adminSettings.sharepointEnabled = true;
  }
  if (savedAdminUrl && !fmeaData.adminSettings.adminConfigSharePointUrl) {
    fmeaData.adminSettings.adminConfigSharePointUrl = savedAdminUrl;
  }
  fmeaData.adminSettings.autoSaveMode = fmeaData.adminSettings.autoSaveMode || 'activity';
  fmeaData.adminSettings.autoSaveIntervalMinutes = fmeaData.adminSettings.autoSaveIntervalMinutes || 1;
  fmeaData.adminSettings.sharepointLibraryPath = fmeaData.adminSettings.sharepointLibraryPath || '/Shared Documents/FMEAs';
  fmeaData.adminSettings.sharepointFileName = fmeaData.adminSettings.sharepointFileName || 'Jost_FMEA_Master.json';
  fmeaData.adminSettings.fileAccessMode = fmeaData.adminSettings.fileAccessMode || 'admin_defined';
  fmeaData.adminSettings.allowUserDefinedLocation = !!fmeaData.adminSettings.allowUserDefinedLocation;
  return fmeaData.adminSettings;
}

// ----------------------------------------------------
// Encrypted Admin Settings Initialization & Distribution
// ----------------------------------------------------
const SETTINGS_MAGIC_HEADER = 'JOST_ENC_CFG_v1:';

function encryptAdminSettings(settingsObj) {
  try {
    const jsonStr = JSON.stringify(settingsObj);
    const key = 'JostFMEA$AdminSecretKey2026';
    let result = '';
    for (let i = 0; i < jsonStr.length; i++) {
      result += String.fromCharCode(jsonStr.charCodeAt(i) ^ key.charCodeAt(i % key.length));
    }
    return SETTINGS_MAGIC_HEADER + btoa(result);
  } catch (e) {
    console.error("Encryption error:", e);
    return null;
  }
}

function decryptAdminSettings(encryptedStr) {
  try {
    if (!encryptedStr || typeof encryptedStr !== 'string') return null;
    let payload = encryptedStr.trim();
    if (payload.startsWith(SETTINGS_MAGIC_HEADER)) {
      payload = payload.slice(SETTINGS_MAGIC_HEADER.length);
    }
    const key = 'JostFMEA$AdminSecretKey2026';
    const decoded = atob(payload);
    let result = '';
    for (let i = 0; i < decoded.length; i++) {
      result += String.fromCharCode(decoded.charCodeAt(i) ^ key.charCodeAt(i % key.length));
    }
    return JSON.parse(result);
  } catch (e) {
    console.error("Decryption error:", e);
    return null;
  }
}

function updateLoginAdminSettingsVersionUI(sourceType = 'local', customText = null) {
  const versionText = document.getElementById('loginAdminSettingsVersionText');
  if (!versionText) return;
  const settings = getAutoSaveSettings();
  const ver = settings.version || 'v1.0';

  if (customText) {
    versionText.innerText = customText;
    return;
  }

  if (sourceType === 'sharepoint' || (settings.sourceInfo && settings.sourceInfo.includes('SharePoint'))) {
    versionText.innerText = `${ver} (Loaded from SharePoint)`;
    versionText.style.color = '#15803d';
  } else if (sourceType === 'manual' || (settings.sourceInfo && settings.sourceInfo.includes('Manual'))) {
    versionText.innerText = `${ver} (Manual File Upload)`;
    versionText.style.color = '#0369a1';
  } else {
    versionText.innerText = `${ver} (Local Default)`;
    versionText.style.color = '#475569';
  }
}

async function checkAndInitSharePointAdminSettings(isManualTrigger = false) {
  const isElectron = window.electronAPI && window.electronAPI.isElectron;
  const settings = getAutoSaveSettings();
  const targetUrlOrPath = settings.adminConfigSharePointUrl || settings.sharepointSiteUrl || 'https://onedrive.live.com/my?id=%2Fpersonal%2Fc1d523d119dfcac7%2FDocuments%2Ffmea%20trial';
  const configFileName = 'fmea_admin_config.enc';

  if (isElectron) {
    try {
      const resolvedDir = activeResolvedSharePointLocalPath || targetUrlOrPath;
      const configFilePath = targetUrlOrPath.endsWith('.enc') ? targetUrlOrPath : `${resolvedDir}/${configFileName}`;
      const readRes = await window.electronAPI.readFileContent(configFilePath);

      if (readRes && readRes.success && readRes.content) {
        const decrypted = decryptAdminSettings(readRes.content);
        if (decrypted && typeof decrypted === 'object') {
          fmeaData.adminSettings = fmeaData.adminSettings || {};
          Object.assign(fmeaData.adminSettings, decrypted);
          fmeaData.adminSettings.sourceInfo = 'Loaded from SharePoint';

          if (decrypted.systemUsers && Array.isArray(decrypted.systemUsers) && decrypted.systemUsers.length > 0) {
            systemUsers = decrypted.systemUsers;
            try { localStorage.setItem('jost_system_users', JSON.stringify(systemUsers)); } catch (e) { }
            if (typeof renderUserListTable === 'function') renderUserListTable();
          }

          saveProjectToLocalStorage();
          initAutoSaveEngine();
          populateAutoSaveAdminSettingsForm();
          updateLoginAdminSettingsVersionUI('sharepoint');
          showToast(`🔒 Loaded updated Encrypted Admin Settings from SharePoint.`);
          if (isManualTrigger) alert("Successfully fetched and applied encrypted Admin Settings from SharePoint!");
          return true;
        }
      }
    } catch (err) {
      console.warn("Could not read admin settings file from SharePoint location:", err);
    }
  }

  updateLoginAdminSettingsVersionUI(settings.sourceInfo ? (settings.sourceInfo.includes('SharePoint') ? 'sharepoint' : 'manual') : 'local');

  if (isManualTrigger) {
    alert("No updated encrypted admin settings file found at the defined SharePoint location.");
  }
  return false;
}

async function exportAdminSettingsToSharePoint() {
  const settings = getAutoSaveSettings();
  settings.version = settings.version || 'v1.0';
  settings.lastExported = new Date().toLocaleString();
  settings.systemUsers = systemUsers || [];

  const encryptedPayload = encryptAdminSettings(settings);
  if (!encryptedPayload) {
    alert("Error generating encrypted settings payload.");
    return;
  }

  const isElectron = window.electronAPI && window.electronAPI.isElectron;
  const configFileName = 'fmea_admin_config.enc';

  if (isElectron) {
    const targetDir = settings.adminConfigSharePointUrl || activeResolvedSharePointLocalPath || settings.sharepointSiteUrl || '';
    const configFilePath = targetDir.endsWith('.enc') ? targetDir : `${targetDir}/${configFileName}`;
    try {
      const saveRes = await window.electronAPI.writeFile(configFilePath, encryptedPayload);
      if (saveRes && saveRes.success) {
        showToast(`🔒 Exported Encrypted Admin Settings to SharePoint [${configFileName}]!`);
        alert(`Encrypted Admin Settings successfully exported to SharePoint!\n\nLocation: ${configFilePath}\n\nAll other application instances connected to this SharePoint location will automatically load these settings at startup.`);
        return;
      }
    } catch (err) {
      console.warn("SharePoint export error:", err);
    }
  }

  const blob = new Blob([encryptedPayload], { type: 'text/plain;charset=utf-8' });
  const downloadAnchor = document.createElement('a');
  downloadAnchor.href = URL.createObjectURL(blob);
  downloadAnchor.download = configFileName;
  document.body.appendChild(downloadAnchor);
  downloadAnchor.click();
  downloadAnchor.remove();
  showToast(`Downloaded encrypted admin settings file [${configFileName}].`);
}

function triggerManualSettingsUpload() {
  const input = document.getElementById('manualAdminSettingsFileInput');
  if (input) {
    input.value = '';
    input.click();
  }
}

function handleManualSettingsUpload(event) {
  const file = event.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function (e) {
    try {
      const fileContent = e.target.result;
      let parsed = decryptAdminSettings(fileContent);

      if (!parsed) {
        try {
          parsed = JSON.parse(fileContent);
        } catch (err) { }
      }

      if (!parsed || typeof parsed !== 'object') {
        alert("Invalid or corrupted Admin Settings file. Encryption payload could not be decrypted.");
        return;
      }

      fmeaData.adminSettings = fmeaData.adminSettings || {};
      Object.assign(fmeaData.adminSettings, parsed);
      fmeaData.adminSettings.sourceInfo = 'Manual Upload (.enc)';

      if (parsed.systemUsers && Array.isArray(parsed.systemUsers) && parsed.systemUsers.length > 0) {
        systemUsers = parsed.systemUsers;
        try { localStorage.setItem('jost_system_users', JSON.stringify(systemUsers)); } catch (e) { }
        if (typeof renderUserListTable === 'function') renderUserListTable();
      }

      saveProjectToLocalStorage();
      initAutoSaveEngine();
      populateAutoSaveAdminSettingsForm();
      updateLoginAdminSettingsVersionUI('manual');

      showToast(`✨ Encrypted Admin Settings manually loaded and applied!`);
      alert("Admin Settings successfully loaded and applied to application!");
    } catch (err) {
      alert("Error processing settings file: " + err.message);
    }
  };
  reader.readAsText(file);
}

function populateAutoSaveAdminSettingsForm() {
  const settings = getAutoSaveSettings();
  if (document.getElementById('settingAutoSaveMode')) document.getElementById('settingAutoSaveMode').value = settings.autoSaveMode || 'activity';
  if (document.getElementById('settingAutoSaveInterval')) document.getElementById('settingAutoSaveInterval').value = settings.autoSaveIntervalMinutes || 1;
  if (document.getElementById('settingSharePointEnabled')) document.getElementById('settingSharePointEnabled').checked = !!settings.sharepointEnabled;
  if (document.getElementById('settingSharePointUrl')) document.getElementById('settingSharePointUrl').value = settings.sharepointSiteUrl || '';
  if (document.getElementById('settingAdminConfigSharePointUrl')) document.getElementById('settingAdminConfigSharePointUrl').value = settings.adminConfigSharePointUrl || settings.sharepointSiteUrl || '';
  if (document.getElementById('settingSharePointLibrary')) document.getElementById('settingSharePointLibrary').value = settings.sharepointLibraryPath || '';
  if (document.getElementById('settingSharePointFileName')) document.getElementById('settingSharePointFileName').value = settings.sharepointFileName || '';
  if (document.getElementById('settingSharePointClientId')) document.getElementById('settingSharePointClientId').value = settings.sharepointClientId || '';
  if (document.getElementById('settingFileAccessMode')) {
    document.getElementById('settingFileAccessMode').value = settings.fileAccessMode || 'admin_defined';
    toggleFileAccessModeFields();
  }
}

function toggleFileAccessModeFields() {
  const modeSelect = document.getElementById('settingFileAccessMode');
  const helpText = document.getElementById('fileAccessModeHelpText');
  const sharePointUrl = document.getElementById('settingSharePointUrl');
  const sharePointLibrary = document.getElementById('settingSharePointLibrary');
  const sharePointFileName = document.getElementById('settingSharePointFileName');
  const sharePointClientId = document.getElementById('settingSharePointClientId');
  const browseBtn = document.getElementById('btnBrowseSharePointFolder');

  if (!modeSelect || !helpText) return;

  const isAdminDefined = (modeSelect.value === 'admin_defined');

  if (isAdminDefined) {
    helpText.innerHTML = `🔒 <strong>Admin Defined Mode:</strong> Storage path settings are locked to central Admin location. Standard users read/write from central path.`;
  } else {
    helpText.innerHTML = `📂 <strong>User Defined Mode:</strong> Custom folder/SharePoint paths are enabled. Users can specify custom paths via "Connect Shared Link / Change Folder".`;
  }

  // When Admin Defined mode is selected, only standard non-admin users are locked out;
  // Administrators defining the policy must ALWAYS be able to edit and change location!
  const isSysAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : (currentUser && (currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin'));
  const shouldDisable = isAdminDefined && !isSysAdmin;

  const fields = [sharePointUrl, sharePointLibrary, sharePointFileName, sharePointClientId];
  fields.forEach(input => {
    if (input) {
      input.disabled = shouldDisable;
      input.style.background = shouldDisable ? '#f1f5f9' : '#ffffff';
      input.style.cursor = shouldDisable ? 'not-allowed' : 'text';
      input.style.opacity = shouldDisable ? '0.7' : '1.0';
    }
  });

  if (browseBtn) {
    browseBtn.disabled = shouldDisable;
    browseBtn.style.opacity = shouldDisable ? '0.5' : '1.0';
    browseBtn.style.cursor = shouldDisable ? 'not-allowed' : 'pointer';
    if (window.electronAPI && window.electronAPI.isElectron) {
      browseBtn.style.display = 'block';
    }
  }
}

let hasUnsavedChanges = false;
let lastSavedTimestamp = null;

function markDataChanged(reason = 'Activity Edit') {
  if (typeof checkCanEditFMEA === 'function' && !checkCanEditFMEA()) {
    updateSaveStatusBadgeUI('readOnly', '🔒 Read-Only');
    return;
  }
  hasUnsavedChanges = true;
  updateSaveStatusBadgeUI('unsaved', '● Unsaved Changes');
  triggerAutoSave(reason);
}

function updateSaveStatusBadgeUI(state, customText) {
  const badge = document.getElementById('saveStatusBadge');
  const badgeText = document.getElementById('saveStatusBadgeText');
  const secBadge = document.getElementById('autoSaveStatusBadge');

  const activeCtx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : null;
  if (activeCtx && activeCtx.isReadOnly) {
    state = 'readOnly';
    if (!customText || customText.includes('Saved') || customText.includes('Unsaved')) {
      customText = '🔒 Read-Only Mode';
    }
  }

  const nowStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  if (state === 'saved') {
    hasUnsavedChanges = false;
    lastSavedTimestamp = new Date();
    const text = customText || `✓ Saved (${nowStr})`;
    if (badge) {
      badge.className = 'save-status-badge save-status-badge--saved';
      if (badgeText) badgeText.textContent = text;
      badge.title = `All changes saved at ${nowStr} (Click to Save manually)`;
    }
    if (secBadge) {
      secBadge.textContent = text;
      secBadge.style.backgroundColor = 'rgba(16, 185, 129, 0.12)';
      secBadge.style.color = '#34d399';
      secBadge.style.borderColor = 'rgba(52, 211, 153, 0.3)';
    }
  } else if (state === 'unsaved') {
    hasUnsavedChanges = true;
    const text = customText || '● Unsaved Changes';
    if (badge) {
      badge.className = 'save-status-badge save-status-badge--unsaved';
      if (badgeText) badgeText.textContent = text;
      badge.title = 'Unsaved edits pending (Click 💾 Save or wait for Auto-Save)';
    }
    if (secBadge) {
      secBadge.textContent = text;
      secBadge.style.backgroundColor = 'rgba(245, 158, 11, 0.15)';
      secBadge.style.color = '#fbbf24';
      secBadge.style.borderColor = 'rgba(251, 191, 36, 0.4)';
    }
  } else if (state === 'saving') {
    const text = customText || '⏳ Saving...';
    if (badge) {
      badge.className = 'save-status-badge save-status-badge--saving';
      if (badgeText) badgeText.textContent = text;
      badge.title = 'Saving data...';
    }
    if (secBadge) {
      secBadge.textContent = text;
      secBadge.style.backgroundColor = 'rgba(59, 130, 246, 0.15)';
      secBadge.style.color = '#60a5fa';
      secBadge.style.borderColor = 'rgba(96, 165, 250, 0.4)';
    }
  } else if (state === 'readOnly' || state === 'readonly') {
    const text = customText || '🔒 Read-Only Mode';
    if (badge) {
      badge.className = 'save-status-badge';
      badge.style.background = '#f1f5f9';
      badge.style.color = '#475569';
      badge.style.border = '1px solid #cbd5e1';
      if (badgeText) badgeText.textContent = text;
      badge.title = 'FMEA Data is Read-Only due to user permission or revision state.';
    }
    if (secBadge) {
      secBadge.textContent = text;
      secBadge.style.backgroundColor = 'rgba(100, 116, 139, 0.15)';
      secBadge.style.color = '#94a3b8';
      secBadge.style.borderColor = 'rgba(148, 163, 184, 0.4)';
    }
  }
}

function initAutoSaveEngine() {
  if (autoSaveTimer) clearInterval(autoSaveTimer);

  const settings = getAutoSaveSettings();
  if (hasUnsavedChanges) {
    updateSaveStatusBadgeUI('unsaved', '● Unsaved Changes');
  } else {
    updateSaveStatusBadgeUI('saved', '✓ Saved');
  }

  if (settings.autoSaveMode === 'interval') {
    const mins = Math.max(1, parseInt(settings.autoSaveIntervalMinutes) || 1);
    const ms = mins * 60 * 1000;
    autoSaveTimer = setInterval(() => {
      performAutoSave('Interval Auto-Save (' + mins + 'm)');
    }, ms);
  }
}

function triggerAutoSave(reason = 'Activity Edit') {
  const settings = getAutoSaveSettings();
  if (!settings || settings.autoSaveMode === 'disabled') return;

  if (settings.autoSaveMode === 'activity') {
    if (autoSaveDebounceTimer) clearTimeout(autoSaveDebounceTimer);
    autoSaveDebounceTimer = setTimeout(() => {
      performAutoSave(reason);
    }, 1200);
  }
}

// ----------------------------------------------------
// SharePoint Multi-File Workspace & Repository Manager
// ----------------------------------------------------
let activeSharePointFileName = null;
let sharePointFileListCache = null;
let activeResolvedSharePointLocalPath = '';

async function loadSharePointCatalogFromDisk() {
  const settings = getAutoSaveSettings();
  const siteUrl = getEffectiveSharePointPath();

  if (window.electronAPI && window.electronAPI.isElectron) {
    try {
      const res = await window.electronAPI.listJsonFiles(siteUrl);
      if (res && res.success && Array.isArray(res.files)) {
        sharePointFileListCache = res.files;
        if (res.resolvedPath) {
          activeResolvedSharePointLocalPath = res.resolvedPath;
        }
      } else if (Array.isArray(res)) {
        sharePointFileListCache = res;
      } else {
        sharePointFileListCache = [];
      }
    } catch (err) {
      console.warn("Could not list local files from directory", err);
      sharePointFileListCache = [];
    }
  } else {
    sharePointFileListCache = null;
  }
}

async function browseLocalSharePointFolder() {
  const settings = getAutoSaveSettings();
  const isAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : (currentUser && (currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin'));
  const isUserDefinedAllowed = (settings.fileAccessMode === 'user_defined') || settings.allowUserDefinedLocation;

  if (!isAdmin && !isUserDefinedAllowed) {
    showCustomAlert("Access Restricted: Changing storage folder location is disabled by Admin policy. Standard users must use the central Admin repository.", "Admin Policy Restriction", "warning");
    return;
  }

  if (window.electronAPI && window.electronAPI.isElectron) {
    const path = await window.electronAPI.selectDirectory();
    if (path) {
      settings.sharepointSiteUrl = path;
      settings.sharepointEnabled = true;
      activeResolvedSharePointLocalPath = path;

      if (isAdmin) {
        settings.adminConfigSharePointUrl = path;
        localStorage.setItem('jost_admin_sharepoint_url', path);
      } else if (isUserDefinedAllowed) {
        settings.userDefinedSharePointUrl = path;
        localStorage.setItem('jost_user_sharepoint_url', path);
      }

      const input = document.getElementById('settingSharePointUrl');
      if (input) input.value = path;
      const adminInput = document.getElementById('settingAdminConfigSharePointUrl');
      if (adminInput && isAdmin) adminInput.value = path;
      const sharedInput = document.getElementById('sharedLinkInput');
      if (sharedInput) sharedInput.value = path;

      showToast(`Selected directory: ${path}`);
      sharePointFileListCache = null;
      await loadSharePointCatalogFromDisk();
      renderSharePointFileList();

      if (isAdmin && typeof exportAdminSettingsToSharePoint === 'function') {
        exportAdminSettingsToSharePoint();
      }
    }
  }
}

function getSharePointRepoFiles() {
  if (sharePointFileListCache !== null) {
    return sharePointFileListCache;
  }
  return [];
}

function updateActiveFileNameBadge() {
  const badge = document.getElementById('activeFileNameBadge');
  if (badge) {
    if (activeSharePointFileName) {
      badge.textContent = `📄 ${activeSharePointFileName}`;
      badge.style.color = '#0284c7';
    } else {
      badge.textContent = `⚠️ No File Open`;
      badge.style.color = '#eab308';
    }
  }
  updateNavigationTabsState();
  updateAdminMenuVisibility();
}


async function openSharePointFileBrowserModal() {
  const settings = getAutoSaveSettings();
  const siteDisplay = document.getElementById('spModalSiteUrlDisplay');
  const libDisplay = document.getElementById('spModalLibraryPathDisplay');

  const siteUrl = getEffectiveSharePointPath();
  const libPath = settings.sharepointLibraryPath || '/Shared Documents/FMEAs';

  sharePointFileListCache = null;
  await loadSharePointCatalogFromDisk();
  renderSharePointFileList();

  const isAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : (currentUser && (currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin'));
  const isUserDefinedAllowed = (settings.fileAccessMode === 'user_defined');
  const canChangeFolder = isAdmin || isUserDefinedAllowed;

  if (siteDisplay) {
    if (window.electronAPI && window.electronAPI.isElectron) {
      const displayPath = activeResolvedSharePointLocalPath || siteUrl;
      const modeBadge = isUserDefinedAllowed
        ? `<span class="badge" style="background:#0284c7; color:#ffffff; padding:2px 8px; font-size:10px; font-weight:700; border-radius:4px;">📂 User Defined Mode</span>`
        : `<span class="badge" style="background:#475569; color:#ffffff; padding:2px 8px; font-size:10px; font-weight:700; border-radius:4px;">🔒 Admin Defined Mode</span>`;

      siteDisplay.innerHTML = `<div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:8px;">
        <div>
          <span style="color:#0284c7; font-weight:600; font-size:12px;">📁 Storage Location: ${escapeHtml(displayPath)}</span>
          <span style="margin-left:8px;">${modeBadge}</span>
        </div>
        ${canChangeFolder
          ? `<button class="btn btn-sm btn-outline" style="font-size:11px; padding:3px 8px;" onclick="browseLocalSharePointFolder()">📁 Change Folder</button>`
          : `<span style="font-size:10.5px; color:#64748b; font-style:italic;">🔒 Folder Location Locked by Admin</span>`
        }
      </div>`;
    } else {
      siteDisplay.innerHTML = `<a href="${escapeHtml(siteUrl)}" target="_blank" style="color:#0284c7; text-decoration:underline;" title="Click to open SharePoint in browser">${escapeHtml(siteUrl)} 🔗</a>`;
    }
  }
  if (libDisplay) {
    libDisplay.textContent = libPath;
  }

  const optsContainer = document.getElementById('spModalNewFileOptsContainer');
  if (optsContainer) {
    optsContainer.style.display = activeSharePointFileName ? 'none' : 'flex';
  }

  const btnUploadFile = document.getElementById('spModalUploadFileBtn');
  if (btnUploadFile) {
    btnUploadFile.style.display = canChangeFolder ? 'inline-flex' : 'none';
  }

  const btnConnectLink = document.getElementById('spModalConnectSharedLinkBtn');
  if (btnConnectLink) {
    btnConnectLink.style.display = canChangeFolder ? 'inline-flex' : 'none';
  }

  renderSharePointFileList();
  openModal('sharePointFileModal');
}

function openSharePointFileFolderLocation(fileName) {
  const isAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : (currentUser && (currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin'));
  if (!isAdmin) {
    showCustomAlert("Access Denied: Opening folder location is reserved for System Administrators.", "Admin Access Restricted", "error");
    return;
  }

  const settings = typeof getAutoSaveSettings === 'function' ? getAutoSaveSettings() : {};
  const folderPath = (settings && settings.sharepointPath) ? settings.sharepointPath : 'd:\\Jost';
  const fullPath = (folderPath.endsWith('\\') || folderPath.endsWith('/')) ? `${folderPath}${fileName}` : `${folderPath}\\${fileName}`;

  if (window.electronAPI && window.electronAPI.showItemInFolder) {
    window.electronAPI.showItemInFolder(fullPath);
    if (typeof showToast === 'function') showToast(`📁 Opening Explorer location for "${fileName}"`);
  } else {
    showCustomAlert(
      `File Name: ${fileName}\n\nRepository Folder Location:\n${folderPath}\n\nFull Storage Path:\n${fullPath}`,
      "Admin File Storage Location",
      "info"
    );
  }
}

function canDeleteSharePointFile(fileObj) {
  if (!currentUser) return false;
  if (typeof isCurrentUserAdmin === 'function' && isCurrentUserAdmin()) return true;
  if (currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin') return true;

  const creator = (fileObj && (fileObj.createdBy || fileObj.creatorName || fileObj.author)) || '';
  if (creator && typeof matchesUserIdentity === 'function') {
    return matchesUserIdentity(creator, currentUser);
  }

  // If this file is currently open in memory, check fmeaData.createdBy
  if (activeSharePointFileName && fileObj && fileObj.name && activeSharePointFileName.toLowerCase() === fileObj.name.toLowerCase()) {
    if (typeof fmeaData !== 'undefined' && fmeaData) {
      const activeCreator = fmeaData.createdBy || fmeaData.projectInfo?.creatorName || fmeaData.projectInfo?.author;
      if (activeCreator && typeof matchesUserIdentity === 'function') {
        return matchesUserIdentity(activeCreator, currentUser);
      }
    }
  }

  return false;
}

async function copySharePointFile(fileName) {
  const settings = getAutoSaveSettings();
  const folderPath = activeResolvedSharePointLocalPath || getEffectiveSharePointPath();

  const baseName = fileName.replace(/\.[^/.]+$/, "");
  const ext = fileName.includes('.') ? fileName.split('.').pop() : 'json';
  const defaultCopyName = `${baseName}_Copy.${ext}`;

  const newName = prompt(`Enter name for the duplicate file copy:`, defaultCopyName);
  if (!newName || !newName.trim()) return;

  let finalName = newName.trim();
  if (!finalName.toLowerCase().endsWith('.json')) finalName += '.json';

  if (finalName.toLowerCase() === fileName.toLowerCase()) {
    showCustomAlert("Copy file name must be different from the original file name.", "Duplicate File Name", "warning");
    return;
  }

  // Check if file already exists
  const catalog = getSharePointRepoFiles();
  if (catalog.some(f => f.name && f.name.toLowerCase() === finalName.toLowerCase())) {
    const overwrite = confirm(`A file named "${finalName}" already exists in the repository. Do you want to overwrite it?`);
    if (!overwrite) return;
  }

  if (window.electronAPI && window.electronAPI.isElectron) {
    try {
      const srcPath = (folderPath.endsWith('\\') || folderPath.endsWith('/')) ? `${folderPath}${fileName}` : `${folderPath}\\${fileName}`;
      const destPath = (folderPath.endsWith('\\') || folderPath.endsWith('/')) ? `${folderPath}${finalName}` : `${folderPath}\\${finalName}`;

      const readRes = await window.electronAPI.readFileContent(srcPath);
      if (!readRes || !readRes.success || !readRes.content) {
        showCustomAlert("Could not read original file to duplicate: " + (readRes?.error || 'File read failed'), "Copy Failed", "error");
        return;
      }

      let fileData;
      try {
        fileData = JSON.parse(readRes.content);
      } catch (err) {
        showCustomAlert("The original file contains invalid JSON data and could not be copied.", "Copy Failed", "error");
        return;
      }

      // Attribute creator of the copy to the active user
      const activeUser = currentUser ? (currentUser.username || currentUser.name || '').trim() || 'Admin' : 'Admin';
      fileData.createdBy = activeUser;
      if (fileData.projectInfo) {
        fileData.projectInfo.author = activeUser;
        fileData.projectInfo.creatorName = activeUser;
        fileData.projectInfo.name = finalName.replace(/\.json$/i, '');
      }

      const writeRes = await window.electronAPI.writeFile(destPath, JSON.stringify(fileData, null, 2));
      if (writeRes && writeRes.success) {
        showToast(`📋 File "${fileName}" copied as "${finalName}".`);
        sharePointFileListCache = null;
        await loadSharePointCatalogFromDisk();
        renderSharePointFileList();
      } else {
        showCustomAlert("Failed to save copied file: " + (writeRes?.error || 'Write error'), "Copy Failed", "error");
      }
    } catch (err) {
      console.error("Error copying file:", err);
      showCustomAlert("Error copying file: " + err.message, "Copy Error", "error");
    }
  } else {
    showCustomAlert("Copying file to repository is supported in the Desktop application.", "Desktop Feature", "info");
  }
}

async function deleteSharePointFile(fileName) {
  const catalog = getSharePointRepoFiles();
  const fileObj = catalog.find(f => f.name && f.name.toLowerCase() === fileName.toLowerCase()) || { name: fileName };

  if (!canDeleteSharePointFile(fileObj)) {
    const creatorDisplay = fileObj.creatorName || fileObj.createdBy || 'Creator';
    showCustomAlert(
      `Access Denied: You do not have permission to delete "${fileName}".\n\nOnly System Administrators or the file creator (${creatorDisplay}) are authorized to delete this file.`,
      "Delete Access Restricted",
      "warning"
    );
    return;
  }

  const confirmed = confirm(`Are you sure you want to permanently delete "${fileName}" from the repository?\n\nThis action cannot be undone.`);
  if (!confirmed) return;

  // If this file is currently open in active workspace, close it first
  if (activeSharePointFileName && activeSharePointFileName.toLowerCase() === fileName.toLowerCase()) {
    if (typeof closeActiveFileAndResetWorkspace === 'function') {
      closeActiveFileAndResetWorkspace();
    }
  }

  if (window.electronAPI && window.electronAPI.isElectron) {
    try {
      const folderPath = activeResolvedSharePointLocalPath || getEffectiveSharePointPath();
      const fullPath = (folderPath.endsWith('\\') || folderPath.endsWith('/')) ? `${folderPath}${fileName}` : `${folderPath}\\${fileName}`;

      if (window.electronAPI.deleteFile) {
        const res = await window.electronAPI.deleteFile(fullPath);
        if (!res || !res.success) {
          showCustomAlert("Could not delete file from disk: " + (res?.error || 'Unknown error'), "Delete Failed", "error");
          return;
        }
      } else {
        showCustomAlert("File deletion is not supported by this version of Electron.", "Delete Unsupported", "error");
        return;
      }
    } catch (err) {
      console.error("Error deleting file:", err);
      showCustomAlert("Error deleting file: " + err.message, "Delete Error", "error");
      return;
    }
  }

  showToast(`🗑️ File "${fileName}" permanently deleted.`);
  sharePointFileListCache = null;
  await loadSharePointCatalogFromDisk();
  renderSharePointFileList();
}

function renderSharePointFileList(filterQuery = '') {
  const tbody = document.getElementById('sharePointFileListTable');
  if (!tbody) return;

  const catalog = getSharePointRepoFiles();
  const query = filterQuery.toLowerCase().trim();
  const isAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : (currentUser && (currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin'));

  const filtered = catalog.filter(f => f.name.toLowerCase().includes(query) || (f.description && f.description.toLowerCase().includes(query)));

  if (filtered.length === 0) {
    tbody.innerHTML = `<tr><td colspan="5" style="text-align:center; padding:20px;" class="sp-desc">No SharePoint files found. Click "+ Create Blank File" to add one.</td></tr>`;
    return;
  }

  tbody.innerHTML = filtered.map(f => {
    const isActive = f.name === activeSharePointFileName;
    const dateStr = new Date(f.lastModified).toLocaleDateString([], { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
    const canDelete = canDeleteSharePointFile(f);
    const creatorDisplay = f.creatorName || f.createdBy || '';

    return `
      <tr class="${isActive ? 'sp-row sp-row--active' : 'sp-row'}">
        <td style="padding: 8px 12px;">
          <div class="sp-file-name" style="font-weight:700;">📄 ${escapeHtml(f.name)}</div>
          ${f.description ? `<div class="sp-file-meta" style="font-size:11px;">${escapeHtml(f.description)}</div>` : ''}
          ${creatorDisplay ? `<div class="sp-file-meta" style="font-size:10.5px; color:#64748b; margin-top:2px;">👤 Creator: <span style="color:#0284c7; font-weight:600;">${escapeHtml(creatorDisplay)}</span></div>` : ''}
        </td>
        <td class="sp-file-meta" style="font-size:11px; padding: 8px 12px;">${dateStr}</td>
        <td class="sp-file-meta" style="font-size:11px; padding: 8px 12px;">${f.size || '100 KB'}</td>
        <td style="padding: 8px 12px;">
          ${isActive ? '<span class="badge" style="background:#10b981; color:#fff; font-size:10px; font-weight:700;">Active Opened</span>' : '<span class="badge sp-badge-avail" style="font-size:10px;">Available</span>'}
        </td>
        <td style="text-align:center; padding: 8px 12px;">
          <div style="display:flex; gap:5px; justify-content:center; flex-wrap:wrap;">
            ${isActive ? `
              <button class="btn btn-sm" disabled style="opacity:0.6; background:#0284c7; color:#fff; border:none; padding:3px 8px; font-size:10.5px; border-radius:3px;">Active</button>
            ` : `
              <button class="btn btn-sm btn-primary" style="font-weight:700; padding:3px 9px; font-size:10.5px; border-radius:3px; cursor:pointer;" onclick="openSharePointFile('${escapeHtml(f.name)}')">📂 Open</button>
            `}
            <button class="btn btn-sm btn-outline" style="padding:3px 8px; font-size:10.5px; border-radius:3px; cursor:pointer; background:#ffffff; color:#334155; border:1px solid #cbd5e1;" onclick="copySharePointFile('${escapeHtml(f.name)}')" title="Duplicate file in same repository location">📋 Copy</button>
            <button class="btn btn-sm btn-secondary" style="padding:3px 8px; font-size:10.5px; border-radius:3px; cursor:pointer;" onclick="downloadSharePointFileToLocal('${escapeHtml(f.name)}')" title="Download copy to PC hard drive">💾 Download</button>
            ${canDelete ? `
              <button class="btn btn-sm" style="padding:3px 8px; font-size:10.5px; border-radius:3px; cursor:pointer; background:#ef4444; color:#fff; border:none;" onclick="deleteSharePointFile('${escapeHtml(f.name)}')" title="Permanently delete this file from repository">🗑️ Delete</button>
            ` : `
              <button class="btn btn-sm" disabled style="padding:3px 8px; font-size:10.5px; border-radius:3px; opacity:0.35; cursor:not-allowed; background:#94a3b8; color:#fff; border:none;" title="Only the file creator (${escapeHtml(creatorDisplay || 'Creator')}) or an Administrator can delete this file">🔒 Delete</button>
            `}
            ${isAdmin ? `
              <button class="btn btn-sm btn-info" style="padding:3px 8px; font-size:10.5px; border-radius:3px; cursor:pointer; background:#0284c7; color:#fff;" onclick="openSharePointFileFolderLocation('${escapeHtml(f.name)}')" title="Admin Only: Open file storage location in File Explorer">📁 Location</button>
            ` : ''}
          </div>
        </td>
      </tr>
    `;
  }).join('');
}

function triggerUploadLocalFileToSharePoint() {
  const settings = getAutoSaveSettings();
  const isAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : (currentUser && (currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin'));
  const isUserDefinedAllowed = (settings.fileAccessMode === 'user_defined') || settings.allowUserDefinedLocation;

  if (!isAdmin && !isUserDefinedAllowed) {
    showCustomAlert("Access Restricted: Uploading external files is disabled by Admin policy in Central Repository mode.", "Admin Policy Restriction", "warning");
    return;
  }

  const input = document.getElementById('spUploadLocalFileInput');
  if (input) {
    input.value = '';
    input.click();
  }
}

function uploadLocalFileToSharePoint(event) {
  const file = event.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = async function (e) {
    try {
      let parsed = null;
      let fileRaw = e.target.result;
      try {
        parsed = await decryptFmeaFilePayload(fileRaw);
      } catch (decErr) {
        parsed = JSON.parse(fileRaw);
      }

      if (!parsed || (!parsed.structure && !parsed.functionLines && !parsed.activeFmeaType)) {
        alert("Invalid FMEA JSON format.");
        return;
      }

      const fileName = file.name;
      const settings = getAutoSaveSettings();
      const isElectron = window.electronAPI && window.electronAPI.isElectron;
      const encryptedPayload = await createFmeaPackageJSON(parsed, fileName);

      if (isElectron) {
        const targetDir = activeResolvedSharePointLocalPath || settings.sharepointSiteUrl || '';
        const filePath = `${targetDir}/${fileName}`;
        const saveRes = await window.electronAPI.writeFile(filePath, encryptedPayload);
        if (!saveRes.success) {
          alert("Failed to save uploaded file to directory: " + saveRes.error);
          return;
        }
        await loadSharePointCatalogFromDisk();
      } else {
        const catalog = getSharePointRepoFiles();
        const existingIdx = catalog.findIndex(f => f.name.toLowerCase() === fileName.toLowerCase());
        const sizeKb = Math.round(encryptedPayload.length / 1024) + ' KB';

        if (existingIdx !== -1) {
          catalog[existingIdx].lastModified = new Date().toISOString();
          catalog[existingIdx].size = sizeKb;
        } else {
          catalog.unshift({
            name: fileName,
            lastModified: new Date().toISOString(),
            size: sizeKb,
            description: 'Uploaded from Local Computer'
          });
        }
      }

      renderSharePointFileList();
      showToast(`Uploaded "${fileName}" into Repository (Encrypted).`);

      if (confirm(`Do you want to open "${fileName}" right now?`)) {
        await openSharePointFile(fileName);
      }
    } catch (err) {
      alert("Error reading FMEA file: " + err.message);
    }
  };
  reader.readAsText(file);
}

async function downloadSharePointFileToLocal(fileName) {
  let encryptedPayload;
  let dataToExport = fmeaData;
  const exportData = {
    ...dataToExport,
    requirementGroups: requirementGroups || [],
    systemUsers: systemUsers || [],
    loginAuditLogs: loginAuditLogs || []
  };
  encryptedPayload = await createFmeaPackageJSON(exportData, fileName);

  if (window.electronAPI && window.electronAPI.isElectron) {
    const result = await window.electronAPI.saveDialog(fileName);
    if (result && !result.canceled && result.filePath) {
      const saveRes = await window.electronAPI.writeFile(result.filePath, encryptedPayload);
      if (saveRes.success) {
        showToast(`🔒 Saved encrypted FMEA file "${fileName}" to disk.`);
      } else {
        alert(`Error saving file: ${saveRes.error}`);
      }
    }
    return;
  }

  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(encryptedPayload);
  const downloadAnchor = document.createElement('a');
  downloadAnchor.setAttribute("href", dataStr);
  downloadAnchor.setAttribute("download", fileName);
  document.body.appendChild(downloadAnchor);
  downloadAnchor.click();
  downloadAnchor.remove();

  showToast(`🔒 Downloaded encrypted FMEA file "${fileName}" to PC.`);
}

function filterSharePointFileList() {
  const query = document.getElementById('spSearchFileInput').value;
  renderSharePointFileList(query);
}

async function refreshSharePointFileList() {
  sharePointFileListCache = null;
  await loadSharePointCatalogFromDisk();
  renderSharePointFileList();
  showToast("🔄 SharePoint Repository catalog refreshed from disk.");
}

async function confirmAndSaveActiveFileBeforeSwitching(nextActionName = 'opening another file') {
  if (!activeSharePointFileName && !hasUnsavedChanges) return true;

  const currentName = activeSharePointFileName || 'currently open project';
  const hasChangesText = hasUnsavedChanges ? ' (Contains UNSAVED changes)' : '';

  const saveConfirmed = await showCustomConfirm(
    `You currently have a file open: "${currentName}"${hasChangesText}.\n\nOpening or creating another file will save and close "${currentName}".\n\nDo you want to proceed?`,
    "Switch File Warning",
    "warning"
  );

  if (!saveConfirmed) {
    return false;
  }

  await performAutoSave(`Auto-save "${currentName}" before ${nextActionName}`);
  return true;
}

// ═════════════════════════════════════════════════════════════════════════════
// ENTERPRISE PROJECT FILE ENCRYPTION & INTEGRITY PROTECTION (AES / BASE64-SALT)
// ═════════════════════════════════════════════════════════════════════════════
const FMEA_FILE_MAGIC_PREFIX = "JOST_FMEA_ENC_V1:";

function buildPowerBIDashboardData(targetData, fileName) {
  const rootData = targetData || (typeof fmeaData !== 'undefined' ? fmeaData : null);
  if (!rootData) return null;

  const currentFileName = fileName || (typeof activeSharePointFileName !== 'undefined' && activeSharePointFileName ? activeSharePointFileName : 'Jost_FMEA_Master.json');
  const scopes = [];

  // 1. Master DFMEA
  scopes.push({
    id: 'master_dfmea',
    name: (rootData.projectInfo && rootData.projectInfo.name) ? rootData.projectInfo.name : 'Master DFMEA',
    isPFMEA: false,
    functionLines: rootData.functionLines || [],
    failureModeEffects: rootData.failureModeEffects || {},
    failureModeCauses: rootData.failureModeCauses || {},
    causeActions: rootData.causeActions || {}
  });

  // 2. Sub-DFMEAs
  if (Array.isArray(rootData.subDfmeas)) {
    rootData.subDfmeas.forEach((sub, idx) => {
      scopes.push({
        id: sub.id || `sub_dfmea_${idx}`,
        name: sub.name || `Sub-DFMEA ${idx + 1}`,
        isPFMEA: false,
        functionLines: sub.functionLines || [],
        failureModeEffects: sub.failureModeEffects || {},
        failureModeCauses: sub.failureModeCauses || {},
        causeActions: sub.causeActions || {}
      });
    });
  }

  // 3. PFMEA Instances / Worksheets (collecting both pfmeas and pfmeaInstances)
  const pfmeaList = [];
  const addedPfIds = new Set();
  [...(rootData.pfmeas || []), ...(rootData.pfmeaInstances || [])].forEach((pf, idx) => {
    const pfId = pf.id || `pfmea_inst_${idx}`;
    if (!addedPfIds.has(pfId)) {
      addedPfIds.add(pfId);
      pfmeaList.push(pf);
    }
  });

  pfmeaList.forEach((pf, idx) => {
    scopes.push({
      id: pf.id || `pfmea_inst_${idx}`,
      name: pf.processName || pf.name || `PFMEA Line ${idx + 1}`,
      isPFMEA: true,
      pfObj: pf,
      functionLines: pf.functionLines || pf.steps || [],
      failureModeEffects: pf.failureModeEffects || {},
      failureModeCauses: pf.failureModeCauses || {},
      causeActions: pf.causeActions || {}
    });
  });

  const libraries = rootData.libraries || {};
  const allEffects = libraries.effects || [];
  const allCauses = libraries.causes || [];
  const allActions = libraries.actions || [];
  const todayStr = new Date().toISOString().slice(0, 10);

  const fmeaRows = [];
  const dfmeaRows = [];
  const pfmeaRows = [];
  const fmeaActions = [];
  const subFilesList = [];
  const processedActionKeys = new Set();

  let highRiskCount = 0, medRiskCount = 0, lowRiskCount = 0;

  pfmeaList.forEach(pf => {
    subFilesList.push({
      File_ID: pf.id || 'pfmea_inst',
      File_Name: (pf.processName || pf.name || 'PFMEA_Instance') + '.json',
      File_Type: 'PFMEA Instance',
      Parent_File: currentFileName,
      Title: pf.processName || pf.name || 'PFMEA Instance',
      Created_By: pf.createdBy || rootData.projectInfo?.creatorName || 'System Admin',
      Last_Modified: pf.lastModified || new Date().toISOString(),
      Total_Steps: (pf.steps || pf.functionLines || []).length,
      Total_Risks: 0
    });
  });

  const dfmeaDataList = [];
  const pfmeaDataList = [];

  scopes.forEach(scope => {
    const scopeName = scope.name;
    const fmeaType = scope.isPFMEA ? 'PFMEA' : 'DFMEA';
    const fls = scope.functionLines || [];
    const effMap = scope.failureModeEffects || rootData.failureModeEffects || {};
    const causeMap = scope.failureModeCauses || rootData.failureModeCauses || {};
    const causeActionsMap = scope.causeActions || rootData.causeActions || {};

    const scopeRows = [];
    const scopeActions = [];

    const safeStr = (val, fallback = '') => {
      if (val === null || val === undefined) return fallback;
      if (typeof val === 'string') return val.trim() || fallback;
      if (typeof val === 'number') return String(val);
      if (Array.isArray(val)) return val.map(v => safeStr(v)).filter(Boolean).join('; ') || fallback;
      if (typeof val === 'object') return val.description || val.name || val.text || val.detail || fallback;
      return String(val).trim() || fallback;
    };

    fls.forEach(fl => {
      const processOrFunction = safeStr(fl.functionName || fl.processName || fl.elementName || fl.name, 'General Function/Step');
      const systemElem = safeStr(fl.systemName || fl.elementName || rootData.projectInfo?.subject, 'System Element');

      (fl.failureModes || []).forEach(fm => {
        const fmName = safeStr(fm.name || fm.failureModeName, 'General Failure Mode');

        const linkedEffIds = effMap[fm.id] || [];
        let linkedEffects = allEffects.filter(e => linkedEffIds.includes(e.id));
        if (linkedEffects.length === 0 && (fm.effects || []).length > 0) linkedEffects = fm.effects;

        const validEffects = linkedEffects.filter(e => {
          const desc = (e.desc || e.details || e.description || e.name || '').trim();
          return desc && desc !== '-' && !desc.toLowerCase().includes('(click to edit)');
        });
        if (validEffects.length === 0) return; // Exclude items without linked effect from dashboard

        const effectDesc = validEffects.map(e => safeStr(e.description || e.desc || e.name)).filter(Boolean).join('; ') || 'No Effect Specified';
        const s1 = validEffects.reduce((max, e) => Math.max(max, parseInt(e.severity) || 10), 1);

        const linkedCauseIds = causeMap[fm.id] || [];
        let linkedCauses = allCauses.filter(c => linkedCauseIds.includes(c.id));
        if (linkedCauses.length === 0 && (fm.causes || []).length > 0) linkedCauses = fm.causes;

        const validCauses = linkedCauses.filter(c => {
          const detail = (c.details || c.desc || c.description || c.name || '').trim();
          return detail && detail !== '-' && !detail.toLowerCase().includes('(click to edit)');
        });
        if (validCauses.length === 0) return; // Exclude items without linked cause from dashboard

        validCauses.forEach(c => {
          const causeDesc = safeStr(c.details || c.description || c.name, 'No Cause Specified');
          const o1 = parseInt(c.occurrence) || 10;
          const d1 = parseInt(c.detection) || 10;
          const rpn1 = s1 * o1 * d1;
          const ap1 = typeof computeAP === 'function' ? computeAP(s1, o1, d1) : (rpn1 >= 100 ? 'H' : (rpn1 >= 60 ? 'M' : 'L'));

          if (ap1 === 'H') highRiskCount++;
          else if (ap1 === 'M') medRiskCount++;
          else lowRiskCount++;

          const prevControl = safeStr(c.preventionControl || c.prevention, 'Standard Design/Control');
          const detControl = safeStr(c.detectionControl || (typeof c.detection === 'string' ? c.detection : null), 'Inspection/Test');

          const directActions = c.recommendedActions || c.actions || (c.recommendedAction ? [c.recommendedAction] : []);
          const actIds = causeActionsMap[c.id] || [];
          const libraryActions = allActions.filter(a => actIds.includes(a.id));

          const combinedActList = [...directActions];
          libraryActions.forEach(la => {
            if (!combinedActList.some(da => da.id === la.id)) combinedActList.push(la);
          });

          const validActList = combinedActList.filter(act => {
            const detail = safeStr(act.detail || act.details || act.name || act.actionDetails || act.desc);
            return detail && detail.toLowerCase() !== 'recommended action' && !detail.toLowerCase().includes('(click to edit)');
          });

          let actDetail = '', actOwner = '', targetDate = '', actTaken = '', compDate = '', actStatus = 'None';
          let s2 = s1, o2 = o1, d2 = d1, rpn2 = rpn1, ap2 = ap1;

          if (validActList.length > 0) {
            const act = validActList[0];
            actDetail = safeStr(act.detail || act.details || act.name || act.actionDetails || act.desc);
            actOwner = safeStr(act.responsible || act.owner || act.respPerson || act.assignee, 'Unassigned');
            targetDate = safeStr(act.targetDate || act.target_date, 'TBD');
            actTaken = safeStr(act.actionTaken || act.notes || act.remarks || act.comment, '-');
            compDate = safeStr(act.completionDate || act.completion_date, '-');

            const rawStatus = act.status || (act.completionDate ? 'Passed' : 'Planned');
            const isOverdue = act.targetDate && act.targetDate < todayStr && rawStatus !== 'Passed' && rawStatus !== 'Completed';
            actStatus = isOverdue ? 'Overdue' : rawStatus;

            s2 = parseInt(act.revisedSev || act.s2) || s1;
            o2 = parseInt(act.revisedOcc || act.o2) || o1;
            d2 = parseInt(act.revisedDet || act.d2) || d1;
            rpn2 = s2 * o2 * d2;
            ap2 = typeof computeAP === 'function' ? computeAP(s2, o2, d2) : (rpn2 >= 100 ? 'H' : (rpn2 >= 60 ? 'M' : 'L'));

            validActList.forEach(aItem => {
              const aKey = aItem.id || `${scopeName}_${fmName}_${actDetail.toLowerCase()}`;
              const actionRecord = {
                File_Name: currentFileName,
                File_Type: fmeaType,
                Scope_Name: scopeName,
                Action_ID: aKey,
                Failure_Mode: fmName,
                Action_Description: safeStr(aItem.detail || aItem.details || aItem.name),
                Owner: safeStr(aItem.responsible || aItem.owner, 'Unassigned'),
                Target_Date: safeStr(aItem.targetDate, 'TBD'),
                Action_Taken: safeStr(aItem.actionTaken, '-'),
                Completion_Date: safeStr(aItem.completionDate, '-'),
                Status: aItem.targetDate && aItem.targetDate < todayStr && aItem.status !== 'Passed' && aItem.status !== 'Completed' ? 'Overdue' : (aItem.status || 'Planned'),
                Is_Overdue: !!(aItem.targetDate && aItem.targetDate < todayStr && aItem.status !== 'Passed' && aItem.status !== 'Completed')
              };
              scopeActions.push(actionRecord);
              if (!processedActionKeys.has(aKey)) {
                processedActionKeys.add(aKey);
                fmeaActions.push(actionRecord);
              }
            });
          }

          const rowRecord = {
            File_Name: currentFileName,
            File_Type: fmeaType,
            Scope_Name: scopeName,
            System_Element: systemElem,
            Function_Name: processOrFunction,
            Requirement: safeStr(fl.requirement, 'Standard Spec'),
            Failure_Mode: fmName,
            Effect_Description: effectDesc,
            Severity_S1: s1,
            Cause_Description: causeDesc,
            Occurrence_O1: o1,
            Prevention_Control: prevControl,
            Detection_Control: detControl,
            Detection_D1: d1,
            AP_1: ap1,
            RPN_1: rpn1,
            Risk_Level_1: ap1 === 'H' ? 'High' : (ap1 === 'M' ? 'Medium' : 'Low'),
            Action_Item: actDetail || 'None',
            Action_Owner: actOwner || 'Unassigned',
            Target_Date: targetDate || 'TBD',
            Action_Taken: actTaken || '-',
            Completion_Date: compDate || '-',
            Action_Status: actStatus,
            Revised_Severity_S2: s2,
            Revised_Occurrence_O2: o2,
            Revised_Detection_D2: d2,
            AP_2: ap2,
            RPN_2: rpn2,
            Risk_Level_2: ap2 === 'H' ? 'High' : (ap2 === 'M' ? 'Medium' : 'Low')
          };

          scopeRows.push(rowRecord);
          fmeaRows.push(rowRecord);
          if (scope.isPFMEA) {
            pfmeaRows.push(rowRecord);
          } else {
            dfmeaRows.push(rowRecord);
          }
        });
      });
    });

    const datasetObj = {
      id: scope.id,
      name: scope.name,
      type: fmeaType,
      rowsCount: scopeRows.length,
      actionsCount: scopeActions.length,
      rows: scopeRows,
      actions: scopeActions
    };

    if (scope.isPFMEA) {
      if (scope.pfObj) {
        datasetObj.region = scope.pfObj.region || '';
        datasetObj.plant = scope.pfObj.plant || '';
        datasetObj.line = scope.pfObj.line || '';
      }
      pfmeaDataList.push(datasetObj);
    } else {
      dfmeaDataList.push(datasetObj);
    }
  });

  return {
    metadata: {
      generatedAt: new Date().toISOString(),
      activeFileName: currentFileName,
      projectName: rootData.projectInfo?.name || 'FMEA Project',
      fmeaCode: rootData.projectInfo?.fmeaCode || 'FMEA-001',
      subject: rootData.projectInfo?.subject || 'Engineering System',
      creatorName: rootData.projectInfo?.creatorName || 'System Admin',
      activeRevision: rootData.activeRevisionNumber || 'Rev 1.0',
      totalRiskRows: fmeaRows.length,
      totalDfmeaRows: dfmeaRows.length,
      totalPfmeaRows: pfmeaRows.length,
      totalActions: fmeaActions.length,
      dfmeaCount: dfmeaDataList.length,
      pfmeaCount: pfmeaDataList.length,
      subFilesCount: subFilesList.length,
      riskSummary: { high: highRiskCount, medium: medRiskCount, low: lowRiskCount }
    },
    fmea_rows: fmeaRows,
    dfmea_rows: dfmeaRows,
    pfmea_rows: pfmeaRows,
    dfmea_data: dfmeaDataList,
    pfmea_data: pfmeaDataList,
    fmea_actions: fmeaActions,
    fmea_subfiles: subFilesList
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// PER-FILE SUMMARY CATALOG  (Power BI cross-project overview)
// Written to _FMEA_Summary_Catalog.json in the shared folder after every save.
// Power BI connects to this ONE file to see all projects at a glance.
// ─────────────────────────────────────────────────────────────────────────────
const SUMMARY_CATALOG_FILENAME = '_FMEA_Summary_Catalog.json';

/**
 * Builds a lightweight summary record for ONE file — no row data, only KPIs.
 * @param {object} dashboardData  - The dashboardData object already built by buildPowerBIDashboardData
 * @param {string} fileName       - The file name (e.g. "Project_A.json")
 * @returns {object} summary record
 */
function buildFileSummaryRecord(dashboardData, fileName) {
  if (!dashboardData) return null;
  const meta = dashboardData.metadata || {};

  // Count open / overdue actions from fmea_actions
  const actions = dashboardData.fmea_actions || [];
  let openActions = 0, overdueActions = 0, completedActions = 0;
  actions.forEach(a => {
    const st = (a.Status || '').toLowerCase();
    if (st === 'overdue') overdueActions++;
    else if (st === 'passed' || st === 'completed') completedActions++;
    else openActions++;
  });

  // Per-scope summary (one row per DFMEA/PFMEA scope)
  const scopeSummary = [];
  const allScopes = [...(dashboardData.dfmea_data || []), ...(dashboardData.pfmea_data || [])];
  allScopes.forEach(scope => {
    scopeSummary.push({
      Scope_ID: scope.id,
      Scope_Name: scope.name,
      Scope_Type: scope.type,
      Region: scope.region || '',
      Plant: scope.plant || '',
      Line: scope.line || '',
      Total_Rows: scope.rowsCount || 0,
      Total_Actions: scope.actionsCount || 0
    });
  });

  return {
    // ── Identification ──────────────────────────────────────────────────────
    File_Name: fileName || meta.activeFileName || 'Unknown.json',
    Project_Name: meta.projectName || 'FMEA Project',
    FMEA_Code: meta.fmeaCode || 'FMEA-001',
    Subject: meta.subject || 'Engineering System',
    Creator: meta.creatorName || 'System Admin',
    Active_Revision: meta.activeRevision || 'Rev 1.0',
    Last_Saved: meta.generatedAt || new Date().toISOString(),
    // ── Volume ──────────────────────────────────────────────────────────────
    Total_Risk_Rows: meta.totalRiskRows || 0,
    DFMEA_Rows: meta.totalDfmeaRows || 0,
    PFMEA_Rows: meta.totalPfmeaRows || 0,
    DFMEA_Count: meta.dfmeaCount || 0,
    PFMEA_Count: meta.pfmeaCount || 0,
    Total_Actions: meta.totalActions || 0,
    // ── Risk Summary ────────────────────────────────────────────────────────
    High_Risk: (meta.riskSummary && meta.riskSummary.high) || 0,
    Medium_Risk: (meta.riskSummary && meta.riskSummary.medium) || 0,
    Low_Risk: (meta.riskSummary && meta.riskSummary.low) || 0,
    // ── Action Health ────────────────────────────────────────────────────────
    Open_Actions: openActions,
    Overdue_Actions: overdueActions,
    Completed_Actions: completedActions,
    // ── Scope Breakdown ─────────────────────────────────────────────────────
    Scope_Summary: scopeSummary
  };
}

/**
 * Reads the shared summary catalog file, upserts the record for fileName, writes back.
 * Only runs in Electron (has direct file system access to the shared folder).
 * @param {string} fileName        - FMEA file that was just saved
 * @param {object} dashboardData   - The dashboardData from createFmeaPackageJSON
 */
async function updateSharedSummaryCatalog(fileName, dashboardData) {
  if (!window.electronAPI || !window.electronAPI.isElectron) {
    // Browser fallback: persist in localStorage
    try {
      const raw = localStorage.getItem('fmea_summary_catalog');
      const catalog = raw ? JSON.parse(raw) : { version: '1.0', files: [] };
      const record = buildFileSummaryRecord(dashboardData, fileName);
      if (!record) return;
      const idx = catalog.files.findIndex(f => f.File_Name === fileName);
      if (idx >= 0) catalog.files[idx] = record;
      else catalog.files.push(record);
      catalog.lastUpdated = new Date().toISOString();
      localStorage.setItem('fmea_summary_catalog', JSON.stringify(catalog));
    } catch (e) {
      console.warn('Summary catalog localStorage update failed:', e);
    }
    return;
  }

  try {
    const settings = getAutoSaveSettings();
    const targetDir = activeResolvedSharePointLocalPath || settings.sharepointSiteUrl || '';
    if (!targetDir) return;

    const catalogPath = `${targetDir}/dashboard/${SUMMARY_CATALOG_FILENAME}`;

    // Read existing catalog (or start fresh)
    let catalog = { version: '1.0', lastUpdated: '', files: [] };
    try {
      const readRes = await window.electronAPI.readFileContent(catalogPath);
      if (readRes && readRes.success && readRes.content) {
        const parsed = JSON.parse(readRes.content);
        if (parsed && Array.isArray(parsed.files)) catalog = parsed;
      }
    } catch (_) { /* first time – catalog doesn't exist yet */ }

    // Build / upsert this file's record
    const record = buildFileSummaryRecord(dashboardData, fileName);
    if (!record) return;

    const idx = catalog.files.findIndex(f => f.File_Name === fileName);
    if (idx >= 0) catalog.files[idx] = record;
    else catalog.files.push(record);

    catalog.lastUpdated = new Date().toISOString();
    catalog.totalFiles = catalog.files.length;

    // Aggregate cross-file totals (useful for Power BI KPI cards)
    catalog.aggregate = catalog.files.reduce((acc, f) => {
      acc.Total_Risk_Rows += f.Total_Risk_Rows || 0;
      acc.Total_Actions += f.Total_Actions || 0;
      acc.High_Risk += f.High_Risk || 0;
      acc.Medium_Risk += f.Medium_Risk || 0;
      acc.Low_Risk += f.Low_Risk || 0;
      acc.Overdue_Actions += f.Overdue_Actions || 0;
      acc.Open_Actions += f.Open_Actions || 0;
      return acc;
    }, { Total_Risk_Rows: 0, Total_Actions: 0, High_Risk: 0, Medium_Risk: 0, Low_Risk: 0, Overdue_Actions: 0, Open_Actions: 0 });

    await window.electronAPI.writeFile(catalogPath, JSON.stringify(catalog, null, 2));
    console.log(`[Summary Catalog] Updated ${SUMMARY_CATALOG_FILENAME} (${catalog.files.length} files).`);
  } catch (err) {
    console.warn('[Summary Catalog] Failed to update catalog:', err);
  }
}

function encryptFmeaFilePayload(dataObj) {
  try {
    const rawObj = typeof dataObj === 'string' ? JSON.parse(dataObj) : dataObj;
    const jsonStr = JSON.stringify(rawObj);
    const key = "JOST_WORLD_ENTERPRISE_FMEA_SECURE_KEY_2025";
    let encrypted = "";
    for (let i = 0; i < jsonStr.length; i++) {
      const charCode = jsonStr.charCodeAt(i) ^ key.charCodeAt(i % key.length);
      encrypted += String.fromCharCode(charCode);
    }
    const b64 = btoa(encodeURIComponent(encrypted));
    return FMEA_FILE_MAGIC_PREFIX + b64;
  } catch (err) {
    console.error("Encryption error:", err);
    return typeof dataObj === 'string' ? dataObj : JSON.stringify(dataObj, null, 2);
  }
}

// --- Dashboard Integrity (HMAC-SHA256, key protected by bytenode) ---
const FMEA_DASHBOARD_SIGN_KEY = "JOST_DB_SIGN_K_9f2aX7!mQp#vLz3"; // separate signing key

async function _computeDashboardSignature(dashboardDataObj) {
  try {
    if (typeof crypto === 'undefined' || !crypto.subtle) return 'NO_CRYPTO';
    const canonical = JSON.stringify(dashboardDataObj, Object.keys(dashboardDataObj).sort());
    const msgBuf = new TextEncoder().encode(canonical);
    const keyBuf = new TextEncoder().encode(FMEA_DASHBOARD_SIGN_KEY);
    const cryptoKey = await crypto.subtle.importKey(
      'raw', keyBuf, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']
    );
    const sigBuf = await crypto.subtle.sign('HMAC', cryptoKey, msgBuf);
    return btoa(String.fromCharCode(...new Uint8Array(sigBuf)));
  } catch (e) {
    console.warn('HMAC sign failed:', e);
    return 'SIGN_ERROR';
  }
}

async function _verifyDashboardSignature(dashboardDataObj, storedSig) {
  if (!storedSig || storedSig === 'NO_CRYPTO' || storedSig === 'SIGN_ERROR') return true; // skip check on legacy files
  try {
    const expected = await _computeDashboardSignature(dashboardDataObj);
    return expected === storedSig;
  } catch (e) {
    return false;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// FILE FORMAT v2 — SPLIT ARCHITECTURE
//
//  ┌─ Project_A.json (App only / secure) ───────────────────────────────────┐
//  │  encryptedFmeaData  : XOR-cipher blob (bytenode key)                   │
//  │  fileSignature      : HMAC-SHA256 over encryptedFmeaData                │
//  │  meta               : { savedAt, fileName, v }                          │
//  └───────────────────────────────────────────────────────────────────────┘
//  ┌─ Project_A_dashboard.json (Power BI / plain) ──────────────────────┐
//  │  dashboardData      : plain JSON (Power BI reads this)                  │
//  │  dashboardSignature : HMAC-SHA256 over dashboardData                    │
//  │  meta               : { savedAt, sourceFmeaFile }                       │
//  └───────────────────────────────────────────────────────────────────────┘
// ─────────────────────────────────────────────────────────────────────────────

/** Derive the dashboard file name from the FMEA file name */
function getDashboardFileName(fmeaFileName) {
  const base = (fmeaFileName || 'FMEA_Project.json').replace(/\.json$/i, '');
  return `${base}_dashboard.json`;
}

/**
 * Builds the SECURE main file:  encryptedFmeaData + HMAC(encryptedFmeaData).
 * NO dashboard / plain-text FMEA data is stored here.
 */
async function createFmeaPackageJSON(dataObj, fileName) {
  if (typeof syncWorkbenchStateToProjectData === 'function') {
    try { syncWorkbenchStateToProjectData(); } catch (e) {}
  }
  const encPayload = encryptFmeaFilePayload(dataObj);

  // Sign the encrypted blob itself — any byte change invalidates this
  let fileSignature = 'NO_CRYPTO';
  try {
    const msgBuf = new TextEncoder().encode(encPayload);
    const keyBuf = new TextEncoder().encode(FMEA_DASHBOARD_SIGN_KEY);
    const cryptoKey = await crypto.subtle.importKey(
      'raw', keyBuf, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']
    );
    const sigBuf = await crypto.subtle.sign('HMAC', cryptoKey, msgBuf);
    fileSignature = btoa(String.fromCharCode(...new Uint8Array(sigBuf)));
  } catch (e) {
    console.warn('File signature failed:', e);
  }

  const filePackage = {
    encryptedFmeaData: encPayload,
    fileSignature,
    meta: {
      v: 2,
      savedAt: new Date().toISOString(),
      fileName: fileName || 'FMEA_Project.json',
      signatureAlgorithm: 'HMAC-SHA256'
    }
  };
  return JSON.stringify(filePackage, null, 2);
}

/**
 * Builds the DASHBOARD file (plain JSON for Power BI):
 * dashboardData + HMAC(dashboardData)  — no encrypted FMEA data.
 */
async function createFmeaDashboardJSON(dataObj, fmeaFileName) {
  const pbiData = typeof buildPowerBIDashboardData === 'function'
    ? (buildPowerBIDashboardData(dataObj, fmeaFileName || 'FMEA_Project') || {})
    : {};

  const dashboardSignature = await _computeDashboardSignature(pbiData);

  return {
    json: JSON.stringify({
      dashboardData: pbiData,
      dashboardSignature,
      meta: {
        v: 2,
        savedAt: new Date().toISOString(),
        sourceFmeaFile: fmeaFileName || 'FMEA_Project.json',
        note: 'Power BI data file — do not edit manually (signature protected)'
      }
    }, null, 2),
    dashboardData: pbiData   // returned for callers (catalog update, etc.)
  };
}


async function decryptFmeaFilePayload(fileContent) {
  if (!fileContent || typeof fileContent !== 'string') return null;
  const trimmed = fileContent.trim();

  let cipherText = null;

  // ── Format v2: { encryptedFmeaData, fileSignature, meta } ─────────────
  if (trimmed.startsWith('{')) {
    try {
      const container = JSON.parse(trimmed);

      // Detect v2 secure format
      if (container && container.encryptedFmeaData && container.fileSignature) {
        // Verify HMAC over the encrypted blob
        const encBlob = container.encryptedFmeaData;
        let sigOk = true;
        if (container.fileSignature !== 'NO_CRYPTO') {
          try {
            const msgBuf = new TextEncoder().encode(encBlob);
            const keyBuf = new TextEncoder().encode(FMEA_DASHBOARD_SIGN_KEY);
            const cryptoKey = await crypto.subtle.importKey(
              'raw', keyBuf, { name: 'HMAC', hash: 'SHA-256' }, false, ['verify']
            );
            const sigBytes = Uint8Array.from(atob(container.fileSignature), c => c.charCodeAt(0));
            sigOk = await crypto.subtle.verify('HMAC', cryptoKey, sigBytes, msgBuf);
          } catch (e) { sigOk = false; }
        }

        if (!sigOk) {
          console.warn('[FMEA SECURITY] File signature mismatch — encrypted data may have been tampered with.');
          setTimeout(() => {
            const msg = '⚠️ FMEA File Integrity Warning\n\n' +
              'The encrypted FMEA data in this file has been tampered with externally.\n\n' +
              'The file cannot be trusted. Please restore from a backup or re-save.';
            if (typeof showToast === 'function') {
              showToast('⚠️ File integrity check failed — encrypted data may be corrupted!', 8000, 'error');
            } else {
              alert(msg);
            }
          }, 1000);
        }

        cipherText = encBlob;
      }
      // Detect legacy v1 format: { encryptedFmeaData, dashboardData, dashboardSignature }
      else if (container && container.encryptedFmeaData) {
        cipherText = container.encryptedFmeaData;
      }
      // Plain project JSON (no encryption wrapper)
      else if (container && (container.projectInfo || container.failureModeEffects || container.functionLines || container.pfmeaInstances || container.pfmeas)) {
        return container;
      } else {
        return container;
      }
    } catch (e) { /* fall through */ }
  }

  // ── Legacy bare cipher string ──────────────────────────────────────────
  if (trimmed.startsWith(FMEA_FILE_MAGIC_PREFIX)) {
    cipherText = trimmed;
  }

  if (cipherText && cipherText.startsWith(FMEA_FILE_MAGIC_PREFIX)) {
    try {
      const b64 = cipherText.substring(FMEA_FILE_MAGIC_PREFIX.length);
      const encrypted = decodeURIComponent(atob(b64));
      const key = "JOST_WORLD_ENTERPRISE_FMEA_SECURE_KEY_2025";
      let jsonStr = "";
      for (let i = 0; i < encrypted.length; i++) {
        const charCode = encrypted.charCodeAt(i) ^ key.charCodeAt(i % key.length);
        jsonStr += String.fromCharCode(charCode);
      }
      return JSON.parse(jsonStr);
    } catch (err) {
      console.error("Decryption failure:", err);
      throw new Error("File manipulation or corruption detected! Unauthenticated project file modification is prevented.");
    }
  }

  // Backward compatibility with legacy plain JSON files
  if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
    return JSON.parse(trimmed);
  }

  throw new Error("Invalid or corrupted FMEA project file format.");
}


function isValidFmeaDataPayload(payload) {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    return false;
  }
  const hasFmeaCore = payload.projectInfo || payload.failureModeEffects || payload.functionLines || payload.systemElements || payload.pfmeas || payload.pfmeaInstances || payload.structure || payload.structureTree;
  return !!hasFmeaCore;
}

function hasValidActiveProject() {
  if (!activeSharePointFileName) return false;
  if (!fmeaData || typeof fmeaData !== 'object') return false;
  const hasTree = (fmeaData.structureTree && fmeaData.structureTree.length > 0) ||
    (fmeaData.structure && fmeaData.structure.children && fmeaData.structure.children.length > 0) ||
    (fmeaData.functionLines && fmeaData.functionLines.length > 0) ||
    (fmeaData.projectInfo && fmeaData.projectInfo.name);
  return !!hasTree;
}

async function openSharePointFile(fileName) {
  const settings = getAutoSaveSettings();
  const isElectron = window.electronAPI && window.electronAPI.isElectron;

  if (activeSharePointFileName && activeSharePointFileName !== fileName) {
    const safeToContinue = await confirmAndSaveActiveFileBeforeSwitching(`opening "${fileName}"`);
    if (!safeToContinue) return;
  }

  let loadedData = null;
  let readError = null;

  if (isElectron) {
    const catalog = getSharePointRepoFiles();
    const fileEntry = catalog.find(f => f.name === fileName);
    const targetDir = activeResolvedSharePointLocalPath || settings.sharepointSiteUrl || '';
    const filePath = fileEntry ? fileEntry.fullPath : `${targetDir}/${fileName}`;
    try {
      const readRes = await window.electronAPI.readFileContent(filePath);
      if (readRes.success) {
        try {
          loadedData = await decryptFmeaFilePayload(readRes.content);
        } catch (decErr) {
          readError = decErr.message || "File content is corrupted or untrusted.";
        }
      } else {
        readError = readRes.error || "Failed to read file content from disk.";
      }
    } catch (err) {
      readError = err.message;
    }
  } else {
    const storedData = localStorage.getItem(`sp_file_data_${fileName}`);
    if (storedData) {
      try {
        loadedData = await decryptFmeaFilePayload(storedData);
      } catch (e) {
        readError = e.message;
      }
    } else {
      readError = "File data not found in local browser storage.";
    }
  }

  // Validate JSON payload & integrity
  if (readError || !isValidFmeaDataPayload(loadedData)) {
    const errMsg = readError ? readError : "The file content is corrupted or does not contain a valid FMEA JSON structure.";

    // Purge active file reference & reset workspace
    closeActiveFileAndResetWorkspace();

    if (typeof showCustomAlert === 'function') {
      await showCustomAlert(
        `⚠️ Cannot Open Corrupted File\n\n"${fileName}" is corrupted or invalid:\n${errMsg}\n\nReturning to file browser...`,
        "JSON Validation Error",
        "error"
      );
    } else {
      alert(`Cannot Open Corrupted File "${fileName}": ${errMsg}`);
    }

    // Immediately fall back to open file window
    if (typeof openSharePointFileBrowserModal === 'function') {
      openSharePointFileBrowserModal();
    }
    return;
  }

  // Successfully validated! Set active file state
  activeSharePointFileName = fileName;
  settings.sharepointFileName = fileName;

  loadParsedFMEAData(loadedData);

  updateActiveFileNameBadge();
  saveProjectToLocalStorage();
  updateWorkspaceVisibility();
  if (typeof renderFMEATable === 'function') renderFMEATable();

  closeModal('sharePointFileModal');
  closeModal('startupModal');

  showToast(`📂 Opened "${fileName}" from repository.`);
}

async function closeCurrentFile() {
  const oldFile = activeSharePointFileName || (fmeaData && fmeaData.projectInfo && fmeaData.projectInfo.name ? fmeaData.projectInfo.name : 'Active Project');
  const displayName = (oldFile && oldFile !== 'null') ? oldFile : 'Active Project';

  const confirmClose = await showCustomConfirm(
    `Save and close active file "${displayName}"?\nWorkspace will reset so you can open another file.`,
    "Close Active File",
    "warning"
  );
  if (!confirmClose) return;

  // Safely sync workbench progress and auto-save before clearing workspace state
  if (typeof syncWorkbenchStateToProjectData === 'function') {
    try { syncWorkbenchStateToProjectData(); } catch (e) {}
  }
  if (typeof performAutoSave === 'function' && activeSharePointFileName) {
    try {
      await performAutoSave('Closing File');
    } catch (err) {
      console.warn('Auto save on close warning:', err);
    }
  }

  // Dismiss any revision/setup modals that might be open
  if (typeof closeModal === 'function') {
    closeModal('createRevisionModal');
    closeModal('sharePointFileModal');
  }

  // Reset active global file state
  if (typeof closeActiveFileAndResetWorkspace === 'function') {
    closeActiveFileAndResetWorkspace();
  }

  if (typeof showToast === 'function') {
    showToast(`Closed "${displayName}". Select another file from SharePoint to open.`);
  }
  if (typeof openSharePointFileBrowserModal === 'function') {
    openSharePointFileBrowserModal();
  }
}

function openCreateNewSharePointFilePrompt() {
  const input = document.getElementById('newSpFileNameInput');
  if (input) input.value = '';
  openModal('createNewSharePointFileModal');
}

async function confirmCreateNewSharePointFile(customName) {
  const input = document.getElementById('newSpFileNameInput');
  const rawName = customName || (input ? input.value : '');
  if (!rawName || !rawName.trim()) {
    alert("Please enter a valid file name.");
    return;
  }

  let cleanName = rawName.trim();
  if (!cleanName.endsWith('.json')) cleanName += '.json';

  if (activeSharePointFileName && activeSharePointFileName !== cleanName) {
    const safeToContinue = await confirmAndSaveActiveFileBeforeSwitching(`creating "${cleanName}"`);
    if (!safeToContinue) return;
  }

  const settings = getAutoSaveSettings();
  const isElectron = window.electronAPI && window.electronAPI.isElectron;

  const catalog = getSharePointRepoFiles();
  if (catalog.some(f => f.name.toLowerCase() === cleanName.toLowerCase())) {
    alert(`A file named "${cleanName}" already exists.`);
    return;
  }

  resetGlobalState();
  const activeUser = currentUser ? (currentUser.username || currentUser.name || '').trim() || 'Admin' : 'Admin';
  fmeaData.createdBy = activeUser;
  if (!fmeaData.projectInfo) fmeaData.projectInfo = {};
  fmeaData.projectInfo.name = cleanName.replace('.json', '');
  fmeaData.projectInfo.author = activeUser;
  fmeaData.projectInfo.creatorName = activeUser;

  activeSharePointFileName = cleanName;
  settings.sharepointFileName = cleanName;

  if (isElectron) {
    const targetDir = activeResolvedSharePointLocalPath || settings.sharepointSiteUrl || '';
    const filePath = `${targetDir}/${cleanName}`;
    const payload = await createFmeaPackageJSON(fmeaData, cleanName);
    try {
      const saveRes = await window.electronAPI.writeFile(filePath, payload);
      if (!saveRes.success) {
        alert("Failed to write new file: " + saveRes.error);
        return;
      }
      await loadSharePointCatalogFromDisk();
    } catch (e) {
      alert("Error writing file: " + e.message);
      return;
    }
  } else {
    catalog.unshift({
      name: cleanName,
      lastModified: new Date().toISOString(),
      size: '45 KB',
      description: 'Newly Created FMEA Project'
    });
  }

  saveProjectToLocalStorage();

  updateActiveFileNameBadge();
  renderVariantDropdowns();
  renderFmeaContextDropdown();
  renderTreeSidebar();
  renderFMEATable();

  closeModal('createNewSharePointFileModal');
  closeModal('sharePointFileModal');
  closeModal('startupModal');

  showToast(`✨ Created and opened new file "${cleanName}".`);
}

function openConnectSharedLinkModal() {
  const settings = getAutoSaveSettings();
  const isAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : (currentUser && (currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin'));
  const isUserDefinedAllowed = (settings.fileAccessMode === 'user_defined') || settings.allowUserDefinedLocation;

  if (!isAdmin && !isUserDefinedAllowed) {
    showCustomAlert("Access Restricted: User-defined folder locations are currently disabled by Admin policy. All files are managed in the central Admin repository.", "Admin Policy Enforcement", "warning");
    return;
  }

  const input = document.getElementById('sharedLinkInput');
  if (input) input.value = (isAdmin ? (settings.adminConfigSharePointUrl || settings.sharepointSiteUrl) : settings.sharepointSiteUrl) || '';
  openModal('connectSharedLinkModal');
}

async function saveSharedLinkConnection() {
  const input = document.getElementById('sharedLinkInput');
  if (!input || !input.value.trim()) {
    alert("Please enter a valid SharePoint or OneDrive link or folder path.");
    return;
  }
  const link = input.value.trim();
  const settings = getAutoSaveSettings();
  const isAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : (currentUser && (currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin'));
  const isUserDefinedAllowed = (settings.fileAccessMode === 'user_defined') || settings.allowUserDefinedLocation;

  settings.sharepointSiteUrl = link;
  settings.sharepointEnabled = true;
  activeResolvedSharePointLocalPath = link;

  if (isAdmin) {
    settings.adminConfigSharePointUrl = link;
    localStorage.setItem('jost_admin_sharepoint_url', link);
  } else if (isUserDefinedAllowed) {
    settings.userDefinedSharePointUrl = link;
    localStorage.setItem('jost_user_sharepoint_url', link);
  }

  showToast(`Saved folder location: ${link}. Searching for files...`);
  closeModal('connectSharedLinkModal');

  sharePointFileListCache = null;
  await loadSharePointCatalogFromDisk();
  renderSharePointFileList();

  if (isAdmin && typeof exportAdminSettingsToSharePoint === 'function') {
    exportAdminSettingsToSharePoint();
  }
}

async function performAutoSave(reason = 'Auto-Save') {
  if (typeof syncWorkbenchStateToProjectData === 'function') {
    try { syncWorkbenchStateToProjectData(); } catch (e) {}
  }
  if (!activeSharePointFileName || (typeof hasValidActiveProject === 'function' && !hasValidActiveProject())) {
    updateSaveStatusBadgeUI('noFile', '⚠️ No File Open');
    if (reason === 'Manual Save' || (typeof reason === 'string' && reason.includes('Ctrl+S'))) {
      if (typeof showToast === 'function') showToast("Save is disabled: No FMEA project file is currently open.", "warning");
      else alert("Save is disabled: No FMEA project file is currently open.");
    }
    return;
  }
  const rev = typeof getContextRevision === 'function' ? getContextRevision() : null;
  const hasInProgressRev = rev && (rev.status === 'In Progress' || rev.status === 'Draft');
  if (!hasInProgressRev) {
    updateSaveStatusBadgeUI('readOnly', '🔒 Rev Frozen');
    if (reason === 'Manual Save' || (typeof reason === 'string' && reason.includes('Ctrl+S'))) {
      if (typeof showToast === 'function') showToast("Save is disabled: Active revision is frozen or not in-progress.", "warning");
      else alert("Save is disabled: Active revision is frozen or not in-progress.");
    }
    return;
  }
  const activeCtx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : null;
  if (activeCtx && activeCtx.isReadOnly) {
    updateSaveStatusBadgeUI('readOnly', '🔒 Read-Only');
    if (reason === 'Manual Save' || (typeof reason === 'string' && reason.includes('Ctrl+S'))) {
      if (typeof showToast === 'function') showToast("Access Denied: Your account is read-only or the active FMEA revision is frozen. Saves are not permitted.", "warning");
      else alert("Access Denied: Your account is read-only or the active FMEA revision is frozen. Saves are not permitted.");
    }
    return;
  }
  updateSaveStatusBadgeUI('saving', '⏳ Saving...');

  // Electron Desktop Mode: Files are persisted directly to origin disk location, NOT localStorage.

  const settings = getAutoSaveSettings();
  const targetFileName = activeSharePointFileName || settings.sharepointFileName || 'Jost_FMEA_Master.json';
  const nowStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  if (settings.sharepointEnabled && settings.sharepointSiteUrl) {
    const result = await saveToSharePoint(settings, targetFileName);
    if (result.success) {
      updateSaveStatusBadgeUI('saved', `☁️ Synced (${nowStr})`);
      showToast(`Auto-Saved to SharePoint [${targetFileName}] at ${nowStr}`);
    } else {
      updateSaveStatusBadgeUI('saved', `💾 Saved locally (${nowStr})`);
    }
  } else {
    updateSaveStatusBadgeUI('saved', `✓ Saved (${nowStr})`);
    if (reason === 'Manual Save' || reason.includes('Ctrl+S')) {
      showToast(`Project file saved successfully! (${nowStr})`);
    }
  }
}

async function saveToSharePoint(settings, targetFileName) {
  try {
    const fileName = targetFileName || activeSharePointFileName || settings.sharepointFileName || 'Jost_FMEA_Master.json';
    const dashFileName = getDashboardFileName(fileName);

    // Build both payloads in parallel
    const [encPayload, dashResult] = await Promise.all([
      createFmeaPackageJSON(fmeaData, fileName),
      createFmeaDashboardJSON(fmeaData, fileName)
    ]);
    const dashPayload = dashResult.json;
    const dashboardData = dashResult.dashboardData;

    const isElectron = window.electronAPI && window.electronAPI.isElectron;

    if (isElectron) {
      const catalog = getSharePointRepoFiles();
      const item = catalog.find(f => f.name === fileName);
      const targetDir = activeResolvedSharePointLocalPath || settings.sharepointSiteUrl || '';
      const filePath = item ? item.fullPath : `${targetDir}/${fileName}`;
      const dashPath = `${targetDir}/dashboard/${dashFileName}`;

      // Write both files (encrypted FMEA + dashboard) simultaneously
      const [saveRes, dashSaveRes] = await Promise.all([
        window.electronAPI.writeFile(filePath, encPayload),
        window.electronAPI.writeFile(dashPath, dashPayload)
      ]);

      if (saveRes.success) {
        if (item) {
          item.lastModified = new Date().toISOString();
          item.size = `${Math.round(encPayload.length / 1024)} KB`;
        }
        if (!dashSaveRes.success) {
          console.warn('[Dashboard] Dashboard file write failed:', dashSaveRes.error);
        }
        // Update the shared cross-file summary catalog
        try {
          await updateSharedSummaryCatalog(fileName, dashboardData);
        } catch (_) { /* non-fatal */ }
        await loadSharePointCatalogFromDisk();
        return { success: true };
      } else {
        console.warn("Direct file save failed:", saveRes.error);
        return { success: false, error: saveRes.error };
      }
    }

    // Non-Electron fallback (Direct memory operation)
    return { success: true };
    await updateSharedSummaryCatalog(fileName, dashboardData);

    // Only attempt HTTP API routes in a web-server context (not in Electron)
    const isElectronEnv = (typeof window !== 'undefined' && window.location && window.location.protocol === 'file:');
    if (!isElectronEnv && typeof fetch !== 'undefined' && settings.sharepointSiteUrl && settings.sharepointSiteUrl.startsWith('http')) {
      try {
        const apiUrl = (typeof window !== 'undefined' && window.location && window.location.port !== '3030') ? 'http://localhost:3030/api/sharepoint/save' : '/api/sharepoint/save';
        const res = await fetch(apiUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            siteUrl: settings.sharepointSiteUrl,
            libraryPath: settings.sharepointLibraryPath,
            fileName: fileName,
            data: fmeaData
          })
        });
        if (res && res.ok) return { success: true };
      } catch (fetchErr) {
        console.warn('SharePoint HTTP API endpoint not available (falling back to local storage):', fetchErr);
      }
    }
    // Temporary in-memory only: Do not persist file payload to localStorage
    return { success: true, cached: true };
  } catch (err) {
    console.warn('SharePoint API push error:', err);
    return { success: false, error: err.message };
  }
}


async function fetchFromSharePoint() {
  const settings = getAutoSaveSettings();
  if (!settings.sharepointSiteUrl) {
    alert("Please enter and save a valid SharePoint Site URL first.");
    return;
  }
  if (!confirm("Retrieve and replace active project dataset from SharePoint?\nAny unsaved local changes will be replaced.")) return;

  // Skip HTTP API in Electron (file:// protocol) — no server running
  const isElectronEnv = (typeof window !== 'undefined' && window.location && window.location.protocol === 'file:');
  if (isElectronEnv) {
    showToast("SharePoint HTTP sync not available in desktop mode. Use local file open/save instead.");
    return;
  }

  try {
    const baseUrl = (typeof window !== 'undefined' && window.location && window.location.port !== '3030') ? 'http://localhost:3030/api/sharepoint/load' : '/api/sharepoint/load';
    const res = await fetch(baseUrl + '?siteUrl=' + encodeURIComponent(settings.sharepointSiteUrl) + '&fileName=' + encodeURIComponent(settings.sharepointFileName || 'Jost_FMEA_Master.json'));
    if (res.ok) {
      const data = await res.json();
      if (data && (data.structure || data.functionLines)) {
        fmeaData = data;
        saveProjectToLocalStorage();
        renderFMEATable();
        showToast("Successfully downloaded & restored project file from SharePoint!");
        return;
      }
    }
    showToast("Connected to SharePoint URL. Local dataset active.");
  } catch (err) {
    alert("SharePoint fetch error: " + err.message);
  }
}

function updateAutoSaveStatusBadge(text, color) {
  const badge = document.getElementById('autoSaveStatusBadge');
  if (!badge) return;

  const settings = getAutoSaveSettings();
  if (text) {
    badge.textContent = text;
    if (color) badge.style.backgroundColor = color;
  } else {
    if (settings.autoSaveMode === 'disabled') {
      badge.textContent = '💾 Auto-Save: Disabled';
      badge.style.backgroundColor = '#64748b';
    } else if (settings.autoSaveMode === 'interval') {
      badge.textContent = `⏱️ Auto-Save: Every ${settings.autoSaveIntervalMinutes}m`;
      badge.style.backgroundColor = '#0284c7';
    } else {
      badge.textContent = '⚡ Auto-Save: Real-Time';
      badge.style.backgroundColor = '#059669';
    }
  }
}

function isAiFeaturesEnabled() {
  const settings = getAutoSaveSettings();
  if (typeof settings.enableAiFeatures !== 'undefined') {
    return !!settings.enableAiFeatures;
  }
  const stored = localStorage.getItem('jost_enable_ai_features');
  if (stored !== null) return stored === 'true';
  return true;
}

function isAiFeatureModuleEnabled(moduleKey) {
  if (!isAiFeaturesEnabled()) return false;
  const settings = getAutoSaveSettings();
  const keyName = 'enable_ai_' + moduleKey;
  if (typeof settings[keyName] !== 'undefined') {
    return !!settings[keyName];
  }
  const stored = localStorage.getItem('jost_enable_ai_' + moduleKey);
  if (stored !== null) return stored === 'true';
  return true;
}

function updateAiFeaturesVisibilityUI() {
  const masterEnabled = isAiFeaturesEnabled();
  const workbenchEnabled = isAiFeatureModuleEnabled('workbench');
  const networkEnabled = isAiFeatureModuleEnabled('network_linker');
  const interfaceEnabled = isAiFeatureModuleEnabled('interface_gen');

  const setVis = (id, isVis) => {
    const el = document.getElementById(id);
    if (el) el.style.display = isVis ? '' : 'none';
  };

  setVis('navItemAiWorkbench', masterEnabled && workbenchEnabled);
  setVis('btnToolbarAiWorkbench', masterEnabled && workbenchEnabled);
  setVis('navItemAiWorkbench2', masterEnabled && workbenchEnabled);
  setVis('btnToolbarAiWorkbench2', masterEnabled && workbenchEnabled);

  setVis('navItemAiNetworkLinker', masterEnabled && networkEnabled);
  setVis('sidebarNetLinkerBtn', masterEnabled && networkEnabled);
  setVis('btnToolbarAiNetLinker', masterEnabled && networkEnabled);

  setVis('navItemAiInterfaceGenerator', masterEnabled && interfaceEnabled);

  const isIfaceEnabled = masterEnabled && interfaceEnabled;
  document.querySelectorAll('button[onclick*="openAiInterfaceGeneratorModal"]').forEach(btn => {
    btn.disabled = !isIfaceEnabled;
    btn.style.opacity = isIfaceEnabled ? '1' : '0.45';
    btn.style.cursor = isIfaceEnabled ? 'pointer' : 'not-allowed';
    btn.style.pointerEvents = isIfaceEnabled ? 'auto' : 'none';
    if (!isIfaceEnabled) {
      btn.setAttribute('title', 'Access Restricted: AI Interface Generator is disabled by System Admin policy.');
    } else {
      btn.removeAttribute('title');
    }
  });

  const helpText = document.getElementById('aiFeaturesHelpText');
  if (helpText) {
    helpText.innerHTML = masterEnabled
      ? '🤖 <strong>AI Enabled:</strong> AI toolbar items, failure network predictors, and content generation assistants are active.'
      : '🚫 <strong>AI Disabled (Admin Policy):</strong> All AI toolbar buttons, failure predictors, and generation workflows are hidden and locked.';
  }
}

function toggleAiFeaturesAdminControl() {
  const masterChk = document.getElementById('settingEnableAiFeatures');
  const wbChk = document.getElementById('settingEnableAiWorkbench');
  const netChk = document.getElementById('settingEnableAiNetworkLinker');
  const ifaceChk = document.getElementById('settingEnableAiInterfaceGen');

  if (!masterChk) return;
  const settings = getAutoSaveSettings();

  settings.enableAiFeatures = masterChk.checked;
  localStorage.setItem('jost_enable_ai_features', masterChk.checked ? 'true' : 'false');

  if (wbChk) {
    settings.enable_ai_workbench = wbChk.checked;
    localStorage.setItem('jost_enable_ai_workbench', wbChk.checked ? 'true' : 'false');
  }
  if (netChk) {
    settings.enable_ai_network_linker = netChk.checked;
    localStorage.setItem('jost_enable_ai_network_linker', netChk.checked ? 'true' : 'false');
  }
  if (ifaceChk) {
    settings.enable_ai_interface_gen = ifaceChk.checked;
    localStorage.setItem('jost_enable_ai_interface_gen', ifaceChk.checked ? 'true' : 'false');
  }

  updateAiFeaturesVisibilityUI();
}

function renderAutoSaveAdminForm() {
  const settings = getAutoSaveSettings();

  const modeSel = document.getElementById('settingAutoSaveMode');
  const intSel = document.getElementById('settingAutoSaveInterval');
  const spCheck = document.getElementById('settingSharePointEnabled');
  const spUrl = document.getElementById('settingSharePointUrl');
  const spLib = document.getElementById('settingSharePointLibrary');
  const spFile = document.getElementById('settingSharePointFileName');
  const spClient = document.getElementById('settingSharePointClientId');
  const aiCheck = document.getElementById('settingEnableAiFeatures');

  const wbChk = document.getElementById('settingEnableAiWorkbench');
  const netChk = document.getElementById('settingEnableAiNetworkLinker');
  const ifaceChk = document.getElementById('settingEnableAiInterfaceGen');

  if (modeSel) modeSel.value = settings.autoSaveMode || 'activity';
  if (intSel) intSel.value = settings.autoSaveIntervalMinutes || 1;
  if (spCheck) spCheck.checked = !!settings.sharepointEnabled;
  if (spUrl) spUrl.value = settings.sharepointSiteUrl || '';
  if (spLib) spLib.value = settings.sharepointLibraryPath || '/Shared Documents/FMEAs';
  if (spFile) spFile.value = settings.sharepointFileName || 'Jost_FMEA_Master.json';
  if (spClient) spClient.value = settings.sharepointClientId || '';

  if (aiCheck) aiCheck.checked = isAiFeaturesEnabled();
  if (wbChk) wbChk.checked = isAiFeatureModuleEnabled('workbench');
  if (netChk) netChk.checked = isAiFeatureModuleEnabled('network_linker');
  if (ifaceChk) ifaceChk.checked = isAiFeatureModuleEnabled('interface_gen');

  // Ensure File Access Mode dropdown and its dependent fields/browse button are fully updated with active user permissions
  const fileAccessModeSelect = document.getElementById('settingFileAccessMode');
  if (fileAccessModeSelect) {
    fileAccessModeSelect.value = settings.fileAccessMode || 'admin_defined';
  }
  if (typeof toggleFileAccessModeFields === 'function') {
    toggleFileAccessModeFields();
  }

  toggleAutoSaveIntervalVisibility();
  toggleSharePointFields();
  updateAiFeaturesVisibilityUI();
}

