function saveAutoSaveAdminSettings(e) {
  e.preventDefault();
  if (!currentUser || currentUser.role !== 'Admin') {
    alert("Access Denied: Admin privileges required.");
    return;
  }

  const settings = getAutoSaveSettings();
  settings.autoSaveMode = document.getElementById('settingAutoSaveMode').value;
  settings.autoSaveIntervalMinutes = parseInt(document.getElementById('settingAutoSaveInterval').value) || 1;
  settings.sharepointEnabled = document.getElementById('settingSharePointEnabled').checked;

  const targetUrl = document.getElementById('settingSharePointUrl').value.trim();
  settings.sharepointSiteUrl = targetUrl;

  const adminConfigUrl = document.getElementById('settingAdminConfigSharePointUrl')
    ? document.getElementById('settingAdminConfigSharePointUrl').value.trim()
    : targetUrl;

  settings.adminConfigSharePointUrl = adminConfigUrl || targetUrl;
  const effectiveAdminPath = settings.adminConfigSharePointUrl || settings.sharepointSiteUrl;

  if (effectiveAdminPath) {
    localStorage.setItem('jost_admin_sharepoint_url', effectiveAdminPath);
    activeResolvedSharePointLocalPath = effectiveAdminPath;
  }

  settings.sharepointLibraryPath = document.getElementById('settingSharePointLibrary').value.trim();
  settings.sharepointFileName = document.getElementById('settingSharePointFileName').value.trim() || 'Jost_FMEA_Master.json';
  settings.sharepointClientId = document.getElementById('settingSharePointClientId').value.trim();

  const aiCheck = document.getElementById('settingEnableAiFeatures');
  if (aiCheck) {
    settings.enableAiFeatures = aiCheck.checked;
    localStorage.setItem('jost_enable_ai_features', aiCheck.checked ? 'true' : 'false');
  }

  if (document.getElementById('settingFileAccessMode')) {
    const accessMode = document.getElementById('settingFileAccessMode').value;
    settings.fileAccessMode = accessMode;
    settings.allowUserDefinedLocation = (accessMode === 'user_defined');
  }

  saveProjectToLocalStorage();
  initAutoSaveEngine();
  updateAiFeaturesVisibilityUI();

  sharePointFileListCache = null;
  loadSharePointCatalogFromDisk().then(() => {
    if (typeof renderSharePointFileList === 'function') renderSharePointFileList();
  });

  if (typeof exportAdminSettingsToSharePoint === 'function') {
    exportAdminSettingsToSharePoint();
  }

  showToast("Auto-Save & File Access Mode settings updated and cascaded to repository.");
}

function renderClassLibraryTable() {
  const tbody = document.getElementById('classLibraryTableBody');
  if (!tbody) return;
  const lib = getClassLibrary();
  const isAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : (currentUser && (currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin'));

  if (lib.length === 0) {
    tbody.innerHTML = '<tr><td colspan="4" class="text-muted">No Class Symbols defined.</td></tr>';
    return;
  }

  tbody.innerHTML = lib.map(item => `
    <tr>
      <td><span class="badge-class" style="font-weight:bold; color:#0f172a; background:#e2e8f0; padding:2px 6px; border-radius:4px;">${escapeHtml(item.symbol)}</span></td>
      <td><strong>${escapeHtml(item.name || item.symbol)}</strong></td>
      <td><span class="badge" style="background:#0284c7; color:#fff; font-weight:bold; padding:2px 8px; border-radius:10px;">${item.weight ?? 0}</span></td>
      <td style="text-align: right;">
        ${isAdmin ? `
          <button class="btn btn-sm btn-secondary" onclick="editClassSymbol('${item.id}')">Edit</button>
          <button class="btn btn-sm btn-danger" onclick="deleteClassSymbol('${item.id}')">Del</button>
        ` : `<span style="font-size:11px; color:#94a3b8;">Admin Only</span>`}
      </td>
    </tr>
  `).join('');
}

function saveProjectToLocalStorage() {
  // Electron Desktop App Mode: Do not write file payloads to localStorage.
  // Files are loaded and saved exclusively from origin disk locations.
  if (!hasUnsavedChanges) {
    hasUnsavedChanges = true;
    updateSaveStatusBadgeUI('unsaved', '● Unsaved Changes');
  }
  triggerAutoSave();
}

function saveClassSymbol(e) {
  e.preventDefault();
  if (!currentUser || (currentUser.role !== 'Admin' && currentUser.role !== 'SuperAdmin')) {
    alert('Access Denied: Only Administrators can modify the Class Library.');
    return;
  }

  const symbol = document.getElementById('classLibSymbol').value.trim();
  const name = document.getElementById('classLibName').value.trim();
  const weightInput = document.getElementById('classLibWeight');
  const weight = weightInput ? parseInt(weightInput.value, 10) || 0 : 0;
  const editId = document.getElementById('classLibEditId').value;

  if (!symbol || !name) {
    alert('Please enter both symbol and description.');
    return;
  }

  const lib = getClassLibrary();

  if (editId) {
    const item = lib.find(i => i.id === editId);
    if (item) {
      item.symbol = symbol;
      item.name = name;
      item.weight = weight;
    }
  } else {
    if (lib.some(i => i.symbol.toLowerCase() === symbol.toLowerCase())) {
      alert(`Symbol "${symbol}" already exists in the library.`);
      return;
    }
    lib.push({
      id: 'cls-' + Date.now(),
      symbol,
      name,
      weight
    });
  }

  cancelEditClassSymbol();
  saveProjectToLocalStorage();
  renderClassLibraryTable();
  renderCauseClassOptions();
  showToast('Class Symbol Library updated.');
}

function editClassSymbol(id) {
  const lib = getClassLibrary();
  const item = lib.find(i => i.id === id);
  if (!item) return;

  document.getElementById('classLibEditId').value = item.id;
  document.getElementById('classLibSymbol').value = item.symbol;
  document.getElementById('classLibName').value = item.name;
  if (document.getElementById('classLibWeight')) {
    document.getElementById('classLibWeight').value = item.weight ?? 5;
  }

  const header = document.getElementById('classLibFormHeader');
  if (header) header.textContent = 'Edit Class Symbol';
  const submitBtn = document.getElementById('classLibSubmitBtn');
  if (submitBtn) submitBtn.textContent = 'Update Symbol';
  const cancelBtn = document.getElementById('classLibCancelBtn');
  if (cancelBtn) cancelBtn.style.display = 'inline-block';
}

function cancelEditClassSymbol() {
  const form = document.getElementById('classLibForm');
  if (form) form.reset();
  document.getElementById('classLibEditId').value = '';
  if (document.getElementById('classLibWeight')) {
    document.getElementById('classLibWeight').value = 5;
  }

  const header = document.getElementById('classLibFormHeader');
  if (header) header.textContent = 'Add New Class Symbol (Admin Only)';
  const submitBtn = document.getElementById('classLibSubmitBtn');
  if (submitBtn) submitBtn.textContent = '+ Add Symbol';
  const cancelBtn = document.getElementById('classLibCancelBtn');
  if (cancelBtn) cancelBtn.style.display = 'none';
}

function deleteClassSymbol(id) {
  if (!currentUser || currentUser.role !== 'Admin') {
    alert('Access Denied: Only Administrators can modify the Class Library.');
    return;
  }

  if (!confirm('Are you sure you want to remove this Class Symbol from the library?')) return;

  const lib = getClassLibrary();
  const idx = lib.findIndex(i => i.id === id);
  if (idx !== -1) {
    lib.splice(idx, 1);
    saveProjectToLocalStorage();
    renderClassLibraryTable();
    renderCauseClassOptions();
    showToast('Class Symbol removed.');
  }
}

function onUserRoleChange(role) {
  const rolePresets = {
    'Admin': { canEditFMEA: true, canCreateRevision: true, canFreezeRevision: true, canExport: true, canManageVariants: true, canManagePFMEA: true, canViewReports: true, canManageUsers: true },
    'Quality Manager': { canEditFMEA: false, canCreateRevision: false, canFreezeRevision: true, canExport: true, canManageVariants: false, canManagePFMEA: false, canViewReports: true, canManageUsers: false },
    'Product Leader': { canEditFMEA: true, canCreateRevision: true, canFreezeRevision: true, canExport: true, canManageVariants: true, canManagePFMEA: false, canViewReports: true, canManageUsers: false },
    'Process Leader': { canEditFMEA: true, canCreateRevision: true, canFreezeRevision: true, canExport: true, canManageVariants: false, canManagePFMEA: true, canViewReports: true, canManageUsers: false },
    'Lead Engineer': { canEditFMEA: true, canCreateRevision: true, canFreezeRevision: false, canExport: true, canManageVariants: true, canManagePFMEA: true, canViewReports: true, canManageUsers: false },
    'Engineer': { canEditFMEA: true, canCreateRevision: true, canFreezeRevision: false, canExport: true, canManageVariants: false, canManagePFMEA: false, canViewReports: true, canManageUsers: false },
    'Viewer': { canEditFMEA: false, canCreateRevision: false, canFreezeRevision: false, canExport: true, canManageVariants: false, canManagePFMEA: false, canViewReports: true, canManageUsers: false }
  };
  const perms = rolePresets[role] || rolePresets['Engineer'];
  if (document.getElementById('perm_canEditFMEA')) document.getElementById('perm_canEditFMEA').checked = perms.canEditFMEA;
  if (document.getElementById('perm_canCreateRevision')) document.getElementById('perm_canCreateRevision').checked = perms.canCreateRevision;
  if (document.getElementById('perm_canFreezeRevision')) document.getElementById('perm_canFreezeRevision').checked = perms.canFreezeRevision;
  if (document.getElementById('perm_canExport')) document.getElementById('perm_canExport').checked = perms.canExport;
  if (document.getElementById('perm_canManageVariants')) document.getElementById('perm_canManageVariants').checked = perms.canManageVariants;
  if (document.getElementById('perm_canManagePFMEA')) document.getElementById('perm_canManagePFMEA').checked = perms.canManagePFMEA;
  if (document.getElementById('perm_canViewReports')) document.getElementById('perm_canViewReports').checked = perms.canViewReports;
  if (document.getElementById('perm_canManageUsers')) document.getElementById('perm_canManageUsers').checked = perms.canManageUsers;
}

function resetUserForm() {
  const form = document.getElementById('userForm');
  if (form) form.reset();
  const editId = document.getElementById('userEditId');
  if (editId) editId.value = '';
  const emailInput = document.getElementById('userEmailInput');
  if (emailInput) emailInput.value = '';
  const title = document.getElementById('userFormTitle');
  if (title) title.innerText = '👤 Add New User';
  onUserRoleChange('Engineer');
}

