    'Admin': { style: 'background:rgba(168, 85, 247, 0.2); color:#c084fc; border:1px solid rgba(168, 85, 247, 0.5);', icon: '👑' },
    'SuperAdmin': { style: 'background:rgba(168, 85, 247, 0.2); color:#c084fc; border:1px solid rgba(168, 85, 247, 0.5);', icon: '👑' },
    'Quality Manager': { style: 'background:rgba(16, 185, 129, 0.2); color:#34d399; border:1px solid rgba(16, 185, 129, 0.5);', icon: '🛡️' },
    'Product Leader': { style: 'background:rgba(56, 189, 248, 0.2); color:#38bdf8; border:1px solid rgba(56, 189, 248, 0.5);', icon: '🚀' },
    'Process Leader': { style: 'background:rgba(244, 63, 94, 0.2); color:#fb7185; border:1px solid rgba(244, 63, 94, 0.5);', icon: '⚙️' },
    'Lead Engineer': { style: 'background:rgba(245, 158, 11, 0.2); color:#fbbf24; border:1px solid rgba(245, 158, 11, 0.5);', icon: '🛠️' },
    'Engineer': { style: 'background:rgba(99, 102, 241, 0.2); color:#818cf8; border:1px solid rgba(99, 102, 241, 0.5);', icon: '💻' },
