function toggleShowAllActionsVariants(checked) {
  window.showAllActionsVariants = checked;
  renderActionsLibraryList();
}
window.toggleShowAllActionsVariants = toggleShowAllActionsVariants;

function resetActionForm() {
  const form = document.getElementById('actionForm');
  if (form) form.reset();
  let hidden = document.getElementById('actEditId');
  if (hidden) hidden.value = '';

  const causeVar = getVariantsForCause(activeCauseId);
  const defaultVar = causeVar || (selectedVariantFilter && selectedVariantFilter !== 'ALL' ? [selectedVariantFilter] : ['ALL']);
  renderVariantCheckboxList('actVariantCheckboxList', 'act', defaultVar);
  const submitBtn = document.querySelector('#actionForm button[type="submit"]');
  if (submitBtn) submitBtn.textContent = '+ Add to Library';
}

function openActionModal(causeId) {
  if (!checkCanEditFMEA()) return;
  activeCauseId = causeId;
  const ctx = getActiveFmeaData();
  const linked = (ctx.causeActions || {})[causeId] || [];
  window.activePendingActionIds = [...linked];
  window.showAllActionsVariants = false;
  const searchInput = document.getElementById('actionSearchInput');
  if (searchInput) searchInput.value = '';
  populateUserDropdown('userSuggestions');
  resetActionForm();
  renderActionsLibraryList();
  openModal('actionModal');
}

function toggleActionSelection(id, checked) {
  if (!window.activePendingActionIds) window.activePendingActionIds = [];
  if (checked) {
    if (!window.activePendingActionIds.includes(id)) window.activePendingActionIds.push(id);
  } else {
    window.activePendingActionIds = window.activePendingActionIds.filter(x => x !== id);
  }
}
window.toggleActionSelection = toggleActionSelection;

function renderActionsLibraryList() {
  const container = document.getElementById('actionsLibraryContainer');
  const ctx = getActiveFmeaData();
  const linkedIds = window.activePendingActionIds || (ctx.causeActions || {})[activeCauseId] || [];

  fmeaData.libraries = fmeaData.libraries || {};
  fmeaData.libraries.actions = fmeaData.libraries.actions || [];

  const isPFMEAAction = (act) => {
    return act.module === 'PFMEA' || act.origin === 'PFMEA' || (act.id && String(act.id).toLowerCase().includes('pfmea'));
  };

  let actions = fmeaData.libraries.actions;
  if (!ctx.isPFMEA) {
    actions = actions.filter(act => !isPFMEAAction(act));
  } else {
    actions = actions.filter(act => isPFMEAAction(act));
  }

  // Filter by cause's variants or global variant filter (unless override unchecked)
  const causeVar = getVariantsForCause(activeCauseId);
  const targetVarFilter = causeVar || (selectedVariantFilter !== 'ALL' ? selectedVariantFilter : null);
  if (targetVarFilter && !window.showAllActionsVariants) {
    actions = actions.filter(act => matchesVariantFilter(act.variants || act.variantId, targetVarFilter));
  }

  const searchQuery = (document.getElementById('actionSearchInput')?.value || '').toLowerCase().trim();
  if (searchQuery) {
    actions = actions.filter(act =>
      (act.detail && act.detail.toLowerCase().includes(searchQuery)) ||
      (act.pd && act.pd.toLowerCase().includes(searchQuery)) ||
      (act.responsible && act.responsible.toLowerCase().includes(searchQuery)) ||
      (act.actionTaken && act.actionTaken.toLowerCase().includes(searchQuery))
    );
  }

  const checkFilter = document.getElementById('actionCheckFilter')?.value || 'ALL';
  if (checkFilter === 'CHECKED') {
    actions = actions.filter(act => linkedIds.includes(act.id));
  } else if (checkFilter === 'UNCHECKED') {
    actions = actions.filter(act => !linkedIds.includes(act.id));
  }

  const varText = causeVar
    ? `Cause Variant: ${getVariantNamesDisplay(causeVar)}`
    : (selectedVariantFilter !== 'ALL' ? `Global Variant Filter` : 'All Variants');

  const filterHeaderHtml = `
    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px; padding:4px 8px; border:1px solid #334155; border-radius:4px;">
      <span style="font-size:10.5px; font-weight:700; color:#38bdf8;">🎯 Active Filter: ${escapeHtml(varText)}</span>
      <label style="font-size:10.5px; font-weight:600; color:#cbd5e1; cursor:pointer; margin:0; display:flex; align-items:center; gap:4px;">
        <input type="checkbox" id="chkShowAllActionVariants" onchange="toggleShowAllActionsVariants(this.checked)" ${window.showAllActionsVariants ? 'checked' : ''}>
        View All Actions (Ignore Variant Filter)
      </label>
    </div>
  `;

  const listHtml = actions.map(act => {
    const isChecked = linkedIds.includes(act.id);
    const pdBadge = act.pd === 'P'
      ? `<span style="background:rgba(16,185,129,0.15); color:#34d399; border:1px solid #059669; font-size:9.5px; padding:1px 5px; border-radius:3px; font-weight:700; margin-right:4px;">[P]</span>`
      : `<span style="background:rgba(245,158,11,0.15); color:#fbbf24; border:1px solid #d97706; font-size:9.5px; padding:1px 5px; border-radius:3px; font-weight:700; margin-right:4px;">[D]</span>`;

    return `
    <div class="checkbox-card" style="display:flex; justify-content:space-between; align-items:center; background:${isChecked ? 'rgba(2, 132, 199, 0.12)' : '#1e293b'}; border:1px solid ${isChecked ? '#0284c7' : '#334155'}; padding:6px 10px; border-radius:6px; margin-bottom:4px;">
      <label style="flex:1; cursor:pointer; margin:0; font-size:11.5px; color:#f8fafc;">
        <input type="checkbox" id="chk_act_${act.id}" ${isChecked ? 'checked' : ''} onchange="toggleActionSelection('${act.id}', this.checked)">
        ${pdBadge}<strong style="">${escapeHtml(act.detail)}</strong> <small style="color:#94a3b8; font-size:10px;">(${getVariantNamesDisplay(act.variants || act.variantId)})</small>
        <br><small style="color:#cbd5e1; font-size:10px;">Resp: ${escapeHtml(act.responsible || '-')} | Target: ${act.targetDate || '-'} | Taken: ${escapeHtml(act.actionTaken || '-')} (${act.completionDate || '-'})</small>
      </label>
      <div class="card-actions" style="display:flex; gap:4px;">
        <button class="btn btn-sm btn-secondary" style="font-size:10px; padding:2px 6px;" onclick="editLibraryAction('${act.id}')">Edit</button>
        <button class="btn btn-sm btn-danger" style="font-size:10px; padding:2px 6px;" onclick="deleteLibraryAction('${act.id}')">Del</button>
      </div>
    </div>
    `;
  }).join('');

  container.innerHTML = filterHeaderHtml + (listHtml || '<p class="text-muted" style="padding:12px; color:#94a3b8;">No recommended actions in library matching active filter. Check "View All Actions" or create one on the left.</p>');
}

