// ----------------------------------------------------
// Add & Manage Failure Modes under specific Function Context
// ----------------------------------------------------
function renderExistingFmsForTargetFunction() {
  const container = document.getElementById('existingFmListContainer');
  if (!container) return;

  const select = document.getElementById('fmTargetFunctionSelect');
  if (!select || !select.value) {
    container.innerHTML = `<div style="font-size:11px; color:#94a3b8; padding:8px 0;">No function line selected.</div>`;
    return;
  }

  const flId = select.value;
  const ctx = getActiveFmeaData();
  const fl = (ctx.functionLines || []).find(l => l.id === flId);
  const failureModes = fl ? (fl.failureModes || []) : [];

  if (failureModes.length === 0) {
    container.innerHTML = `<div style="font-size:11px; color:#94a3b8; padding:8px 0;">No Failure Modes defined under this function line yet.</div>`;
    return;
  }

  let html = `<ul style="list-style:none; padding:0; margin:0;">`;
  failureModes.forEach(fm => {
    html += `
      <li style="display:flex; justify-content:space-between; align-items:center; padding:6px 10px; border:1px solid #334155; background:#1e293b; margin-bottom:4px; border-radius:6px; font-size:11.5px; color:#f8fafc;">
        <span style="color:#f8fafc; font-weight:600;">${escapeHtml(fm.name)}</span>
        <button type="button" class="btn btn-xs btn-danger" style="font-size:10px; padding:2px 8px;" onclick="deleteFailureMode('${flId}', '${fm.id}', event)">Delete</button>
      </li>
    `;
  });
  html += `</ul>`;
  container.innerHTML = html;
}

function deleteFailureMode(flId, fmId, e) {
  if (e) {
    e.stopPropagation();
    e.preventDefault();
  }
  if (!checkCanEditFMEA()) return;
  const ctx = getActiveFmeaData();
  const fmObj = (fmeaData.libraries?.failureModes || []).find(f => f.id === fmId);
  if (ctx.isPFMEA && fmObj && (fmObj.origin === 'DFMEA' || fmObj.module === 'DFMEA' || fmObj.dfmeaFmId || String(fmObj.id).startsWith('dfm-'))) {
    alert("DFMEA Synced Failure Modes cannot be deleted from PFMEA mode. They must be managed in DFMEA mode.");
    return;
  }

  if (!confirm("Are you sure you want to delete this Failure Mode?\nAll linked Effects, Causes, and Action mappings associated with this Failure Mode will be unlinked/removed.")) {
    return;
  }

  // Find fl and remove fmId
  let targetFl = (ctx.functionLines || []).find(l => l.id === flId);
  if (!targetFl) {
    for (const line of (ctx.functionLines || [])) {
      if (line.failureModes && line.failureModes.some(m => m.id === fmId)) {
        targetFl = line;
        break;
      }
    }
  }

  if (targetFl && targetFl.failureModes) {
    targetFl.failureModes = targetFl.failureModes.filter(m => m.id !== fmId);
  }

  // Also remove from global root functionLines if active sub-context is active
  if (fmeaData.functionLines) {
    fmeaData.functionLines.forEach(line => {
      if (line.failureModes) {
        line.failureModes = line.failureModes.filter(m => m.id !== fmId);
      }
    });
  }

  // Remove linked mapping entries
  if (ctx.failureModeEffects) delete ctx.failureModeEffects[fmId];
  if (ctx.failureModeCauses) delete ctx.failureModeCauses[fmId];
  if (fmeaData.failureModeEffects) delete fmeaData.failureModeEffects[fmId];
  if (fmeaData.failureModeCauses) delete fmeaData.failureModeCauses[fmId];

  saveProjectToLocalStorage();
  renderFMEATable();
  renderExistingFmsForTargetFunction();
  if (typeof updateDashboardInsights === 'function') updateDashboardInsights();
  showToast("Failure Mode deleted successfully.");
}

function openAddFailureModeModal(targetFlId = null) {
  if (!checkCanEditFMEA()) return;
  const ctx = getActiveFmeaData();
  const select = document.getElementById('fmTargetFunctionSelect');
  if (!select) return;

  let allLines = ctx.functionLines || [];
  let lines = [...allLines];

  const targetFl = targetFlId ? allLines.find(fl => fl.id === targetFlId) : null;

  if (selectedStructureId && !targetFl) {
    const filtered = allLines.filter(fl => {
      if (fl.structId === selectedStructureId) return true;
      if (ctx.isPFMEA && ctx.processSteps) {
        const ps = ctx.processSteps.find(p => p.id === fl.structId);
        if (ps && String(ps.dfmeaStructId) === String(selectedStructureId)) return true;
      }
      return false;
    });
    if (filtered.length > 0) {
      lines = filtered;
    }
  }

  // Always ensure targetFl is present in options list if provided
  if (targetFl && !lines.some(fl => fl.id === targetFl.id)) {
    lines.unshift(targetFl);
  }

  let opts = '';
  lines.forEach(fl => {
    let elemLabel = 'Element';
    if (ctx.isPFMEA && ctx.processSteps) {
      const ps = ctx.processSteps.find(p => p.id === fl.structId);
      if (ps) elemLabel = ps.opNo ? `${ps.opNo} - ${ps.name}` : ps.name;
    } else {
      const structNode = getStructureNodeById(ctx.structure, fl.structId);
      if (structNode) elemLabel = structNode.partNo ? `${structNode.partNo} - ${structNode.name}` : structNode.name;
    }
    const funcObj = (ctx.functions || []).find(f => f.id === fl.funcId);
    if (funcObj && funcObj.isConsidered !== false) {
      opts += `<option value="${fl.id}">[${escapeHtml(elemLabel)}] ${escapeHtml(funcObj.name)}</option>`;
    }
  });

  if (!opts) {
    alert(ctx.isPFMEA ? "No active process function lines available. Run Function Analysis first to enable process functions." : "No active function lines available. Run Function Analysis first to enable functions.");
    return;
  }

  select.innerHTML = opts;
  const addFmForm = document.getElementById('addFmForm');
  if (addFmForm) addFmForm.reset();

  // Pre-select target or active function line
  if (targetFl) {
    select.value = targetFl.id;
  } else if (targetFlId && lines.some(fl => fl.id === targetFlId)) {
    select.value = targetFlId;
  } else if (typeof activeFunctionLineId !== 'undefined' && activeFunctionLineId && lines.some(fl => fl.id === activeFunctionLineId)) {
    select.value = activeFunctionLineId;
  }

  // Lock dropdown to target function line
  select.disabled = true;
  select.title = "Target function line locked to selected function";

  renderExistingFmsForTargetFunction();
  openModal('addFmModal');
}

function saveFailureModeToFunction(e) {
  e.preventDefault();
  const ctx = getActiveFmeaData();
  if (ctx.isReadOnly) {
    alert("Editing is disabled. Current FMEA context is Read-Only or Frozen.");
    return;
  }

  const select = document.getElementById('fmTargetFunctionSelect');
  const flId = select ? select.value : '';
  const fmName = document.getElementById('fmNewName').value.trim();

  if (!fmName || !flId) return;

  const fl = (ctx.functionLines || []).find(l => l.id === flId);
  if (fl) {
    const newFmId = 'fm-' + Date.now() + '-' + Math.floor(Math.random() * 1000);
    fl.failureModes = fl.failureModes || [];
    fl.failureModes.push({
      id: newFmId,
      name: fmName
    });
    // Ensure mapping structures exist
    ctx.failureModeEffects = ctx.failureModeEffects || {};
    ctx.failureModeCauses = ctx.failureModeCauses || {};
    ctx.failureModeEffects[newFmId] = ctx.failureModeEffects[newFmId] || [];
    ctx.failureModeCauses[newFmId] = ctx.failureModeCauses[newFmId] || [];
  }

  document.getElementById('fmNewName').value = '';
  saveProjectToLocalStorage();
  renderFMEATable();
  renderExistingFmsForTargetFunction();
  showToast("Failure Mode added successfully.");
}

function quickAddFmToFunction(flId, e) {
  if (e) {
    e.stopPropagation();
    e.preventDefault();
  }
  openAddFailureModeModal(flId);
}

