function addFailureModeRow() {
  if (!checkCanEditFMEA()) return;
  const ctx = getActiveFmeaData();

  let targetFl = (ctx.functionLines || []).find(fl => !selectedStructureId || fl.structId === selectedStructureId);
  if (!targetFl && (ctx.functionLines || []).length > 0) {
    targetFl = ctx.functionLines[0];
  }
  if (!targetFl) {
    alert(ctx.isPFMEA ? "Please perform Function Analysis first to link functions to process steps." : "Please perform Function Analysis first to link functions to structure elements.");
    return;
  }

  const newFmId = 'fm-' + Date.now() + '-' + Math.floor(Math.random() * 1000);
  targetFl.failureModes = targetFl.failureModes || [];
  targetFl.failureModes.push({
    id: newFmId,
    name: ctx.isPFMEA ? 'Process Failure Mode (Click to edit)' : 'New Failure Mode (Click to edit)'
  });

  ctx.failureModeEffects = ctx.failureModeEffects || {};
  ctx.failureModeCauses = ctx.failureModeCauses || {};
  ctx.failureModeEffects[newFmId] = ctx.failureModeEffects[newFmId] || [];
  ctx.failureModeCauses[newFmId] = ctx.failureModeCauses[newFmId] || [];

  saveProjectToLocalStorage();
  renderFMEATable();
}

