let activeRatingChartMode = 'AIAG';
let activeRatingChartType = 'severity';

function switchMethodologyMode(mode) {
  fmeaData.methodologyMode = mode;
  const sel = document.getElementById('methodologyModeSelect');
  if (sel) sel.value = mode;
  renderFMEATable();
}

function calculateAIAGVDA_AP(s, o, d, classSymbol = '') {
  let numS = parseInt(s) || 1;
  if (classSymbol && typeof getClassWeight === 'function') {
    const w = getClassWeight(classSymbol);
    if (w > numS) numS = w;
  }
  s = numS;
  o = parseInt(o) || 1;
  d = parseInt(d) || 1;

  if (s >= 9) {
    if (o >= 8) return 'H';
    if (o >= 6) return d >= 5 ? 'H' : (d >= 2 ? 'M' : 'L');
    if (o >= 4) return d >= 7 ? 'H' : (d >= 2 ? 'M' : 'L');
    if (o >= 2) return d >= 7 ? 'H' : (d >= 5 ? 'M' : 'L');
    return d >= 5 ? 'M' : 'L';
  } else if (s >= 7) {
    if (o >= 8) return d >= 5 ? 'H' : (d >= 2 ? 'M' : 'L');
    if (o >= 6) return d >= 7 ? 'H' : (d >= 3 ? 'M' : 'L');
    if (o >= 4) return d >= 7 ? 'H' : (d >= 5 ? 'M' : 'L');
    if (o >= 2) return d >= 7 ? 'M' : 'L';
    return 'L';
  } else if (s >= 4) {
    if (o >= 8) return d >= 7 ? 'H' : (d >= 5 ? 'M' : 'L');
    if (o >= 6) return d >= 7 ? 'M' : 'L';
    if (o >= 4) return d >= 7 ? 'M' : 'L';
    return 'L';
  } else if (s >= 2) {
    if (o >= 8) return d >= 7 ? 'M' : 'L';
    return 'L';
  } else {
    return 'L'; // Severity 1
  }
}

function getAIAGSettings() {
  if (!fmeaData.aiagSettings) {
    fmeaData.aiagSettings = {
      sev9HighRpn: 40,
      sev1to8HighRpn: 100,
      sev1to8MedRpn: 80
    };
  }
  return fmeaData.aiagSettings;
}

function updateAIAGRiskThresholds() {
  const s9 = parseInt(document.getElementById('cfgSev9HighRpn')?.value) || 40;
  const sHigh = parseInt(document.getElementById('cfgSev1to8HighRpn')?.value) || 100;
  const sMed = parseInt(document.getElementById('cfgSev1to8MedRpn')?.value) || 80;

  fmeaData.aiagSettings = {
    sev9HighRpn: s9,
    sev1to8HighRpn: sHigh,
    sev1to8MedRpn: sMed
  };

  renderRatingChartContent();
  renderFMEATable();
  if (typeof showToast === 'function') {
    showToast('AIAG RPN Risk thresholds updated and applied!');
  }
}

function resetAIAGRiskThresholds() {
  fmeaData.aiagSettings = {
    sev9HighRpn: 40,
    sev1to8HighRpn: 100,
    sev1to8MedRpn: 80
  };

  renderRatingChartContent();
  renderFMEATable();
  if (typeof showToast === 'function') {
    showToast('AIAG RPN Risk thresholds reset to defaults.');
  }
}

function getAIAGRiskClassification(s, rpn) {
  s = parseInt(s) || 1;
  rpn = parseInt(rpn) || 0;

  const cfg = getAIAGSettings();
  const sev9Cutoff = parseInt(cfg.sev9HighRpn) || 40;
  const highCutoff = parseInt(cfg.sev1to8HighRpn) || 100;
  const medCutoff = parseInt(cfg.sev1to8MedRpn) || 80;

  if (s >= 9) {
    if (rpn > sev9Cutoff) return { level: 'High Risk', color: 'red', bg: '#fee2e2', text: '#991b1b', border: '#f87171' };
    return { level: 'Low Risk', color: 'green', bg: '#dcfce7', text: '#166534', border: '#86efac' };
  } else {
    // Severity 1-8
    if (rpn > highCutoff) return { level: 'High Risk', color: 'red', bg: '#fee2e2', text: '#991b1b', border: '#f87171' };
    if (rpn > medCutoff) return { level: 'Medium Risk', color: 'yellow', bg: '#fef3c7', text: '#92400e', border: '#fbbf24' };
    return { level: 'Low Risk', color: 'green', bg: '#dcfce7', text: '#166534', border: '#86efac' };
  }
}

function openRatingChartModal() {
  activeRatingChartMode = fmeaData.methodologyMode || 'AIAG';
  activeRatingChartType = 'severity';
  renderRatingChartContent();
  openModal('ratingChartModal');
}

function setRatingChartMode(mode) {
  activeRatingChartMode = mode;
  renderRatingChartContent();
}

function setRatingChartType(type) {
  activeRatingChartType = type;
  renderRatingChartContent();
}

function renderRatingChartContent() {
  const container = document.getElementById('ratingChartContentContainer');
  const badge = document.getElementById('ratingModalModeBadge');
  const btnAIAG = document.getElementById('ratingTabBtnAIAG');
  const btnVDA = document.getElementById('ratingTabBtnVDA');

  if (badge) badge.textContent = `Active Mode: ${activeRatingChartMode === 'AIAG-VDA' ? 'AIAG-VDA 1st Edition' : 'AIAG 4th Edition'}`;

  if (btnAIAG && btnVDA) {
    btnAIAG.className = activeRatingChartMode === 'AIAG' ? 'btn btn-sm btn-primary' : 'btn btn-sm btn-secondary';
    btnVDA.className = activeRatingChartMode === 'AIAG-VDA' ? 'btn btn-sm btn-primary' : 'btn btn-sm btn-secondary';
  }

  ['Sev', 'Occ', 'Det', 'RPN', 'AP'].forEach(t => {
    const btn = document.getElementById(`ratingTypeBtn${t}`);
    if (btn) {
      const typeKey = t.toLowerCase();
      if (typeKey === activeRatingChartType) {
        btn.className = 'btn btn-sm btn-primary';
      } else {
        btn.className = 'btn btn-sm btn-outline';
      }
    }
  });

  if (!container) return;

  if (activeRatingChartType === 'severity') {
    renderSeverityRatingChart(container);
  } else if (activeRatingChartType === 'occurrence') {
    renderOccurrenceRatingChart(container);
  } else if (activeRatingChartType === 'detection') {
    renderDetectionRatingChart(container);
  } else if (activeRatingChartType === 'rpn') {
    renderRPNRatingChart(container);
  } else if (activeRatingChartType === 'ap') {
    renderAPRatingChart(container);
  }
}

function renderRPNRatingChart(container) {
  const cfg = getAIAGSettings();
  const sev9Cutoff = parseInt(cfg.sev9HighRpn) || 40;
  const highCutoff = parseInt(cfg.sev1to8HighRpn) || 100;
  const medCutoff = parseInt(cfg.sev1to8MedRpn) || 80;

  container.innerHTML = `
    <h4 style="margin-bottom:8px; color:var(--text-primary);">📊 RPN Risk Highlighting Criteria (AIAG Standard / Customized)</h4>
    <p style="margin-bottom:10px; color:var(--text-muted); font-size:12px;">
      In AIAG mode, matrix cells are dynamically highlighted in <strong>Red</strong>, <strong>Yellow</strong>, or <strong>Green</strong> based on Severity (S) and RPN threshold settings below.
    </p>

    <div style="background:var(--bg-card); border:1px solid var(--border-color); border-radius:8px; padding:12px; margin-bottom:14px; color:var(--text-primary);">
      <h5 style="margin:0 0 10px 0; color:var(--text-primary); font-size:13px; display:flex; align-items:center; gap:6px;">
        ⚙️ Customize Highlighting Criteria & Threshold Values
      </h5>
      <div style="display:grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap:12px; margin-bottom:10px;">
        <div>
          <label style="font-size:11px; font-weight:600; color:var(--text-muted); display:block; margin-bottom:4px;">
            Severity 9-10 Red RPN Threshold (&gt;):
          </label>
          <input type="number" id="cfgSev9HighRpn" value="${sev9Cutoff}" min="1" max="1000" style="width:100%; padding:5px 8px; border:1px solid var(--border-color); border-radius:4px; font-size:12px; font-weight:600; background:var(--bg-card); color:var(--text-primary);">
        </div>
        <div>
          <label style="font-size:11px; font-weight:600; color:var(--text-muted); display:block; margin-bottom:4px;">
            Severity 1-8 Red RPN Threshold (&gt;):
          </label>
          <input type="number" id="cfgSev1to8HighRpn" value="${highCutoff}" min="1" max="1000" style="width:100%; padding:5px 8px; border:1px solid var(--border-color); border-radius:4px; font-size:12px; font-weight:600; background:var(--bg-card); color:var(--text-primary);">
        </div>
        <div>
          <label style="font-size:11px; font-weight:600; color:var(--text-muted); display:block; margin-bottom:4px;">
            Severity 1-8 Yellow RPN Threshold (&gt;):
          </label>
          <input type="number" id="cfgSev1to8MedRpn" value="${medCutoff}" min="1" max="1000" style="width:100%; padding:5px 8px; border:1px solid var(--border-color); border-radius:4px; font-size:12px; font-weight:600; background:var(--bg-card); color:var(--text-primary);">
        </div>
      </div>
      <div style="display:flex; justify:flex-end; gap:8px;">
        <button type="button" class="btn btn-sm btn-outline" onclick="resetAIAGRiskThresholds()" style="font-size:11px; padding:4px 10px;">Reset Defaults</button>
        <button type="button" class="btn btn-sm btn-primary" onclick="updateAIAGRiskThresholds()" style="font-size:11px; padding:4px 14px;">Apply & Save Thresholds</button>
      </div>
    </div>

    <div style="display:flex; gap:12px; margin-bottom:12px;">
      <div style="flex:1; padding:10px; background:rgba(239,68,68,0.12); border:1px solid rgba(239,68,68,0.4); border-radius:6px;">
        <strong style="color:#ef4444; font-size:13px;">🔴 High Risk (Red)</strong>
        <p style="font-size:11px; color:var(--text-primary); margin-top:4px;">
          • Severity 9-10 and RPN &gt; ${sev9Cutoff}<br>
          • Severity 1-8 and RPN &gt; ${highCutoff}
        </p>
      </div>
      <div style="flex:1; padding:10px; background:rgba(245,158,11,0.12); border:1px solid rgba(245,158,11,0.4); border-radius:6px;">
        <strong style="color:#f59e0b; font-size:13px;">🟡 Medium Risk (Yellow)</strong>
        <p style="font-size:11px; color:var(--text-primary); margin-top:4px;">
          • Severity 1-8 and RPN ${medCutoff + 1} to ${highCutoff}
        </p>
      </div>
      <div style="flex:1; padding:10px; background:rgba(16,185,129,0.12); border:1px solid rgba(16,185,129,0.4); border-radius:6px;">
        <strong style="color:#10b981; font-size:13px;">🟢 Low Risk (Green)</strong>
        <p style="font-size:11px; color:var(--text-primary); margin-top:4px;">
          • Severity 9-10 and RPN ≤ ${sev9Cutoff}<br>
          • Severity 1-8 and RPN ≤ ${medCutoff}
        </p>
      </div>
    </div>

    <table class="matrix-table" style="width:100%; border-collapse:collapse; border:1px solid var(--border-color); font-size:12px;">
      <thead>
        <tr style="background:var(--table-header-bg); color:var(--table-header-text);">
          <th style="padding:8px; text-align:center; background:var(--table-header-bg); color:var(--table-header-text);">Severity Level</th>
          <th style="padding:8px; text-align:center; background:var(--table-header-bg); color:var(--table-header-text);">RPN Range</th>
          <th style="padding:8px; text-align:center; background:var(--table-header-bg); color:var(--table-header-text);">Highlight Color</th>
          <th style="padding:8px; background:var(--table-header-bg); color:var(--table-header-text);">Risk Category & Action Mandate</th>
        </tr>
      </thead>
      <tbody>
        <tr style="border-bottom:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary);">
          <td style="text-align:center; font-weight:bold; padding:8px; color:var(--text-primary);">Severity 9 - 10</td>
          <td style="text-align:center; font-weight:bold; padding:8px; color:var(--text-primary);">RPN &gt; ${sev9Cutoff}</td>
          <td style="text-align:center; padding:8px;"><span class="badge" style="background:rgba(239,68,68,0.2); color:#ef4444; border:1px solid #ef4444; font-weight:bold; padding:3px 8px;">🔴 Red (High)</span></td>
          <td style="padding:8px; color:var(--text-primary);">Critical Safety/Regulatory Concern. Mandatory engineering action plan required.</td>
        </tr>
        <tr style="border-bottom:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary);">
          <td style="text-align:center; font-weight:bold; padding:8px; color:var(--text-primary);">Severity 9 - 10</td>
          <td style="text-align:center; font-weight:bold; padding:8px; color:var(--text-primary);">RPN ≤ ${sev9Cutoff}</td>
          <td style="text-align:center; padding:8px;"><span class="badge" style="background:rgba(16,185,129,0.2); color:#10b981; border:1px solid #10b981; font-weight:bold; padding:3px 8px;">🟢 Green (Low)</span></td>
          <td style="padding:8px; color:var(--text-primary);">Critical Severity with strong occurrence/detection controls. Monitor & maintain controls.</td>
        </tr>
        <tr style="border-bottom:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary);">
          <td style="text-align:center; font-weight:bold; padding:8px; color:var(--text-primary);">Severity 1 - 8</td>
          <td style="text-align:center; font-weight:bold; padding:8px; color:var(--text-primary);">RPN &gt; ${highCutoff}</td>
          <td style="text-align:center; padding:8px;"><span class="badge" style="background:rgba(239,68,68,0.2); color:#ef4444; border:1px solid #ef4444; font-weight:bold; padding:3px 8px;">🔴 Red (High)</span></td>
          <td style="padding:8px; color:var(--text-primary);">High Risk RPN item. Action plan required to reduce Occurrence or Detection.</td>
        </tr>
        <tr style="border-bottom:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary);">
          <td style="text-align:center; font-weight:bold; padding:8px; color:var(--text-primary);">Severity 1 - 8</td>
          <td style="text-align:center; font-weight:bold; padding:8px; color:var(--text-primary);">RPN ${medCutoff + 1} - ${highCutoff}</td>
          <td style="text-align:center; padding:8px;"><span class="badge" style="background:rgba(245,158,11,0.2); color:#f59e0b; border:1px solid #f59e0b; font-weight:bold; padding:3px 8px;">🟡 Yellow (Medium)</span></td>
          <td style="padding:8px; color:var(--text-primary);">Moderate Risk RPN item. Review design controls and optimize where feasible.</td>
        </tr>
        <tr style="border-bottom:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary);">
          <td style="text-align:center; font-weight:bold; padding:8px; color:var(--text-primary);">Severity 1 - 8</td>
          <td style="text-align:center; font-weight:bold; padding:8px; color:var(--text-primary);">RPN ≤ ${medCutoff}</td>
          <td style="text-align:center; padding:8px;"><span class="badge" style="background:rgba(16,185,129,0.2); color:#10b981; border:1px solid #10b981; font-weight:bold; padding:3px 8px;">🟢 Green (Low)</span></td>
          <td style="padding:8px; color:var(--text-primary);">Acceptable Risk. No immediate action required.</td>
        </tr>
      </tbody>
    </table>
  `;
}

function renderSeverityRatingChart(container) {
  const isVDA = activeRatingChartMode === 'AIAG-VDA';
  const data = isVDA ? [
    { rank: 10, effect: 'Very High', criteria: 'Affects safe operation of vehicle and/or involves non-compliance with government regulations without warning.' },
    { rank: 9, effect: 'Very High', criteria: 'Affects safe operation of vehicle and/or involves non-compliance with government regulations with warning.' },
    { rank: 8, effect: 'High', criteria: 'Loss of primary function (vehicle inoperable, loss of core functionality).' },
    { rank: 7, effect: 'High', criteria: 'Degradation of primary function (vehicle operable, but at reduced level of performance).' },
    { rank: 6, effect: 'Medium', criteria: 'Loss of secondary function (convenience functions unavailable).' },
    { rank: 5, effect: 'Medium', criteria: 'Degradation of secondary function (convenience functions performance reduced).' },
    { rank: 4, effect: 'Low', criteria: 'Appearance/Noise/Haptics/Comfort issue noticed by most customers (>75%).' },
    { rank: 3, effect: 'Low', criteria: 'Appearance/Noise/Haptics/Comfort issue noticed by average customer (50%).' },
    { rank: 2, effect: 'Low', criteria: 'Appearance/Noise/Haptics/Comfort issue noticed by discriminating customer (<25%).' },
    { rank: 1, effect: 'No Effect', criteria: 'No discernable effect on product or process performance.' }
  ] : [
    { rank: 10, effect: 'Hazardous w/o warning', criteria: 'Very high severity rating when a potential failure mode affects safe vehicle operation and/or involves noncompliance with government regulations without warning.' },
    { rank: 9, effect: 'Hazardous w/ warning', criteria: 'Very high severity rating when a potential failure mode affects safe vehicle operation and/or involves noncompliance with government regulations with warning.' },
    { rank: 8, effect: 'Very High', criteria: 'Vehicle/item inoperable (loss of primary function).' },
    { rank: 7, effect: 'High', criteria: 'Vehicle/item operable, but at reduced level of performance. Customer very dissatisfied.' },
    { rank: 6, effect: 'Moderate', criteria: 'Vehicle/item operable, but Comfort/Convenience item(s) inoperable. Customer dissatisfied.' },
    { rank: 5, effect: 'Low', criteria: 'Vehicle/item operable, but Comfort/Convenience item(s) operable at reduced level of performance.' },
    { rank: 4, effect: 'Very Low', criteria: 'Fit & Finish / Squeak & Rattle item does not conform. Item noticed by most customers (>75%).' },
    { rank: 3, effect: 'Minor', criteria: 'Fit & Finish / Squeak & Rattle item does not conform. Item noticed by 50% of customers.' },
    { rank: 2, effect: 'Very Minor', criteria: 'Fit & Finish / Squeak & Rattle item does not conform. Item noticed by discriminating customers (<25%).' },
    { rank: 1, effect: 'None', criteria: 'No discernable effect.' }
  ];

  container.innerHTML = `
    <h4 style="margin-bottom:8px; color:var(--text-primary);">⚠️ Severity (S) Evaluation Criteria - ${isVDA ? 'AIAG-VDA 1st Edition' : 'AIAG 4th Edition'}</h4>
    <table class="matrix-table" style="width:100%; border-collapse:collapse; border:1px solid var(--border-color); font-size:12px;">
      <thead>
        <tr style="background:var(--table-header-bg); color:var(--table-header-text);">
          <th style="width:70px; text-align:center; padding:8px; background:var(--table-header-bg); color:var(--table-header-text);">Rating</th>
          <th style="width:130px; text-align:center; padding:8px; background:var(--table-header-bg); color:var(--table-header-text);">Risk Level</th>
          <th style="width:180px; padding:8px; background:var(--table-header-bg); color:var(--table-header-text);">Impact Level</th>
          <th style="padding:8px; background:var(--table-header-bg); color:var(--table-header-text);">Criteria & Description</th>
        </tr>
      </thead>
      <tbody>
        ${data.map(d => {
    const isHigh = d.rank >= 8;
    const isMed = d.rank >= 5;
    const riskBadge = isHigh
      ? '<span class="badge" style="background:rgba(239,68,68,0.2); color:#ef4444; border:1px solid #ef4444; font-weight:bold; padding:3px 8px;">🔴 High Risk</span>'
      : (isMed
        ? '<span class="badge" style="background:rgba(245,158,11,0.2); color:#f59e0b; border:1px solid #f59e0b; font-weight:bold; padding:3px 8px;">🟡 Medium Risk</span>'
        : '<span class="badge" style="background:rgba(16,185,129,0.2); color:#10b981; border:1px solid #10b981; font-weight:bold; padding:3px 8px;">🟢 Low Risk</span>');
    const rankColor = isHigh ? '#ef4444' : (isMed ? '#f59e0b' : '#10b981');

    return `
            <tr style="border-bottom:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary);">
              <td style="text-align:center; font-weight:bold; padding:8px; font-size:14px; color:${rankColor};">${d.rank}</td>
              <td style="text-align:center; padding:8px;">${riskBadge}</td>
              <td style="padding:8px; font-weight:bold; color:var(--text-primary);">${escapeHtml(d.effect)}</td>
              <td style="padding:8px; color:var(--text-primary);">${escapeHtml(d.criteria)}</td>
            </tr>
          `;
  }).join('')}
      </tbody>
    </table>
  `;
}

function renderOccurrenceRatingChart(container) {
  const isVDA = activeRatingChartMode === 'AIAG-VDA';
  const data = isVDA ? [
    { rank: 10, prob: 'Extremely High', rate: '>= 100 per 1,000', criteria: 'New technology/design without field experience or previous data.' },
    { rank: 9, prob: 'Very High', rate: '50 per 1,000', criteria: 'New application of design with limited field experience.' },
    { rank: 8, prob: 'High', rate: '20 per 1,000', criteria: 'Similar application to previous design with known field issues.' },
    { rank: 7, prob: 'High', rate: '10 per 1,000', criteria: 'Similar application to previous design with minor field issues.' },
    { rank: 6, prob: 'Moderate', rate: '2 per 1,000', criteria: 'Similar application to previous design with no known field issues.' },
    { rank: 5, prob: 'Moderate', rate: '0.5 per 1,000', criteria: 'Proven design with minor modifications for new application.' },
    { rank: 4, prob: 'Moderate', rate: '0.1 per 1,000', criteria: 'Proven design with standard modifications.' },
    { rank: 3, prob: 'Low', rate: '0.01 per 1,000', criteria: 'Proven design with identical application and field usage history.' },
    { rank: 2, prob: 'Very Low', rate: '0.001 per 1,000', criteria: 'Highly proven design with virtually no failure history.' },
    { rank: 1, prob: 'Extremely Low', rate: '< 0.001 per 1,000', criteria: 'Failure is eliminated through physical design prevention controls.' }
  ] : [
    { rank: 10, prob: 'Very High: Persistent', rate: '>= 100 per 1,000 (1 in 10)', criteria: 'Very high likelihood of failure.' },
    { rank: 9, prob: 'Very High: Persistent', rate: '50 per 1,000 (1 in 20)', criteria: 'High likelihood of failure.' },
    { rank: 8, prob: 'High: Frequent', rate: '20 per 1,000 (1 in 50)', criteria: 'Frequent failures expected.' },
    { rank: 7, prob: 'High: Frequent', rate: '10 per 1,000 (1 in 100)', criteria: 'Repeated failures expected.' },
    { rank: 6, prob: 'Moderate: Occasional', rate: '2 per 1,000 (1 in 500)', criteria: 'Moderate failure rate.' },
    { rank: 5, prob: 'Moderate: Occasional', rate: '0.5 per 1,000 (1 in 2,000)', criteria: 'Occasional failures.' },
    { rank: 4, prob: 'Moderate: Occasional', rate: '0.1 per 1,000 (1 in 10,000)', criteria: 'Infrequent failures.' },
    { rank: 3, prob: 'Low: Relatively Few', rate: '0.01 per 1,000 (1 in 100,000)', criteria: 'Few failures expected.' },
    { rank: 2, prob: 'Low: Relatively Few', rate: '0.001 per 1,000 (1 in 1,000,000)', criteria: 'Very few failures expected.' },
    { rank: 1, prob: 'Remote: Unlikely', rate: '< 0.001 per 1,000', criteria: 'Failure is eliminated through preventive design controls.' }
  ];

  container.innerHTML = `
    <h4 style="margin-bottom:8px; color:var(--text-primary);">🔁 Occurrence (O) Evaluation Criteria - ${isVDA ? 'AIAG-VDA 1st Edition' : 'AIAG 4th Edition'}</h4>
    <table class="matrix-table" style="width:100%; border-collapse:collapse; border:1px solid var(--border-color); font-size:12px;">
      <thead>
        <tr style="background:var(--table-header-bg); color:var(--table-header-text);">
          <th style="width:70px; text-align:center; padding:8px; background:var(--table-header-bg); color:var(--table-header-text);">Rating</th>
          <th style="width:130px; text-align:center; padding:8px; background:var(--table-header-bg); color:var(--table-header-text);">Risk Level</th>
          <th style="width:180px; padding:8px; background:var(--table-header-bg); color:var(--table-header-text);">Probability</th>
          <th style="width:170px; padding:8px; background:var(--table-header-bg); color:var(--table-header-text);">Estimated Frequency</th>
          <th style="padding:8px; background:var(--table-header-bg); color:var(--table-header-text);">Criteria & Prevention Standards</th>
        </tr>
      </thead>
      <tbody>
        ${data.map(d => {
    const isHigh = d.rank >= 8;
    const isMed = d.rank >= 5;
    const riskBadge = isHigh
      ? '<span class="badge" style="background:rgba(239,68,68,0.2); color:#ef4444; border:1px solid #ef4444; font-weight:bold; padding:3px 8px;">🔴 High Risk</span>'
      : (isMed
        ? '<span class="badge" style="background:rgba(245,158,11,0.2); color:#f59e0b; border:1px solid #f59e0b; font-weight:bold; padding:3px 8px;">🟡 Medium Risk</span>'
        : '<span class="badge" style="background:rgba(16,185,129,0.2); color:#10b981; border:1px solid #10b981; font-weight:bold; padding:3px 8px;">🟢 Low Risk</span>');
    const rankColor = isHigh ? '#ef4444' : (isMed ? '#f59e0b' : '#10b981');

    return `
            <tr style="border-bottom:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary);">
              <td style="text-align:center; font-weight:bold; padding:8px; font-size:14px; color:${rankColor};">${d.rank}</td>
              <td style="text-align:center; padding:8px;">${riskBadge}</td>
              <td style="padding:8px; font-weight:bold; color:var(--text-primary);">${escapeHtml(d.prob)}</td>
              <td style="padding:8px;"><code style="background:var(--bg-card); padding:2px 6px; border-radius:4px; color:var(--text-primary); font-weight:bold;">${escapeHtml(d.rate)}</code></td>
              <td style="padding:8px; color:var(--text-primary);">${escapeHtml(d.criteria)}</td>
            </tr>
          `;
  }).join('')}
      </tbody>
    </table>
  `;
}

function renderDetectionRatingChart(container) {
  const isVDA = activeRatingChartMode === 'AIAG-VDA';
  const data = isVDA ? [
    { rank: 10, prob: 'Very Low', criteria: 'No detection method established; unproven or non-existent test.' },
    { rank: 9, prob: 'Very Low', criteria: 'Analysis or test method not validated for this application.' },
    { rank: 8, prob: 'Low', criteria: 'Pass/fail testing on system level after design freeze.' },
    { rank: 7, prob: 'Low', criteria: 'Testing to failure on system level after design freeze.' },
    { rank: 6, prob: 'Medium', criteria: 'Pass/fail testing on subsystem level before design freeze.' },
    { rank: 5, prob: 'Medium', criteria: 'Testing to failure on subsystem level before design freeze.' },
    { rank: 4, prob: 'High', criteria: 'Pass/fail testing on component level before design freeze.' },
    { rank: 3, prob: 'High', criteria: 'Testing to failure on component level before design freeze.' },
    { rank: 2, prob: 'Very High', criteria: 'Virtual simulation / CAD CAE analysis validated prior to design freeze.' },
    { rank: 1, prob: 'Very High', criteria: 'Detection method proven to prevent error from occurring due to physical impossibility.' }
  ] : [
    { rank: 10, prob: 'Absolute Uncertainty', criteria: 'Design controls will not or cannot detect potential cause/mechanism and failure mode.' },
    { rank: 9, prob: 'Very Remote', criteria: 'Very remote chance design controls will detect potential cause/mechanism and failure mode.' },
    { rank: 8, prob: 'Remote', criteria: 'Remote chance design controls will detect potential cause/mechanism and failure mode.' },
    { rank: 7, prob: 'Very Low', criteria: 'Very low chance design controls will detect potential cause/mechanism and failure mode.' },
    { rank: 6, prob: 'Low', criteria: 'Low chance design controls will detect potential cause/mechanism and failure mode.' },
    { rank: 5, prob: 'Moderate', criteria: 'Moderate chance design controls will detect potential cause/mechanism and failure mode.' },
    { rank: 4, prob: 'Moderately High', criteria: 'Moderately high chance design controls will detect potential cause/mechanism and failure mode.' },
    { rank: 3, prob: 'High', criteria: 'High chance design controls will detect potential cause/mechanism and failure mode.' },
    { rank: 2, prob: 'Very High', criteria: 'Very high chance design controls will detect potential cause/mechanism and failure mode.' },
    { rank: 1, prob: 'Almost Certain', criteria: 'Design controls will almost certainly detect potential cause/mechanism and failure mode.' }
  ];

  container.innerHTML = `
    <h4 style="margin-bottom:8px; color:var(--text-primary);">🔍 Detection (D) Evaluation Criteria - ${isVDA ? 'AIAG-VDA 1st Edition' : 'AIAG 4th Edition'}</h4>
    <table class="matrix-table" style="width:100%; border-collapse:collapse; border:1px solid var(--border-color); font-size:12px;">
      <thead>
        <tr style="background:var(--table-header-bg); color:var(--table-header-text);">
          <th style="width:70px; text-align:center; padding:8px; background:var(--table-header-bg); color:var(--table-header-text);">Rating</th>
          <th style="width:130px; text-align:center; padding:8px; background:var(--table-header-bg); color:var(--table-header-text);">Risk Level</th>
          <th style="width:180px; padding:8px; background:var(--table-header-bg); color:var(--table-header-text);">Detection Capability</th>
          <th style="padding:8px; background:var(--table-header-bg); color:var(--table-header-text);">Verification & Testing Criteria</th>
        </tr>
      </thead>
      <tbody>
        ${data.map(d => {
    const isHigh = d.rank >= 8;
    const isMed = d.rank >= 5;
    const riskBadge = isHigh
      ? '<span class="badge" style="background:rgba(239,68,68,0.2); color:#ef4444; border:1px solid #ef4444; font-weight:bold; padding:3px 8px;">🔴 High Risk</span>'
      : (isMed
        ? '<span class="badge" style="background:rgba(245,158,11,0.2); color:#f59e0b; border:1px solid #f59e0b; font-weight:bold; padding:3px 8px;">🟡 Medium Risk</span>'
        : '<span class="badge" style="background:rgba(16,185,129,0.2); color:#10b981; border:1px solid #10b981; font-weight:bold; padding:3px 8px;">🟢 Low Risk</span>');
    const rankColor = isHigh ? '#ef4444' : (isMed ? '#f59e0b' : '#10b981');

    return `
            <tr style="border-bottom:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary);">
              <td style="text-align:center; font-weight:bold; padding:8px; font-size:14px; color:${rankColor};">${d.rank}</td>
              <td style="text-align:center; padding:8px;">${riskBadge}</td>
              <td style="padding:8px; font-weight:bold; color:var(--text-primary);">${escapeHtml(d.prob)}</td>
              <td style="padding:8px; color:var(--text-primary);">${escapeHtml(d.criteria)}</td>
            </tr>
          `;
  }).join('')}
      </tbody>
    </table>
  `;
}

