function openFunctionalMatrixModal() {
  renderFunctionalMatrix();
  openModal('functionalMatrixModal');
}

function openSystemFilterModal() {
  const container = document.getElementById('systemFilterCheckboxList');
  const structNodes = getAllStructureNodesFlat(fmeaData.structure);

  if (selectedSystemFilterIds === null) {
    selectedSystemFilterIds = structNodes.map(s => s.id);
  }

  container.innerHTML = structNodes.map(s => `
    <div class="checkbox-card" style="padding: 6px 10px;">
      <label>
        <input type="checkbox" name="sysFilterChk" value="${s.id}" ${selectedSystemFilterIds.includes(s.id) ? 'checked' : ''}>
        <strong>${escapeHtml(s.partNo)}</strong> - ${escapeHtml(s.name)}
      </label>
    </div>
  `).join('');

  openModal('systemFilterModal');
}

function selectAllSystemsFilter(selectState) {
  const checkboxes = document.querySelectorAll('input[name="sysFilterChk"]');
  if (selectState === 'non-checked' || selectState === 'unchecked') {
    checkboxes.forEach(chk => chk.checked = !chk.checked);
  } else if (selectState === 'checked') {
    // Keep currently checked
  } else {
    const isChecked = selectState === true || selectState === 'all';
    checkboxes.forEach(chk => chk.checked = isChecked);
  }
}

function applySystemFilterSelection() {
  const selected = Array.from(document.querySelectorAll('input[name="sysFilterChk"]:checked')).map(el => el.value);
  selectedSystemFilterIds = selected;

  const countLabel = document.getElementById('selectedSysCount');
  if (countLabel) {
    const total = getAllStructureNodesFlat(fmeaData.structure).length;
    countLabel.innerText = selected.length === total ? 'All' : `${selected.length} / ${total}`;
  }

  closeModal('systemFilterModal');
  renderFunctionalMatrix();
}

function getAllStructureNodesFlat(node, result = []) {
  if (!node) return result;
  if (Array.isArray(node)) {
    node.forEach(item => getAllStructureNodesFlat(item, result));
    return result;
  }
  result.push(node);
  if (node.children && Array.isArray(node.children)) {
    node.children.forEach(child => getAllStructureNodesFlat(child, result));
  }
  return result;
}

function getFlatStructureNodes(node) {
  return getAllStructureNodesFlat(node);
}

function renderFunctionalMatrix() {
  const table = document.getElementById('functionalMatrixTable');
  if (!table) return;

  const ctx = getActiveFmeaData();
  const activeOnly = document.getElementById('matrixFilterActiveOnly') ? document.getElementById('matrixFilterActiveOnly').checked : true;
  const hideRoot = document.getElementById('matrixFilterSystemOnly') ? document.getElementById('matrixFilterSystemOnly').checked : false;

  let structNodes = [];
  if (ctx.isPFMEA) {
    structNodes = (ctx.processSteps || []).map(ps => ({ id: ps.id, partNo: ps.stepNo, name: ps.name }));
  } else {
    structNodes = getAllStructureNodesFlat(fmeaData.structure);
    if (hideRoot && structNodes.length > 0) {
      structNodes = structNodes.filter(s => s.id !== 'struct-root');
    }
  }

  // Filter functions
  let funcs = ctx.functions || [];
  if (selectedSystemFilterIds !== null) {
    funcs = funcs.filter(f => selectedSystemFilterIds.includes(f.structId));
  }

  if (activeOnly) {
    funcs = funcs.filter(f => f.isConsidered !== false);
  }

  let headerHtml = `
    <thead>
      <tr>
        <th style="position:sticky; left:0; top:0; z-index:25; background:var(--table-header-bg); color:var(--table-header-text); min-width:220px; border:1px solid var(--table-border);">
          ${ctx.isPFMEA ? 'Process Step (Y-Axis)' : 'Structure Element (Y-Axis)'}
        </th>`;

  funcs.forEach(f => {
    let systemName = 'Unassigned';
    if (ctx.isPFMEA) {
      const ps = (ctx.processSteps || []).find(p => p.id === f.structId);
      systemName = ps ? `${ps.stepNo} - ${ps.name}` : 'Unassigned Step';
    } else {
      const allNodes = getAllStructureNodesFlat(fmeaData.structure);
      const parentNode = allNodes.find(s => s.id === f.structId);
      systemName = parentNode ? `${parentNode.partNo} - ${parentNode.name}` : 'Unassigned System';
    }
    headerHtml += `
      <th style="position:sticky; top:0; z-index:20; background:var(--table-header-bg); color:var(--table-header-text); min-width:180px; text-align:center; border:1px solid var(--table-border);">
        <div>${escapeHtml(f.name)}</div>
        <div style="font-size:10px; font-weight:normal; opacity:0.85; margin-top:2px;">[Defined in: ${escapeHtml(systemName)}]</div>
      </th>`;
  });

  headerHtml += `</tr></thead>`;

  let bodyHtml = `<tbody>`;

  structNodes.forEach(node => {
    bodyHtml += `
      <tr>
        <td style="position:sticky; left:0; background:var(--table-header-bg); color:var(--table-header-text); z-index:15; font-weight:bold; border-right:2px solid var(--table-border);">
          ${escapeHtml(node.partNo)} - ${escapeHtml(node.name)}
        </td>`;

    funcs.forEach(f => {
      const isDirect = f.structId === node.id;
      const isLinkedLine = (ctx.functionLines || []).some(fl => fl.structId === node.id && fl.funcId === f.id);

      if (isDirect) {
        bodyHtml += `<td style="text-align:center; background:#dcfce7; color:#15803d; font-weight:bold;" title="Defined in this element">✓ [Defined]</td>`;
      } else if (isLinkedLine) {
        bodyHtml += `<td style="text-align:center; background:#e0f2fe; color:#0369a1;" title="Inherited/Linked in FMEA">🔗 [Linked]</td>`;
      } else {
        bodyHtml += `<td style="text-align:center; color:#94a3b8;">-</td>`;
      }
    });

    bodyHtml += `</tr>`;
  });

  bodyHtml += `</tbody>`;

  table.innerHTML = headerHtml + bodyHtml;
}

// ----------------------------------------------------
// 22. AIAG-VDA Header Specification & Export Feature
// ----------------------------------------------------
let currentHeaderTargetScopeId = 'DFMEA';

function openAiagVdaHeaderModal() {
  const hasActiveFile = typeof hasValidActiveProject === 'function' ? hasValidActiveProject() : !!activeSharePointFileName;
  const rev = typeof getContextRevision === 'function' ? getContextRevision() : null;
  const hasInProgressRev = hasActiveFile && rev && (rev.status === 'In Progress' || rev.status === 'Draft');

  if (!hasActiveFile || !hasInProgressRev) {
    if (typeof showToast === 'function') {
      showToast("Form Header is disabled: An FMEA file must be open with an active in-progress revision.", "warning");
    } else {
      alert("Form Header is disabled: An FMEA file must be open with an active in-progress revision.");
    }
    return;
  }
  const select = document.getElementById('hdr_scopeSelector');
  if (select) {
    let optionsHtml = `<option value="DFMEA">🚗 DFMEA Header (Design Master)</option>`;
    if (fmeaData.pfmeas && fmeaData.pfmeas.length > 0) {
      fmeaData.pfmeas.forEach(p => {
        optionsHtml += `<option value="PFMEA_${p.id}">🏭 PFMEA Header: ${escapeHtml(p.name || 'Process FMEA')}</option>`;
      });
    }
    select.innerHTML = optionsHtml;

    // Select active scope by default
    const activeCtx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : null;
    if (activeCtx && activeCtx.isPFMEA && activeCtx.pfmea) {
      currentHeaderTargetScopeId = `PFMEA_${activeCtx.pfmea.id}`;
      select.value = currentHeaderTargetScopeId;
    } else {
      currentHeaderTargetScopeId = 'DFMEA';
      select.value = 'DFMEA';
    }
  }

  switchAiagVdaHeaderScope();
  openModal('aiagVdaHeaderModal');
}

function getHeaderTargetObj(scopeId) {
  if (scopeId && scopeId.startsWith('PFMEA_')) {
    const pfmeaId = scopeId.replace('PFMEA_', '');
    const pfmea = (fmeaData.pfmeas || []).find(p => String(p.id) === String(pfmeaId));
    if (pfmea) {
      pfmea.headerInfo = pfmea.headerInfo || {};
      return pfmea.headerInfo;
    }
  }
  fmeaData.headerInfo = fmeaData.headerInfo || {};
  return fmeaData.headerInfo;
}

function switchAiagVdaHeaderScope() {
  const select = document.getElementById('hdr_scopeSelector');
  const scopeId = select ? select.value : 'DFMEA';
  currentHeaderTargetScopeId = scopeId;

  const h = getHeaderTargetObj(scopeId);
  const curRev = typeof getContextRevision === 'function' ? getContextRevision() : null;
  const revList = typeof getContextRevisionList === 'function' ? getContextRevisionList() : [];

  // First revision creation date (FMEA Start Date)
  const firstRev = (revList && revList.length > 0) ? revList[0] : (curRev || null);
  const firstDateRaw = firstRev ? (firstRev.createdDate || firstRev.freezeDate || firstRev.date) : null;
  h.startDate = firstDateRaw ? firstDateRaw.slice(0, 10) : (h.startDate || new Date().toISOString().slice(0, 10));

  // Currently open FMEA revision date (FMEA Revision Date)
  const openDateRaw = curRev ? (curRev.freezeDate || curRev.createdDate || curRev.date) : null;
  h.revDate = openDateRaw ? openDateRaw.slice(0, 10) : (h.revDate || new Date().toISOString().slice(0, 10));

  if (curRev) {
    h.fmeaDocNo = h.fmeaDocNo || `${curRev.fmeaType || 'FMEA'}-${curRev.revNumber || '1.0'}`;
    h.revNumber = curRev.revNumber;
  }

  document.getElementById('hdr_companyName').value = h.companyName || '';
  document.getElementById('hdr_engLocation').value = h.engLocation || '';
  document.getElementById('hdr_customerName').value = h.customerName || '';
  document.getElementById('hdr_modelYear').value = h.modelYear || '';
  document.getElementById('hdr_subjectSystem').value = h.subjectSystem || (fmeaData.structure ? fmeaData.structure.name : '');
  document.getElementById('hdr_fmeaDocNo').value = h.fmeaDocNo || '';
  document.getElementById('hdr_designResp').value = h.designResp || '';
  document.getElementById('hdr_keyLead').value = h.keyLead || (curRev ? curRev.creator : (currentUser ? currentUser.name : ''));
  document.getElementById('hdr_crossTeam').value = h.crossTeam || '';
  
  const startEl = document.getElementById('hdr_startDate');
  if (startEl) {
    startEl.value = h.startDate;
    startEl.readOnly = true;
  }
  
  const revDateEl = document.getElementById('hdr_revDate');
  if (revDateEl) {
    revDateEl.value = h.revDate;
    revDateEl.readOnly = true;
  }
  
  document.getElementById('hdr_confidentiality').value = h.confidentiality || 'Internal Confidential';

  const revInfoBadge = document.getElementById('hdr_revInfoNotice');
  if (revInfoBadge) {
    const isPf = scopeId.startsWith('PFMEA_');
    if (curRev) {
      revInfoBadge.innerHTML = `ℹ️ Synced header for <strong>${isPf ? 'PFMEA Scope' : 'DFMEA Scope'}</strong>: Revision <strong>${escapeHtml(curRev.revNumber)}</strong> (${escapeHtml(curRev.status)})`;
    } else {
      revInfoBadge.innerHTML = `ℹ️ Configuring custom header settings for: <strong>${isPf ? 'PFMEA Scope' : 'DFMEA Scope'}</strong>`;
    }
  }
}

function saveAiagVdaHeaderInfo(e) {
  e.preventDefault();
  const select = document.getElementById('hdr_scopeSelector');
  const scopeId = select ? select.value : currentHeaderTargetScopeId;

  const h = getHeaderTargetObj(scopeId);
  h.companyName = document.getElementById('hdr_companyName').value.trim();
  h.engLocation = document.getElementById('hdr_engLocation').value.trim();
  h.customerName = document.getElementById('hdr_customerName').value.trim();
  h.modelYear = document.getElementById('hdr_modelYear').value.trim();
  h.subjectSystem = document.getElementById('hdr_subjectSystem').value.trim();
  h.fmeaDocNo = document.getElementById('hdr_fmeaDocNo').value.trim();
  h.designResp = document.getElementById('hdr_designResp').value.trim();
  h.keyLead = document.getElementById('hdr_keyLead').value.trim();
  h.crossTeam = document.getElementById('hdr_crossTeam').value.trim();
  h.startDate = document.getElementById('hdr_startDate').value;
  h.revDate = document.getElementById('hdr_revDate').value;
  h.confidentiality = document.getElementById('hdr_confidentiality').value.trim();

  if (scopeId === 'DFMEA') {
    fmeaData.headerInfo = Object.assign({}, h);
  }

  closeModal('aiagVdaHeaderModal');
  showToast(`Header Info saved for ${scopeId.startsWith('PFMEA_') ? 'PFMEA' : 'DFMEA'}.`);
  renderExportHeaderSummary();
}

function renderExportHeaderSummary() {
  const summaryEl = document.getElementById('exportHeaderSummary');
  if (!summaryEl) return;
  const ctx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : { isPFMEA: false };
  let h = {};
  if (ctx && ctx.headerInfo && Object.keys(ctx.headerInfo).length > 0) {
    h = ctx.headerInfo;
  } else if (ctx && ctx.pfmea && ctx.pfmea.headerInfo && Object.keys(ctx.pfmea.headerInfo).length > 0) {
    h = ctx.pfmea.headerInfo;
  } else {
    h = fmeaData.headerInfo || {};
  }
  const curRev = typeof getContextRevision === 'function' ? getContextRevision() : null;
  const typeLabel = ctx.isPFMEA ? `PFMEA: ${ctx.pfmea?.name || 'Process FMEA'}` : 'DFMEA (Design Master)';

  summaryEl.innerHTML = `
    <strong>Scope Type:</strong> ${typeLabel} | <strong>Revision:</strong> ${curRev ? curRev.revNumber : 'Rev 1.0'}<br>
    <strong>Company / Location:</strong> ${escapeHtml(h.companyName || 'Not Set')} (${escapeHtml(h.engLocation || '-')}) | <strong>Doc No:</strong> ${escapeHtml(h.fmeaDocNo || 'N/A')}<br>
    <strong>Customer / Model:</strong> ${escapeHtml(h.customerName || '-')} / ${escapeHtml(h.modelYear || '-')} | <strong>Key Lead:</strong> ${escapeHtml(h.keyLead || '-')}<br>
    <strong>Start Date / Rev Date:</strong> ${h.startDate || '-'} / ${h.revDate || '-'} | <strong>Confidentiality:</strong> ${escapeHtml(h.confidentiality || 'Internal Confidential')}
  `;
}

function openExportModal() {
  if (typeof checkCanExport === 'function' && !checkCanExport()) {
    return;
  }

  const container = document.getElementById('exportNodeTree');
  let html = '';
  function buildExportTreeHTML(node) {
    if (!node) return;
    html += `
      <label class="checkbox-label" style="margin-left: 10px; display:block; font-size:12px;">
        <input type="checkbox" name="exportNodeChk" value="${node.id}" checked>
        ${escapeHtml(node.partNo || '')} - ${escapeHtml(node.name || '')}
      </label>
    `;
    if (node.children) node.children.forEach(c => buildExportTreeHTML(c));
  }
  buildExportTreeHTML(fmeaData.structure);
  if (container) container.innerHTML = html || '<span class="text-muted">No structure nodes available</span>';

  // Default export to Entire Project (DFMEA + All PFMEAs) if PFMEAs exist
  const scopeContainer = document.getElementById('exportScopeMultiSelectContainer');
  if (scopeContainer && (!scopeContainer.dataset.selectedValues || scopeContainer.dataset.selectedValues === '["ACTIVE"]')) {
    if (fmeaData.pfmeas && fmeaData.pfmeas.length > 0) {
      scopeContainer.dataset.selectedValues = JSON.stringify(['ALL']);
    }
  }

  populateFmeaScopeCheckboxDropdown('exportScopeMultiSelectContainer', 'renderExportHeaderSummary');

  const varSelect = document.getElementById('exportVariantSelect');
  if (varSelect) {
    let opts = '<option value="ALL">All Variants</option>';
    (fmeaData.variants || []).forEach(v => {
      const selectedAttr = (typeof selectedVariantFilter !== 'undefined' && selectedVariantFilter === v.id) ? 'selected' : '';
      opts += `<option value="${escapeHtml(v.id)}" ${selectedAttr}>${escapeHtml(v.name || v.id)}</option>`;
    });
    varSelect.innerHTML = opts;
  }

  renderExportHeaderSummary();
  openModal('exportModal');
}

function executeExport() {
  if (typeof checkCanExport === 'function' && !checkCanExport()) {
    return;
  }

  const checkedNodes = Array.from(document.querySelectorAll('input[name="exportNodeChk"]:checked')).map(el => el.value);
  const formatEl = document.querySelector('input[name="exportFormat"]:checked');
  const format = formatEl ? formatEl.value : 'pdf';
  const selectedScopeVals = getSelectedScopeValues('exportScopeMultiSelectContainer');
  const targetScopes = resolveSelectedScopes(selectedScopeVals);

  const varSelect = document.getElementById('exportVariantSelect');
  const targetVariant = varSelect ? varSelect.value : (typeof selectedVariantFilter !== 'undefined' ? selectedVariantFilter : 'ALL');

  if (checkedNodes.length === 0) {
    alert("Please select at least one structure element to export.");
    return;
  }

  if (format === 'excel') {
    exportToExcel(checkedNodes, targetScopes, targetVariant);
  } else {
    exportToPDF(checkedNodes, targetScopes, targetVariant);
  }
  closeModal('exportModal');
}

function getAiagVdaHeaderHTML(overrideScope, hideTitleBar = false) {
  const ctx = overrideScope || (typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : { isPFMEA: false });

  let h = {};
  if (ctx && ctx.headerInfo && Object.keys(ctx.headerInfo).length > 0) {
    h = ctx.headerInfo;
  } else if (ctx && ctx.pfmea && ctx.pfmea.headerInfo && Object.keys(ctx.pfmea.headerInfo).length > 0) {
    h = ctx.pfmea.headerInfo;
  } else {
    h = fmeaData.headerInfo || fmeaData.header || {};
  }

  const curRev = typeof getContextRevision === 'function' ? getContextRevision() : (fmeaData.currentRevision || null);
  const isPFMEA = ctx.isPFMEA || (ctx.pfmea ? true : false);
  const fmeaTitle = isPFMEA
    ? `Process Failure Mode and Effect Analysis (PROCESS-FMEA)`
    : `Design Failure Mode and Effect Analysis (DESIGN-FMEA)`;

  const revNum = (curRev && (curRev.revNumber || curRev.number || curRev.revNo)) || h.revNumber || h.revNo || '1.0';
  const rawStartDate = (curRev && (curRev.createdDate || curRev.startDate || curRev.createdAt || curRev.date)) || h.startDate || h.createdDate || new Date().toISOString().slice(0, 10);
  const rawRevDate = (curRev && (curRev.freezeDate || curRev.revDate || curRev.updatedAt || curRev.createdDate)) || h.revDate || h.startDate || new Date().toISOString().slice(0, 10);

  const startDate = String(rawStartDate).slice(0, 10);
  const revDate = String(rawRevDate).slice(0, 10);
  const scopeSubject = h.subjectSystem || ctx.name || (ctx.pfmea ? ctx.pfmea.name : '') || fmeaData.projectName || '';

  return `
    <div style="border: 2px solid #0f172a; margin-bottom: 12px; font-family: Arial, sans-serif; font-size: 10px; background: #ffffff;">
      ${hideTitleBar ? '' : `
      <div style="background: #0f172a; color: #ffffff; display:flex; align-items:center; justify-content:space-between; padding: 6px 12px;">
        <img src="Logo_Jost.svg.webp" alt="JOST World" style="height:26px; width:auto; object-fit:contain;" onerror="this.style.display='none'">
        <div style="flex:1; text-align:center; font-weight:bold; font-size:13px; letter-spacing:0.5px; text-transform:uppercase;">
          AIAG-VDA ${fmeaTitle}
        </div>
        <div style="text-align:right; font-size:9px; color:#94a3b8; white-space:nowrap;">JOST World<br>FMEA Workbench</div>
      </div>
      `}
      <table style="width: 100%; border-collapse: collapse; border: none; font-size: 10px;">
        <tr style="background:#f8fafc;">
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px; width: 25%;"><strong>Company Name:</strong> ${escapeHtml(h.companyName || '')}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px; width: 25%;"><strong>Subject:</strong> ${escapeHtml(scopeSubject)}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px; width: 25%;"><strong>FMEA ID Number:</strong> ${escapeHtml(h.fmeaDocNo || '')}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px; width: 25%;"><strong>Confidentiality Level:</strong> ${escapeHtml(h.confidentiality || 'Internal')}</td>
        </tr>
        <tr>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>Engineering Location:</strong> ${escapeHtml(h.engLocation || '')}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>FMEA Start Date:</strong> ${escapeHtml(startDate)}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>Design / Process Responsibility:</strong> ${escapeHtml(h.designResp || '')}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>FMEA Revision Date:</strong> ${escapeHtml(revDate)} (Rev ${escapeHtml(revNum)})</td>
        </tr>
        <tr style="background:#f8fafc;">
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>Customer Name:</strong> ${escapeHtml(h.customerName || h.projectName || fmeaData.projectName || '')} ${h.modelYear ? '(' + escapeHtml(h.modelYear) + ')' : ''}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px;" colspan="2"><strong>Cross-Functional Team:</strong> ${escapeHtml(h.crossTeam || '')}</td>
          <td style="border: 1px solid #cbd5e1; padding: 4px 8px;"><strong>Key Lead / Facilitator:</strong> ${escapeHtml(h.keyLead || '')}</td>
        </tr>
      </table>
    </div>
  `;
}

