function switchDashboardMode(mode) {
  activeDashboardMode = mode;
  renderInsightsDashboard();
}

function computeAP(s, o, d) {
  s = parseInt(s) || 1;
  o = parseInt(o) || 1;
  d = parseInt(d) || 1;

  if (s === 1) return 'L';

  if (s >= 2 && s <= 3) {
    if (d >= 5 && o >= 8) return 'M';
    return 'L';
  }

  if (s >= 4 && s <= 6) {
    if (d === 1) return 'L';
    if (d >= 2 && d <= 4) {
      if (o >= 6) return 'M';
      return 'L';
    }
    if (d >= 5 && d <= 6) {
      if (o >= 8) return 'H';
      if (o >= 6) return 'M';
      return 'L';
    }
    if (d >= 7) {
      if (o >= 8) return 'H';
      if (o >= 4) return 'M';
      return 'L';
    }
    return 'L';
  }

  if (s >= 7 && s <= 8) {
    if (d === 1) return 'L';
    if (d >= 2 && d <= 4) {
      if (o >= 8) return 'H';
      if (o >= 4) return 'M';
      return 'L';
    }
    if (d >= 5 && d <= 6) {
      if (o >= 6) return 'H';
      if (o >= 2) return 'M';
      return 'L';
    }
    if (d >= 7) {
      if (o >= 4) return 'H';
      if (o >= 2) return 'M';
      return 'L';
    }
    return 'L';
  }

  if (s >= 9) {
    if (d === 1) {
      if (o >= 6) return 'H';
      if (o >= 4) return 'M';
      return 'L';
    }
    if (d >= 2 && d <= 4) {
      if (o >= 4) return 'H';
      return 'L';
    }
    if (d >= 5 && d <= 6) {
      if (o >= 4) return 'H';
      if (o >= 2) return 'M';
      return 'L';
    }
    if (d >= 7) {
      if (o >= 2) return 'H';
      return 'L';
    }
    return 'L';
  }

  return 'L';
}

function getRpnBinIndex(rpn) {
  if (rpn <= 100) return 0;
  if (rpn <= 200) return 1;
  if (rpn <= 300) return 2;
  if (rpn <= 400) return 3;
  if (rpn <= 500) return 4;
  if (rpn <= 600) return 5;
  if (rpn <= 700) return 6;
  if (rpn <= 800) return 7;
  if (rpn <= 900) return 8;
  return 9;
}

function getApMatrixIndices(s, d, o) {
  let sIdx = 0;
  if (s === 1) sIdx = 0;
  else if (s <= 3) sIdx = 1;
  else if (s <= 6) sIdx = 2;
  else if (s <= 8) sIdx = 3;
  else sIdx = 4;

  let dIdx = 0;
  if (d === 1) dIdx = 0;
  else if (d <= 4) dIdx = 1;
  else if (d <= 6) dIdx = 2;
  else dIdx = 3;

  let oIdx = 0;
  if (o === 1) oIdx = 0;
  else if (o <= 3) oIdx = 1;
  else if (o <= 5) oIdx = 2;
  else if (o <= 7) oIdx = 3;
  else oIdx = 4;

  return { sIdx, dIdx, oIdx };
}

function generateApMatrixHtml(gridData, title, badgeText, badgeBg) {
  const apMatrixConfig = [
    {
      sLabel: '1', rowSpan: 4, dRows: [
        { dLabel: '1', apList: ['L', 'L', 'L', 'L', 'L'], dIdx: 0 },
        { dLabel: '2-4', apList: ['L', 'L', 'L', 'L', 'L'], dIdx: 1 },
        { dLabel: '5-6', apList: ['L', 'L', 'L', 'L', 'L'], dIdx: 2 },
        { dLabel: '7-10', apList: ['L', 'L', 'L', 'L', 'L'], dIdx: 3 }
      ]
    },
    {
      sLabel: '2-3', rowSpan: 4, dRows: [
        { dLabel: '1', apList: ['L', 'L', 'L', 'L', 'L'], dIdx: 0 },
        { dLabel: '2-4', apList: ['L', 'L', 'L', 'L', 'L'], dIdx: 1 },
        { dLabel: '5-6', apList: ['L', 'L', 'L', 'L', 'M'], dIdx: 2 },
        { dLabel: '7-10', apList: ['L', 'L', 'L', 'L', 'M'], dIdx: 3 }
      ]
    },
    {
      sLabel: '4-6', rowSpan: 4, dRows: [
        { dLabel: '1', apList: ['L', 'L', 'L', 'L', 'L'], dIdx: 0 },
        { dLabel: '2-4', apList: ['L', 'L', 'L', 'M', 'M'], dIdx: 1 },
        { dLabel: '5-6', apList: ['L', 'L', 'L', 'M', 'H'], dIdx: 2 },
        { dLabel: '7-10', apList: ['L', 'L', 'M', 'M', 'H'], dIdx: 3 }
      ]
    },
    {
      sLabel: '7-8', rowSpan: 4, dRows: [
        { dLabel: '1', apList: ['L', 'L', 'L', 'L', 'L'], dIdx: 0 },
        { dLabel: '2-4', apList: ['L', 'L', 'M', 'H', 'H'], dIdx: 1 },
        { dLabel: '5-6', apList: ['L', 'M', 'M', 'H', 'H'], dIdx: 2 },
        { dLabel: '7-10', apList: ['L', 'M', 'H', 'H', 'H'], dIdx: 3 }
      ]
    },
    {
      sLabel: '9-10', rowSpan: 4, dRows: [
        { dLabel: '1', apList: ['L', 'L', 'M', 'H', 'H'], dIdx: 0 },
        { dLabel: '2-4', apList: ['L', 'L', 'H', 'H', 'H'], dIdx: 1 },
        { dLabel: '5-6', apList: ['L', 'M', 'H', 'H', 'H'], dIdx: 2 },
        { dLabel: '7-10', apList: ['L', 'H', 'H', 'H', 'H'], dIdx: 3 }
      ]
    }
  ];

  let html = `
    <div style="background:var(--bg-card); border:1px solid var(--border-color); border-radius:8px; padding:12px; color:var(--text-primary); flex:1; min-width:0;">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;">
        <h4 style="font-size:12px; margin:0; color:#38bdf8; font-weight:bold;">${title}</h4>
        <span class="badge" style="background:${badgeBg}; color:#ffffff; font-size:10px; padding:2px 6px; border-radius:4px;">${badgeText}</span>
      </div>

      <div style="overflow-x:auto;">
        <table style="width:100%; border-collapse:collapse; text-align:center; font-size:10px;">
          <thead>
            <tr>
              <th rowspan="2" style="background:var(--table-header-bg); border:1px solid var(--border-color); width:35px; padding:4px; color:var(--table-header-text);">S</th>
              <th rowspan="2" style="background:var(--table-header-bg); border:1px solid var(--border-color); width:40px; padding:4px; color:var(--table-header-text);">D</th>
              <th colspan="5" style="background:var(--table-header-bg); border:1px solid var(--border-color); padding:4px; color:var(--table-header-text); font-size:11px;">O (Occurrence)</th>
            </tr>
            <tr>
              <th style="background:var(--table-header-bg); border:1px solid var(--border-color); width:18%; padding:3px; color:var(--table-header-text);">1</th>
              <th style="background:var(--table-header-bg); border:1px solid var(--border-color); width:18%; padding:3px; color:var(--table-header-text);">2-3</th>
              <th style="background:var(--table-header-bg); border:1px solid var(--border-color); width:18%; padding:3px; color:var(--table-header-text);">4-5</th>
              <th style="background:var(--table-header-bg); border:1px solid var(--border-color); width:18%; padding:3px; color:var(--table-header-text);">6-7</th>
              <th style="background:var(--table-header-bg); border:1px solid var(--border-color); width:18%; padding:3px; color:var(--table-header-text);">8-10</th>
            </tr>
          </thead>
          <tbody>
  `;

  apMatrixConfig.forEach((sGroup, sIdx) => {
    sGroup.dRows.forEach((dRow, dSubIdx) => {
      html += `<tr>`;
      if (dSubIdx === 0) {
        html += `<td rowspan="${sGroup.rowSpan}" style="background:var(--bg-card); border:1px solid var(--border-color); font-weight:bold; color:#38bdf8; font-size:11px;">S ${sGroup.sLabel}</td>`;
      }
      html += `<td style="background:var(--bg-card); border:1px solid var(--border-color); color:var(--text-muted); font-weight:bold;">${dRow.dLabel}</td>`;

      dRow.apList.forEach((apVal, oIdx) => {
        const bg = apVal === 'H' ? '#ef4444' : (apVal === 'M' ? '#f59e0b' : '#10b981');
        const count = gridData[sIdx][dRow.dIdx][oIdx];

        let cellContent = '';
        if (count > 0) {
          cellContent = `<span style="background:rgba(15,23,42,0.95); color:#ffffff; border-radius:3px; padding:1px 4px; font-weight:bold; font-size:10px; border:1px solid #ffffff;">${count}</span>`;
        }

        html += `
          <td style="background:${bg}; border:1px solid var(--border-color); padding:3px 2px; height:24px; vertical-align:middle;" title="S:${sGroup.sLabel} D:${dRow.dLabel} O-bin:${oIdx + 1} | AP=${apVal} | Count: ${count}">
            ${cellContent}
          </td>
        `;
      });

      html += `</tr>`;
    });
  });

  html += `
          </tbody>
        </table>
      </div>
    </div>
  `;

  return html;
}

function toggleDashPrintMenu(e) {
  if (e) e.stopPropagation();
  const m = document.getElementById('dashPrintSecMenu');
  if (m) m.style.display = m.style.display === 'none' ? 'block' : 'none';
}

document.addEventListener('click', function (e) {
  const m = document.getElementById('dashPrintSecMenu');
  if (m && !e.target.closest('#dashPrintSecMenu') && !e.target.closest('button[onclick*="toggleDashPrintMenu"]')) {
    m.style.display = 'none';
  }
});

function printDashboardA4Report() {
  const secMap = {
    'dashSecKpi': document.getElementById('chkPrintKpi')?.checked ?? true,
    'dashSecRiskSummary': document.getElementById('chkPrintRiskSummary')?.checked ?? true,
    'dashSecMethodology': document.getElementById('chkPrintMethodology')?.checked ?? true,
    'dashSecComparisonBar': document.getElementById('chkPrintComparison')?.checked ?? true,
    'dashSecTopRisks': document.getElementById('chkPrintTopRisks')?.checked ?? true,
    'dashSecActionSummary': document.getElementById('chkPrintActionSummary')?.checked ?? true
  };

  Object.keys(secMap).forEach(secId => {
    const el = document.getElementById(secId);
    if (el) {
      if (!secMap[secId]) {
        el.classList.add('hide-on-print');
        el.style.setProperty('display', 'none', 'important');
      } else {
        el.classList.remove('hide-on-print');
        el.style.removeProperty('display');
      }
    }
  });

  // Short delay to ensure DOM styles apply cleanly before print preview opens
  setTimeout(() => {
    try { window.print(); } catch (e) { }
    setTimeout(unlockApplicationPointerEvents, 200);
  }, 100);
}

function handleRpnCriteriaChange() {
  const criteriaSelect = document.getElementById('dashRpnCriteriaSelect');
  const highInput = document.getElementById('dashRpnHighThresholdInput');
  const medInput = document.getElementById('dashRpnMedThresholdInput');

  if (!criteriaSelect || !highInput || !medInput) return;
  const mode = criteriaSelect.value || 'AIAG';

  if (mode === 'AIAG') {
    highInput.value = 100;
    medInput.value = 80;
    highInput.disabled = true;
    medInput.disabled = true;
    highInput.style.background = '#f8fafc';
    medInput.style.background = '#f8fafc';
  } else {
    highInput.disabled = false;
    medInput.disabled = false;
    highInput.style.background = '#ffffff';
    medInput.style.background = '#ffffff';
  }

  if (fmeaData) {
    fmeaData.rpnSettings = fmeaData.rpnSettings || {};
    fmeaData.rpnSettings.mode = mode;
    fmeaData.rpnSettings.highThreshold = parseInt(highInput.value) || 100;
    fmeaData.rpnSettings.medThreshold = parseInt(medInput.value) || 80;
  }

  renderInsightsDashboard();
}

function handleRpnThresholdInput() {
  const highInput = document.getElementById('dashRpnHighThresholdInput');
  const medInput = document.getElementById('dashRpnMedThresholdInput');

  if (fmeaData && highInput && medInput) {
    fmeaData.rpnSettings = fmeaData.rpnSettings || {};
    fmeaData.rpnSettings.highThreshold = parseInt(highInput.value) || 100;
    fmeaData.rpnSettings.medThreshold = parseInt(medInput.value) || 80;
  }

  renderInsightsDashboard();
}

