function openInsightsDashboardModal() {
  activeDashboardMode = (fmeaData && fmeaData.methodologyMode === 'AIAG-VDA') ? 'AIAG-VDA' : 'AIAG';
  populateFmeaScopeCheckboxDropdown('dashScopeMultiSelectContainer', 'renderInsightsDashboard');
  populateDashVariantDropdown();
  renderInsightsDashboard();
  openModal('insightsDashboardModal');
}

function renderInsightsDashboard() {
  const container = document.getElementById('dashboardContentContainer');
  const scopeBadge = document.getElementById('dashActiveScopeBadge');
  const btnAIAG = document.getElementById('dashModeBtnAIAG');
  const btnVDA = document.getElementById('dashModeBtnVDA');

  if (!container) return;
  if (!fmeaData) {
    container.innerHTML = `<div style="padding:30px; text-align:center; color:var(--text-muted);">Please open an FMEA file to view dashboard insights & analytics.</div>`;
    return;
  }

  if (btnAIAG && btnVDA) {
    if (activeDashboardMode === 'AIAG') {
      btnAIAG.style.background = 'var(--primary-color, #0284c7)';
      btnAIAG.style.color = '#ffffff';
      btnAIAG.style.boxShadow = '0 2px 6px rgba(2, 132, 199, 0.4)';
      btnAIAG.innerHTML = '📊 AIAG 4th Ed (RPN) <span style="margin-left:4px; font-size:9.5px; background:rgba(255,255,255,0.25); color:#ffffff; padding:1px 6px; border-radius:10px; font-weight:800;">ACTIVE</span>';

      btnVDA.style.background = 'transparent';
      btnVDA.style.color = 'var(--text-muted)';
      btnVDA.style.boxShadow = 'none';
      btnVDA.innerHTML = '🎯 AIAG-VDA 1st Ed (AP & SOD)';
    } else {
      btnVDA.style.background = 'var(--primary-color, #0284c7)';
      btnVDA.style.color = '#ffffff';
      btnVDA.style.boxShadow = '0 2px 6px rgba(2, 132, 199, 0.4)';
      btnVDA.innerHTML = '🎯 AIAG-VDA 1st Ed (AP & SOD) <span style="margin-left:4px; font-size:9.5px; background:rgba(255,255,255,0.25); color:#ffffff; padding:1px 6px; border-radius:10px; font-weight:800;">ACTIVE</span>';

      btnAIAG.style.background = 'transparent';
      btnAIAG.style.color = 'var(--text-muted)';
      btnAIAG.style.boxShadow = 'none';
      btnAIAG.innerHTML = '📊 AIAG 4th Ed (RPN)';
    }
  }

  const selectedScopeVals = getSelectedScopeValues('dashScopeMultiSelectContainer');

  const variantFilter = document.getElementById('dashVariantSelect')?.value || 'ALL';
  const topRiskMaxCount = parseInt(document.getElementById('dashTopRiskCountSelect')?.value) || 10;

  // Resolve RPN Highlighting Criteria Thresholds (AIAG Standard vs Customized)
  fmeaData.rpnSettings = fmeaData.rpnSettings || { mode: 'AIAG', highThreshold: 100, medThreshold: 80 };
  const rpnCriteriaMode = document.getElementById('dashRpnCriteriaSelect')?.value || fmeaData.rpnSettings.mode || 'AIAG';
  const rpnHighThreshold = parseInt(document.getElementById('dashRpnHighThresholdInput')?.value) || fmeaData.rpnSettings.highThreshold || 100;
  const rpnMedThreshold = parseInt(document.getElementById('dashRpnMedThresholdInput')?.value) || fmeaData.rpnSettings.medThreshold || 80;

  // Resolve multi-selected scope function lines
  const targetScopes = resolveSelectedScopes(selectedScopeVals);
  const scopeNamesStr = targetScopes.map(s => s.name || (s.isPFMEA ? 'PFMEA' : 'DFMEA')).join(', ');

  if (scopeBadge) {
    const criteriaDesc = rpnCriteriaMode === 'AIAG' ? 'AIAG Standard (100/50)' : `Custom (${rpnHighThreshold}/${rpnMedThreshold})`;
    scopeBadge.textContent = `Scopes: ${scopeNamesStr} | Variant: ${variantFilter} | RPN Criteria: ${criteriaDesc}`;
  }

  if (!container) return;

  const libraries = fmeaData.libraries || {};
  const allEffects = libraries.effects || [];
  const allCauses = libraries.causes || [];
  const allActions = libraries.actions || [];

  const causeMapObj = {};
  allCauses.forEach(c => { causeMapObj[c.id] = c; });

  const todayStr = new Date().toISOString().slice(0, 10);

  let totalItemsCount = 0;
  let currentHighCount = 0;
  let currentMedCount = 0;
  let currentLowCount = 0;

  let forecastHighCount = 0;
  let forecastMedCount = 0;
  let forecastLowCount = 0;

  let totalActionsCount = 0;
  let overdueActionsCount = 0;
  let plannedActionsCount = 0;
  let inProgressActionsCount = 0;
  let completedActionsCount = 0;

  const sevCounts = Array(11).fill(0);
  const rpn1Bins = Array(10).fill(0);
  const rpn2Bins = Array(10).fill(0);

  // 5 S-ranges x 4 D-ranges x 5 O-ranges
  const apCurrentGrid = Array(5).fill(0).map(() => Array(4).fill(0).map(() => Array(5).fill(0)));
  const apForecastGrid = Array(5).fill(0).map(() => Array(4).fill(0).map(() => Array(5).fill(0)));

  const itemsList = [];
  const actionsSummaryList = [];
  const processedActionIds = new Set();

  targetScopes.forEach(scope => {
    const fls = scope.functionLines || [];
    const effMap = scope.failureModeEffects || fmeaData.failureModeEffects || {};
    const causeMap = scope.failureModeCauses || fmeaData.failureModeCauses || {};
    const causeActionsMap = scope.causeActions || fmeaData.causeActions || {};

    fls.forEach(fl => {
      if (variantFilter !== 'ALL') {
        const flVars = Array.isArray(fl.variantId) ? fl.variantId : [fl.variantId];
        if (!flVars.includes('ALL') && !flVars.includes(variantFilter)) return;
      }

      (fl.failureModes || []).forEach(fm => {
        const linkedEffIds = effMap[fm.id] || [];
        let linkedEffects = allEffects.filter(e => linkedEffIds.includes(e.id));
        if (linkedEffects.length === 0 && (fm.effects || []).length > 0) {
          linkedEffects = fm.effects;
        }

        const validEffects = linkedEffects.filter(e => {
          const desc = (e.desc || e.details || e.description || e.name || '').trim();
          return desc && desc !== '-' && !desc.toLowerCase().includes('(click to edit)');
        });
        if (validEffects.length === 0) return; // Exclude items without linked effect

        const s1 = validEffects.reduce((max, e) => Math.max(max, parseInt(e.severity) || 10), 1);

        const linkedCauseIds = causeMap[fm.id] || [];
        let linkedCauses = allCauses.filter(c => linkedCauseIds.includes(c.id));
        if (linkedCauses.length === 0 && (fm.causes || []).length > 0) {
          linkedCauses = fm.causes;
        }

        const validCauses = linkedCauses.filter(c => {
          const detail = (c.details || c.desc || c.description || c.name || '').trim();
          return detail && detail !== '-' && !detail.toLowerCase().includes('(click to edit)');
        });
        if (validCauses.length === 0) return; // Exclude items without linked cause

        validCauses.forEach(c => {
          totalItemsCount++;
          sevCounts[s1]++;
          const o1 = parseInt(c.occurrence) || 10;
          const d1 = parseInt(c.detection) || 10;
          const rpn1 = s1 * o1 * d1;
          const ap1 = computeAP(s1, o1, d1);

          rpn1Bins[getRpnBinIndex(rpn1)]++;

          const pos1 = getApMatrixIndices(s1, d1, o1);
          apCurrentGrid[pos1.sIdx][pos1.dIdx][pos1.oIdx]++;

          const currentCat = evalRiskCategory(s1, rpn1, rpnHighThreshold, rpnMedThreshold, 40);
          if ((activeDashboardMode === 'AIAG' && currentCat === 'H') || (activeDashboardMode !== 'AIAG' && ap1 === 'H')) currentHighCount++;
          else if ((activeDashboardMode === 'AIAG' && currentCat === 'M') || (activeDashboardMode !== 'AIAG' && ap1 === 'M')) currentMedCount++;
          else currentLowCount++;

          const directActions = c.recommendedActions || c.actions || (c.recommendedAction ? [c.recommendedAction] : []);
          const actIds = causeActionsMap[c.id] || [];
          const libraryActions = allActions.filter(a => actIds.includes(a.id));

          const combinedActList = [...directActions];
          libraryActions.forEach(la => {
            if (!combinedActList.some(da => da.id === la.id)) {
              combinedActList.push(la);
            }
          });

          let assignedAction = null;
          let s2 = s1, o2 = o1, d2 = d1;

          const validActList = combinedActList.filter(act => {
            const detail = (act.detail || act.details || act.name || act.actionDetails || act.desc || '').trim();
            const isBlankDetail = !detail || detail.toLowerCase() === 'recommended action' || detail.toLowerCase().includes('(click to edit)');
            return !isBlankDetail;
          });

          if (validActList.length > 0) {
            assignedAction = validActList[0];
            s2 = parseInt(assignedAction.revisedSev || assignedAction.s2) || s1;
            o2 = parseInt(assignedAction.revisedOcc || assignedAction.o2) || o1;
            d2 = parseInt(assignedAction.revisedDet || assignedAction.d2) || d1;

            validActList.forEach(act => {
              const resp = (act.responsible || act.owner || act.respPerson || act.assignee || 'Unassigned').trim();
              const detail = (act.detail || act.details || act.name || act.actionDetails || act.desc || '').trim();
              const status = act.status || (act.completionDate ? 'Passed' : 'Planned');
              const isOverdue = act.targetDate && act.targetDate < todayStr && status !== 'Passed' && status !== 'Completed';

              const actKey = act.id || `${scope.name || ''}_${fm.name || ''}_${detail.toLowerCase()}`;

              if (!processedActionIds.has(actKey)) {
                processedActionIds.add(actKey);
                totalActionsCount++;

                if (isOverdue) overdueActionsCount++;
                if (status === 'Passed' || status === 'Completed') completedActionsCount++;
                else if (status === 'In Progress') inProgressActionsCount++;
                else plannedActionsCount++;

                actionsSummaryList.push({
                  id: actKey,
                  scopeName: scope.name || (scope.isPFMEA ? 'PFMEA' : 'DFMEA'),
                  fmName: fm.name,
                  actionDetails: detail,
                  responsible: resp,
                  targetDate: act.targetDate || act.target_date || 'TBD',
                  actionTaken: act.actionTaken || act.notes || act.remarks || act.comment || '-',
                  completionDate: act.completionDate || act.completion_date || '-',
                  status: isOverdue ? 'Overdue' : status
                });
              }
            });
          }

          const rpn2 = s2 * o2 * d2;
          const ap2 = computeAP(s2, o2, d2);

          rpn2Bins[getRpnBinIndex(rpn2)]++;

          const pos2 = getApMatrixIndices(s2, d2, o2);
          apForecastGrid[pos2.sIdx][pos2.dIdx][pos2.oIdx]++;

          const forecastCat = evalRiskCategory(s2, rpn2, rpnHighThreshold, rpnMedThreshold, 40);
          if ((activeDashboardMode === 'AIAG' && forecastCat === 'H') || (activeDashboardMode !== 'AIAG' && ap2 === 'H')) forecastHighCount++;
          else if ((activeDashboardMode === 'AIAG' && forecastCat === 'M') || (activeDashboardMode !== 'AIAG' && ap2 === 'M')) forecastMedCount++;
          else forecastLowCount++;

          itemsList.push({
            scopeName: scope.name || (scope.isPFMEA ? 'PFMEA' : 'DFMEA'),
            fmName: fm.name,
            causeDetails: c.details || 'General Cause',
            s1, o1, d1, rpn1, ap1,
            assignedAction,
            s2, o2, d2, rpn2, ap2
          });
        });
      });
    });
  });

  itemsList.sort((a, b) => {
    if (activeDashboardMode === 'AIAG') {
      return b.rpn1 - a.rpn1;
    } else {
      const apRank = { 'H': 3, 'M': 2, 'L': 1 };
      if (apRank[b.ap1] !== apRank[a.ap1]) {
        return apRank[b.ap1] - apRank[a.ap1];
      }
      return b.s1 - a.s1 || b.rpn1 - a.rpn1;
    }
  });

  const topCriticalItems = itemsList.slice(0, topRiskMaxCount);

  const projName = fmeaData.header?.projectName || fmeaData.headerInfo?.customerName || fmeaData.projectName || 'FMEA Project';
  const curRev = typeof getContextRevision === 'function' ? getContextRevision() : (fmeaData.currentRevision || null);
  const revStr = curRev ? `Rev ${curRev.revNumber || curRev.number || '1.0'} (${curRev.status || 'Draft'})` : 'No Revision';
  const activeVar = variantFilter === 'ALL' ? 'All Variants' : (fmeaData.variants?.find(v => v.id === variantFilter)?.name || variantFilter);
  const activeScopeName = scopeNamesStr || 'All Scopes';

  let html = `
    <!-- Dedicated Print Header for Dashboard Report -->
    <div id="dashPrintHeader" class="dash-print-header">
      <div>
        <h2 style="margin:0; font-size:15px; font-weight:bold; color:var(--text-primary);">📊 GLOBAL RISK INSIGHTS DASHBOARD REPORT</h2>
        <div style="font-size:11px; color:var(--text-muted); margin-top:2px;">
          Project: <strong>${escapeHtml(projName)}</strong> &nbsp;|&nbsp; Scope: <strong>${escapeHtml(activeScopeName)}</strong> &nbsp;|&nbsp; Variant: <strong>${escapeHtml(activeVar)}</strong> &nbsp;|&nbsp; Rev: <strong>${escapeHtml(revStr)}</strong> &nbsp;|&nbsp; Mode: <strong>${escapeHtml(activeDashboardMode)}</strong>
        </div>
      </div>
      <div style="text-align:right; font-size:10px; color:var(--text-muted);">
        Generated: ${new Date().toLocaleDateString()}
      </div>
    </div>
    <div id="dashSecKpi" class="dash-print-section" style="display:flex !important; flex-direction:row !important; flex-wrap:nowrap !important; gap:12px !important; margin-bottom:14px !important; width:100% !important;">
      <div style="flex:1 1 0% !important; min-width:0 !important; background:var(--bg-card); border:1px solid var(--border-color); border-left:4px solid #3b82f6; border-radius:6px; padding:10px; color:var(--text-primary);">
        <span style="font-size:10px; color:var(--text-muted); font-weight:bold; text-transform:uppercase;">Total Risk Items</span>
        <div style="font-size:22px; font-weight:bold; color:var(--text-primary); margin-top:2px;">${totalItemsCount}</div>
      </div>
      <div style="flex:1 1 0% !important; min-width:0 !important; background:var(--bg-card); border:1px solid var(--border-color); border-left:4px solid #ef4444; border-radius:6px; padding:10px; color:var(--text-primary);">
        <span style="font-size:10px; color:#ef4444; font-weight:bold; text-transform:uppercase;">⚠️ Overdue Actions</span>
        <div style="font-size:22px; font-weight:bold; color:#ef4444; margin-top:2px;">${overdueActionsCount}</div>
        <div style="font-size:10px; color:var(--text-muted); margin-top:2px;">Past Target Completion Date</div>
      </div>
      <div style="flex:1 1 0% !important; min-width:0 !important; background:var(--bg-card); border:1px solid var(--border-color); border-left:4px solid #8b5cf6; border-radius:6px; padding:10px; color:var(--text-primary);">
        <span style="font-size:10px; color:#8b5cf6; font-weight:bold; text-transform:uppercase;">Total Recommended Actions</span>
        <div style="font-size:22px; font-weight:bold; color:#8b5cf6; margin-top:2px;">${totalActionsCount}</div>
        <div style="font-size:11px; color:var(--text-muted); margin-top:2px;"><strong style="color:#10b981;">${completedActionsCount} Passed</strong> | <strong style="color:#f59e0b;">${inProgressActionsCount} In Progress</strong> | <strong style="color:var(--text-primary);">${plannedActionsCount} Planned</strong></div>
      </div>
    </div>

    <!-- Separate Group Rectangles for Current vs Forecasted Situations -->
    <div id="dashSecRiskSummary" class="dash-print-section" style="display:flex !important; flex-direction:row !important; flex-wrap:nowrap !important; gap:16px !important; margin-bottom:16px !important; width:100% !important;">
      <!-- GROUP RECTANGLE 1: CURRENT SITUATION -->
      <div style="flex:1 1 0% !important; min-width:0 !important; background:var(--bg-card); border:1px solid var(--border-color); border-top:4px solid var(--risk-high-text); border-radius:8px; padding:14px; color:var(--text-primary);">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; border-bottom:1px solid var(--border-color); padding-bottom:6px;">
          <h4 style="margin:0; font-size:13px; color:var(--text-primary); font-weight:bold;">📍 CURRENT SITUATION (${activeDashboardMode === 'AIAG' ? 'RPN1' : 'AP1'})</h4>
          <span style="background:var(--risk-high-bg); color:var(--risk-high-text); border:1px solid var(--risk-high-border); font-size:11px; font-weight:600; padding:2px 8px; border-radius:4px;">Initial Baseline Risk</span>
        </div>
        
        <div style="display:flex; flex-direction:row; flex-wrap:nowrap; gap:10px; width:100%;">
          <!-- Current High -->
          <div style="flex:1 1 0%; min-width:0; background:var(--risk-high-bg); border:1px solid var(--risk-high-border); border-radius:6px; padding:10px 6px; text-align:center;">
            <span style="font-size:10px; color:var(--risk-high-text); font-weight:bold; text-transform:uppercase; display:block;">Current High</span>
            <div style="font-size:24px; font-weight:bold; color:var(--risk-high-text); margin-top:2px;">${currentHighCount}</div>
            <div style="font-size:9.5px; color:var(--text-muted); line-height:1.35; margin-top:4px; font-weight:500; text-align:center;">
              ${activeDashboardMode === 'AIAG' ? `• Severity 9-10 and RPN &gt; 40<br>• Severity 1-8 and RPN &gt; ${rpnHighThreshold || 100}` : '• AP1 = High'}
            </div>
          </div>

          <!-- Current Med -->
          <div style="flex:1 1 0%; min-width:0; background:var(--risk-med-bg); border:1px solid var(--risk-med-border); border-radius:6px; padding:10px 6px; text-align:center;">
            <span style="font-size:10px; color:var(--risk-med-text); font-weight:bold; text-transform:uppercase; display:block;">Current Med</span>
            <div style="font-size:24px; font-weight:bold; color:var(--risk-med-text); margin-top:2px;">${currentMedCount}</div>
            <div style="font-size:9.5px; color:var(--text-muted); line-height:1.35; margin-top:4px; font-weight:500; text-align:center;">
              ${activeDashboardMode === 'AIAG' ? `• Severity 1-8 and RPN ${rpnMedThreshold + 1} to ${rpnHighThreshold || 100}` : '• AP1 = Med'}
            </div>
          </div>

          <!-- Current Low -->
          <div style="flex:1 1 0%; min-width:0; background:var(--risk-low-bg); border:1px solid var(--risk-low-border); border-radius:6px; padding:10px 6px; text-align:center;">
            <span style="font-size:10px; color:var(--risk-low-text); font-weight:bold; text-transform:uppercase; display:block;">Current Low</span>
            <div style="font-size:24px; font-weight:bold; color:var(--risk-low-text); margin-top:2px;">${currentLowCount}</div>
            <div style="font-size:9.5px; color:var(--text-muted); line-height:1.35; margin-top:4px; font-weight:500; text-align:center;">
              ${activeDashboardMode === 'AIAG' ? `• Severity 9-10 and RPN ≤ 40<br>• Severity 1-8 and RPN ≤ ${rpnMedThreshold || 80}` : '• AP1 = Low'}
            </div>
          </div>
        </div>
      </div>

      <!-- GROUP RECTANGLE 2: FORECASTED SITUATION -->
      <div style="flex:1 1 0% !important; min-width:0 !important; background:var(--bg-card); border:1px solid var(--border-color); border-top:4px solid var(--risk-low-text); border-radius:8px; padding:14px; color:var(--text-primary);">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; border-bottom:1px solid var(--border-color); padding-bottom:6px;">
          <h4 style="margin:0; font-size:13px; color:var(--text-primary); font-weight:bold;">🎯 FORECASTED SITUATION (${activeDashboardMode === 'AIAG' ? 'RPN2' : 'AP2'})</h4>
          <span style="background:var(--risk-low-bg); color:var(--risk-low-text); border:1px solid var(--risk-low-border); font-size:11px; font-weight:600; padding:2px 8px; border-radius:4px;">Post-Action Residual Risk</span>
        </div>

        <div style="display:flex; flex-direction:row; flex-wrap:nowrap; gap:10px; width:100%;">
          <!-- Forecast High -->
          <div style="flex:1 1 0%; min-width:0; background:var(--risk-high-bg); border:1px solid var(--risk-high-border); border-radius:6px; padding:10px 6px; text-align:center;">
            <span style="font-size:10px; color:var(--risk-high-text); font-weight:bold; text-transform:uppercase; display:block;">Forecast High</span>
            <div style="font-size:24px; font-weight:bold; color:var(--risk-high-text); margin-top:2px;">${forecastHighCount}</div>
            <div style="font-size:9.5px; color:var(--text-muted); line-height:1.35; margin-top:4px; font-weight:500; text-align:center;">
              ${activeDashboardMode === 'AIAG' ? `• Severity 9-10 and RPN &gt; 40<br>• Severity 1-8 and RPN &gt; ${rpnHighThreshold || 100}` : '• AP2 = High'}
            </div>
          </div>

          <!-- Forecast Med -->
          <div style="flex:1 1 0%; min-width:0; background:var(--risk-med-bg); border:1px solid var(--risk-med-border); border-radius:6px; padding:10px 6px; text-align:center;">
            <span style="font-size:10px; color:var(--risk-med-text); font-weight:bold; text-transform:uppercase; display:block;">Forecast Med</span>
            <div style="font-size:24px; font-weight:bold; color:var(--risk-med-text); margin-top:2px;">${forecastMedCount}</div>
            <div style="font-size:9.5px; color:var(--text-muted); line-height:1.35; margin-top:4px; font-weight:500; text-align:center;">
              ${activeDashboardMode === 'AIAG' ? `• Severity 1-8 and RPN ${rpnMedThreshold + 1} to ${rpnHighThreshold || 100}` : '• AP2 = Med'}
            </div>
          </div>

          <!-- Forecast Low -->
          <div style="flex:1 1 0%; min-width:0; background:var(--risk-low-bg); border:1px solid var(--risk-low-border); border-radius:6px; padding:10px 6px; text-align:center;">
            <span style="font-size:10px; color:var(--risk-low-text); font-weight:bold; text-transform:uppercase; display:block;">Forecast Low</span>
            <div style="font-size:24px; font-weight:bold; color:var(--risk-low-text); margin-top:2px;">${forecastLowCount}</div>
            <div style="font-size:9.5px; color:var(--text-muted); line-height:1.35; margin-top:4px; font-weight:500; text-align:center;">
              ${activeDashboardMode === 'AIAG' ? `• Severity 9-10 and RPN ≤ 40<br>• Severity 1-8 and RPN ≤ ${rpnMedThreshold || 80}` : '• AP2 = Low'}
            </div>
          </div>
        </div>
      </div>
    </div>
  `;

  if (activeDashboardMode === 'AIAG') {
    html += `
      <!-- RPN Ranges Comparison Bar Chart (1-100, 101-200 ... 901-1000) -->
        <div id="dashSecMethodology" class="dash-print-section" style="background:var(--bg-card); border:1px solid var(--border-color); border-radius:8px; padding:14px; margin-bottom:16px; color:var(--text-primary);">
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;">
            <h3 style="font-size:14px; margin:0; color:var(--text-primary); font-weight:bold;">📊 RPN Distribution Ranges: Before (RPN1) vs After (RPN2) Recommended Actions</h3>
            <div style="display:flex; gap:16px; font-size:11px; font-weight:600; color:var(--text-primary);">
              <span style="display:flex; align-items:center; gap:5px;"><span style="width:12px; height:12px; background:#3b82f6; border-radius:2px; display:inline-block;"></span> Before Action (RPN1)</span>
              <span style="display:flex; align-items:center; gap:5px;"><span style="width:12px; height:12px; background:#10b981; border-radius:2px; display:inline-block;"></span> After Action (RPN2)</span>
            </div>
          </div>
          
          <div style="display:flex; gap:8px; align-items:flex-end; height:130px; border-bottom:2px solid var(--border-color); padding-bottom:4px; overflow-x:auto;">
      `;

    const binLabels = ['1-100', '101-200', '201-300', '301-400', '401-500', '501-600', '601-700', '701-800', '801-900', '901-1000'];
    const maxRpnBinVal = Math.max(...rpn1Bins, ...rpn2Bins, 1);

    binLabels.forEach((label, idx) => {
      const c1 = rpn1Bins[idx];
      const c2 = rpn2Bins[idx];
      const h1Px = Math.max(Math.round((c1 / maxRpnBinVal) * 70), c1 ? 8 : 2);
      const h2Px = Math.max(Math.round((c2 / maxRpnBinVal) * 70), c2 ? 8 : 2);

      html += `
          <div style="flex:1; min-width:55px; display:flex; flex-direction:column; align-items:center; height:100%; justify-content:flex-end;">
            <div style="display:flex; gap:3px; align-items:flex-end; width:100%; height:90px; justify-content:center;">
              <!-- RPN1 Bar -->
              <div style="width:45%; background:#3b82f6 !important; height:${h1Px}px !important; min-height:${h1Px}px !important; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; border-radius:3px 3px 0 0; display:flex; align-items:flex-start; justify-content:center;" title="Before Action (RPN1 ${label}): ${c1}">
                <span style="font-size:9px; color:${c1 ? '#3b82f6' : 'transparent'}; font-weight:bold; margin-top:-14px;">${c1 || ''}</span>
              </div>
              <!-- RPN2 Bar -->
              <div style="width:45%; background:#10b981 !important; height:${h2Px}px !important; min-height:${h2Px}px !important; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; border-radius:3px 3px 0 0; display:flex; align-items:flex-start; justify-content:center;" title="After Action (RPN2 ${label}): ${c2}">
                <span style="font-size:9px; color:${c2 ? '#10b981' : 'transparent'}; font-weight:bold; margin-top:-14px;">${c2 || ''}</span>
              </div>
            </div>
            <span style="font-size:9.5px; font-weight:bold; margin-top:6px; color:var(--text-muted); white-space:nowrap;">${label}</span>
          </div>
        `;
    });

    html += `
          </div>
        </div>
      `;
  } else {
    html += `
        <!-- AIAG-VDA Dual Action Priority (AP) SOD Matrix Heatmaps (Before vs After) -->
        <div id="dashSecMethodology" class="dash-print-section" style="margin-bottom:16px; color:var(--text-primary);">
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;">
            <h3 style="font-size:14px; margin:0; color:var(--text-primary); font-weight:bold;">🎯 AIAG-VDA Action Priority (AP) SOD Matrices (Before vs After Actions)</h3>
            <div style="display:flex; gap:12px; font-size:11px; color:var(--text-primary);">
              <span style="display:flex; align-items:center; gap:4px;"><span style="width:12px; height:12px; background:#10b981; border-radius:2px; display:inline-block;"></span> Low (L)</span>
              <span style="display:flex; align-items:center; gap:4px;"><span style="width:12px; height:12px; background:#f59e0b; border-radius:2px; display:inline-block;"></span> Medium (M)</span>
              <span style="display:flex; align-items:center; gap:4px;"><span style="width:12px; height:12px; background:#ef4444; border-radius:2px; display:inline-block;"></span> High (H)</span>
            </div>
          </div>

          <div style="display:flex; gap:16px; align-items:flex-start;">
            ${generateApMatrixHtml(apCurrentGrid, '📍 Current Situation (AP1 - Before Action)', 'Baseline Risk Matrix', '#ef4444')}
            ${generateApMatrixHtml(apForecastGrid, '🎯 Forecasted Situation (AP2 - After Action)', 'Post-Action Residual Matrix', '#10b981')}
          </div>
        </div>
      `;
  }

  html += `
    <!-- Current vs. Forecasted Risk Comparison Bar -->
    <div id="dashSecComparisonBar" class="dash-print-section">
      <div style="background:var(--bg-card); border:1px solid var(--border-color); border-radius:8px; padding:14px; margin-bottom:16px; color:var(--text-primary);">
      <h3 style="font-size:14px; margin:0 0 10px 0; color:var(--text-primary);">
        📊 Current Risk (${activeDashboardMode === 'AIAG' ? 'RPN1' : 'AP1'}) vs Forecasted Risk (${activeDashboardMode === 'AIAG' ? 'RPN2' : 'AP2'})
      </h3>
      
      <div style="display:grid; grid-template-columns: 1fr 1fr; gap:16px;">
        <div>
          <span style="font-size:11px; font-weight:bold; color:var(--text-muted); display:block; margin-bottom:4px;">CURRENT SITUATION (${activeDashboardMode === 'AIAG' ? 'RPN1' : 'AP1'})</span>
          <div style="display:flex; height:22px; border-radius:4px; overflow:hidden; background:var(--bg-card); border:1px solid var(--border-color); -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">
            <div style="width:${totalItemsCount ? (currentHighCount / totalItemsCount * 100) : 0}%; background:#ef4444 !important; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; display:flex; align-items:center; justify-content:center; color:#fff; font-size:11px; font-weight:bold;" title="Current High Risk">
              ${currentHighCount ? `${currentHighCount} High` : ''}
            </div>
            <div style="width:${totalItemsCount ? (currentMedCount / totalItemsCount * 100) : 0}%; background:#f59e0b !important; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; display:flex; align-items:center; justify-content:center; color:#fff; font-size:11px; font-weight:bold;" title="Current Med Risk">
              ${currentMedCount ? `${currentMedCount} Med` : ''}
            </div>
            <div style="width:${totalItemsCount ? (currentLowCount / totalItemsCount * 100) : 0}%; background:#10b981 !important; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; display:flex; align-items:center; justify-content:center; color:#fff; font-size:11px; font-weight:bold;" title="Current Low Risk">
              ${currentLowCount ? `${currentLowCount} Low` : ''}
            </div>
          </div>
        </div>

        <div>
          <span style="font-size:11px; font-weight:bold; color:var(--text-muted); display:block; margin-bottom:4px;">FORECASTED / RESIDUAL SITUATION (${activeDashboardMode === 'AIAG' ? 'RPN2' : 'AP2'})</span>
          <div style="display:flex; height:22px; border-radius:4px; overflow:hidden; background:var(--bg-card); border:1px solid var(--border-color); -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">
            <div style="width:${totalItemsCount ? (forecastHighCount / totalItemsCount * 100) : 0}%; background:#ef4444 !important; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; display:flex; align-items:center; justify-content:center; color:#fff; font-size:11px; font-weight:bold;" title="Forecast High Risk">
              ${forecastHighCount ? `${forecastHighCount} High` : ''}
            </div>
            <div style="width:${totalItemsCount ? (forecastMedCount / totalItemsCount * 100) : 0}%; background:#f59e0b !important; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; display:flex; align-items:center; justify-content:center; color:#fff; font-size:11px; font-weight:bold;" title="Forecast Med Risk">
              ${forecastMedCount ? `${forecastMedCount} Med` : ''}
            </div>
            <div style="width:${totalItemsCount ? (forecastLowCount / totalItemsCount * 100) : 0}%; background:#10b981 !important; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; display:flex; align-items:center; justify-content:center; color:#fff; font-size:11px; font-weight:bold;" title="Forecast Low Risk">
              ${forecastLowCount ? `${forecastLowCount} Low` : ''}
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- Severity Distribution Bar Chart -->
    <div style="background:var(--bg-card); border:1px solid var(--border-color); border-radius:8px; padding:14px; margin-bottom:16px; color:var(--text-primary);">
      <h3 style="font-size:14px; margin:0 0 10px 0; color:var(--text-primary);">⚠️ Severity (S1) Rating Distribution (S1 to S10)</h3>
      <div style="display:flex; gap:8px; align-items:flex-end; height:110px; border-bottom:2px solid var(--border-color); padding-bottom:4px;">
  `;

  for (let s = 1; s <= 10; s++) {
    const count = sevCounts[s];
    const maxVal = Math.max(...sevCounts.slice(1), 1);
    const heightPx = Math.max(Math.round((count / maxVal) * 70), count ? 8 : 2);
    const color = s >= 9 ? '#dc2626' : (s >= 7 ? '#f59e0b' : '#3b82f6');

    html += `
      <div style="flex:1; display:flex; flex-direction:column; align-items:center; height:100%; justify-content:flex-end;">
        <span style="font-size:10px; font-weight:bold; color:var(--text-muted); margin-bottom:2px;">${count || ''}</span>
        <div style="width:70%; background:${color} !important; height:${heightPx}px !important; min-height:${heightPx}px !important; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; border-radius:4px 4px 0 0;" title="Severity ${s}: ${count} occurrences"></div>
        <span style="font-size:10px; font-weight:bold; margin-top:4px; color:${s >= 9 ? '#dc2626' : 'var(--text-primary)'};">S${s}</span>
      </div>
    `;
  }

  html += `
      </div>
    </div>

    <!-- Top Risk Items Matrix (User Selectable Count Up to 20) -->
    <div id="dashSecTopRisks" class="dash-print-section" style="background:var(--bg-card); border:1px solid var(--border-color); border-radius:8px; padding:14px; margin-bottom:16px; color:var(--text-primary);">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;">
        <h3 style="font-size:14px; margin:0; color:var(--text-primary);">⚡ Top ${topCriticalItems.length} High-Risk Items &amp; Forecast Matrix</h3>
        <span style="font-size:11px; color:var(--text-muted);">Showing Top ${topCriticalItems.length} of ${totalItemsCount} total items</span>
      </div>
      <table style="width:100%; border-collapse:collapse; font-size:12px;">
        <thead>
          <tr style="background:var(--table-header-bg); color:var(--table-header-text);">
            <th style="padding:10px 8px; width:35px; text-align:center; border-bottom:2px solid var(--border-color); color:var(--table-header-text);">#</th>
            <th style="padding:10px 8px; text-align:left; border-bottom:2px solid var(--border-color); color:var(--table-header-text);">Failure Mode / Cause Context</th>
            <th style="padding:10px 8px; width:130px; text-align:center; border-bottom:2px solid var(--border-color); color:var(--table-header-text);">Current Risk (1)<br><small style="font-weight:normal; opacity:0.85;">S1 | O1 | D1</small></th>
            <th style="padding:10px 8px; width:110px; text-align:center; border-bottom:2px solid var(--border-color); color:var(--table-header-text);">${activeDashboardMode === 'AIAG' ? 'RPN1' : 'AP1'}</th>
            <th style="padding:10px 8px; width:250px; text-align:left; border-bottom:2px solid var(--border-color); color:var(--table-header-text);">Recommended Action &amp; Status</th>
            <th style="padding:10px 8px; width:130px; text-align:center; border-bottom:2px solid var(--border-color); color:var(--table-header-text);">Forecast Risk (2)<br><small style="font-weight:normal; opacity:0.85;">S2 | O2 | D2</small></th>
            <th style="padding:10px 8px; width:110px; text-align:center; border-bottom:2px solid var(--border-color); color:var(--table-header-text);">${activeDashboardMode === 'AIAG' ? 'RPN2' : 'AP2'}</th>
          </tr>
        </thead>
        <tbody>
  `;

  if (topCriticalItems.length === 0) {
    html += `<tr><td colspan="7" style="text-align:center; padding:16px; color:var(--text-muted);">No risk items found matching active scope &amp; variant filter criteria.</td></tr>`;
  } else {
    topCriticalItems.forEach((item, idx) => {
      const ap1Badge = item.ap1 === 'H'
        ? '<span class="badge" style="background:var(--risk-high-bg); color:var(--risk-high-text); border:1px solid var(--risk-high-border);">High (H)</span>'
        : (item.ap1 === 'M' ? '<span class="badge" style="background:var(--risk-med-bg); color:var(--risk-med-text); border:1px solid var(--risk-med-border);">Med (M)</span>' : '<span class="badge" style="background:var(--risk-low-bg); color:var(--risk-low-text); border:1px solid var(--risk-low-border);">Low (L)</span>');

      const ap2Badge = item.ap2 === 'H'
        ? '<span class="badge" style="background:var(--risk-high-bg); color:var(--risk-high-text); border:1px solid var(--risk-high-border);">High (H)</span>'
        : (item.ap2 === 'M' ? '<span class="badge" style="background:var(--risk-med-bg); color:var(--risk-med-text); border:1px solid var(--risk-med-border);">Med (M)</span>' : '<span class="badge" style="background:var(--risk-low-bg); color:var(--risk-low-text); border:1px solid var(--risk-low-border);">Low (L)</span>');

      let actionHTML = '<span style="color:var(--text-muted); font-style:italic;">No Action Assigned</span>';
      if (item.assignedAction) {
        const act = item.assignedAction;
        const status = act.status || (act.completionDate ? 'Passed' : 'Planned');
        const isOverdue = act.targetDate && act.targetDate < todayStr && status !== 'Passed' && status !== 'Completed';

        let statusBadge = `<span class="badge" style="background:var(--bg-card); color:var(--text-primary); border:1px solid var(--border-color);">${escapeHtml(status)}</span>`;
        if (isOverdue) {
          statusBadge = `<span class="badge" style="background:var(--status-overdue-bg); color:var(--status-overdue-text); border:1px solid var(--status-overdue-border); font-weight:bold;">⚠️ OVERDUE</span>`;
        } else if (status === 'Passed' || status === 'Completed') {
          statusBadge = `<span class="badge" style="background:var(--status-passed-bg); color:var(--status-passed-text); border:1px solid var(--status-passed-border);">Passed</span>`;
        } else if (status === 'In Progress') {
          statusBadge = `<span class="badge" style="background:var(--status-progress-bg); color:var(--status-progress-text); border:1px solid var(--status-progress-border);">In Progress</span>`;
        }

        const respText = act.responsible && act.responsible !== 'Unassigned' && act.responsible !== '-' ? `👤 ${escapeHtml(act.responsible)}` : '';
        const targetText = act.targetDate && act.targetDate !== '-' ? `📅 Target: ${escapeHtml(act.targetDate)}` : '';

        actionHTML = `
          <div style="font-weight:600; color:var(--text-primary);">${escapeHtml(act.detail || act.desc || '')}</div>
          <div style="font-size:11px; color:var(--text-muted); margin-top:2px;">
            ${respText} ${respText && targetText ? '| ' : ''}${targetText}
          </div>
          <div style="margin-top:4px;">${statusBadge}</div>
        `;
      }

      const rpnReduced = item.rpn2 < item.rpn1;
      const rpnChangeText = rpnReduced ? `<span style="font-size:10px; color:#10b981;">(-${item.rpn1 - item.rpn2})</span>` : '';

      html += `
        <tr style="border-bottom:1px solid var(--border-color); background:${idx % 2 === 0 ? 'var(--bg-card)' : 'var(--table-row-alt, rgba(255,255,255,0.02))'}; color:var(--text-primary);">
          <td style="padding:8px; text-align:center; font-weight:bold; color:var(--text-muted);">${idx + 1}</td>
          <td style="padding:8px;">
            <span style="font-size:10px; font-weight:bold; color:#38bdf8; display:block;">${escapeHtml(item.scopeName)}</span>
            <strong style="color:var(--text-primary); font-size:12px;">${escapeHtml(item.fmName)}</strong>
            ${item.causeDetails ? `<div style="color:var(--text-muted); font-size:11px; margin-top:2px;">Cause: ${escapeHtml(item.causeDetails)}</div>` : ''}
          </td>
          <td style="padding:8px; text-align:center; font-weight:bold; color:var(--text-primary);">
            <span style="${item.s1 >= 9 ? 'color:#ef4444;' : ''}">${item.s1}</span> | ${item.o1} | ${item.d1}
          </td>
          <td style="padding:8px; text-align:center;">
            ${activeDashboardMode === 'AIAG' ? `<strong style="font-size:13px; color:var(--text-primary);">${item.rpn1}</strong>` : ap1Badge}
          </td>
          <td style="padding:8px;">${actionHTML}</td>
          <td style="padding:8px; text-align:center; font-weight:bold; color:var(--text-primary);">
            <span style="${item.s2 >= 9 ? 'color:#ef4444;' : ''}">${item.s2}</span> | ${item.o2} | ${item.d2}
          </td>
          <td style="padding:8px; text-align:center;">
            ${activeDashboardMode === 'AIAG' ? `<strong style="font-size:13px; color:${rpnReduced ? '#10b981' : 'var(--text-primary)'};">${item.rpn2}</strong> ${rpnChangeText}` : ap2Badge}
          </td>
        </tr>
      `;
    });
  }

  html += `
        </tbody>
      </table>
    </div>

    <!-- Recommended Action Summary Table Section -->
    <div id="dashSecActionSummary" class="dash-print-section" style="background:var(--bg-card); border:1px solid var(--border-color); border-radius:8px; padding:14px; margin-bottom:16px; color:var(--text-primary);">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;">
        <h3 style="font-size:14px; margin:0; color:var(--text-primary); font-weight:bold;">📋 Recommended Actions Detailed Summary Table</h3>
        <span class="badge" style="background:#8b5cf6; color:#ffffff; font-size:11px;">${actionsSummaryList.length} Total Actions</span>
      </div>

      <div style="overflow-x:auto;">
        <table class="table" style="width:100%; border-collapse:collapse; font-size:11px; text-align:left; border:1px solid var(--border-color);">
          <thead>
            <tr style="background:var(--table-header-bg); color:var(--table-header-text);">
              <th style="padding:6px 8px; border:1px solid var(--border-color); width:35px; text-align:center; color:var(--table-header-text);">#</th>
              <th style="padding:6px 8px; border:1px solid var(--border-color); width:130px; color:var(--table-header-text);">Scope / FMEA Ref</th>
              <th style="padding:6px 8px; border:1px solid var(--border-color); width:200px; color:var(--table-header-text);">Failure Mode</th>
              <th style="padding:6px 8px; border:1px solid var(--border-color); color:var(--table-header-text);">Recommended Action</th>
              <th style="padding:6px 8px; border:1px solid var(--border-color); width:110px; color:var(--table-header-text);">Responsible</th>
              <th style="padding:6px 8px; border:1px solid var(--border-color); width:85px; text-align:center; color:var(--table-header-text);">Target Date</th>
              <th style="padding:6px 8px; border:1px solid var(--border-color); color:var(--table-header-text);">Action Taken / Remarks</th>
              <th style="padding:6px 8px; border:1px solid var(--border-color); width:85px; text-align:center; color:var(--table-header-text);">Completion Date</th>
              <th style="padding:6px 8px; border:1px solid var(--border-color); width:85px; text-align:center; color:var(--table-header-text);">Status</th>
            </tr>
          </thead>
          <tbody>
  `;

  if (actionsSummaryList.length === 0) {
    html += `
      <tr>
        <td colspan="9" style="text-align:center; padding:16px; color:var(--text-muted); font-style:italic;">No recommended actions found in current filter scope.</td>
      </tr>
    `;
  } else {
    actionsSummaryList.forEach((item, index) => {
      const status = item.status || (item.completionDate ? 'Passed' : 'Planned');
      const isOverdue = item.targetDate && item.targetDate < todayStr && status !== 'Passed' && status !== 'Completed';

      let statusBadge = `<span class="badge" style="background:var(--bg-card); color:var(--text-primary); border:1px solid var(--border-color);">${escapeHtml(status)}</span>`;
      if (isOverdue) {
        statusBadge = `<span class="badge" style="background:var(--status-overdue-bg); color:var(--status-overdue-text); border:1px solid var(--status-overdue-border); font-weight:bold;">⚠️ OVERDUE</span>`;
      } else if (status === 'Passed' || status === 'Completed') {
        statusBadge = `<span class="badge" style="background:var(--status-passed-bg); color:var(--status-passed-text); border:1px solid var(--status-passed-border);">Passed</span>`;
      } else if (status === 'In Progress') {
        statusBadge = `<span class="badge" style="background:var(--status-progress-bg); color:var(--status-progress-text); border:1px solid var(--status-progress-border);">In Progress</span>`;
      }

      html += `
        <tr style="border-bottom:1px solid var(--border-color); background:${index % 2 === 0 ? 'var(--bg-card)' : 'var(--table-row-alt, rgba(255,255,255,0.02))'}; color:var(--text-primary);">
          <td style="padding:6px 8px; border:1px solid var(--border-color); text-align:center; font-weight:bold; color:var(--text-muted);">${index + 1}</td>
          <td style="padding:6px 8px; border:1px solid var(--border-color);">
            <span style="font-size:10px; font-weight:bold; color:#38bdf8; display:block;">${escapeHtml(item.scopeName)}</span>
            <span style="font-size:10px; color:var(--text-muted);">${escapeHtml(item.fmeaType)}</span>
          </td>
          <td style="padding:6px 8px; border:1px solid var(--border-color); font-weight:500;">${escapeHtml(item.failureMode)}</td>
          <td style="padding:6px 8px; border:1px solid var(--border-color); font-weight:600; color:var(--text-primary);">${escapeHtml(item.actionDetails)}</td>
          <td style="padding:6px 8px; border:1px solid var(--border-color);">${escapeHtml(item.owner || 'Unassigned')}</td>
          <td style="padding:6px 8px; border:1px solid var(--border-color); text-align:center;">${escapeHtml(item.targetDate || 'TBD')}</td>
          <td style="padding:6px 8px; border:1px solid var(--border-color);">${escapeHtml(item.actionTaken || '-')}</td>
          <td style="padding:6px 8px; border:1px solid var(--border-color); text-align:center;">${escapeHtml(item.completionDate || '-')}</td>
          <td style="padding:6px 8px; border:1px solid var(--border-color); text-align:center;">${statusBadge}</td>
        </tr>
      `;
    });
  }

  html += `
          </tbody>
        </table>
      </div>
    </div>
  `;

  if (container) {
    container.innerHTML = html;
  }
}

function escapeHtml(str) {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function formatCleanCellText(val) {
  if (val === null || val === undefined) return '-';
  const str = String(val).trim();
  if (!str || str === '-' || str.toLowerCase().includes('(click to edit)')) return '-';
  return str;
}

function formatAPBadge(s, o, d, isVDA) {
  const sNum = parseInt(s) || 1;
  const oNum = parseInt(o) || 1;
  const dNum = parseInt(d) || 1;
  if (!isVDA) {
    const rpn = sNum * oNum * dNum;
    let bg = '#10b981', color = '#ffffff';
    if (rpn > 100) { bg = '#ef4444'; }
    else if (rpn > 80) { bg = '#f59e0b'; }
    return `<span style="background:${bg}; color:${color}; font-weight:bold; padding:2px 6px; border-radius:3px; font-size:10px;">${rpn}</span>`;
  }
  const ap = computeAP(sNum, oNum, dNum);
  let bg = '#10b981', color = '#ffffff', label = 'L';
  if (ap === 'H') { bg = '#ef4444'; color = '#ffffff'; label = 'H'; }
  else if (ap === 'M') { bg = '#f59e0b'; color = '#ffffff'; label = 'M'; }
  return `<span style="background:${bg}; color:${color}; font-weight:bold; padding:2px 8px; border-radius:3px; font-size:10px;" title="Action Priority: ${ap === 'H' ? 'High' : (ap === 'M' ? 'Medium' : 'Low')}">${label}</span>`;
}

function getScopeTableHeaderHTML(isVDA, isPFMEA) {
  if (!isVDA) {
    return `
        <thead>
          <tr style="background:#0f172a !important; color:#ffffff !important; font-weight:bold; font-size:9.5px; text-transform:uppercase; text-align:center;">
            <th style="width:28px;">No.</th>
            <th style="width:130px;">${isPFMEA ? 'Process Step Station No. & Name' : 'Focus Element (System / Subsystem)'}</th>
            <th style="width:130px;">${isPFMEA ? 'Function & Requirement of Process Step' : 'Function & Requirement of Focus Element'}</th>
            <th style="width:120px;">${isPFMEA ? 'Failure Mode (FM) of Process Step' : 'Failure Mode (FM)'}</th>
            <th style="width:140px;">${isPFMEA ? 'Failure Effect (FE) [Higher Level / End User]' : 'Failure Effect (FE) [Higher Level]'}</th>
            <th style="width:22px;">S</th>
            <th style="width:130px;">${isPFMEA ? 'Failure Cause (FC) [Work Element & Function]' : 'Failure Cause (FC) [Lower Level Element & Function]'}</th>
            <th style="width:110px;">Lower Level Characteristic / Spec</th>
            <th style="width:40px;">Class</th>
            <th style="width:50px;">Variant</th>
            <th style="width:120px;">Current Prevention Control</th>
            <th style="width:22px;">O</th>
            <th style="width:120px;">Current Detection Control</th>
            <th style="width:22px;">D</th>
            <th style="width:48px;">RPN</th>
            <th style="width:120px;">Recommended Action</th>
            <th style="width:30px;">P/D</th>
            <th style="width:90px;">Responsible Person</th>
            <th style="width:70px;">Target Date</th>
            <th style="width:110px;">Action Taken & Date</th>
            <th style="width:22px;">S2</th>
            <th style="width:22px;">O2</th>
            <th style="width:22px;">D2</th>
            <th style="width:48px;">RPN2</th>
            <th style="width:90px;">Comments</th>
          </tr>
        </thead>`;
  }
  return `
        <thead>
          <tr style="background:#0f172a !important; color:#ffffff !important; font-weight:bold; font-size:9.5px; text-transform:uppercase; text-align:center;">
            <th style="width:28px;" rowspan="2">No.</th>
            <th colspan="3" style="background:#1e293b !important; color:#fff !important; border:1px solid #475569;">STRUCTURAL ANALYSIS (STEP 2)</th>
            <th colspan="3" style="background:#1e3a8a !important; color:#fff !important; border:1px solid #475569;">FUNCTIONAL ANALYSIS (STEP 3)</th>
            <th colspan="4" style="background:#4c1d95 !important; color:#fff !important; border:1px solid #475569;">FAILURE ANALYSIS (STEP 4)</th>
            <th colspan="6" style="background:#065f46 !important; color:#fff !important; border:1px solid #475569;">RISK ANALYSIS (STEP 5)</th>
            <th colspan="10" style="background:#831843 !important; color:#fff !important; border:1px solid #475569;">OPTIMIZATION (STEP 6)</th>
            <th style="width:80px;" rowspan="2">Filter Code / Remarks</th>
          </tr>
          <tr style="background:#334155 !important; color:#ffffff !important; font-weight:bold; font-size:9px; text-align:center;">
            <th style="width:110px;">${isPFMEA ? '1. Process Item System, Subsystem, Element or Name of Process' : '1. System, Subsystem, Subelement or Name of System'}</th>
            <th style="width:120px;">${isPFMEA ? '2. Process Step Station No. and Name of Focus Element' : '2. Focus Element (System, Subsystem, Component)'}</th>
            <th style="width:100px;">${isPFMEA ? '3. Process Work Elements Type 4M' : '3. Next Lower Level Element'}</th>
            <th style="width:130px;">${isPFMEA ? '1. Function of Process Item & Higher System' : '1. Function of Next Higher Level Element & Higher System'}</th>
            <th style="width:120px;">${isPFMEA ? '2. Function & Requirement of Process Step' : '2. Function & Requirement of Focus Element'}</th>
            <th style="width:110px;">${isPFMEA ? '3. Function of Process Work Element' : '3. Function of Next Lower Level Element'}</th>
            <th style="width:130px;">${isPFMEA ? '1. Failure Effects (FE) to Next Higher Element / End User' : '1. Failure Effects (FE) to Higher Level / Vehicle / End User'}</th>
            <th style="width:22px;">S</th>
            <th style="width:120px;">${isPFMEA ? '2. Failure Mode (FM) of Process Step' : '2. Failure Mode (FM) of Focus Element'}</th>
            <th style="width:120px;">${isPFMEA ? '3. Failure Cause (FC) of Work Element' : '3. Failure Cause (FC) of Next Lower Level Element'}</th>
            <th style="width:120px;">Current Prevention Control (PC) of FC</th>
            <th style="width:22px;">O</th>
            <th style="width:120px;">Current Detection Control (DC) of FC or FM</th>
            <th style="width:22px;">D</th>
            <th style="width:48px;">AP</th>
            <th style="width:45px;">Class</th>
            <th style="width:110px;">Preventive Action</th>
            <th style="width:110px;">Detection Action</th>
            <th style="width:85px;">Responsible Person Name</th>
            <th style="width:70px;">Target Date</th>
            <th style="width:60px;">Status</th>
            <th style="width:100px;">Action Taken with Completion Date</th>
            <th style="width:22px;">S</th>
            <th style="width:22px;">O</th>
            <th style="width:22px;">D</th>
            <th style="width:48px;">AP2</th>
          </tr>
        </thead>`;
}

function buildScopeTableRowsHTML(scope, nodeIds, targetVariant) {
  let html = '';
  const fls = scope.functionLines || (scope.isPFMEA ? scope.pfmea?.functionLines : fmeaData.functionLines) || [];
  const functionsList = scope.functions || (scope.isPFMEA ? (scope.pfmea?.functions || fmeaData.functions || []) : (fmeaData.functions || []));
  const reqsList = getActiveRequirementsList(scope);
  const effMap = scope.failureModeEffects || (scope.isPFMEA ? scope.pfmea?.failureModeEffects : fmeaData.failureModeEffects) || {};
  const causeMap = scope.failureModeCauses || (scope.isPFMEA ? scope.pfmea?.failureModeCauses : fmeaData.failureModeCauses) || {};
  const causeControls = scope.causeControls || (scope.isPFMEA ? scope.pfmea?.causeControls : fmeaData.causeControls) || {};
  const causeActions = scope.causeActions || (scope.isPFMEA ? scope.pfmea?.causeActions : fmeaData.causeActions) || {};
  const reqMap = scope.functionRequirements || (scope.isPFMEA ? scope.pfmea?.functionRequirements : fmeaData.functionRequirements) || {};
  const isVDA = (fmeaData.methodologyMode === 'AIAG-VDA');
  let rowCounter = 0;

  const systemOrProcessItemStr = scope.name || (scope.isPFMEA ? (scope.pfmea?.name || 'Process Item') : 'System Element');

  fls.forEach(fl => {
    let structNode = null;
    if (scope.isPFMEA && scope.pfmea && scope.pfmea.processSteps) {
      const pstep = scope.pfmea.processSteps.find(ps => ps.id === fl.structId);
      if (pstep) {
        structNode = {
          id: pstep.id,
          partNo: pstep.stepNo,
          name: pstep.name,
          description: pstep.description,
          variantId: pstep.variantId,
          dfmeaStructId: pstep.dfmeaStructId,
          workElement: pstep.workElement || pstep.type4M || ''
        };
      }
    }
    if (!structNode) {
      structNode = getStructureNodeById(fmeaData.structure, fl.structId);
    }

    let structCellText = scope.isPFMEA ? 'Process Step' : 'Focus Element';
    let workElementStr = scope.isPFMEA ? '-' : '-';
    if (structNode) {
      structCellText = `${structNode.partNo ? structNode.partNo + ' ' : ''}${structNode.name || ''}`.trim();
      workElementStr = structNode.workElement || structNode.type4M || structNode.description || '-';
    }

    if (nodeIds && nodeIds.length > 0) {
      if (scope.isPFMEA) {
        const allDfmeaNodes = getStructureNodesArray(fmeaData.structure);
        const isAllDfmeaChecked = allDfmeaNodes.every(n => nodeIds.includes(n.id));
        if (!isAllDfmeaChecked) {
          const isDirectMatch = nodeIds.includes(fl.structId);
          const isStructMatch = structNode && nodeIds.includes(structNode.id);
          const isDfmeaParentMatch = structNode && structNode.dfmeaStructId && nodeIds.includes(structNode.dfmeaStructId);
          if (!isDirectMatch && !isStructMatch && !isDfmeaParentMatch) return;
        }
      } else {
        const isDirectMatch = nodeIds.includes(fl.structId);
        const isStructMatch = structNode && nodeIds.includes(structNode.id);
        if (!isDirectMatch && !isStructMatch) return;
      }
    }

    if (structNode && !matchesVariantFilter(structNode.variantId, targetVariant)) return;

    const funcObj = functionsList.find(f => f.id === fl.funcId);
    if (!funcObj || fl.isConsidered === false) return;
    if (!matchesVariantFilter(funcObj.variants || funcObj.variantId, targetVariant)) return;

    const higherLevelFuncStr = funcObj.higherLevelFunc || (scope.isPFMEA ? 'Process Item Function' : 'System Function');
    const reqIds = reqMap[fl.id] || [];
    const assignedReqs = reqsList.filter(r => reqIds.includes(r.id) && matchesVariantFilter(r.variants || r.variantId, targetVariant));
    const reqTextStr = assignedReqs.length > 0 ? assignedReqs.map(r => `${r.reqNo ? r.reqNo + ': ' : ''}${r.text}`).join('; ') : '-';

    (fl.failureModes || []).forEach(fm => {
      const fmNameStr = formatCleanCellText(fm.name);
      const linkedEffIds = effMap[fm.id] || [];
      const linkedEffects = (fmeaData.libraries && fmeaData.libraries.effects || []).filter(e => linkedEffIds.includes(e.id));
      const validEffects = linkedEffects.filter(e => {
        const desc = (e.desc || e.details || e.description || e.name || '').trim();
        return desc && desc !== '-' && !desc.toLowerCase().includes('(click to edit)');
      });
      const hasValidEffect = validEffects.length > 0;
      const maxSev = hasValidEffect ? validEffects.reduce((max, e) => Math.max(max, parseInt(e.severity) || 10), 1) : 10;

      const effectsText = hasValidEffect
        ? validEffects.map((e, idx) => {
          const numPrefix = validEffects.length > 1 ? `${idx + 1}. ` : '';
          return `${numPrefix}${escapeHtml(formatCleanCellText(e.desc || e.details || e.description))} <strong>(S:${e.severity || 10})</strong>`;
        }).join('<br>')
        : '-';

      // Calculate Higher Level System Names for Column 1 (Strict 1:1 Link with Failure Effects in Column 8)
      let higherSystemCellHTML = '-';
      if (hasValidEffect) {
        higherSystemCellHTML = validEffects.map((e, idx) => {
          const numPrefix = validEffects.length > 1 ? `${idx + 1}. ` : '';
          const rawSys = (e.systemName || e.system || e.higherLevelSystem || '').trim();
          const sName = (rawSys && rawSys !== '-' && !rawSys.toLowerCase().includes('(click to edit)'))
            ? formatCleanCellText(rawSys)
            : '-';
          return `${numPrefix}${escapeHtml(sName)}`;
        }).join('<br>');
      }

      // Calculate Higher Level Function Names for Column 4 (Strict 1:1 Link with Failure Effects in Column 8)
      let higherFuncCellHTML = '-';
      if (hasValidEffect) {
        higherFuncCellHTML = validEffects.map((e, idx) => {
          const numPrefix = validEffects.length > 1 ? `${idx + 1}. ` : '';
          const rawFunc = (e.functionName || e.function || e.higherLevelFunc || '').trim();
          const fName = (rawFunc && rawFunc !== '-' && !rawFunc.toLowerCase().includes('(click to edit)'))
            ? formatCleanCellText(rawFunc)
            : '-';
          return `${numPrefix}${escapeHtml(fName)}`;
        }).join('<br>');
      }

      const linkedCauseIds = causeMap[fm.id] || [];
      const linkedCauses = (fmeaData.libraries && fmeaData.libraries.causes || []).filter(c => linkedCauseIds.includes(c.id) && matchesVariantFilter(c.variants || c.variantId, targetVariant));

      let fmTotalRows = 0;
      if (linkedCauses.length === 0) {
        fmTotalRows = 1;
      } else {
        linkedCauses.forEach(cause => {
          const actIds = causeActions[cause.id] || [];
          const linkedActions = (fmeaData.libraries && fmeaData.libraries.actions || []).filter(a => actIds.includes(a.id) && matchesVariantFilter(a.variants || a.variantId, targetVariant));
          fmTotalRows += Math.max(1, linkedActions.length);
        });
      }

      let isFirstRowForFm = true;

      if (linkedCauses.length === 0) {
        rowCounter++;
        const fallbackRpnBadge = formatAPBadge(maxSev, 1, 1, isVDA);
        const fallbackRiskStyle = getRiskRatingStyle(maxSev, 1, 1, isVDA);
        if (!isVDA) {
          // AIAG 4th Ed layout (25 Cols)
          html += `<tr>
            <td style="text-align:center; font-weight:bold; color:#64748b;">${rowCounter}</td>
            <td rowspan="${fmTotalRows}">${escapeHtml(structCellText)}</td>
            <td rowspan="${fmTotalRows}">
              <div><strong>${escapeHtml(formatCleanCellText(funcObj.name))}</strong></div>
              ${reqTextStr && reqTextStr !== '-' ? `<div style="margin-top:4px; font-size:10px; color:#0284c7; font-weight:600; text-align:left;">📌 ${escapeHtml(reqTextStr)}</div>` : ''}
            </td>
            <td rowspan="${fmTotalRows}">${escapeHtml(fmNameStr)}</td>
            <td rowspan="${fmTotalRows}">${effectsText}</td>
            <td rowspan="${fmTotalRows}" style="text-align:center; font-weight:bold; ${fallbackRiskStyle}">${maxSev}</td>
            <td>-</td>
            <td>-</td>
            <td style="text-align:center;">-</td>
            <td style="text-align:center;">ALL</td>
            <td>-</td>
            <td style="text-align:center; font-weight:bold; ${fallbackRiskStyle}">1</td>
            <td>-</td>
            <td style="text-align:center;">1</td>
            <td style="text-align:center; font-weight:bold;">${fallbackRpnBadge}</td>
            <td>-</td>
            <td style="text-align:center;">-</td>
            <td>-</td>
            <td style="text-align:center;">-</td>
            <td>-</td>
            <td style="text-align:center;">-</td>
            <td style="text-align:center;">-</td>
            <td style="text-align:center;">-</td>
            <td style="text-align:center; font-weight:bold;">-</td>
            <td rowspan="${fmTotalRows}">${escapeHtml(formatCleanCellText(fm.comments))}</td>
          </tr>`;
        } else {
          // AIAG-VDA 7-Step layout (28 Cols)
          html += `<tr>
            <td style="text-align:center; font-weight:bold; color:#64748b;">${rowCounter}</td>
            <td rowspan="${fmTotalRows}">${higherSystemCellHTML}</td>
            <td rowspan="${fmTotalRows}">${escapeHtml(structCellText)}</td>
            <td>-</td>
            <td rowspan="${fmTotalRows}">${higherFuncCellHTML}</td>
            <td rowspan="${fmTotalRows}">
              <div><strong>${escapeHtml(formatCleanCellText(funcObj.name))}</strong></div>
              ${reqTextStr && reqTextStr !== '-' ? `<div style="margin-top:4px; font-size:10px; color:#0284c7; font-weight:600; text-align:left;">📌 ${escapeHtml(reqTextStr)}</div>` : ''}
            </td>
            <td>-</td>
            <td rowspan="${fmTotalRows}">${effectsText}</td>
            <td rowspan="${fmTotalRows}" style="text-align:center; font-weight:bold; ${fallbackRiskStyle}">${maxSev}</td>
            <td rowspan="${fmTotalRows}">${escapeHtml(fmNameStr)}</td>
            <td>-</td>
            <td>-</td><td style="text-align:center; font-weight:bold; ${fallbackRiskStyle}">1</td><td>-</td><td style="text-align:center;">1</td>
            <td style="text-align:center; font-weight:bold;">${fallbackRpnBadge}</td>
            <td style="text-align:center;">-</td>
            <td>-</td><td>-</td><td>-</td><td style="text-align:center;">-</td><td style="text-align:center;">-</td><td>-</td>
            <td style="text-align:center;">-</td><td style="text-align:center;">-</td><td style="text-align:center;">-</td><td style="text-align:center;">-</td>
            <td rowspan="${fmTotalRows}">${escapeHtml(formatCleanCellText(fm.comments))}</td>
          </tr>`;
        }
        return;
      }

      linkedCauses.forEach((cause, cIdx) => {
        const causeNum = linkedCauses.length > 1 ? `${cIdx + 1}. ` : '';
        const causeDetailsStr = `${causeNum}<strong>${escapeHtml(formatCleanCellText(cause.details || ''))}</strong>`;

        const rawCauseElem = (cause.systemElement || cause.workElement || cause.processStep || '').trim();
        const causeWorkElemStr = (rawCauseElem && rawCauseElem !== '-' && !rawCauseElem.toLowerCase().includes('(click to edit)'))
          ? formatCleanCellText(rawCauseElem)
          : '-';

        const rawCauseFunc = (cause.function || cause.lowerLevelFunc || '').trim();
        const causeFuncStr = (rawCauseFunc && rawCauseFunc !== '-' && !rawCauseFunc.toLowerCase().includes('(click to edit)'))
          ? formatCleanCellText(rawCauseFunc)
          : '-';

        const ctrlIds = causeControls[cause.id] || [];
        const linkedCtrls = (fmeaData.libraries && fmeaData.libraries.controls || []).filter(c => ctrlIds.includes(c.id) && matchesVariantFilter(c.variants || c.variantId, targetVariant));
        const prevCtrls = linkedCtrls.filter(c => c.type === 'Prevention').map(c => c.desc).join('; ') || '-';
        const detCtrls = linkedCtrls.filter(c => c.type === 'Detection').map(c => c.desc).join('; ') || '-';

        const occ = parseInt(cause.occurrence) || 1;
        const det = parseInt(cause.detection) || 1;
        const rpnBadge = formatAPBadge(maxSev, occ, det, isVDA);
        const causeRiskStyle = getRiskRatingStyle(maxSev, occ, det, isVDA);
        const causeVarNames = getVariantNamesDisplay(cause.variants) || 'ALL';
        const causeClassSym = cause.classSymbol || cause.class || '-';

        const actIds = causeActions[cause.id] || [];
        const linkedActions = (fmeaData.libraries && fmeaData.libraries.actions || []).filter(a => actIds.includes(a.id) && matchesVariantFilter(a.variants || a.variantId, targetVariant));

        if (linkedActions.length === 0) {
          rowCounter++;
          if (!isVDA) {
            // AIAG 4th Ed
            html += `<tr>
              <td style="text-align:center; font-weight:bold; color:#64748b;">${rowCounter}</td>`;
            if (isFirstRowForFm) {
              html += `
              <td rowspan="${fmTotalRows}">${escapeHtml(structCellText)}</td>
              <td rowspan="${fmTotalRows}">
                <div><strong>${escapeHtml(formatCleanCellText(funcObj.name))}</strong></div>
                ${reqTextStr && reqTextStr !== '-' ? `<div style="margin-top:4px; font-size:10px; color:#0284c7; font-weight:600; text-align:left;">📌 ${escapeHtml(reqTextStr)}</div>` : ''}
              </td>
              <td rowspan="${fmTotalRows}">${escapeHtml(fmNameStr)}</td>
              <td rowspan="${fmTotalRows}">${effectsText}</td>
              <td rowspan="${fmTotalRows}" style="text-align:center; font-weight:bold; ${causeRiskStyle}">${maxSev}</td>`;
            }
            const causeFullText = `${causeDetailsStr}${causeFuncStr !== '-' ? '<br/><span style="color:#64748b; font-size:10px;">Func: ' + escapeHtml(causeFuncStr) + '</span>' : ''}`;
            html += `
              <td>${causeFullText}</td>
              <td>${escapeHtml(formatCleanCellText(cause.characteristics || cause.characteristic || cause.spec || '-'))}</td>
              <td style="text-align:center;">${escapeHtml(causeClassSym)}</td>
              <td style="text-align:center;">${escapeHtml(causeVarNames)}</td>
              <td>${escapeHtml(prevCtrls)}</td>
              <td style="text-align:center; font-weight:bold; ${causeRiskStyle}">${occ}</td>
              <td>${escapeHtml(detCtrls)}</td>
              <td style="text-align:center;">${det}</td>
              <td style="text-align:center; font-weight:bold;">${rpnBadge}</td>
              <td>-</td>
              <td style="text-align:center;">-</td>
              <td>-</td>
              <td style="text-align:center;">-</td>
              <td>-</td>
              <td style="text-align:center;">-</td>
              <td style="text-align:center;">-</td>
              <td style="text-align:center;">-</td>
              <td style="text-align:center; font-weight:bold;">-</td>`;
            if (isFirstRowForFm) {
              html += `<td rowspan="${fmTotalRows}">${escapeHtml(formatCleanCellText(fm.comments))}</td>`;
              isFirstRowForFm = false;
            }
            html += `</tr>`;
          } else {
            // AIAG-VDA 7-Step
            html += `<tr>
              <td style="text-align:center; font-weight:bold; color:#64748b;">${rowCounter}</td>`;
            if (isFirstRowForFm) {
              html += `
              <td rowspan="${fmTotalRows}">${higherSystemCellHTML}</td>
              <td rowspan="${fmTotalRows}">${escapeHtml(structCellText)}</td>`;
            }
            html += `<td>${escapeHtml(causeWorkElemStr)}</td>`;
            if (isFirstRowForFm) {
              html += `
              <td rowspan="${fmTotalRows}">${higherFuncCellHTML}</td>
              <td rowspan="${fmTotalRows}">
                <div><strong>${escapeHtml(formatCleanCellText(funcObj.name))}</strong></div>
                ${reqTextStr && reqTextStr !== '-' ? `<div style="margin-top:4px; font-size:10px; color:#0284c7; font-weight:600; text-align:left;">📌 ${escapeHtml(reqTextStr)}</div>` : ''}
              </td>`;
            }
            html += `<td>${escapeHtml(causeFuncStr)}</td>`;
            if (isFirstRowForFm) {
              html += `
              <td rowspan="${fmTotalRows}">${effectsText}</td>
              <td rowspan="${fmTotalRows}" style="text-align:center; font-weight:bold; ${causeRiskStyle}">${maxSev}</td>
              <td rowspan="${fmTotalRows}">${escapeHtml(fmNameStr)}</td>`;
            }
            html += `
              <td>${causeDetailsStr}</td>
              <td>${escapeHtml(prevCtrls)}</td>
              <td style="text-align:center; font-weight:bold; ${causeRiskStyle}">${occ}</td>
              <td>${escapeHtml(detCtrls)}</td>
              <td style="text-align:center;">${det}</td>
              <td style="text-align:center; font-weight:bold;">${rpnBadge}</td>
              <td style="text-align:center;">${escapeHtml(causeClassSym)}</td>
              <td>-</td><td>-</td><td>-</td><td style="text-align:center;">-</td><td style="text-align:center;">-</td><td>-</td>
              <td style="text-align:center;">-</td><td style="text-align:center;">-</td><td style="text-align:center;">-</td><td style="text-align:center;">-</td>`;
            if (isFirstRowForFm) {
              html += `<td rowspan="${fmTotalRows}">${escapeHtml(formatCleanCellText(fm.comments))}</td>`;
              isFirstRowForFm = false;
            }
            html += `</tr>`;
          }
        } else {
          linkedActions.forEach(act => {
            rowCounter++;
            const s2 = parseInt(act.s2) || maxSev;
            const o2 = parseInt(act.o2) || occ;
            const d2 = parseInt(act.d2) || det;
            const actDetailStr = formatCleanCellText(act.detail || act.desc || act.actionDetails || '');
            const isPreventive = (act.type === 'Prevention' || act.actionType === 'Prevention');
            const prevActStr = isPreventive ? actDetailStr : '-';
            const detActStr = !isPreventive ? actDetailStr : '-';
            const rpn2Badge = actDetailStr !== '-' ? formatAPBadge(s2, o2, d2, isVDA) : '-';
            const actRiskStyle = actDetailStr !== '-' ? getRiskRatingStyle(s2, o2, d2, isVDA) : '';
            const actStatusStr = act.status || (act.completionDate ? 'Passed' : (actDetailStr !== '-' ? 'Planned' : '-'));
            const actTakenStr = actDetailStr !== '-' ? (act.actionTaken ? act.actionTaken + (act.completionDate ? ' (' + act.completionDate + ')' : '') : '-') : '-';

            if (!isVDA) {
              // AIAG 4th Ed
              html += `<tr>
                <td style="text-align:center; font-weight:bold; color:#64748b;">${rowCounter}</td>`;
              if (isFirstRowForFm) {
                html += `
                <td rowspan="${fmTotalRows}">${escapeHtml(structCellText)}</td>
                <td rowspan="${fmTotalRows}">
                  <div><strong>${escapeHtml(formatCleanCellText(funcObj.name))}</strong></div>
                  ${reqTextStr && reqTextStr !== '-' ? `<div style="margin-top:4px; font-size:10px; color:#0284c7; font-weight:600; text-align:left;">📌 ${escapeHtml(reqTextStr)}</div>` : ''}
                </td>
                <td rowspan="${fmTotalRows}">${escapeHtml(fmNameStr)}</td>
                <td rowspan="${fmTotalRows}">${effectsText}</td>
                <td rowspan="${fmTotalRows}" style="text-align:center; font-weight:bold; ${causeRiskStyle}">${maxSev}</td>`;
              }
              const causeFullText = `${causeDetailsStr}${causeFuncStr !== '-' ? '<br/><span style="color:#64748b; font-size:10px;">Func: ' + escapeHtml(causeFuncStr) + '</span>' : ''}`;
              html += `
                <td>${causeFullText}</td>
                <td>${escapeHtml(formatCleanCellText(cause.characteristics || cause.characteristic || cause.spec || '-'))}</td>
                <td style="text-align:center;">${escapeHtml(causeClassSym)}</td>
                <td style="text-align:center;">${escapeHtml(causeVarNames)}</td>
                <td>${escapeHtml(prevCtrls)}</td>
                <td style="text-align:center; font-weight:bold; ${causeRiskStyle}">${occ}</td>
                <td>${escapeHtml(detCtrls)}</td>
                <td style="text-align:center;">${det}</td>
                <td style="text-align:center; font-weight:bold;">${rpnBadge}</td>
                <td>${escapeHtml(actDetailStr)}</td>
                <td style="text-align:center;">${isPreventive ? 'P' : (actDetailStr !== '-' ? 'D' : '-')}</td>
                <td>${actDetailStr !== '-' ? escapeHtml(act.responsible || '-') : '-'}</td>
                <td style="text-align:center;">${actDetailStr !== '-' ? (act.targetDate || '-') : '-'}</td>
                <td>${escapeHtml(actTakenStr)}</td>
                <td style="text-align:center; font-weight:bold; ${actRiskStyle}">${actDetailStr !== '-' ? s2 : '-'}</td>
                <td style="text-align:center; font-weight:bold; ${actRiskStyle}">${actDetailStr !== '-' ? o2 : '-'}</td>
                <td style="text-align:center;">${actDetailStr !== '-' ? d2 : '-'}</td>
                <td style="text-align:center; font-weight:bold;">${rpn2Badge}</td>`;
              if (isFirstRowForFm) {
                html += `<td rowspan="${fmTotalRows}">${escapeHtml(formatCleanCellText(act.comments || fm.comments))}</td>`;
                isFirstRowForFm = false;
              }
              html += `</tr>`;
            } else {
              // AIAG-VDA 7-Step
              html += `<tr>
                <td style="text-align:center; font-weight:bold; color:#64748b;">${rowCounter}</td>`;
              if (isFirstRowForFm) {
                html += `
                <td rowspan="${fmTotalRows}">${higherSystemCellHTML}</td>
                <td rowspan="${fmTotalRows}">${escapeHtml(structCellText)}</td>`;
              }
              html += `<td>${escapeHtml(causeWorkElemStr)}</td>`;
              if (isFirstRowForFm) {
                html += `
                <td rowspan="${fmTotalRows}">${higherFuncCellHTML}</td>
                <td rowspan="${fmTotalRows}">
                  <div><strong>${escapeHtml(formatCleanCellText(funcObj.name))}</strong></div>
                  ${reqTextStr && reqTextStr !== '-' ? `<div style="margin-top:4px; font-size:10px; color:#0284c7; font-weight:600; text-align:left;">📌 ${escapeHtml(reqTextStr)}</div>` : ''}
                </td>`;
              }
              html += `<td>${escapeHtml(causeFuncStr)}</td>`;
              if (isFirstRowForFm) {
                html += `
                <td rowspan="${fmTotalRows}">${effectsText}</td>
                <td rowspan="${fmTotalRows}" style="text-align:center; font-weight:bold; ${causeRiskStyle}">${maxSev}</td>
                <td rowspan="${fmTotalRows}">${escapeHtml(fmNameStr)}</td>`;
              }
              html += `
                <td>${causeDetailsStr}</td>
                <td>${escapeHtml(prevCtrls)}</td>
                <td style="text-align:center; font-weight:bold; ${causeRiskStyle}">${occ}</td>
                <td>${escapeHtml(detCtrls)}</td>
                <td style="text-align:center;">${det}</td>
                <td style="text-align:center; font-weight:bold;">${rpnBadge}</td>
                <td style="text-align:center;">${escapeHtml(causeClassSym)}</td>
                <td>${escapeHtml(prevActStr)}</td>
                <td>${escapeHtml(detActStr)}</td>
                <td>${actDetailStr !== '-' ? escapeHtml(act.responsible || '-') : '-'}</td>
                <td style="text-align:center;">${actDetailStr !== '-' ? (act.targetDate || '-') : '-'}</td>
                <td style="text-align:center;">${actDetailStr !== '-' ? escapeHtml(actStatusStr) : '-'}</td>
                <td>${escapeHtml(actTakenStr)}</td>
                <td style="text-align:center; font-weight:bold; ${actRiskStyle}">${actDetailStr !== '-' ? s2 : '-'}</td>
                <td style="text-align:center; font-weight:bold; ${actRiskStyle}">${actDetailStr !== '-' ? o2 : '-'}</td>
                <td style="text-align:center;">${actDetailStr !== '-' ? d2 : '-'}</td>
                <td style="text-align:center; font-weight:bold;">${rpn2Badge}</td>`;
              if (isFirstRowForFm) {
                html += `<td rowspan="${fmTotalRows}">${escapeHtml(formatCleanCellText(act.comments || fm.comments))}</td>`;
                isFirstRowForFm = false;
              }
              html += `</tr>`;
            }
          });
        }
      });
    });
  });

  return html;
}

async function exportToExcel(nodeIds, targetScopes, targetVariant) {
  if (!targetScopes || targetScopes.length === 0) {
    const selectedScopeVals = getSelectedScopeValues('exportScopeMultiSelectContainer');
    targetScopes = resolveSelectedScopes(selectedScopeVals);
  }
  if (!targetVariant) {
    const varSelect = document.getElementById('exportVariantSelect');
    targetVariant = varSelect ? varSelect.value : (typeof selectedVariantFilter !== 'undefined' ? selectedVariantFilter : 'ALL');
  }

  const isVDA = (fmeaData.methodologyMode === 'AIAG-VDA');

  let html = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
  <head><meta charset="utf-8"/><style>
    table { border-collapse: collapse; width: 100%; font-family: Arial, sans-serif; font-size: 11px; margin-bottom: 20px; }
    th { background-color: #1e293b; color: #ffffff; border: 1px solid #475569; padding: 6px; text-align: center; font-size: 10px; }
    td { border: 1px solid #cbd5e1; padding: 5px; vertical-align: top; }
  </style></head>
  <body>`;

  targetScopes.forEach(scope => {
    const rowsHtml = buildScopeTableRowsHTML(scope, nodeIds, targetVariant);
    const headerBlock = getAiagVdaHeaderHTML(scope, false);
    const varDisplay = targetVariant && targetVariant !== 'ALL' ? ` (Variant: ${escapeHtml(targetVariant)})` : '';
    const isPFMEA = scope.isPFMEA;

    html += `
    <div style="margin-bottom:20px;">
      ${headerBlock}
      ${varDisplay ? `<div style="font-weight:bold; font-size:11px; margin-bottom:6px; color:#1e293b;">🔍 ${varDisplay}</div>` : ''}
      <table>
        ${getScopeTableHeaderHTML(isVDA, isPFMEA)}
        <tbody>
          ${rowsHtml || `<tr><td colspan="${isVDA ? 29 : 26}" style="text-align:center; padding:15px;">No FMEA items defined for ${escapeHtml(scope.name || 'Scope')}${varDisplay}.</td></tr>`}
        </tbody>
      </table>
    </div><br/>`;
  });

  html += `</body></html>`;

  const fileName = `AIAG_VDA_FMEA_Report_${new Date().toISOString().slice(0, 10)}.xls`;

  if (window.electronAPI && window.electronAPI.isElectron) {
    try {
      const saveFn = window.electronAPI.showSaveDialog || window.electronAPI.saveDialog;
      const saveRes = await saveFn(fileName);
      if (saveRes && !saveRes.canceled && saveRes.filePath) {
        const writeRes = await window.electronAPI.writeFile(saveRes.filePath, html);
        if (writeRes && writeRes.success !== false) {
          showToast(`📊 Exported FMEA Excel report to: ${saveRes.filePath}`);
        } else {
          alert(`Error saving Excel file: ${writeRes ? writeRes.error : 'Unknown error'}`);
        }
        return;
      }
    } catch (e) {
      console.warn("Electron Excel save fallback:", e);
    }
  }

  const blob = new Blob([html], { type: 'application/vnd.ms-excel;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  a.remove();
  showToast(`📊 Downloaded FMEA Excel report!`);
}

function getInsightsExportDataset() {
  const selectedScopeVals = getSelectedScopeValues('dashScopeMultiSelectContainer');
  const targetScopes = resolveSelectedScopes(selectedScopeVals);
  const variantFilter = document.getElementById('dashVariantSelect')?.value || 'ALL';

  fmeaData.rpnSettings = fmeaData.rpnSettings || { mode: 'AIAG', highThreshold: 100, medThreshold: 80 };
  const rpnCriteriaMode = document.getElementById('dashRpnCriteriaSelect')?.value || fmeaData.rpnSettings.mode || 'AIAG';
  const rpnHighThreshold = parseInt(document.getElementById('dashRpnHighThresholdInput')?.value) || fmeaData.rpnSettings.highThreshold || 100;
  const rpnMedThreshold = parseInt(document.getElementById('dashRpnMedThresholdInput')?.value) || fmeaData.rpnSettings.medThreshold || 80;

  const libraries = fmeaData.libraries || {};
  const allEffects = libraries.effects || [];
  const allCauses = libraries.causes || [];
  const allActions = libraries.actions || [];
  const todayStr = new Date().toISOString().slice(0, 10);

  const itemsList = [];
  const actionsList = [];
  const processedActionIds = new Set();

  let totalItemsCount = 0;
  let currentHighCount = 0, currentMedCount = 0, currentLowCount = 0;

  targetScopes.forEach(scope => {
    const scopeName = scope.name || (scope.isPFMEA ? 'PFMEA' : 'DFMEA');
    const fmeaType = scope.isPFMEA ? 'PFMEA' : 'DFMEA';
    const fls = scope.functionLines || [];
    const effMap = scope.failureModeEffects || fmeaData.failureModeEffects || {};
    const causeMap = scope.failureModeCauses || fmeaData.failureModeCauses || {};
    const causeActionsMap = scope.causeActions || fmeaData.causeActions || {};

    fls.forEach(fl => {
      if (variantFilter !== 'ALL') {
        const flVars = Array.isArray(fl.variantId) ? fl.variantId : [fl.variantId];
        if (!flVars.includes('ALL') && !flVars.includes(variantFilter)) return;
      }

      const processOrFunction = (fl.functionName || fl.processName || fl.elementName || fl.name || 'General Process').trim();

      (fl.failureModes || []).forEach(fm => {
        const fmName = (fm.name || fm.failureModeName || 'General Failure Mode').trim();
        const linkedEffIds = effMap[fm.id] || [];
        let linkedEffects = allEffects.filter(e => linkedEffIds.includes(e.id));
        if (linkedEffects.length === 0 && (fm.effects || []).length > 0) linkedEffects = fm.effects;

        const validEffects = linkedEffects.filter(e => {
          const desc = (e.desc || e.details || e.description || e.name || '').trim();
          return desc && desc !== '-' && !desc.toLowerCase().includes('(click to edit)');
        });
        if (validEffects.length === 0) return; // Exclude items without linked effect

        const effectDesc = validEffects.map(e => e.description || e.desc || e.name || '').filter(Boolean).join('; ') || 'No Effect Specified';
        const s1 = validEffects.reduce((max, e) => Math.max(max, parseInt(e.severity) || 10), 1);

        const linkedCauseIds = causeMap[fm.id] || [];
        let linkedCauses = allCauses.filter(c => linkedCauseIds.includes(c.id));
        if (linkedCauses.length === 0 && (fm.causes || []).length > 0) linkedCauses = fm.causes;

        const validCauses = linkedCauses.filter(c => {
          const detail = (c.details || c.desc || c.description || c.name || '').trim();
          return detail && detail !== '-' && !detail.toLowerCase().includes('(click to edit)');
        });
        if (validCauses.length === 0) return; // Exclude items without linked cause

        validCauses.forEach(c => {
          totalItemsCount++;
          const causeDesc = (c.details || c.description || c.name || 'No Cause Specified').trim();
          const o1 = parseInt(c.occurrence) || 10;
          const d1 = parseInt(c.detection) || 10;
          const rpn1 = s1 * o1 * d1;
          const ap1 = computeAP(s1, o1, d1);

          const currentCat = evalRiskCategory(s1, rpn1, rpnHighThreshold, rpnMedThreshold, 40);
          if ((activeDashboardMode === 'AIAG' && currentCat === 'H') || (activeDashboardMode !== 'AIAG' && ap1 === 'H')) currentHighCount++;
          else if ((activeDashboardMode === 'AIAG' && currentCat === 'M') || (activeDashboardMode !== 'AIAG' && ap1 === 'M')) currentMedCount++;
          else currentLowCount++;

          const directActions = c.recommendedActions || c.actions || (c.recommendedAction ? [c.recommendedAction] : []);
          const actIds = causeActionsMap[c.id] || [];
          const libraryActions = allActions.filter(a => actIds.includes(a.id));

          const combinedActList = [...directActions];
          libraryActions.forEach(la => {
            if (!combinedActList.some(da => da.id === la.id)) combinedActList.push(la);
          });

          const validActList = combinedActList.filter(act => {
            const detail = (act.detail || act.details || act.name || act.actionDetails || act.desc || '').trim();
            return detail && detail.toLowerCase() !== 'recommended action' && !detail.toLowerCase().includes('(click to edit)');
          });

          let actDetail = '', actOwner = '', targetDate = '', actTaken = '', compDate = '', actStatus = 'None';
          let s2 = s1, o2 = o1, d2 = d1, rpn2 = rpn1, ap2 = ap1;

          if (validActList.length > 0) {
            const act = validActList[0];
            actDetail = (act.detail || act.details || act.name || act.actionDetails || act.desc || '').trim();
            actOwner = (act.responsible || act.owner || act.respPerson || act.assignee || 'Unassigned').trim();
            targetDate = act.targetDate || act.target_date || 'TBD';
            actTaken = act.actionTaken || act.notes || act.remarks || act.comment || '-';
            compDate = act.completionDate || act.completion_date || '-';

            const rawStatus = act.status || (act.completionDate ? 'Passed' : 'Planned');
            const isOverdue = act.targetDate && act.targetDate < todayStr && rawStatus !== 'Passed' && rawStatus !== 'Completed';
            actStatus = isOverdue ? 'Overdue' : rawStatus;

            s2 = parseInt(act.revisedSev || act.s2) || s1;
            o2 = parseInt(act.revisedOcc || act.o2) || o1;
            d2 = parseInt(act.revisedDet || act.d2) || d1;
            rpn2 = s2 * o2 * d2;
            ap2 = computeAP(s2, o2, d2);

            validActList.forEach(aItem => {
              const aKey = aItem.id || `${scopeName}_${fmName}_${actDetail.toLowerCase()}`;
              if (!processedActionIds.has(aKey)) {
                processedActionIds.add(aKey);
                actionsList.push({
                  actionId: aKey,
                  scopeName: scopeName,
                  fmeaType: fmeaType,
                  failureMode: fmName,
                  actionDetails: (aItem.detail || aItem.details || aItem.name || '').trim(),
                  owner: (aItem.responsible || aItem.owner || 'Unassigned').trim(),
                  targetDate: aItem.targetDate || 'TBD',
                  actionTaken: aItem.actionTaken || '-',
                  completionDate: aItem.completionDate || '-',
                  status: aItem.targetDate && aItem.targetDate < todayStr && aItem.status !== 'Passed' && aItem.status !== 'Completed' ? 'Overdue' : (aItem.status || 'Planned')
                });
              }
            });
          }

          itemsList.push({
            Scope_Name: scopeName,
            FMEA_Type: fmeaType,
            Process_Function: processOrFunction,
            Failure_Mode: fmName,
            Effect_Details: effectDesc,
            Cause_Details: causeDesc,
            Severity_S1: s1,
            Occurrence_O1: o1,
            Detection_D1: d1,
            RPN_1: rpn1,
            AP_1: ap1,
            Risk_Level_1: currentCat === 'H' ? 'High' : (currentCat === 'M' ? 'Medium' : 'Low'),
            Action_Details: actDetail || 'None',
            Action_Owner: actOwner || 'Unassigned',
            Target_Date: targetDate || 'TBD',
            Action_Taken: actTaken || '-',
            Completion_Date: compDate || '-',
            Action_Status: actStatus,
            Revised_S2: s2,
            Revised_O2: o2,
            Revised_D2: d2,
            RPN_2: rpn2,
            AP_2: ap2
          });
        });
      });
    });
  });

  return {
    metadata: {
      exportedAt: new Date().toISOString(),
      activeDashboardMode: activeDashboardMode,
      selectedScopes: targetScopes.map(s => s.name || (s.isPFMEA ? 'PFMEA' : 'DFMEA')),
      variantFilter: variantFilter,
      rpnCriteria: { mode: rpnCriteriaMode, highThreshold: rpnHighThreshold, medThreshold: rpnMedThreshold }
    },
    summaryMetrics: {
      totalItemsEvaluated: totalItemsCount,
      riskDistribution: { high: currentHighCount, medium: currentMedCount, low: currentLowCount },
      totalRegisteredActions: actionsList.length
    },
    riskItems: itemsList,
    actionsList: actionsList
  };
}

