async function exportDashboardInsightsToExcel() {
  const dataset = getInsightsExportDataset();
  const items = dataset.riskItems;

  if (!items || items.length === 0) {
    alert("No risk items available to export.");
    return;
  }

  const headers = Object.keys(items[0]);
  const csvRows = [];
  csvRows.push(headers.join('\t'));

  items.forEach(item => {
    const row = headers.map(h => {
      let val = item[h] !== undefined && item[h] !== null ? String(item[h]) : '';
      val = val.replace(/\r?\n|\r/g, ' ').replace(/\t/g, ' ');
      return val;
    });
    csvRows.push(row.join('\t'));
  });

  const fileContent = csvRows.join('\n');
  const fileName = `JOST_FMEA_Dashboard_Insights_${new Date().toISOString().slice(0, 10)}.xls`;

  if (window.electronAPI && window.electronAPI.isElectron) {
    try {
      const saveFn = window.electronAPI.showSaveDialog || window.electronAPI.saveDialog;
      const saveRes = await saveFn(fileName);
      if (saveRes && !saveRes.canceled && saveRes.filePath) {
        await window.electronAPI.writeFile(saveRes.filePath, fileContent);
        showToast(`📊 Exported PowerBI Excel/CSV Insights to [${saveRes.filePath}]`);
        return;
      }
    } catch (e) {
      console.warn("Electron save dialog fallback:", e);
    }
  }

  const blob = new Blob(['\ufeff' + fileContent], { type: 'application/vnd.ms-excel;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  a.remove();
  showToast(`📊 Downloaded PowerBI Excel/CSV Insights file!`);
}

