function unlockApplicationPointerEvents() {
  document.querySelectorAll('.nav-dropdown').forEach(m => {
    m.style.display = 'none';
  });
  if (document.activeElement && document.activeElement !== document.body) {
    try { document.activeElement.blur(); } catch (e) { }
  }
  document.body.style.pointerEvents = 'auto';

  const ws = document.getElementById('appWorkspaceWrapper') || document.body;
  if (ws) {
    const prevPos = ws.style.position;
    ws.style.position = 'relative';
    ws.offsetHeight;
    ws.style.position = prevPos;
  }

  window.dispatchEvent(new Event('resize'));
  try {
    window.dispatchEvent(new MouseEvent('mousemove', { bubbles: true, clientX: 10, clientY: 10 }));
  } catch (e) { }
}

window.addEventListener('focus', unlockApplicationPointerEvents);
window.addEventListener('afterprint', unlockApplicationPointerEvents);

function executeHtmlPrint(htmlContent) {
  const cleanHtml = htmlContent.replace(/<script>[\s\S]*?window\.print\(\);[\s\S]*?<\/script>/gi, '');

  let printIframe = document.getElementById('appPrintIframe');
  if (!printIframe) {
    printIframe = document.createElement('iframe');
    printIframe.id = 'appPrintIframe';
    printIframe.name = 'appPrintIframe';
    printIframe.style.position = 'fixed';
    printIframe.style.right = '0';
    printIframe.style.bottom = '0';
    printIframe.style.width = '1px';
    printIframe.style.height = '1px';
    printIframe.style.border = '0';
    printIframe.style.opacity = '0.01';
    printIframe.style.pointerEvents = 'none';
    document.body.appendChild(printIframe);
  }

  const iframeWin = printIframe.contentWindow;
  const iframeDoc = iframeWin.document;

  iframeDoc.open();
  iframeDoc.write(cleanHtml);
  iframeDoc.close();

  let printed = false;
  const doPrint = () => {
    if (printed) return;
    printed = true;
    try {
      iframeWin.focus();
      iframeWin.print();
    } catch (e) {
      console.warn("Print execution notice:", e);
    } finally {
      setTimeout(unlockApplicationPointerEvents, 100);
      setTimeout(unlockApplicationPointerEvents, 400);
    }
  };

  if (iframeDoc.readyState === 'complete') {
    setTimeout(doPrint, 250);
  } else {
    printIframe.onload = () => setTimeout(doPrint, 250);
    setTimeout(doPrint, 500);
  }
}

let activeModalStackZIndex = 100000;

function openModal(id) {
  const modal = document.getElementById(id);
  if (!modal) return;

  // Ensure modal is attached to document.body
  if (modal.parentElement !== document.body) {
    document.body.appendChild(modal);
  }

  // Elevate z-index above failureNetworkModal (which is 9999999) if it is open
  const fnModal = document.getElementById('failureNetworkModal');
  if (fnModal && fnModal.style.display !== 'none' && id !== 'failureNetworkModal') {
    activeModalStackZIndex = Math.max(activeModalStackZIndex, 10000050);
  }

  // Calculate dynamic z-index so stacked modals always appear on top
  activeModalStackZIndex += 10;
  modal.style.zIndex = activeModalStackZIndex;
  modal.style.display = 'flex';

  setTimeout(() => {
    const input = modal.querySelector('input:not([type="hidden"]), select, textarea, button');
    if (input) input.focus();
  }, 50);
}

function closeModal(id) {
  const modal = document.getElementById(id);
  if (!modal) return;
  if (document.activeElement && modal.contains(document.activeElement)) {
    document.activeElement.blur();
  }
  modal.style.display = 'none';
  window.focus();
  requestAnimationFrame(() => {
    window.dispatchEvent(new Event('resize'));
  });
}
function escapeHtml(str) {
  if (!str) return '';
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function escapeXml(str) { return escapeHtml(str); }

function showToast(message, duration = 3000) {
  let container = document.getElementById('toastContainer');
  if (!container) {
    container = document.createElement('div');
    container.id = 'toastContainer';
    container.style.cssText = 'position:fixed; bottom:20px; right:20px; z-index:2000000 !important; display:flex; flex-direction:column; gap:8px; pointer-events:none;';
    document.body.appendChild(container);
  } else {
    container.style.zIndex = '2000000';
  }

  const toast = document.createElement('div');
  toast.style.cssText = 'background:#0f172a; color:#ffffff; border:1px solid #3b82f6; border-left:5px solid #10b981; border-radius:8px; padding:12px 18px; font-size:13px; font-weight:600; box-shadow:0 12px 30px rgba(0,0,0,0.5); transition:all 0.3s ease; opacity:0; transform:translateY(10px); pointer-events:auto;';
  toast.textContent = message;

  container.appendChild(toast);

  setTimeout(() => {
    toast.style.opacity = '1';
    toast.style.transform = 'translateY(0)';
  }, 10);

  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(10px)';
    setTimeout(() => toast.remove(), 300);
  }, duration);
}

function evalRiskCategory(s, rpn, highThreshold = 100, medThreshold = 80, sevHighRpnThreshold = 40) {
  s = parseInt(s) || 1;
  rpn = parseInt(rpn) || 1;

  if (s >= 9) {
    if (rpn > sevHighRpnThreshold) return 'H';
    return 'L';
  } else {
    if (rpn > highThreshold) return 'H';
    if (rpn > medThreshold && rpn <= highThreshold) return 'M';
    return 'L';
  }
}

function populateFmeaScopeCheckboxDropdown(containerId, callbackFuncName) {
  const container = document.getElementById(containerId);
  if (!container) return;

  const activeCtx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : { isPFMEA: false };
  const activeName = activeCtx.isPFMEA ? `Active PFMEA: ${activeCtx.pfmea?.name || ''}` : 'Active DFMEA Master';

  let currentValues = [];
  if (container.dataset.selectedValues) {
    try { currentValues = JSON.parse(container.dataset.selectedValues); } catch (e) { }
  }
  if (!currentValues || currentValues.length === 0) {
    currentValues = ['ACTIVE'];
  }
  const selectedSet = new Set(currentValues);

  const optionsList = [
    { value: 'ACTIVE', label: `📍 ${activeName}` },
    { value: 'DFMEA', label: '🚗 DFMEA Master Only' }
  ];

  const pfmeas = fmeaData.pfmeas || [];
  if (pfmeas.length > 0) {
    optionsList.push({ isGroupHeader: true, label: 'Process FMEAs (PFMEAs)' });
    optionsList.push({ value: 'ALL_PFMEA', label: `🏭 All PFMEAs (${pfmeas.length})` });
    pfmeas.forEach(p => {
      optionsList.push({ value: `PFMEA_${p.id}`, label: `🏭 PFMEA: ${p.name}` });
    });
  }

  optionsList.push({ isGroupHeader: true, label: 'Entire Project' });
  optionsList.push({ value: 'ALL', label: '🌐 Entire Project (DFMEA + PFMEAs)' });

  let btnLabel = '📍 ' + activeName;
  if (selectedSet.has('ALL')) {
    btnLabel = '🌐 Entire Project (DFMEA + PFMEAs)';
  } else if (selectedSet.size === 1) {
    const singleVal = Array.from(selectedSet)[0];
    const match = optionsList.find(o => o.value === singleVal);
    if (match) btnLabel = match.label;
  } else if (selectedSet.size > 1) {
    btnLabel = `${selectedSet.size} Scopes Selected`;
  }

  let menuHtml = `
    <div style="position:relative; display:inline-block;">
      <button type="button" class="scope-dropdown-btn" onclick="toggleScopeDropdownMenu('${containerId}')" style="padding:4px 10px; font-size:11px; border:1px solid #cbd5e1; border-radius:4px; background:#ffffff; font-weight:bold; cursor:pointer; display:flex; align-items:center; justify-content:space-between; min-width:210px; height:32px; color:#1e293b;">
        <span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:180px;">${escapeHtml(btnLabel)}</span>
        <span style="font-size:9px; color:#64748b; margin-left:6px;">▼</span>
      </button>
      <div id="${containerId}_menu" class="scope-dropdown-menu" style="display:none; position:absolute; top:100%; left:0; z-index:1000; background:#ffffff; border:1px solid #cbd5e1; border-radius:6px; box-shadow:0 10px 25px rgba(0,0,0,0.15); width:270px; max-height:260px; overflow-y:auto; padding:6px 0; margin-top:4px;">
  `;

  optionsList.forEach(opt => {
    if (opt.isGroupHeader) {
      menuHtml += `<div style="font-size:10px; font-weight:bold; color:#64748b; padding:6px 12px 2px 12px; text-transform:uppercase; background:#f8fafc; border-top:1px solid #e2e8f0; border-bottom:1px solid #e2e8f0; margin:4px 0 2px 0;">${escapeHtml(opt.label)}</div>`;
    } else {
      const checked = selectedSet.has(opt.value) ? 'checked' : '';
      menuHtml += `
        <label style="display:flex; align-items:center; gap:8px; padding:6px 12px; font-size:12px; color:#334155; cursor:pointer; user-select:none; transition:background 0.15s;" onmouseover="this.style.background='#f1f5f9'" onmouseout="this.style.background='transparent'">
          <input type="checkbox" class="scope-chk-item" value="${escapeHtml(opt.value)}" ${checked} onchange="handleScopeCheckboxChange('${containerId}', '${callbackFuncName}')" style="cursor:pointer; accent-color:#3b82f6;">
          <span style="font-weight:${checked ? '600' : 'normal'};">${escapeHtml(opt.label)}</span>
        </label>
      `;
    }
  });

  menuHtml += `
      </div>
    </div>
  `;

  container.innerHTML = menuHtml;
  container.dataset.selectedValues = JSON.stringify(Array.from(selectedSet));
}

function populateFmeaScopeDropdown(containerOrSelectId) {
  const containerId = containerOrSelectId === 'dvpFmeaScopeSelect' ? 'dvpScopeMultiSelectContainer' : (containerOrSelectId === 'dashFmeaScopeSelect' ? 'dashScopeMultiSelectContainer' : containerOrSelectId);
  const callbackName = containerId.includes('dvp') ? 'renderDvpTable' : 'renderInsightsDashboard';
  populateFmeaScopeCheckboxDropdown(containerId, callbackName);
}

function toggleScopeDropdownMenu(containerId) {
  const menu = document.getElementById(`${containerId}_menu`);
  if (!menu) return;
  const isHidden = menu.style.display === 'none';
  document.querySelectorAll('.scope-dropdown-menu').forEach(m => m.style.display = 'none');
  if (isHidden) {
    menu.style.display = 'block';
  }
}

function handleScopeCheckboxChange(containerId, callbackFuncName) {
  const container = document.getElementById(containerId);
  if (!container) return;

  const checkedBoxes = Array.from(container.querySelectorAll('.scope-chk-item:checked')).map(c => c.value);
  container.dataset.selectedValues = JSON.stringify(checkedBoxes);

  const btnSpan = container.querySelector('.scope-dropdown-btn span');
  if (btnSpan) {
    if (checkedBoxes.includes('ALL')) {
      btnSpan.textContent = '🌐 Entire Project (DFMEA + PFMEAs)';
    } else if (checkedBoxes.length === 1) {
      const singleChk = container.querySelector(`.scope-chk-item[value="${checkedBoxes[0]}"]`);
      const labelText = singleChk ? singleChk.parentElement.textContent.trim() : checkedBoxes[0];
      btnSpan.textContent = labelText;
    } else if (checkedBoxes.length > 1) {
      btnSpan.textContent = `${checkedBoxes.length} Scopes Selected`;
    } else {
      btnSpan.textContent = 'Select Scopes';
    }
  }

  if (typeof window[callbackFuncName] === 'function') {
    window[callbackFuncName]();
  }
}

function getSelectedScopeValues(containerId) {
  const container = document.getElementById(containerId);
  if (container && container.dataset.selectedValues) {
    try {
      const vals = JSON.parse(container.dataset.selectedValues);
      if (Array.isArray(vals) && vals.length > 0) return vals;
    } catch (e) { }
  }
  return ['ACTIVE'];
}

document.addEventListener('click', function (e) {
  if (!e.target.closest('.custom-multiselect')) {
    document.querySelectorAll('.scope-dropdown-menu').forEach(m => m.style.display = 'none');
  }
});

function resolveSelectedScopes(selectedValues) {
  let values = Array.isArray(selectedValues) ? selectedValues : [selectedValues];
  if (values.length === 0) values = ['ACTIVE'];

  const ctx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : { isPFMEA: false };
  let targetScopes = [];
  const addedKeys = new Set();

  values.forEach(val => {
    if (val === 'ALL') {
      if (!addedKeys.has('DFMEA')) {
        addedKeys.add('DFMEA');
        targetScopes.push({
          isPFMEA: false,
          name: 'DFMEA Master',
          functions: fmeaData.functions || [],
          requirements: fmeaData.requirements || [],
          functionRequirements: fmeaData.functionRequirements || {},
          functionLines: fmeaData.functionLines || [],
          failureModeEffects: fmeaData.failureModeEffects || {},
          failureModeCauses: fmeaData.failureModeCauses || {},
          causeControls: fmeaData.causeControls || {},
          causeActions: fmeaData.causeActions || {}
        });
      }
      (fmeaData.pfmeas || []).forEach(p => {
        const key = `PFMEA_${p.id}`;
        if (!addedKeys.has(key)) {
          addedKeys.add(key);
          targetScopes.push({
            isPFMEA: true,
            pfmea: p,
            name: `PFMEA: ${p.name || 'Process FMEA'}`,
            processSteps: p.processSteps || [],
            functions: p.functions || [],
            requirements: p.requirements || [],
            functionRequirements: p.functionRequirements || {},
            functionLines: p.functionLines || [],
            failureModeEffects: p.failureModeEffects || {},
            failureModeCauses: p.failureModeCauses || {},
            causeControls: p.causeControls || {},
            causeActions: p.causeActions || {}
          });
        }
      });
    } else if (val === 'ACTIVE') {
      const activeKey = ctx.isPFMEA ? `PFMEA_${ctx.pfmea?.id}` : 'DFMEA';
      if (!addedKeys.has(activeKey)) {
        addedKeys.add(activeKey);
        targetScopes.push(ctx);
      }
    } else if (val === 'DFMEA') {
      if (!addedKeys.has('DFMEA')) {
        addedKeys.add('DFMEA');
        targetScopes.push({
          isPFMEA: false,
          name: 'DFMEA Master',
          functions: fmeaData.functions || [],
          requirements: fmeaData.requirements || [],
          functionRequirements: fmeaData.functionRequirements || {},
          functionLines: fmeaData.functionLines || [],
          failureModeEffects: fmeaData.failureModeEffects || {},
          failureModeCauses: fmeaData.failureModeCauses || {},
          causeControls: fmeaData.causeControls || {},
          causeActions: fmeaData.causeActions || {}
        });
      }
    } else if (val === 'ALL_PFMEA') {
      (fmeaData.pfmeas || []).forEach(p => {
        const key = `PFMEA_${p.id}`;
        if (!addedKeys.has(key)) {
          addedKeys.add(key);
          targetScopes.push({
            isPFMEA: true,
            pfmea: p,
            name: `PFMEA: ${p.name || 'Process FMEA'}`,
            processSteps: p.processSteps || [],
            functions: p.functions || [],
            requirements: p.requirements || [],
            functionRequirements: p.functionRequirements || {},
            functionLines: p.functionLines || [],
            failureModeEffects: p.failureModeEffects || {},
            failureModeCauses: p.failureModeCauses || {},
            causeControls: p.causeControls || {},
            causeActions: p.causeActions || {}
          });
        }
      });
    } else if (val.startsWith('PFMEA_')) {
      const pId = val.replace('PFMEA_', '');
      const p = (fmeaData.pfmeas || []).find(pf => pf.id === pId);
      if (p && !addedKeys.has(val)) {
        addedKeys.add(val);
        targetScopes.push({
          isPFMEA: true,
          pfmea: p,
          name: `PFMEA: ${p.name || 'Process FMEA'}`,
          processSteps: p.processSteps || [],
          functions: p.functions || [],
          requirements: p.requirements || [],
          functionRequirements: p.functionRequirements || {},
          functionLines: p.functionLines || [],
          failureModeEffects: p.failureModeEffects || {},
          failureModeCauses: p.failureModeCauses || {},
          causeControls: p.causeControls || {},
          causeActions: p.causeActions || {}
        });
      }
    }
  });

  if (targetScopes.length === 0) {
    targetScopes.push(ctx);
  }

  return targetScopes;
}

// ----------------------------------------------------
// 24. DVP & Action Plan View Functions
// ----------------------------------------------------
function populateDvpVariantDropdown() {
  const select = document.getElementById('dvpFilterVariant');
  if (!select) return;
  const currentVal = select.value || 'ALL';
  const variants = fmeaData.variants || [];

  let html = `<option value="ALL">All Variants</option>`;
  variants.forEach(v => {
    const vId = typeof v === 'object' ? v.id : v;
    const vName = typeof v === 'object' ? v.name : v;
    html += `<option value="${escapeHtml(vId)}">🚗 ${escapeHtml(vName)}</option>`;
  });

  select.innerHTML = html;
  select.value = currentVal;
}

function openDvpViewModal() {
  populateFmeaScopeCheckboxDropdown('dvpScopeMultiSelectContainer', 'renderDvpTable');
  populateDvpVariantDropdown();
  renderDvpTable();
  openModal('dvpViewModal');
}

function getDvpItemsList(targetScopes) {
  if (!targetScopes || targetScopes.length === 0) {
    const ctx = typeof getActiveFmeaData === 'function' ? getActiveFmeaData() : { isPFMEA: false };
    targetScopes = [ctx];
  }

  const items = [];
  const libraries = fmeaData.libraries || {};
  const controls = libraries.controls || [];
  const actions = libraries.actions || [];
  const causes = libraries.causes || [];

  const causeMapObj = {};
  causes.forEach(c => { causeMapObj[c.id] = c.details; });

  // Map causes & context paths across ALL target scopes
  const causeContextMap = {};
  targetScopes.forEach(scope => {
    const scopeName = scope.name || (scope.isPFMEA ? 'PFMEA' : 'DFMEA Master');
    const functionLines = scope.functionLines || [];
    const causeMap = scope.failureModeCauses || fmeaData.failureModeCauses || {};

    functionLines.forEach(fl => {
      const structNode = getStructureNodeById(fmeaData.structure, fl.structId);
      const structName = structNode ? `${structNode.partNo || ''} ${structNode.name || ''}`.trim() : (fl.structName || 'System Element');
      (fl.failureModes || []).forEach(fm => {
        const causeIds = causeMap[fm.id] || [];
        causeIds.forEach(cId => {
          const causeDetail = causeMapObj[cId] || 'Cause';
          causeContextMap[cId] = `[${scopeName} - ${structName}] ${fm.name} → ${causeDetail}`;
        });
      });
    });
  });

  // Collect Controls
  controls.forEach(ctrl => {
    let linkedCauseTexts = [];
    targetScopes.forEach(scope => {
      const causeMap = scope.causeControls || fmeaData.causeControls || {};
      Object.keys(causeMap).forEach(cId => {
        if ((causeMap[cId] || []).includes(ctrl.id)) {
          if (causeContextMap[cId]) {
            linkedCauseTexts.push(causeContextMap[cId]);
          }
        }
      });
    });

    if (linkedCauseTexts.length > 0 || targetScopes.some(s => !s.isPFMEA)) {
      items.push({
        id: ctrl.id,
        itemType: ctrl.type === 'Prevention' ? 'Prevention Control' : 'Detection Control',
        category: ctrl.type === 'Prevention' ? 'Prevention Control' : 'Detection Control',
        context: linkedCauseTexts.length > 0 ? linkedCauseTexts.join('; ') : 'General Master Control',
        desc: ctrl.desc || '',
        responsible: ctrl.responsible || '',
        targetDate: ctrl.targetDate || '',
        completionDate: ctrl.completionDate || '',
        status: ctrl.status || (ctrl.completionDate ? 'Passed' : 'Planned'),
        remark: ctrl.remark || ctrl.actionTaken || '',
        variants: ctrl.variants || ctrl.variantId || ['ALL'],
        isControl: true,
        rawRef: ctrl
      });
    }
  });

  // Collect Recommended Actions
  actions.forEach(act => {
    let linkedCauseTexts = [];
    targetScopes.forEach(scope => {
      const causeMap = scope.causeActions || fmeaData.causeActions || {};
      Object.keys(causeMap).forEach(cId => {
        if ((causeMap[cId] || []).includes(act.id)) {
          if (causeContextMap[cId]) {
            linkedCauseTexts.push(causeContextMap[cId]);
          }
        }
      });
    });

    if (linkedCauseTexts.length > 0 || targetScopes.some(s => !s.isPFMEA)) {
      items.push({
        id: act.id,
        itemType: `Action (${act.pd || 'Prevention'})`,
        category: 'Action',
        context: linkedCauseTexts.length > 0 ? linkedCauseTexts.join('; ') : 'General Master Action',
        desc: act.detail || '',
        responsible: act.responsible || '',
        targetDate: act.targetDate || '',
        completionDate: act.completionDate || '',
        status: act.status || (act.completionDate ? 'Passed' : (act.targetDate ? 'In Progress' : 'Planned')),
        remark: act.remark || act.actionTaken || act.comments || '',
        variants: act.variants || act.variantId || ['ALL'],
        isControl: false,
        rawRef: act
      });
    }
  });

  return items;
}

function renderDvpTable() {
  const tbody = document.getElementById('dvpTableBody');
  const cardsContainer = document.getElementById('dvpTableSummaryCards');
  if (!tbody) return;

  const selectedScopeVals = getSelectedScopeValues('dvpScopeMultiSelectContainer');
  const targetScopes = resolveSelectedScopes(selectedScopeVals);

  const badge = document.getElementById('dvpScopeBadge');
  if (badge) {
    const scopeNamesStr = targetScopes.map(s => s.name || (s.isPFMEA ? 'PFMEA' : 'DFMEA')).join(', ');
    badge.textContent = `Scopes: ${scopeNamesStr}`;
  }

  // Global Toolbar Filters
  const variantFilter = document.getElementById('dvpFilterVariant')?.value || 'ALL';
  const typeFilter = document.getElementById('dvpFilterType')?.value || 'ALL';
  const statusFilter = document.getElementById('dvpFilterStatus')?.value || 'ALL';
  const searchText = (document.getElementById('dvpSearchInput')?.value || '').toLowerCase().trim();

  // Per-column Header Filters
  const colTypeFilter = document.getElementById('dvpColFilterType')?.value || 'ALL';
  const colDescFilter = (document.getElementById('dvpColFilterDesc')?.value || '').toLowerCase().trim();
  const colRespFilter = (document.getElementById('dvpColFilterResp')?.value || '').toLowerCase().trim();
  const colTargetDateFilter = (document.getElementById('dvpColFilterTargetDate')?.value || '').toLowerCase().trim();
  const colCompDateFilter = (document.getElementById('dvpColFilterCompDate')?.value || '').toLowerCase().trim();
  const colStatusFilter = document.getElementById('dvpColFilterStatus')?.value || 'ALL';
  const colRemarkFilter = (document.getElementById('dvpColFilterRemark')?.value || '').toLowerCase().trim();

  let items = getDvpItemsList(targetScopes);

  // Filter by Variant
  if (variantFilter !== 'ALL') {
    items = items.filter(item => {
      const vars = Array.isArray(item.variants) ? item.variants : [item.variants];
      return vars.includes('ALL') || vars.includes(variantFilter);
    });
  }

  // Filter by Item Category
  if (typeFilter !== 'ALL') {
    items = items.filter(i => i.category === typeFilter || i.itemType.includes(typeFilter));
  }

  // Filter by Status
  if (statusFilter !== 'ALL') {
    items = items.filter(i => i.status === statusFilter);
  }

  // Filter by Search Text
  if (searchText) {
    items = items.filter(i =>
      i.desc.toLowerCase().includes(searchText) ||
      i.context.toLowerCase().includes(searchText) ||
      i.responsible.toLowerCase().includes(searchText) ||
      i.remark.toLowerCase().includes(searchText)
    );
  }

  // Apply Per-Column Header Filters
  if (colTypeFilter !== 'ALL') {
    items = items.filter(i => i.category === colTypeFilter || i.itemType.includes(colTypeFilter));
  }
  if (colDescFilter) {
    items = items.filter(i => (i.desc || '').toLowerCase().includes(colDescFilter) || (i.context || '').toLowerCase().includes(colDescFilter));
  }
  if (colRespFilter) {
    items = items.filter(i => (i.responsible || '').toLowerCase().includes(colRespFilter));
  }
  if (colTargetDateFilter) {
    items = items.filter(i => (i.targetDate || '').toLowerCase().includes(colTargetDateFilter));
  }
  if (colCompDateFilter) {
    items = items.filter(i => (i.completionDate || '').toLowerCase().includes(colCompDateFilter));
  }
  if (colStatusFilter !== 'ALL') {
    items = items.filter(i => i.status === colStatusFilter);
  }
  if (colRemarkFilter) {
    items = items.filter(i => (i.remark || '').toLowerCase().includes(colRemarkFilter));
  }

  // Summary Metrics
  const totalCount = items.length;
  const plannedCount = items.filter(i => i.status === 'Planned').length;
  const inProgressCount = items.filter(i => i.status === 'In Progress').length;
  const passedCount = items.filter(i => i.status === 'Passed').length;
  const failedCount = items.filter(i => i.status === 'Failed').length;

  if (cardsContainer) {
    cardsContainer.innerHTML = `
      <div style="background:var(--bg-card); border:1px solid var(--border-color); border-left:4px solid #3b82f6; border-radius:6px; padding:10px; color:var(--text-primary);">
        <span style="font-size:11px; color:var(--text-muted); font-weight:bold; text-transform:uppercase;">Total DVP Items</span>
        <div style="font-size:20px; font-weight:bold; color:var(--text-primary);">${totalCount}</div>
      </div>
      <div style="background:var(--bg-card); border:1px solid var(--border-color); border-left:4px solid #f59e0b; border-radius:6px; padding:10px; color:var(--text-primary);">
        <span style="font-size:11px; color:var(--text-muted); font-weight:bold; text-transform:uppercase;">Planned / In Progress</span>
        <div style="font-size:20px; font-weight:bold; color:#d97706;">${plannedCount + inProgressCount}</div>
      </div>
      <div style="background:var(--bg-card); border:1px solid var(--border-color); border-left:4px solid #10b981; border-radius:6px; padding:10px; color:var(--text-primary);">
        <span style="font-size:11px; color:var(--text-muted); font-weight:bold; text-transform:uppercase;">Passed / Completed</span>
        <div style="font-size:20px; font-weight:bold; color:#059669;">${passedCount}</div>
      </div>
      <div style="background:var(--bg-card); border:1px solid var(--border-color); border-left:4px solid #ef4444; border-radius:6px; padding:10px; color:var(--text-primary);">
        <span style="font-size:11px; color:var(--text-muted); font-weight:bold; text-transform:uppercase;">Failed / Action Needed</span>
        <div style="font-size:20px; font-weight:bold; color:#dc2626;">${failedCount}</div>
      </div>
    `;
  }

  if (items.length === 0) {
    tbody.innerHTML = `<tr><td colspan="8" style="text-align:center; padding:16px; color:var(--text-muted);">No DVP controls or actions matching active filter criteria.</td></tr>`;
    return;
  }

  tbody.innerHTML = items.map((item, idx) => {
    const isCtrl = item.isControl;
    const catBadge = isCtrl
      ? (item.category === 'Prevention Control'
        ? '<span class="badge" style="background:#dbeafe; color:#1e40af;">🛡 Prevention</span>'
        : '<span class="badge" style="background:#fef3c7; color:#92400e;">🔍 Detection</span>')
      : '<span class="badge" style="background:#f3e8ff; color:#6b21a8;">⚡ Action</span>';

    return `
      <tr style="border-bottom:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary);">
        <td style="padding:8px; text-align:center; font-weight:bold; color:var(--text-muted);">${idx + 1}</td>
        <td style="padding:8px;">${catBadge}</td>
        <td style="padding:8px; font-weight:600; color:var(--text-primary);">${escapeHtml(item.desc)}</td>
        <td style="padding:6px;">
          <input type="text" value="${escapeHtml(item.responsible)}" placeholder="Assign responsible..." style="width:100%; padding:4px 6px; border:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary); border-radius:4px; font-size:11px;" onchange="updateDvpItemField('${item.id}', ${isCtrl}, 'responsible', this.value)">
        </td>
        <td style="padding:6px; text-align:center;">
          <input type="date" value="${item.targetDate}" style="width:100%; padding:3px 4px; border:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary); border-radius:4px; font-size:11px;" onchange="updateDvpItemField('${item.id}', ${isCtrl}, 'targetDate', this.value)">
        </td>
        <td style="padding:6px; text-align:center;">
          <input type="date" value="${item.completionDate}" style="width:100%; padding:3px 4px; border:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary); border-radius:4px; font-size:11px;" onchange="updateDvpItemField('${item.id}', ${isCtrl}, 'completionDate', this.value)">
        </td>
        <td style="padding:6px; text-align:center;">
          <select style="width:100%; padding:4px 6px; border:1px solid var(--border-color); border-radius:4px; font-size:11px; font-weight:bold; ${item.status === 'Passed' ? 'background:#dcfce7; color:#15803d;' : (item.status === 'Failed' ? 'background:#fee2e2; color:#b91c1c;' : 'background:var(--bg-card); color:var(--text-primary);')}" onchange="updateDvpItemField('${item.id}', ${isCtrl}, 'status', this.value)">
            <option value="Planned" ${item.status === 'Planned' ? 'selected' : ''}>Planned</option>
            <option value="In Progress" ${item.status === 'In Progress' ? 'selected' : ''}>In Progress</option>
            <option value="Passed" ${item.status === 'Passed' ? 'selected' : ''}>Passed / Complete</option>
            <option value="Failed" ${item.status === 'Failed' ? 'selected' : ''}>Failed / Action Req.</option>
          </select>
        </td>
        <td style="padding:6px;">
          <input type="text" value="${escapeHtml(item.remark)}" placeholder="Action taken / remarks..." style="width:100%; padding:4px 6px; border:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary); border-radius:4px; font-size:11px;" onchange="updateDvpItemField('${item.id}', ${isCtrl}, 'remark', this.value)">
        </td>
      </tr>
    `;
  }).join('');
}

function updateDvpItemField(itemId, isControl, field, value) {
  const libraries = fmeaData.libraries || {};
  const list = isControl ? (libraries.controls || []) : (libraries.actions || []);
  const item = list.find(i => i.id === itemId);
  if (item) {
    item[field] = value;
    if (field === 'remark') {
      item.actionTaken = value;
      item.comments = value;
    }
    showToast(`Saved DVP ${field}`);
    renderFMEATable();
  }
}

function getFilteredDvpItems() {
  const selectedScopeVals = getSelectedScopeValues('dvpScopeMultiSelectContainer');
  const targetScopes = resolveSelectedScopes(selectedScopeVals);

  const variantFilter = document.getElementById('dvpFilterVariant')?.value || 'ALL';
  const typeFilter = document.getElementById('dvpFilterType')?.value || 'ALL';
  const statusFilter = document.getElementById('dvpFilterStatus')?.value || 'ALL';
  const searchText = (document.getElementById('dvpSearchInput')?.value || '').toLowerCase().trim();

  let items = getDvpItemsList(targetScopes);

  if (variantFilter !== 'ALL') {
    items = items.filter(item => {
      const vars = Array.isArray(item.variants) ? item.variants : [item.variants];
      return vars.includes('ALL') || vars.includes(variantFilter);
    });
  }

  if (typeFilter !== 'ALL') {
    items = items.filter(i => i.category === typeFilter || (i.itemType && i.itemType.includes(typeFilter)));
  }

  if (statusFilter !== 'ALL') {
    items = items.filter(i => i.status === statusFilter);
  }

  if (searchText) {
    items = items.filter(i =>
      (i.desc && i.desc.toLowerCase().includes(searchText)) ||
      (i.responsible && i.responsible.toLowerCase().includes(searchText)) ||
      (i.context && i.context.toLowerCase().includes(searchText)) ||
      (i.remark && i.remark.toLowerCase().includes(searchText))
    );
  }

  return items;
}

async function exportDvpToExcel() {
  const items = getFilteredDvpItems();
  const h = fmeaData.headerInfo || fmeaData.header || {};

  let html = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
  <head><meta charset="utf-8"/><style>
    table { border-collapse: collapse; width: 100%; font-family: Arial, sans-serif; font-size: 11px; }
    .hdr-title { background-color: #0f172a; color: #ffffff; font-weight: bold; font-size: 14px; text-align: center; padding: 8px; }
    th { background-color: #1e293b; color: #ffffff; border: 1px solid #475569; padding: 6px; text-align: center; }
    td { border: 1px solid #cbd5e1; padding: 5px; vertical-align: top; }
  </style></head>
  <body>
  <table>
    <tr><td colspan="8" class="hdr-title">DESIGN VERIFICATION PLAN &amp; REPORT (DVP&amp;R) - CONTROL ACTION MATRIX</td></tr>
    <tr><td colspan="8">Company: ${escapeHtml(h.companyName || '-')} | Project: ${escapeHtml(h.customerName || h.projectName || fmeaData.projectName || '-')} | Date: ${new Date().toLocaleDateString()}</td></tr>
    <tr><td colspan="8" style="height:10px; border:none;"></td></tr>
    <thead>
      <tr>
        <th>#</th>
        <th>Item Category</th>
        <th>Control / Action Description</th>
        <th>Responsible Person</th>
        <th>Target Date</th>
        <th>Completion Date</th>
        <th>Status</th>
        <th>Action Taken / Remarks</th>
      </tr>
    </thead>
    <tbody>`;

  if (items.length === 0) {
    html += `<tr><td colspan="8" style="text-align:center; padding:15px; color:#64748b;">No DVP items found matching current filters.</td></tr>`;
  } else {
    items.forEach((item, idx) => {
      html += `<tr>
        <td style="text-align:center;">${idx + 1}</td>
        <td>${escapeHtml(item.itemType || '')}</td>
        <td>${escapeHtml(item.desc || '')}</td>
        <td>${item.responsible && item.responsible !== 'Unassigned' && item.responsible !== '-' ? escapeHtml(item.responsible) : '-'}</td>
        <td style="text-align:center;">${item.targetDate || '-'}</td>
        <td style="text-align:center;">${item.completionDate || '-'}</td>
        <td style="text-align:center;">${escapeHtml(item.status || '')}</td>
        <td>${item.remark || '-'}</td>
      </tr>`;
    });
  }

  html += `</tbody></table></body></html>`;

  const fileName = `DVP_Action_Report_${new Date().toISOString().slice(0, 10)}.xls`;

  if (window.electronAPI && window.electronAPI.isElectron) {
    try {
      const saveFn = window.electronAPI.showSaveDialog || window.electronAPI.saveDialog;
      const saveRes = await saveFn(fileName);
      if (saveRes && !saveRes.canceled && saveRes.filePath) {
        const writeRes = await window.electronAPI.writeFile(saveRes.filePath, html);
        if (writeRes && writeRes.success !== false) {
          showToast(`📊 Exported DVP Action Report to: ${saveRes.filePath}`);
        } else {
          alert(`Error saving DVP report: ${writeRes ? writeRes.error : 'Unknown error'}`);
        }
        return;
      }
    } catch (e) {
      console.warn("Electron DVP save fallback:", e);
    }
  }

  const blob = new Blob([html], { type: 'application/vnd.ms-excel;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  a.remove();
  showToast(`📊 Downloaded DVP Action Report!`);
}

