// ═════════════════════════════════════════════════════════════════════════════
// SUBFILES PACKAGE EXPORT & SELECTIVE IMPORT MODULE
// ═════════════════════════════════════════════════════════════════════════════
let pendingImportPackageData = null;

function openSubfileExportModal() {
  if (typeof hasValidActiveProject === 'function' && !hasValidActiveProject()) {
    if (typeof showToast === 'function') showToast("Export is disabled: Please open an FMEA file first.", "warning");
    else alert("Export is disabled: Please open an FMEA file first.");
    return;
  }
  const container = document.getElementById('exportSubfilesChecklist');
  if (!container) return;

  const structNodes = getStructureNodesArray(fmeaData.structure);
  const variants = fmeaData.variants || [];

  if (structNodes.length === 0 && variants.length === 0) {
    alert("No subfiles or structure elements available in the active project to export.");
    return;
  }

  let html = `<div style="font-weight:bold; font-size:12px; color:#475569; margin-bottom:6px;">🌳 Structure Subfiles / Elements:</div>`;
  structNodes.forEach(node => {
    html += `
      <label style="display:flex; align-items:center; gap:8px; font-size:12px; padding:4px 6px; border-bottom:1px solid #e2e8f0; cursor:pointer;">
        <input type="checkbox" class="export_subfile_chk" value="struct:${node.id}" checked>
        <span><strong>[${escapeHtml(node.partNo || node.partNumber || 'Node')}]</strong> ${escapeHtml(node.name)}</span>
      </label>
    `;
  });

  const pfmeas = fmeaData.pfmeas || [];
  if (pfmeas.length > 0) {
    html += `<div style="font-weight:bold; font-size:12px; color:#475569; margin-top:12px; margin-bottom:6px;">🏭 Process FMEA Studies (PFMEAs):</div>`;
    pfmeas.forEach(p => {
      html += `
        <label style="display:flex; align-items:center; gap:8px; font-size:12px; padding:4px 6px; border-bottom:1px solid #e2e8f0; cursor:pointer;">
          <input type="checkbox" class="export_subfile_chk" value="pfmea:${p.id}" checked>
          <span>🏭 <strong>[PFMEA]</strong> ${escapeHtml(p.name || 'Process FMEA')} (${p.id})</span>
        </label>
      `;
    });
  }

  if (variants.length > 0) {
    html += `<div style="font-weight:bold; font-size:12px; color:#475569; margin-top:12px; margin-bottom:6px;">🌟 Variant Modules:</div>`;
    variants.forEach(v => {
      html += `
        <label style="display:flex; align-items:center; gap:8px; font-size:12px; padding:4px 6px; border-bottom:1px solid #e2e8f0; cursor:pointer;">
          <input type="checkbox" class="export_subfile_chk" value="var:${v.id}" checked>
          <span>🌟 ${escapeHtml(v.name)} (${v.id})</span>
        </label>
      `;
    });
  }

  container.innerHTML = html;
  openModal('exportSubfileModal');
}

function selectAllExportSubfiles(selectAll) {
  const chks = document.querySelectorAll('.export_subfile_chk');
  if (selectAll === 'non-checked' || selectAll === 'unchecked') {
    chks.forEach(c => c.checked = !c.checked);
  } else if (selectAll === 'checked') {
    // Keep currently checked
  } else {
    const isChecked = selectAll === true || selectAll === 'all';
    chks.forEach(c => c.checked = isChecked);
  }
}

function selectAllImportSubfiles(selectAll) {
  const chks = document.querySelectorAll('.import_subfile_chk');
  if (selectAll === 'non-checked' || selectAll === 'unchecked') {
    chks.forEach(c => c.checked = !c.checked);
  } else if (selectAll === 'checked') {
    // Keep currently checked
  } else {
    const isChecked = selectAll === true || selectAll === 'all';
    chks.forEach(c => c.checked = isChecked);
  }
}

function getStructureNodesArray(target) {
  const struct = target || (fmeaData ? fmeaData.structure : null);
  if (!struct) return [];
  if (Array.isArray(struct)) return struct;
  if (typeof struct === 'object') {
    if (typeof getFlatStructureNodes === 'function') {
      return getFlatStructureNodes(struct);
    }
    const list = [struct];
    function traverse(n) {
      if (n && n.children && Array.isArray(n.children)) {
        n.children.forEach(c => { list.push(c); traverse(c); });
      }
    }
    traverse(struct);
    return list;
  }
  return [];
}

async function executeSubfilesExport() {
  const selectedVals = Array.from(document.querySelectorAll('.export_subfile_chk:checked')).map(c => c.value);
  if (selectedVals.length === 0) {
    alert("Please select at least one subfile or structure element to export.");
    return;
  }

  const structIds = selectedVals.filter(v => v.startsWith('struct:')).map(v => v.substring(7));
  const varIds = selectedVals.filter(v => v.startsWith('var:')).map(v => v.substring(4));
  const pfmeaIds = selectedVals.filter(v => v.startsWith('pfmea:')).map(v => v.substring(6));

  if (typeof getActiveFmeaData === 'function') {
    getActiveFmeaData(); // ensure active PFMEA live edits are reflected
  }

  // Deduplicate current structure before export
  if (fmeaData && fmeaData.structure && typeof deduplicateStructureTree === 'function') {
    deduplicateStructureTree(fmeaData.structure);
  }

  const currentStructArray = getStructureNodesArray(fmeaData.structure);
  const selectedNodes = currentStructArray.filter(s => structIds.includes(s.id));

  // Clone nodes cleanly with parentId and empty children array to prevent recursive duplicate serialization
  const exportStruct = selectedNodes.map(n => {
    const pNode = getParentStructureNode(fmeaData.structure, n.id);
    return {
      id: String(n.id),
      parentId: n.parentId ? String(n.parentId) : (pNode ? String(pNode.id) : null),
      name: String(n.name || 'Component'),
      partNo: String(n.partNo || n.partNumber || ''),
      partNumber: String(n.partNumber || n.partNo || ''),
      type: n.type || 'Component',
      description: n.description || '',
      variantId: n.variantId || 'ALL',
      children: []
    };
  });

  const exportVariants = (fmeaData.variants || []).filter(v => varIds.includes(v.id));
  const exportPfmeas = (fmeaData.pfmeas || []).filter(p => pfmeaIds.includes(p.id));

  const exportFunctionLines = (fmeaData.functionLines || []).filter(fl => structIds.includes(fl.structId));
  const exportFunctions = (fmeaData.functions || []).filter(f => structIds.includes(f.structId));
  const exportRequirements = (fmeaData.requirements || []).filter(r => structIds.includes(r.structId));

  const pkgObj = {
    packageMagic: "JOST_FMEA_SUBFILE_PKG_V1",
    projectName: fmeaData.projectInfo?.name || "FMEA_Project",
    exportedAt: new Date().toISOString(),
    structure: exportStruct,
    variants: exportVariants,
    pfmeas: exportPfmeas,
    functionLines: exportFunctionLines,
    functions: exportFunctions,
    requirements: exportRequirements,
    failureModeEffects: fmeaData.failureModeEffects || {},
    failureModeCauses: fmeaData.failureModeCauses || {},
    causeControls: fmeaData.causeControls || {},
    causeActions: fmeaData.causeActions || {},
    libraries: fmeaData.libraries || {}
  };

  const encryptedPayload = encryptFmeaFilePayload(pkgObj);
  const defaultName = `Subfiles_Export_${(fmeaData.projectInfo?.name || 'Project').replace(/\s+/g, '_')}.fmea-pkg`;

  if (window.electronAPI && window.electronAPI.isElectron) {
    try {
      const res = await window.electronAPI.saveDialog(defaultName);
      if (res && !res.canceled && res.filePath) {
        const writeRes = await window.electronAPI.writeFile(res.filePath, encryptedPayload);
        if (writeRes.success) {
          closeModal('exportSubfileModal');
          showToast(`✨ Exported encrypted subfile package to: ${res.filePath}`);
        } else {
          alert(`Export failed: ${writeRes.error}`);
        }
      }
    } catch (err) {
      alert("Export error: " + err.message);
    }
    return;
  }

  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(encryptedPayload);
  const anchor = document.createElement('a');
  anchor.setAttribute("href", dataStr);
  anchor.setAttribute("download", defaultName);
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  closeModal('exportSubfileModal');
  showToast("✨ Downloaded encrypted subfiles package!");
}

async function triggerImportSubfilesPackage() {
  const hasActiveFile = typeof hasValidActiveProject === 'function' ? hasValidActiveProject() : !!activeSharePointFileName;
  const rev = typeof getContextRevision === 'function' ? getContextRevision() : null;
  const hasInProgressRev = hasActiveFile && rev && (rev.status === 'In Progress' || rev.status === 'Draft');

  if (!hasActiveFile || !hasInProgressRev) {
    if (typeof showToast === 'function') {
      showToast("⚠️ Import options are disabled before file open or when revision is frozen / not in-progress.", "warning");
    } else {
      alert("Import options are disabled before file open or when revision is frozen / not in-progress.");
    }
    return;
  }
  if (window.electronAPI && window.electronAPI.isElectron) {
    try {
      const res = await window.electronAPI.openDialog();
      if (res && res.content) {
        loadSubfilesPackageFile(res.content);
      }
    } catch (err) {
      alert("Error opening package file: " + err.message);
    }
    return;
  }

  let input = document.getElementById('subfilePkgInput');
  if (!input) {
    input = document.createElement('input');
    input.type = 'file';
    input.id = 'subfilePkgInput';
    input.style.display = 'none';
    input.onchange = (e) => {
      const file = e.target.files[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (evt) => loadSubfilesPackageFile(evt.target.result);
        reader.readAsText(file);
      }
    };
    document.body.appendChild(input);
  }
  input.value = '';
  input.click();
}

async function loadSubfilesPackageFile(rawContent) {
  try {
    const pkgObj = await decryptFmeaFilePayload(rawContent);
    if (!pkgObj || (!pkgObj.packageMagic && !pkgObj.structure && !pkgObj.structureTree)) {
      alert("Invalid or corrupted FMEA subfile package format.");
      return;
    }

    pendingImportPackageData = pkgObj;

    const pkgStructNodes = getStructureNodesArray(pkgObj.structureTree || pkgObj.structure);
    const currentStructNodes = getStructureNodesArray(fmeaData ? fmeaData.structure : null);

    const metaContainer = document.getElementById('importSubfileMeta');
    if (metaContainer) {
      metaContainer.innerHTML = `
        <strong>📦 Package Source:</strong> ${escapeHtml(pkgObj.projectName || 'FMEA Project')}<br>
        <strong>📅 Exported Date:</strong> ${pkgObj.exportedAt || 'N/A'}<br>
        <strong>🌳 Available Items:</strong> ${pkgStructNodes.length} structure subfile(s), ${(pkgObj.variants || []).length} variant(s), ${(pkgObj.pfmeas || []).length} PFMEA(s)
      `;
    }

    const checklistContainer = document.getElementById('importSubfilesChecklist');
    if (checklistContainer) {
      let html = `<div style="font-weight:bold; font-size:12px; color:#475569; margin-bottom:6px;">Select Subfiles / Structure Items to Import:</div>`;
      pkgStructNodes.forEach(node => {
        const exists = currentStructNodes.some(s => s.id === node.id || s.name === node.name);
        html += `
          <label style="display:flex; align-items:center; gap:8px; font-size:12px; padding:4px 6px; border-bottom:1px solid #e2e8f0; cursor:pointer;">
            <input type="checkbox" class="import_subfile_chk" value="struct:${node.id}" checked>
            <span><strong>[${escapeHtml(node.partNumber || node.partNo || 'Node')}]</strong> ${escapeHtml(node.name)} ${exists ? '<span class="badge" style="background:#fef3c7; color:#92400e; font-size:10px;">Already Exists</span>' : ''}</span>
          </label>
        `;
      });

      if ((pkgObj.pfmeas || []).length > 0) {
        html += `<div style="font-weight:bold; font-size:12px; color:#475569; margin-top:12px; margin-bottom:6px;">Select Process FMEA Studies (PFMEAs) to Import:</div>`;
        (pkgObj.pfmeas || []).forEach(p => {
          const exists = (fmeaData.pfmeas || []).some(ep => ep.id === p.id);
          html += `
            <label style="display:flex; align-items:center; gap:8px; font-size:12px; padding:4px 6px; border-bottom:1px solid #e2e8f0; cursor:pointer;">
              <input type="checkbox" class="import_subfile_chk" value="pfmea:${p.id}" checked>
              <span>🏭 <strong>[PFMEA]</strong> ${escapeHtml(p.name || 'Process FMEA')} (${p.id}) ${exists ? '<span class="badge" style="background:#fef3c7; color:#92400e; font-size:10px;">Already Exists</span>' : ''}</span>
            </label>
          `;
        });
      }

      if ((pkgObj.variants || []).length > 0) {
        html += `<div style="font-weight:bold; font-size:12px; color:#475569; margin-top:12px; margin-bottom:6px;">Select Variant Modules to Import:</div>`;
        (pkgObj.variants || []).forEach(v => {
          const exists = (fmeaData.variants || []).some(ev => ev.id === v.id);
          html += `
            <label style="display:flex; align-items:center; gap:8px; font-size:12px; padding:4px 6px; border-bottom:1px solid #e2e8f0; cursor:pointer;">
              <input type="checkbox" class="import_subfile_chk" value="var:${v.id}" checked>
              <span>🌟 ${escapeHtml(v.name)} (${v.id}) ${exists ? '<span class="badge" style="background:#fef3c7; color:#92400e; font-size:10px;">Already Exists</span>' : ''}</span>
            </label>
          `;
        });
      }

      checklistContainer.innerHTML = html;
    }

    openModal('importSubfileModal');
  } catch (err) {
    alert("Decryption / Import Error: " + err.message);
  }
}

function selectAllImportSubfiles(selectAll) {
  const chks = document.querySelectorAll('.import_subfile_chk');
  chks.forEach(c => c.checked = selectAll);
}

function executeSubfilesImport() {
  if (!pendingImportPackageData) return;
  const selectedVals = Array.from(document.querySelectorAll('.import_subfile_chk:checked')).map(c => c.value);
  if (selectedVals.length === 0) {
    alert("Please select at least one item to import.");
    return;
  }

  const structIds = selectedVals.filter(v => v.startsWith('struct:')).map(v => v.substring(7));
  const varIds = selectedVals.filter(v => v.startsWith('var:')).map(v => v.substring(4));
  const pfmeaIds = selectedVals.filter(v => v.startsWith('pfmea:')).map(v => v.substring(6));

  const pkg = pendingImportPackageData;
  fmeaData.variants = fmeaData.variants || [];
  fmeaData.pfmeas = fmeaData.pfmeas || [];
  fmeaData.functionLines = fmeaData.functionLines || [];
  fmeaData.functions = fmeaData.functions || [];
  fmeaData.requirements = fmeaData.requirements || [];

  let importedCount = 0;

  // 1. Import Structure Nodes with dynamic existence check and parentId preservation
  fmeaData.structure = fmeaData.structure || { id: "struct-root", partNo: "SYS-100", name: "Vehicle System Root", description: "Top level system base node", variantId: "ALL", children: [] };
  if (typeof deduplicateStructureTree === 'function') {
    deduplicateStructureTree(fmeaData.structure);
  }

  const existingNodes = getStructureNodesArray(fmeaData.structure);
  const existingIds = new Set(existingNodes.map(s => String(s.id)));

  const pkgStructNodes = getStructureNodesArray(pkg.structureTree || pkg.structure);

  pkgStructNodes.forEach(node => {
    if (!structIds.includes(node.id)) return;
    if (existingIds.has(String(node.id))) return; // Already exists anywhere in tree, DO NOT duplicate!

    const cleanNode = {
      id: String(node.id),
      parentId: node.parentId ? String(node.parentId) : null,
      name: String(node.name || 'Component'),
      partNo: String(node.partNo || node.partNumber || ''),
      partNumber: String(node.partNumber || node.partNo || ''),
      type: node.type || 'Component',
      description: node.description || '',
      variantId: node.variantId || 'ALL',
      children: []
    };

    let attached = false;
    if (cleanNode.parentId) {
      const parentNode = getStructureNodeById(fmeaData.structure, cleanNode.parentId);
      if (parentNode) {
        parentNode.children = parentNode.children || [];
        if (!parentNode.children.some(c => String(c.id) === cleanNode.id)) {
          parentNode.children.push(cleanNode);
          attached = true;
        }
      }
    }

    if (!attached) {
      if (Array.isArray(fmeaData.structure)) {
        fmeaData.structure.push(cleanNode);
      } else if (fmeaData.structure && fmeaData.structure.children) {
        if (!fmeaData.structure.children.some(c => String(c.id) === cleanNode.id)) {
          fmeaData.structure.children.push(cleanNode);
        }
      } else {
        fmeaData.structure = cleanNode;
      }
    }

    existingIds.add(cleanNode.id);
    importedCount++;
  });

  if (typeof deduplicateStructureTree === 'function') {
    deduplicateStructureTree(fmeaData.structure);
  }

  // 2. Import Variants
  (pkg.variants || []).forEach(v => {
    if (varIds.includes(v.id)) {
      if (!fmeaData.variants.some(ev => ev.id === v.id)) {
        fmeaData.variants.push(v);
      }
    }
  });

  // 3. Import PFMEAs
  (pkg.pfmeas || []).forEach(p => {
    if (pfmeaIds.includes(p.id)) {
      const existingIdx = fmeaData.pfmeas.findIndex(ep => ep.id === p.id);
      if (existingIdx >= 0) {
        Object.assign(fmeaData.pfmeas[existingIdx], p);
      } else {
        fmeaData.pfmeas.push(p);
        importedCount++;
      }
    }
  });
  fmeaData.pfmeaInstances = fmeaData.pfmeas;

  // 4. Import Function Lines and Reqs for imported structure nodes
  (pkg.functionLines || []).forEach(fl => {
    if (structIds.includes(fl.structId) && !fmeaData.functionLines.some(existing => existing.id === fl.id)) {
      fmeaData.functionLines.push(fl);
    }
  });

  (pkg.functions || []).forEach(fn => {
    if (structIds.includes(fn.structId) && !fmeaData.functions.some(existing => existing.id === fn.id)) {
      fmeaData.functions.push(fn);
    }
  });

  (pkg.requirements || []).forEach(rq => {
    if (structIds.includes(rq.structId) && !fmeaData.requirements.some(existing => existing.id === rq.id)) {
      fmeaData.requirements.push(rq);
    }
  });

  // 5. Merge libraries and failure mode effects, causes, controls, actions dictionary mappings
  fmeaData.libraries = fmeaData.libraries || { mainEffectFunctions: [], effects: [], causes: [], controls: [], actions: [] };
  fmeaData.libraries.effects = fmeaData.libraries.effects || [];
  fmeaData.libraries.causes = fmeaData.libraries.causes || [];
  fmeaData.libraries.controls = fmeaData.libraries.controls || [];
  fmeaData.libraries.actions = fmeaData.libraries.actions || [];

  if (pkg.libraries) {
    (pkg.libraries.effects || []).forEach(eff => {
      if (!fmeaData.libraries.effects.some(e => e.id === eff.id)) fmeaData.libraries.effects.push(eff);
    });
    (pkg.libraries.causes || []).forEach(cause => {
      let existing = fmeaData.libraries.causes.find(c => c.id === cause.id);
      if (!existing) {
        fmeaData.libraries.causes.push(cause);
      } else {
        Object.assign(existing, cause);
      }
    });
    (pkg.libraries.controls || []).forEach(ctrl => {
      if (!fmeaData.libraries.controls.some(c => c.id === ctrl.id)) fmeaData.libraries.controls.push(ctrl);
    });
    (pkg.libraries.actions || []).forEach(act => {
      if (!fmeaData.libraries.actions.some(a => a.id === act.id)) fmeaData.libraries.actions.push(act);
    });
  }

  // Also ingest any causes from pkg.causes (standard in PFMEA generator packages)
  (pkg.causes || []).forEach(cause => {
    let existing = fmeaData.libraries.causes.find(c => c.id === cause.id);
    const linkedWE = (pkg.workElements || []).find(we => we.id === cause.workElementId);
    const microActivityFunc = cause.microActivity || cause.micro_activity || (linkedWE ? (linkedWE.microActivity || linkedWE.function) : '') || cause.function || (linkedWE ? linkedWE.name : '') || '';
    const causeDesc = cause.description || cause.desc || cause.details || cause.name || '';
    const causeObj = {
      id: cause.id,
      desc: causeDesc,
      details: causeDesc,
      name: causeDesc,
      workElementId: cause.workElementId || '',
      systemElement: cause.systemElement || (linkedWE ? linkedWE.category : '') || cause.fiveM || cause.category || '',
      function: microActivityFunc,
      microActivity: microActivityFunc,
      requirement: cause.requirement || (linkedWE ? (linkedWE.function || linkedWE.spec || '') : '') || '',
      occurrence: parseInt(cause.occurrence) || 4,
      detection: parseInt(cause.detection) || 2,
      actionPriority: cause.actionPriority || 'L',
      specialCharacteristic: cause.specialCharacteristic || '',
      classSymbol: cause.specialCharacteristic || '',
      origin: cause.origin || 'PFMEA',
      module: cause.module || 'PFMEA',
      isPFMEA: true,
      variants: cause.variants || cause.variantId || 'ALL',
      variantId: cause.variantId || cause.variants || 'ALL',
      structId: cause.structId || cause.operationId || '',
      failureModeId: cause.failureModeId || ''
    };
    if (!existing) {
      fmeaData.libraries.causes.push(causeObj);
    } else {
      Object.assign(existing, causeObj);
    }
  });

  if (pkg.failureModeEffects) Object.assign(fmeaData.failureModeEffects, pkg.failureModeEffects);
  if (pkg.failureModeCauses) Object.assign(fmeaData.failureModeCauses, pkg.failureModeCauses);
  if (pkg.causeControls) Object.assign(fmeaData.causeControls, pkg.causeControls);
  if (pkg.causeActions) Object.assign(fmeaData.causeActions, pkg.causeActions);

  // Normalize dataset to build failureModes array and functionRequirements map
  normalizeFmeaDataset(fmeaData);

  saveProjectToLocalStorage();
  renderVariantDropdowns();
  renderFmeaContextDropdown();
  renderTreeSidebar();
  renderFMEATable();

  closeModal('importSubfileModal');
  pendingImportPackageData = null;

  showToast(`✨ Successfully imported ${importedCount} subfile(s) / study into your project workspace!`);
}

/* ==========================================
   CHARACTERISTICS & SPECIFICATIONS EXTRACTION TOOL
   ========================================== */

function openCharacteristicsSpecsModal() {
  const activeScope = getActiveFmeaScope();
  const scopeSel = document.getElementById('charSpecScopeFilter');
  if (scopeSel) {
    scopeSel.value = activeScope;
  }
  const varSel = document.getElementById('charSpecVariantFilter');
  if (varSel) {
    varSel.innerHTML = '<option value="ALL">All Variants</option>' + (fmeaData.variants || []).map(v => `<option value="${v.id}">${escapeHtml(v.name)} (${escapeHtml(v.code)})</option>`).join('');
  }
  renderCharacteristicsSpecsTable();
  openModal('characteristicsSpecsModal');
}

function getExtractedCharacteristicsData() {
  ensureAllCharacteristicsStoredAndLinked();
  const extracted = [];
  const search = (document.getElementById('charSpecSearchInput')?.value || '').toLowerCase().trim();
  const scopeFilter = document.getElementById('charSpecScopeFilter')?.value || getActiveFmeaScope();
  const variantFilter = document.getElementById('charSpecVariantFilter')?.value || 'ALL';

  const seenDedupeKeys = new Set();
  let itemCounter = 1;

  const allCauses = (fmeaData && fmeaData.libraries && fmeaData.libraries.causes) ? fmeaData.libraries.causes : [];
  const getCauseObj = (cId) => allCauses.find(c => c.id === cId) || { id: cId, details: 'FMEA Cause' };

  // Helper to add characteristic entry
  const pushCharEntry = (ch, causeObj, elementPath, modType, dedupeKey) => {
    if (seenDedupeKeys.has(dedupeKey)) return;
    seenDedupeKeys.add(dedupeKey);

    const app = ch.applicability || causeObj.module || causeObj.origin || modType || 'ALL';
    const matchesScope = (scopeFilter === 'ALL') || (app === 'ALL') || (scopeFilter === app);
    if (!matchesScope) return;

    const vars = ch.variants || ch.variantId || causeObj.variants || causeObj.variantId || ['ALL'];
    const matchesVariant = (variantFilter === 'ALL') || vars.includes('ALL') || vars.includes(variantFilter);
    if (!matchesVariant) return;

    extracted.push({
      num: `CHAR-${String(itemCounter++).padStart(3, '0')}`,
      text: ch.name || ch.details || causeObj.details || 'Characteristic',
      spec: ch.spec || causeObj.spec || '-',
      classSymbol: ch.classSymbol || causeObj.classSymbol || 'None',
      element: elementPath,
      variants: getVariantNamesDisplay(vars),
      module: modType || (app === 'ALL' ? 'DFMEA / PFMEA' : app),
      raw: causeObj,
      rawChar: ch
    });
  };

  // 1. Scan DFMEA Function Lines & Failure Modes
  const dfmeaLines = fmeaData.functionLines || [];
  const dfmeaCausesMap = fmeaData.failureModeCauses || {};

  dfmeaLines.forEach(line => {
    const sNode = getStructureNodeById(fmeaData.structure, line.structId);
    const sysName = sNode ? (sNode.partNo ? `${sNode.partNo} - ${sNode.name}` : sNode.name) : 'DFMEA System';

    (line.failureModes || []).forEach(fm => {
      const causeIds = dfmeaCausesMap[fm.id] || [];
      causeIds.forEach(cId => {
        const cObj = getCauseObj(cId);
        const linkedChars = getLinkedCharacteristicsForCause(cObj);
        linkedChars.forEach(ch => {
          const key = `${ch.id || ch.name}_DFMEA_${line.structId}_${cId}`;
          pushCharEntry(ch, cObj, sysName, 'DFMEA', key);
        });
      });
    });
  });

  // 2. Scan ALL PFMEA Subfiles & Active PFMEAs
  const allPfmeas = [];
  if (Array.isArray(fmeaData.pfmeas) && fmeaData.pfmeas.length > 0) {
    fmeaData.pfmeas.forEach(p => {
      if (p && !allPfmeas.some(existing => String(existing.id) === String(p.id))) {
        allPfmeas.push(p);
      }
    });
  }
  if (fmeaData.pfmea && !allPfmeas.some(existing => String(existing.id) === String(fmeaData.pfmea.id))) {
    allPfmeas.push(fmeaData.pfmea);
  }
  const activeCtx = getActiveFmeaData();
  if (activeCtx && activeCtx.isPFMEA && activeCtx.pfmea && !allPfmeas.some(existing => String(existing.id) === String(activeCtx.pfmea.id))) {
    allPfmeas.push(activeCtx.pfmea);
  }

  allPfmeas.forEach(pfmea => {
    const psteps = pfmea.processSteps || [];
    const pfmeaLines = pfmea.functionLines || [];
    const pfmeaCausesMap = pfmea.failureModeCauses || {};

    pfmeaLines.forEach(line => {
      const pstep = psteps.find(ps => String(ps.id) === String(line.structId));
      let pstepName = pstep ? (pstep.stepNo || pstep.opNo ? `${pstep.stepNo || pstep.opNo}: ${pstep.name}` : pstep.name) : (line.stepName || 'Process Step');

      let sysName = '';
      if (pstep && pstep.dfmeaStructId) {
        const sNode = getStructureNodeById(fmeaData.structure, pstep.dfmeaStructId);
        if (sNode) sysName = sNode.partNo ? `${sNode.partNo} - ${sNode.name}` : sNode.name;
      }
      if (!sysName) {
        sysName = pstep?.systemElement || pfmea.name || (fmeaData.structure ? (fmeaData.structure.partNo ? `${fmeaData.structure.partNo} - ${fmeaData.structure.name}` : fmeaData.structure.name) : 'System Element');
      }

      const fullPath = pstep ? `${sysName} ➔ ${pstepName}` : `${sysName} ➔ ${pstepName}`;

      (line.failureModes || []).forEach(fm => {
        const causeIds = pfmeaCausesMap[fm.id] || [];
        causeIds.forEach(cId => {
          const cObj = getCauseObj(cId);
          const linkedChars = getLinkedCharacteristicsForCause(cObj);
          linkedChars.forEach(ch => {
            const key = `${ch.id || ch.name}_PFMEA_${pfmea.id || 'pf'}_${line.structId}_${cId}`;
            pushCharEntry(ch, cObj, fullPath, 'PFMEA', key);
          });
        });
      });
    });
  });



  // Filter items based on search query
  if (search) {
    return extracted.filter(item =>
      (item.num && item.num.toLowerCase().includes(search)) ||
      (item.text && item.text.toLowerCase().includes(search)) ||
      (item.spec && item.spec.toLowerCase().includes(search)) ||
      (item.element && item.element.toLowerCase().includes(search)) ||
      (item.variants && item.variants.toLowerCase().includes(search)) ||
      (item.module && item.module.toLowerCase().includes(search))
    );
  }

  return extracted;
}

function renderCharacteristicsSpecsTable() {
  const tbody = document.getElementById('charSpecExtractTbody');
  const countBadge = document.getElementById('charSpecCountBadge');
  if (!tbody) return;

  const data = getExtractedCharacteristicsData();
  if (countBadge) countBadge.textContent = `${data.length} Items Extracted`;

  if (data.length === 0) {
    tbody.innerHTML = `
      <tr>
        <td colspan="6" style="text-align:center; padding:30px; color:var(--text-muted);">
          No characteristics or specifications match the search/variant criteria.
        </td>
      </tr>
    `;
    return;
  }

  tbody.innerHTML = data.map(item => `
    <tr style="border-bottom:1px solid var(--border-color); background:var(--bg-card); color:var(--text-primary);">
      <td style="padding:10px; font-weight:bold; color:#0284c7;">${escapeHtml(item.num)}</td>
      <td style="padding:10px; font-weight:500; color:var(--text-primary);">
        ${item.classSymbol && item.classSymbol !== 'None' ? `<span style="font-weight:bold; color:#d97706; background:#fef3c7; border:1px solid #fcd34d; padding:1px 4px; border-radius:3px; font-size:10px; margin-right:4px;">${escapeHtml(item.classSymbol)}</span>` : ''}
        ${escapeHtml(item.text)}
      </td>
      <td style="padding:10px; color:#0f766e; font-weight:600; background:var(--table-row-alt); border-radius:4px;">${escapeHtml(item.spec)}</td>
      <td style="padding:10px; color:var(--text-primary);">⚙️ ${escapeHtml(item.element)}</td>
      <td style="padding:10px; color:var(--text-muted); font-size:11px;">${escapeHtml(item.variants || 'ALL')}</td>
      <td style="padding:10px; text-align:center;">
        <span class="badge" style="background:${item.module === 'PFMEA' ? '#8b5cf6' : (item.module === 'DFMEA' ? '#2563eb' : '#0284c7')}; color:#ffffff;">${item.module}</span>
      </td>
    </tr>
  `).join('');
}

async function exportCharacteristicsSpecsToCSV() {
  const data = getExtractedCharacteristicsData();
  if (data.length === 0) {
    alert("No characteristics data available to export.");
    return;
  }

  let csv = "Number,Description,Engineering Specification,Class Symbol,Linked System Element / Process Step,Assigned Variants,Module\n";
  data.forEach(item => {
    const num = `"${(item.num || '').replace(/"/g, '""')}"`;
    const text = `"${(item.text || '').replace(/"/g, '""')}"`;
    const spec = `"${(item.spec || '').replace(/"/g, '""')}"`;
    const cls = `"${(item.classSymbol || '').replace(/"/g, '""')}"`;
    const elem = `"${(item.element || '').replace(/"/g, '""')}"`;
    const vars = `"${(item.variants || '').replace(/"/g, '""')}"`;
    const mod = `"${(item.module || '').replace(/"/g, '""')}"`;
    csv += `${num},${text},${spec},${cls},${elem},${vars},${mod}\n`;
  });

  const fileName = `Characteristics_Specifications_${new Date().toISOString().slice(0, 10)}.csv`;

  if (window.electronAPI && window.electronAPI.isElectron) {
    try {
      const saveFn = window.electronAPI.showSaveDialog || window.electronAPI.saveDialog;
      const saveRes = await saveFn(fileName);
      if (saveRes && !saveRes.canceled && saveRes.filePath) {
        const writeRes = await window.electronAPI.writeFile(saveRes.filePath, csv);
        if (writeRes && writeRes.success !== false) {
          showToast(`📊 Exported Characteristics CSV to: ${saveRes.filePath}`);
        } else {
          alert(`Error saving CSV: ${writeRes ? writeRes.error : 'Unknown error'}`);
        }
        return;
      }
    } catch (e) {
      console.warn("Electron CSV save fallback:", e);
    }
  }

  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.setAttribute('href', url);
  link.setAttribute('download', fileName);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  showToast(`📊 Downloaded Characteristics Specifications CSV!`);
}

function copyCharacteristicsSpecsTableToClipboard() {
  const data = getExtractedCharacteristicsData();
  if (data.length === 0) {
    alert("No data available to copy.");
    return;
  }

  let tsv = "Number\tDescription\tEngineering Specification\tClass Symbol\tLinked System Element / Process Step\tAssigned Variants\tModule\n";
  data.forEach(item => {
    tsv += `${item.num}\t${item.text}\t${item.spec}\t${item.classSymbol || '-'}\t${item.element}\t${item.variants || 'ALL'}\t${item.module}\n`;
  });

  if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
    navigator.clipboard.writeText(tsv).then(() => {
      alert("📋 Characteristics table copied to clipboard! You can now paste directly into Microsoft Excel or Word.");
    }).catch(err => {
      const ta = document.createElement("textarea");
      ta.value = tsv;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.select();
      try {
        document.execCommand('copy');
        alert("📋 Characteristics table copied to clipboard! You can now paste directly into Microsoft Excel or Word.");
      } catch (e) {
        alert("Failed to copy table: " + err);
      }
      document.body.removeChild(ta);
    });
  } else {
    const ta = document.createElement("textarea");
    ta.value = tsv;
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    try {
      document.execCommand('copy');
      alert("📋 Characteristics table copied to clipboard! You can now paste directly into Microsoft Excel or Word.");
    } catch (e) {
      alert("Failed to copy table.");
    }
    document.body.removeChild(ta);
  }
}

