let aiWorkbenchState = {
  currentStep: 1,
  selectedElementIds: new Set(),
  elementContexts: {},        // { [structId]: "support notes..." }
  generatedFunctions: {},     // { [structId]: [ { id, name, type } ] }
  generatedRequirements: {},  // { [funcId]: [ { id, funcId, structId, reqText } ] }
  generatedFailureModes: {}   // { [reqId]: [ { id, reqId, funcId, structId, modeText, effect, cause } ] }
};

async function fetchLocalOllamaModels() {
  try {
    let res = await fetch('http://localhost:11434/api/tags');
    if (!res.ok) {
      res = await fetch('http://localhost:3030/api/ollama/proxy', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: 'http://127.0.0.1:11434/api/tags', body: {} })
      });
    }
    if (res && res.ok) {
      const data = await res.json();
      if (data.models && data.models.length > 0) {
        const modelNames = data.models.map(m => m.name);
        const modelInput = document.getElementById('aiOllamaModel');
        if (modelInput && !modelNames.includes(modelInput.value)) {
          modelInput.value = modelNames[0];
        }
        return modelNames;
      }
    }
  } catch (e) {
    console.log('Ollama model discovery:', e);
  }
  return [];
}

