function generateWb2MasterPrompt(targetNodeId = null) {
  const ctx = getActiveFmeaData();
  const nodeId = targetNodeId || aiWorkbench2State.currentNodeId;
  const node = getStructureNodeById(ctx.structure, nodeId);
  if (!node) return '';

  const isRoot = (node.id === ctx.structure.id);
  const parentNode = isRoot ? null : getParentStructureNode(ctx.structure, nodeId);
  const userCtx = aiWorkbench2State.nodeContexts[nodeId] || {};
  const tsPrefix = 't' + Date.now().toString().slice(-6);

  let parentContextStr = 'TOP-TO-BOTTOM PARENT SYSTEM CONTEXT: None (Top-Level Root System)';
  if (parentNode) {
    const parentFns = (ctx.functions || []).filter(f => f.structId === parentNode.id);
    parentContextStr = `TOP-TO-BOTTOM PARENT SYSTEM CONTEXT (Level n+1):
- Parent Name: "${parentNode.name}" (Part No: "${parentNode.partNo || 'N/A'}")
- Confirmed Parent Functions:
${parentFns.map(f => `  * [${f.id}] ${f.name} (${f.type || 'Primary'})`).join('\n') || '  (None documented yet)'}`;
  }

  const existingEffects = (fmeaData && fmeaData.libraries && fmeaData.libraries.effects) ? fmeaData.libraries.effects : ((ctx.libraries && ctx.libraries.effects) ? ctx.libraries.effects : []);
  const existingCauses = (fmeaData && fmeaData.libraries && fmeaData.libraries.causes) ? fmeaData.libraries.causes : ((ctx.libraries && ctx.libraries.causes) ? ctx.libraries.causes : []);
  const existingControls = (fmeaData && fmeaData.libraries && fmeaData.libraries.controls) ? fmeaData.libraries.controls : ((ctx.libraries && ctx.libraries.controls) ? ctx.libraries.controls : []);

  const prompt = `# MASTER CFT AUTOMOTIVE DFMEA ENGINE — AIAG & VDA (JOST_FMEA_SUBFILE_PKG_V1)

You are an Autonomous Cross-Functional Team (CFT) Automotive DFMEA Expert.
Generate a complete, technically defensible, production-ready FMEA subpackage conforming strictly to "JOST_FMEA_SUBFILE_PKG_V1".

TARGET ELEMENT:
- Element Name: "${userCtx.itemName || node.name}"
- Part Number: "${userCtx.partNumber || node.partNo || 'PN-001'}"
- Classification: ${userCtx.itemType || 'Assembly'}
- Description: "${userCtx.itemDesc || node.desc || 'Automotive Element'}"
${userCtx.joints && userCtx.joints.length > 0 ? `- Selected Joints: ${userCtx.joints.join(', ')}\n` : ''}${userCtx.material ? `- Material: ${userCtx.material}\n` : ''}${userCtx.gdt ? `- GD&T: ${userCtx.gdt}\n` : ''}${userCtx.env ? `- Operating Environment: ${userCtx.env}\n` : ''}
${parentContextStr}

CRITICAL METHODOLOGY RULES:
1. FUNCTION DEFINITIONS: Use Active Verb + Measurable Noun across AIAG-VDA domains (Primary, Safety, Regulatory, Durability, NVH). For sub-elements, link to parent functions.
2. FAILURE MODES: Systematically evaluate 7 failure types (Loss, Partial, Intermittent, Degradation, Exceeding, Unintended, Delayed), but output ONLY physically applicable modes.
3. 3-LEVEL EFFECTS: Provide End User, OEM Assembly Plant, and Component Plant consequences.
   EXACT SEVERITY (1-10) SCALE:
   - S=10: Safety-Related Effect (crash hazard, injury, catastrophic loss of control).
   - S=9: Regulatory Non-Compliance (fails government standards/mandates).
   - S=8: Failure of Primary Function (loss of main function, vehicle disabled, stranded).
   - S=7: Degradation of Primary Function (limp-home mode, sluggish steering).
   - S=6: Failure of Secondary Function (loss of HVAC, wipers, lighting).
   - S=5: Degradation of Secondary Function (reduced cooling, noisy wipers).
   - S=4: Moderate Annoyance (>75% of customers).
   - S=3: Minor Annoyance (~50% of customers).
   - S=2: Very Minor Annoyance (<25%).
   - S=1: No Effect.
4. ROOT CAUSES: Ground causes in specific joint mechanics (for Assembly/Mixed) or design geometry/metallurgy (for Component). STRICTLY NO CLUBBING. State physical characteristic and define limit using placeholder "____". NEVER hallucinate numbers!
5. CONTROLS: Keep Prevention Controls (standards, FEA, calculations) and Detection Controls (bench tests, inspections) strictly separate.
6. RETURN ONLY VALID JSON conforming exactly to JOST_FMEA_SUBFILE_PKG_V1.`;

  return prompt;
}

