function ingestWb2MasterPromptResponse() {
  const txt = document.getElementById('wb2MasterPromptResponse');
  if (!txt || !txt.value.trim()) {
    alert("Please paste the AI subpackage JSON response first.");
    return;
  }

  try {
    const raw = sanitizeJsonString(txt.value);
    const pkg = JSON.parse(raw);
    if (!pkg.packageMagic || !pkg.structure) {
      alert("Invalid package format. Missing packageMagic or structure.");
      return;
    }

    parseAndIngestWb2FullSubpackage(pkg);
    aiWorkbench2State.processedNodes.add(pkg.structure[0].id);
    renderWb2StructureNavBar();
    closeWb2MasterPromptModal();
    closeAiWorkbench2Modal();
    if (typeof showToast === 'function') showToast("📥 Ingested full Master Subpackage!", "success");
  } catch (err) {
    alert("JSON Parsing Error: " + err.message);
  }
}

function copyWb2StepPrompt(step) {
  let prompt = '';
  if (step === 2) prompt = generateWb2Step2Prompt();
  else if (step === 3) prompt = generateWb2Step3Prompt();
  else if (step === 4) prompt = generateWb2Step4Prompt();
  else if (step === 5) prompt = generateWb2Step5Prompt();
  else if (step === 6) prompt = generateWb2Step6Prompt();
  else if (step === 7) prompt = generateWb2Step7Prompt();

  if (prompt) {
    navigator.clipboard.writeText(prompt).then(() => {
      if (typeof showToast === 'function') showToast(`📋 Copied Step ${step} prompt!`, 'success');
    });
  }
}

function sanitizeJsonString(str) {
  let cleaned = str.trim();
  const firstBrace = cleaned.indexOf('{');
  const firstBracket = cleaned.indexOf('[');
  let startIdx = 0;
  if (firstBrace !== -1 && firstBracket !== -1) startIdx = Math.min(firstBrace, firstBracket);
  else if (firstBrace !== -1) startIdx = firstBrace;
  else if (firstBracket !== -1) startIdx = firstBracket;
  cleaned = cleaned.slice(startIdx);

  const lastBrace = cleaned.lastIndexOf('}');
  const lastBracket = cleaned.lastIndexOf(']');
  let endIdx = cleaned.length;
  if (lastBrace !== -1 && lastBracket !== -1) endIdx = Math.max(lastBrace, lastBracket) + 1;
  else if (lastBrace !== -1) endIdx = lastBrace + 1;
  else if (lastBracket !== -1) endIdx = lastBracket + 1;
  cleaned = cleaned.slice(0, endIdx);

  cleaned = cleaned.replace(/,\s*([}\]])/g, '$1');
  return cleaned;
}

// Helper to extract text from OpenAI Responses API (/v1/responses)
function extractResponsesApiText(data) {
  if (!data) return '';
  // 1. Direct convenience property (SDKs or gateway wrappers)
  if (typeof data.output_text === 'string' && data.output_text.trim()) {
    return data.output_text.trim();
  }
  if (typeof data.text === 'string' && data.text.trim()) {
    return data.text.trim();
  }
  // 2. Structured output array from /v1/responses: [ { type: "message", content: [ { type: "output_text", text: "..." } ] } ]
  if (Array.isArray(data.output)) {
    let combined = '';
    for (const item of data.output) {
      if (typeof item === 'string') {
        combined += item;
      } else if (item && typeof item === 'object') {
        if (typeof item.text === 'string') {
          combined += item.text;
        } else if (Array.isArray(item.content)) {
          for (const c of item.content) {
            if (typeof c === 'string') {
              combined += c;
            } else if (c && typeof c === 'object') {
              if (typeof c.text === 'string') combined += c.text;
              else if (typeof c.output_text === 'string') combined += c.output_text;
            }
          }
        }
      }
    }
    if (combined.trim()) return combined.trim();
  }
  // 3. Fallback to standard chat completions choices if present
  if (Array.isArray(data.choices) && data.choices[0]?.message?.content) {
    return data.choices[0].message.content.trim();
  }
  // 4. Fallback to data.response or data.result
  if (typeof data.response === 'string') return data.response.trim();
  if (typeof data.result === 'string') return data.result.trim();
  return typeof data === 'string' ? data : JSON.stringify(data);
}

