function buildWb3ComponentFeaturesPromptText(selectedFeatures = [], customFeaturesText = '') {
  const sections = [];
  const handled = new Set();

  if (Array.isArray(selectedFeatures)) {
    selectedFeatures.forEach(f => {
      if (!f || handled.has(f)) return;
      handled.add(f);
      const chars = WB3_COMPONENT_FEATURES[f];
      if (chars) {
        sections.push(`* **${f}:** ${chars}`);
      } else {
        sections.push(`* **${f}:** Dimensional tolerance, surface quality, functional positioning`);
      }
    });
  }

  if (customFeaturesText && typeof customFeaturesText === 'string') {
    customFeaturesText.split(/[,;\n]/).forEach(line => {
      const trimmed = line.trim();
      if (!trimmed || handled.has(trimmed)) return;
      handled.add(trimmed);
      sections.push(`* **${trimmed} (User Specified):** Address this exact feature / characteristic as specified by user`);
    });
  }

  if (sections.length === 0) return '';
  return `\n════════════════════════════════════════════════════════════════════════════════\nPRODUCT / PROCESS FEATURES & IMPORTANT CHARACTERISTICS:\nCheck the following component features and their measurable characteristics when formulating causes:\nCRITICAL INSTRUCTION: Link ONLY those features and characteristics that are logically and physically relevant to the specific failure mode, component function, and root cause mechanism under consideration (do not link unrelated features).\n\n${sections.join('\n')}\n════════════════════════════════════════════════════════════════════════════════\n`;
}

