// WB3 STEP 3: FAILURE MODES
// ══════════════════════════════════════════════════════════════════════════════

function generateWb3Step3Prompt() {
  const ctx = getActiveFmeaData();
  const nodeId = aiWorkbench3State.currentNodeId;
  const node = getStructureNodeById(ctx.structure, nodeId);
  if (!node) return '';
  const fns = aiWorkbench3State.nodeFunctions[nodeId] || [];
  const userCtx = aiWorkbench3State.nodeContexts[nodeId] || {};
  const isCatalogue = !!userCtx.isCatalogueItem;
  const catalogueTag = isCatalogue ? ' [CATALOGUE / OFF-THE-SHELF PART — NOT DESIGN RESPONSIBLE]' : '';
  const catalogueFmRule = isCatalogue ? '\nCATALOGUE SELECTION DIRECTIVE: We are selecting this standard part from a product catalogue (not design responsible). Focus failure modes on loss or degradation of specified rating, incorrect application limits, interface non-conformance, or exceeding catalogue specifications.\n' : '';

  const prompt = `DFMEA Step 3 — Failure Mode Analysis (AIAG-VDA 1st Ed.)
ELEMENT: "${userCtx.itemName || node.name}" (${userCtx.itemType || 'Assembly'})${catalogueTag}
FUNCTIONS:
${JSON.stringify(fns.map(f => ({ tempId: f.tempId, name: f.name, type: f.type })), null, 2)}

For each  primary function, derive applicable failure modes across types: loss / partial / degradation / unintended. 
For remaining type of function consider ONLY loss of function failure type
${getWb3AnalysisModeDirectives(3)}
${catalogueFmRule}RULES: (1) Physically credible only — no modes without a real mechanism. (2) One entry = one failure type x one function. (3) for primary consider all types of failure for others function consider only loss and degradation type of failure subjected to applicability Keep name values minimal.
Keep name values minimal. Output JSON only:
{
  "failureModes": [
    {
      "tempId": "${Date.now()}-fm-1",
      "functionTempId": "${fns[0] ? fns[0].tempId : 'fn-temp-1'}",
      "name": "<failure mode name>",
      "failureType": "Loss of function",
      "severity": 8
    }
  ]
}`;

  const preview = document.getElementById('wb3Step3PromptPreview');
  if (preview) preview.value = prompt;
  return prompt;
}

function parseWb3Step3Json() {
  const input = document.getElementById('wb3Step3JsonResponseInput');
  if (!input || !input.value.trim()) {
    alert("Please paste the failure modes JSON response first.");
    return;
  }
  try {
    const raw = sanitizeJsonString(input.value);
    const parsed = JSON.parse(raw);
    let modes = parsed.failureModes || parsed.modes || parsed.data || (Array.isArray(parsed) ? parsed : []);
    if (!modes.length && parsed.failureModeEffects) modes = parsed.failureModeEffects;
    if (!Array.isArray(modes) || modes.length === 0) {
      alert("No valid failure modes found in JSON response.");
      return;
    }
    const nodeId = aiWorkbench3State.currentNodeId;
    aiWorkbench3State.nodeFailures[nodeId] = modes.map((fn, idx) => ({
      tempId: fn.tempId || fn.id || fn.failureId || `fm-${idx + 1}`,
      functionTempId: fn.functionTempId || fn.fnTempId || fn.functionId || '',
      name: fn.name || fn.failureName || fn.desc || `Failure Mode ${idx + 1}`,
      failureType: fn.failureType || fn.type || 'Loss of function',
      severity: parseInt(fn.severity || fn.sev || 8, 10) || 8,
      effectsList: fn.effectsList || [],
      effects: fn.effects || {},
      causesList: fn.causesList || []
    }));
    aiWorkbench3State.step4FmPointer[nodeId] = 0;
    aiWorkbench3State.step5FmPointer[nodeId] = 0;
    aiWorkbench3State.updatedEffectsLibrary[nodeId] = null;
    renderWb3FailureModesList();
    if (typeof showToast === 'function') showToast(`📥 Loaded ${modes.length} failure modes!`, 'success');
  } catch (err) {
    alert("JSON Parsing Error: " + err.message);
  }
}

function renderWb3FailureModesList() {
  const nodeId = aiWorkbench3State.currentNodeId;
  const tbody = document.getElementById('wb3FailureModesTableBody');
  const countEl = document.getElementById('wb3FailureModesCount');
  if (!tbody) return;
  const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
  if (countEl) countEl.textContent = fms.length;
  if (fms.length === 0) {
    tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:18px; color:#64748b;">No failure modes loaded yet.</td></tr>';
    return;
  }
  const typeColors = { 'Loss of function': '#ef4444', 'Partial function': '#f59e0b', 'Intermittent function': '#8b5cf6', 'Degradation over time': '#10b981', 'Exceeding function': '#0284c7', 'Unintended function': '#ec4899', 'Delayed function': '#64748b' };
  tbody.innerHTML = fms.map((fm, idx) => {
    const tc = typeColors[fm.failureType] || '#64748b';
    return `<tr style="border-bottom:1px solid #1e293b;">
      <td style="width:36px; text-align:center; padding:4px;"><input type="checkbox" checked class="wb3-fm-chk" value="${escapeHtml(fm.tempId)}"></td>
      <td style="padding:6px 8px; color:#cbd5e1; font-weight:600; font-size:11px;">${escapeHtml(fm.name)}</td>
      <td style="padding:6px 8px;"><span style="font-size:10px; font-weight:700; color:${tc}; background:${tc}22; padding:1px 6px; border-radius:3px;">${escapeHtml(fm.failureType)}</span></td>
      <td style="padding:6px 8px; text-align:center;"><input type="number" min="1" max="10" value="${fm.severity}" onchange="updateWb3FailureSeverity(${idx}, this.value)" style="width:42px; background:#020617; border:1px solid #334155; border-radius:4px; color:#ef4444; font-weight:800; text-align:center; font-size:11px; padding:2px;"></td>
      <td style="padding:6px 8px; text-align:center;"><button class="btn btn-sm" onclick="deleteWb3FailureMode(${idx})" style="padding:1px 6px; font-size:10px; color:#ef4444; background:transparent; border:1px solid #ef4444;">✕</button></td>
    </tr>`;
  }).join('');
}

function updateWb3FailureSeverity(idx, val) {
  const nodeId = aiWorkbench3State.currentNodeId;
  if (aiWorkbench3State.nodeFailures[nodeId] && aiWorkbench3State.nodeFailures[nodeId][idx]) {
    aiWorkbench3State.nodeFailures[nodeId][idx].severity = parseInt(val, 10) || 8;
  }
}

function deleteWb3FailureMode(idx) {
  const nodeId = aiWorkbench3State.currentNodeId;
  if (aiWorkbench3State.nodeFailures[nodeId]) {
    aiWorkbench3State.nodeFailures[nodeId].splice(idx, 1);
    renderWb3FailureModesList();
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// WB3 STEP 4: MICRO-STEP EFFECTS (One FM at a Time)
// ══════════════════════════════════════════════════════════════════════════════

function renderWb3Step4MicroNav() {
  const nodeId = aiWorkbench3State.currentNodeId;
  const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
  const pointer = aiWorkbench3State.step4FmPointer[nodeId] || 0;
  const nav = document.getElementById('wb3Step4MicroNav');
  const promptArea = document.getElementById('wb3Step4FmPromptArea');
  const responseArea = document.getElementById('wb3Step4FmResponseArea');
  if (!nav) return;

  if (fms.length === 0) {
    nav.innerHTML = '<div style="text-align:center; padding:18px; color:#64748b; font-size:11px;">No failure modes yet. Complete Step 3 first.</div>';
    if (promptArea) promptArea.style.display = 'none';
    if (responseArea) responseArea.style.display = 'none';
    return;
  }

  const fm = fms[pointer];
  const allDone = fms.every((f) => (f.effectsList && f.effectsList.length > 0));
  const currentDone = fm && fm.effectsList && fm.effectsList.length > 0;

  nav.innerHTML = `
    <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:10px; padding:10px; background:#0f172a; border:1px solid #1e293b; border-radius:8px; margin-bottom:12px;">
      <div style="display:flex; align-items:center; gap:12px;">
        <button onclick="goToWb3Step4Fm(${pointer - 1})" ${pointer === 0 ? 'disabled' : ''} style="padding:4px 10px; background:#1e293b; border:1px solid #334155; border-radius:6px; color:#94a3b8; cursor:${pointer === 0 ? 'not-allowed' : 'pointer'}; font-size:11px;">◀ Prev FM</button>
        <div style="text-align:center;">
          <div style="font-size:12px; font-weight:800; color:#38bdf8;">Failure Mode ${pointer + 1} / ${fms.length}</div>
          <div style="font-size:10px; color:#64748b; margin-top:2px;">${escapeHtml(fm ? fm.name.slice(0, 80) + (fm.name.length > 80 ? '…' : '') : '')} ${currentDone ? '<span style="color:#10b981;">✓ Done</span>' : ''}</div>
        </div>
        <button onclick="goToWb3Step4Fm(${pointer + 1})" ${pointer >= fms.length - 1 ? 'disabled' : ''} style="padding:4px 10px; background:#1e293b; border:1px solid #334155; border-radius:6px; color:#94a3b8; cursor:${pointer >= fms.length - 1 ? 'not-allowed' : 'pointer'}; font-size:11px;">Next FM ▶</button>
      </div>
      <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
        <button onclick="copyWb3Step4FmPrompt(${pointer})" style="padding:5px 12px; background:#0284c7; border:none; border-radius:6px; color:#fff; font-size:11px; font-weight:700; cursor:pointer;">📋 Copy Prompt for FM ${pointer + 1}</button>
        <button id="wb3Step4ApiAllBtn" onclick="runWb3Step4AllApi()" style="display:none; padding:5px 12px; background:#7c3aed; border:none; border-radius:6px; color:#fff; font-size:11px; font-weight:700; cursor:pointer;">⚡ Run All ${fms.length} FMs via API</button>
        ${allDone ? '<span style="color:#10b981; font-weight:700; font-size:11px;">✅ All FMs Done</span>' : ''}
      </div>
    </div>
    <div style="margin-bottom:8px;">
      <div style="display:flex; gap:6px; flex-wrap:wrap; margin-bottom:4px;">
        ${fms.map((f, i) => {
          const done = f.effectsList && f.effectsList.length > 0;
          return `<button onclick="goToWb3Step4Fm(${i})" style="padding:2px 8px; font-size:10px; border-radius:4px; border:1px solid ${i === pointer ? '#38bdf8' : (done ? '#10b981' : '#334155')}; background:${i === pointer ? '#1e293b' : (done ? '#064e3b' : '#0f172a')}; color:${i === pointer ? '#38bdf8' : (done ? '#10b981' : '#64748b')}; cursor:pointer;" title="${escapeHtml(f.name)}">${done ? '✓' : ''} ${i + 1}</button>`;
        }).join('')}
      </div>
    </div>
  `;

  if (promptArea) {
    const promptText = generateWb3Step4FmPromptText(nodeId, pointer);
    const previewTA = document.getElementById('wb3Step4FmPromptPreview');
    if (previewTA) previewTA.value = promptText;
    promptArea.style.display = 'block';
  }
  if (responseArea) responseArea.style.display = 'block';

  renderWb3Step4EffectsForFm(nodeId, pointer);

  if (aiWorkbench3State.executionMode === 'API') {
    const btn = document.getElementById('wb3Step4ApiAllBtn');
    if (btn) btn.style.display = 'inline-flex';
  }
}

function goToWb3Step4Fm(idx) {
  const nodeId = aiWorkbench3State.currentNodeId;
  const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
  if (idx < 0 || idx >= fms.length) return;
  aiWorkbench3State.step4FmPointer[nodeId] = idx;
  renderWb3Step4MicroNav();
}

/**
 * Recursively resolves the maximum severity of an entire upstream failure chain
 * (Level N+1 -> Level N+2 -> ... -> Root).
 * @param {string} nodeId - Parent node ID
 * @param {string} fmId - Failure mode ID at this parent node
 * @returns {number} Maximum severity encountered along the upstream chain (1-10)
 */
function getUpstreamFailureChainSeverity(nodeId, fmId) {
  let maxSev = 1;
  const ctx = getActiveFmeaData();
  if (!nodeId || !fmId) return maxSev;

  // 1. Check in aiWorkbench3State for this node
  const stateFms = (aiWorkbench3State.nodeFailures && aiWorkbench3State.nodeFailures[nodeId]) || [];
  const fmState = stateFms.find(f => f.tempId === fmId || f.id === fmId || f.name === fmId);
  if (fmState) {
    if (fmState.severity) maxSev = Math.max(maxSev, parseInt(fmState.severity, 10) || 1);
    if (Array.isArray(fmState.effectsList) && fmState.effectsList.length > 0) {
      fmState.effectsList.forEach(eff => {
        if (eff.severity) maxSev = Math.max(maxSev, parseInt(eff.severity, 10) || 1);
      });
    }
  }

  // 2. Check in project functionLines if ingested
  if (ctx && Array.isArray(ctx.functionLines)) {
    const lines = ctx.functionLines.filter(fl => fl.structId === nodeId && (fl.failureModeId === fmId || fl.failureModeName === fmId || fl.id === fmId));
    lines.forEach(fl => {
      if (fl.severity) maxSev = Math.max(maxSev, parseInt(fl.severity, 10) || 1);
    });
  }

  // 3. Check in ctx.failureModeEffects & ctx.effects
  if (ctx && ctx.failureModeEffects && ctx.failureModeEffects[fmId]) {
    const effIds = ctx.failureModeEffects[fmId] || [];
    effIds.forEach(eid => {
      const eff = (ctx.effects || []).find(e => e.id === eid);
      if (eff && eff.severity) maxSev = Math.max(maxSev, parseInt(eff.severity, 10) || 1);
    });
  }

  // 4. If parent node has a higher parent (N+2), traverse upward recursively
  if (ctx && ctx.structure) {
    const parentOfParent = getParentStructureNode(ctx.structure, nodeId);
    if (parentOfParent && fmState && fmState.linkedHigherFailureId) {
      const higherSev = getUpstreamFailureChainSeverity(parentOfParent.id, fmState.linkedHigherFailureId);
      maxSev = Math.max(maxSev, higherSev);
    }
  }

  return maxSev;
}

function generateWb3Step4FmPromptText(nodeId, fmIndex, isFirstCall) {
  if (isFirstCall === undefined) isFirstCall = true;
  const ctx = getActiveFmeaData();
  let node = (ctx && ctx.structure) ? getStructureNodeById(ctx.structure, nodeId) : null;
  const userCtx = aiWorkbench3State.nodeContexts[nodeId] || {};
  const isCatalogue = !!userCtx.isCatalogueItem;
  const catalogueTag = isCatalogue ? ' [CATALOGUE SELECTION]' : '';
  if (!node) node = { id: nodeId, name: userCtx.itemName || 'Element Under Analysis' };
  const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
  const fm = fms[fmIndex];
  if (!fm) return '';
  const isRoot = (ctx && ctx.structure && node.id === ctx.structure.id);
  const parentNode = (ctx && ctx.structure && !isRoot) ? getParentStructureNode(ctx.structure, nodeId) : null;

  // Current node functions (what this FM violates)
  const nodeFnsFromCtx = (ctx && ctx.functions) ? (ctx.functions || []).filter(f => f.structId === nodeId) : [];
  const nodeFnsFromState = aiWorkbench3State.nodeFunctions[nodeId] || [];
  const nodeFns = nodeFnsFromCtx.length > 0
    ? nodeFnsFromCtx
    : nodeFnsFromState.map(f => ({ id: f.tempId || f.id, name: f.name, type: f.type }));
  const nodeFnsText = nodeFns.length > 0
    ? '\nFunctions violated: ' + nodeFns.map(f => `[${f.id || f.tempId}] "${f.name}"`).join(', ') + '\n'
    : '';

  // ── ROOT ELEMENT ────────────────────────────────────────────────────────────
  if (isRoot || !parentNode) {
    const liveLib = aiWorkbench3State.updatedEffectsLibrary[nodeId] || [];
    const effectsLibText = liveLib.length > 0
      ? '\nEFFECTS LIBRARY (reuse existingLibraryId if match found):\n' +
        liveLib.map(e => `[${e.id || e.tempId}] ${e.category} | S${e.severity}: "${e.desc}"`).join('\n') + '\n'
      : '';

    if (!isFirstCall) {
      return `DFMEA Step 4 Effects (Root) — continuation.
FM ${fmIndex + 1}/${fms.length}: [${fm.tempId}] "${fm.name}" | ${fm.failureType}${nodeFnsText}${effectsLibText}
Apply same stakeholder tiers, severity scale, and rules as FM 1. Keep desc max 12 words. Output JSON only:
{ "failureTempId": "${fm.tempId}", "isRootSystem": true, "effects": [{ "tempId": "${Date.now()}-eff-1", "category": "End User Level", "desc": "<effect>", "severity": 0, "existingLibraryId": "" }] }`;
    }

    return `DFMEA Step 4 — Effects Analysis for TOP-LEVEL ROOT SYSTEM (AIAG-VDA 1st Ed.)
TARGET ROOT ELEMENT: "${userCtx.itemName || node.name}" (${userCtx.itemType || 'System Assembly'})
FM ${fmIndex + 1}/${fms.length}: [${fm.tempId}] "${fm.name}" | Type: ${fm.failureType} | Prelim Sev: ${fm.severity}${nodeFnsText}
TOP-LEVEL SYSTEMIC EFFECTS CRITERIA (SUBJECT TO APPLICABILITY FOR THIS SPECIFIC FUNCTION):
1. End User / Driver: safety hazard / primary fn loss / degradation / regulatory non-compliance / annoyance
2. OEM Assembly Plant: line stoppage / offline repair / vehicle containment (subject to applicability)
3. Own / Component Manufacturing Plant: scrap / quarantine / sorting (subject to applicability)
*Do NOT invent fake or forced plant entries if the failure only impacts the vehicle end user.*

EXACT AIAG-VDA SEVERITY (S) SCALE:
- S = 10: Safety-Related Effect (crash hazard, injury to occupants/pedestrians, catastrophic loss of control without warning).
- S = 9: Regulatory Non-Compliance | S = 8-7: Primary Function Loss/Degradation
- S = 6-5: Secondary Function Loss/Degradation | S = 4-3: Customer Annoyance | S = 2-1: Minor / No Effect
${getWb3AnalysisModeDirectives(4)}
CRITICAL RULES:
1. Multiple effects per level permitted. Keep each effect standalone (no clubbing).
2. Effects are consequences only — never embed root causes or mechanisms.
3. Provide description in minimal possible length (max 10-12 words).
${effectsLibText}
OUTPUT ONLY VALID JSON:
{
  "failureTempId": "${fm.tempId}",
  "isRootSystem": true,
  "effects": [
    {
      "tempId": "${Date.now()}-eff-1",
      "category": "End User Level",
      "desc": "Vehicle immobilized during field operation leaving operator stranded",
      "severity": 8,
      "existingLibraryId": ""
    }
  ]
}`;
  }

  // ── NON-ROOT ELEMENT ────────────────────────────────────────────────────────
  const parentFnsMap = {};
  const wb3ParentFns = (aiWorkbench3State.nodeFunctions && aiWorkbench3State.nodeFunctions[parentNode.id]) || [];
  wb3ParentFns.forEach(fn => {
    parentFnsMap[fn.tempId || fn.id] = { id: fn.tempId || fn.id, name: fn.name, type: fn.type || 'Primary function', fms: [] };
  });
  if (ctx) {
    (ctx.functions || []).filter(f => f.structId === parentNode.id).forEach(fn => {
      if (!parentFnsMap[fn.id] || parentFnsMap[fn.id].name === 'Parent Element Main Function') {
        parentFnsMap[fn.id] = { id: fn.id, name: fn.name, type: fn.type || 'Primary function', fms: [] };
      }
    });
  }
  const wb3ParentFms = (aiWorkbench3State.nodeFailures && aiWorkbench3State.nodeFailures[parentNode.id]) || [];
  wb3ParentFms.forEach(pfm => {
    const fnId = pfm.functionTempId || Object.keys(parentFnsMap)[0] || 'parent-fn-1';
    if (!parentFnsMap[fnId]) parentFnsMap[fnId] = { id: fnId, name: 'Parent Element Main Function', type: 'Primary function', fms: [] };
    const chainSev = getUpstreamFailureChainSeverity(parentNode.id, pfm.tempId || pfm.id);
    parentFnsMap[fnId].fms.push({ id: pfm.tempId || pfm.id, name: pfm.name, failureType: pfm.failureType || 'Loss of function', severity: chainSev });
  });
  if (ctx) {
    (ctx.functionLines || []).filter(fl => fl.structId === parentNode.id).forEach(fl => {
      const fnId = fl.functionId || Object.keys(parentFnsMap)[0] || 'parent-fn-1';
      if (!parentFnsMap[fnId]) parentFnsMap[fnId] = { id: fnId, name: fl.functionName || 'Parent Element Main Function', type: 'Primary function', fms: [] };
      const existing = parentFnsMap[fnId].fms.find(f => f.id === fl.failureModeId || f.name === fl.failureModeName);
      if (!existing && fl.failureModeName) {
        const chainSev = getUpstreamFailureChainSeverity(parentNode.id, fl.failureModeId || fl.id);
        parentFnsMap[fnId].fms.push({ id: fl.failureModeId || fl.id, name: fl.failureModeName, failureType: fl.failureType || 'Loss of function', severity: Math.max(chainSev, parseInt(fl.severity, 10) || 1) });
      }
    });
  }

  // Build parent hierarchy
  const parentFnKeys = Object.keys(parentFnsMap);
  let totalParentFms = 0;
  let parentHierarchyText = '';
  if (parentFnKeys.length > 0) {
    parentHierarchyText = parentFnKeys.map(k => {
      const fnObj = parentFnsMap[k];
      totalParentFms += fnObj.fms.length;
      let out = `▶ PARENT FUNCTION [${fnObj.id}]: "${fnObj.name}" (${fnObj.type})\n`;
      if (fnObj.fms.length > 0) {
        out += fnObj.fms.map(pf => `    • N+1 FAILURE MODE [${pf.id}]: "${pf.name}" | Chain Severity: ${pf.severity} | Type: ${pf.failureType}`).join('\n');
      } else {
        out += '    (No failure modes defined yet for this parent function)';
      }
      return out;
    }).join('\n\n');
  }
  if (!parentHierarchyText || totalParentFms === 0) {
    parentHierarchyText = `▶ PARENT ELEMENT: "${parentNode.name}" [${parentNode.partNo || 'PN-001'}]\n(Parent element functions and failure modes are not yet populated in the project. Please select or identify the parent functional failure mode that this component failure mode triggers).`;
  }

  const exFirstFm = parentFnKeys.length > 0 && parentFnsMap[parentFnKeys[0]].fms.length > 0
    ? parentFnsMap[parentFnKeys[0]].fms[0].id : 'fm-p1';
  const exFirstFmName = parentFnKeys.length > 0 && parentFnsMap[parentFnKeys[0]].fms.length > 0
    ? parentFnsMap[parentFnKeys[0]].fms[0].name : 'Parent Failure Mode';
  const exFirstFnName = parentFnKeys.length > 0
    ? parentFnsMap[parentFnKeys[0]].name : 'Parent Function';

  if (!isFirstCall) {
    return `DFMEA Step 4 N+1 Linkage — continuation.
FM ${fmIndex + 1}/${fms.length}: [${fm.tempId}] "${fm.name}" | ${fm.failureType}${nodeFnsText}
N+1 FAILURE MODES:
${parentHierarchyText}
Apply same linkage rules as FM 1. Output JSON only:
{ "failureTempId": "${fm.tempId}", "isRootSystem": false, "linkedParentFailureModes": [{ "parentFmId": "${exFirstFm}", "parentFmName": "${exFirstFmName}", "parentFunction": "${exFirstFnName}", "chainSeverity": 0 }] }`;
  }

  return `You are an Automotive Reliability & Safety Engineer performing AIAG-VDA DFMEA Step 4 Failure Network Linkage.

FOCUSED ELEMENT (Level N): "${userCtx.itemName || node.name}" (${userCtx.itemType || 'Component'})
SPECIFIC FAILURE MODE UNDER ANALYSIS (FM ${fmIndex + 1}/${fms.length}):
- Temp ID: "${fm.tempId}"
- Name: "${fm.name}"
- Failure Type: "${fm.failureType}"
${nodeFnsText}
PARENT ELEMENT (Level N+1): "${parentNode.name}" [${parentNode.partNo || 'PN-001'}]

AVAILABLE N+1 PARENT FUNCTIONS & FAILURE MODES (THE ONLY VALID EFFECTS FOR LEVEL N):
Below is the verified hierarchy of functions and failure modes of the parent element, including their total upstream chain severity:

${parentHierarchyText}

🔴 STRICT AIAG-VDA FAILURE NETWORK RULES:
1. ZERO NEW EFFECT GENERATION:
   - You MUST NOT invent, write, or generate any new failure effects, descriptions, or sentences.
   - The generic 3-Level Effects criteria (End User/OEM/Own Plant) is NOT valid for this element level and MUST NOT be used.
2. STRICT N+1 LINKAGE ONLY:
   - In AIAG-VDA DFMEA, the Failure Effects of a component (Level N) ARE the Failure Modes of its Parent Element (Level N+1).
   - Evaluate which specific N+1 parent failure mode(s) listed above are PHYSICALLY CAUSED by this component failure mode ("${fm.name}").
   - You MUST pick directly from the available N+1 Failure Mode IDs listed above.
3. MULTI-CHAIN SEVERITY INHERITANCE:
   - For each linked N+1 failure mode, the chain severity traces upstream through N+2 up to the ultimate Root Effect.
   - If this component failure mode links to multiple N+1 failure modes, resolve severity as the maximum of all linked chains.
${isRoot?getWb3AnalysisModeDirectives(4):''}
OUTPUT ONLY VALID JSON:
{
  "failureTempId": "${fm.tempId}",
  "isRootSystem": false,
  "linkedParentFailureModes": [
    {
      "parentFmId": "${exFirstFm}",
      "parentFmName": "${exFirstFmName}",
      "parentFunction": "${exFirstFnName}",
      "chainSeverity": 8
    }
  ]
}`;
}


function copyWb3Step4FmPrompt(fmIndex) {
  const nodeId = aiWorkbench3State.currentNodeId;
  const prompt = generateWb3Step4FmPromptText(nodeId, fmIndex, true);
  if (!prompt) return;
  navigator.clipboard.writeText(prompt).then(() => {
    if (typeof showToast === 'function') showToast(`📋 Copied Step 4 prompt for FM ${fmIndex + 1}!`, 'success');
  });
}

function parseWb3Step4FmJson(nodeId, fmIndex) {
  const input = document.getElementById('wb3Step4FmJsonInput');
  if (!input || !input.value.trim()) {
    alert("Please paste the effects JSON for this failure mode first.");
    return;
  }
  try {
    const raw = sanitizeJsonString(input.value);
    const parsed = JSON.parse(raw);

    const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
    const fm = fms[fmIndex];
    if (!fm) return;

    const ctx = getActiveFmeaData();
    const node = (ctx && ctx.structure) ? getStructureNodeById(ctx.structure, nodeId) : null;
    const isRoot = (ctx && ctx.structure && node && node.id === ctx.structure.id);
    const parentNode = (ctx && ctx.structure && !isRoot) ? getParentStructureNode(ctx.structure, nodeId) : null;

    let effectsList = [];

    // CASE 1: Non-Root Element with linkedParentFailureModes
    if (Array.isArray(parsed.linkedParentFailureModes) && parsed.linkedParentFailureModes.length > 0) {
      effectsList = parsed.linkedParentFailureModes.map((link, i) => {
        const pNodeId = parentNode ? parentNode.id : '';
        const chainSev = getUpstreamFailureChainSeverity(pNodeId, link.parentFmId) || parseInt(link.chainSeverity || link.severity, 10) || 5;
        return {
          tempId: link.parentFmId || `eff-link-${Date.now()}-${i + 1}`,
          category: 'N+1 Parent Failure Mode',
          desc: link.parentFmName || link.desc || link.name || 'Parent Failure Mode',
          severity: chainSev,
          existingLibraryId: link.parentFmId || '',
          parentFunction: link.parentFunction || '',
          causalRationale: link.causalRationale || ''
        };
      });
    } else if (Array.isArray(parsed.effects)) {
      effectsList = parsed.effects;
    } else if (Array.isArray(parsed)) {
      effectsList = parsed;
    }

    if (effectsList.length === 0) {
      alert("No effects or linked parent failure modes found in JSON. Check the format.");
      return;
    }

    const prefix = `eff-wb3-${nodeId.slice(0, 4)}-${fm.tempId.replace(/[^a-zA-Z0-9]/g, '')}-`;
    fm.effectsList = effectsList.map((e, i) => {
      const pNodeId = parentNode ? parentNode.id : '';
      let sev = parseInt(e.severity, 10) || 5;
      if (e.category === 'N+1 Parent Failure Mode' || !isRoot) {
        const upstream = getUpstreamFailureChainSeverity(pNodeId, e.existingLibraryId || e.tempId);
        if (upstream > sev) sev = upstream;
      }
      return {
        tempId: e.tempId || `${prefix}${i + 1}`,
        category: e.category || (!isRoot ? 'N+1 Parent Failure Mode' : 'End User Level'),
        desc: e.desc || e.description || '',
        severity: sev,
        existingLibraryId: e.existingLibraryId || '',
        parentFunction: e.parentFunction || '',
        causalRationale: e.causalRationale || ''
      };
    });

    // Multi-Chain Severity: Find max of each chain, then get max of result of all chains
    const maxSev = Math.max(...fm.effectsList.map(e => e.severity));
    fm.severity = maxSev;

    if (fm.effectsList.length > 0 && fm.effectsList[0].existingLibraryId) {
      fm.linkedHigherFailureId = fm.effectsList[0].existingLibraryId;
    }

    if (!aiWorkbench3State.updatedEffectsLibrary[nodeId]) aiWorkbench3State.updatedEffectsLibrary[nodeId] = [];
    const liveLib = aiWorkbench3State.updatedEffectsLibrary[nodeId];
    let newAdded = 0;
    fm.effectsList.forEach(e => {
      if (e.existingLibraryId) return;
      const exists = liveLib.find(le => le.desc && e.desc && le.desc.toLowerCase() === e.desc.toLowerCase());
      if (!exists) {
        const newId = e.tempId || `eff-lib-${Date.now()}-${newAdded}`;
        liveLib.push({ id: newId, category: e.category, desc: e.desc, severity: e.severity, existingLibraryId: '' });
        newAdded++;
      }
    });

    const linkNotice = !isRoot
      ? `🔗 Linked to ${fm.effectsList.length} N+1 Parent FMs (Max Chain Sev: S=${maxSev})!`
      : `✅ FM ${fmIndex + 1}: Loaded ${fm.effectsList.length} 3-Level effects (Max Sev: S=${maxSev})!`;

    if (typeof showToast === 'function') showToast(linkNotice, 'success');

    if (input) input.value = '';

    const nextIdx = fmIndex + 1;
    if (nextIdx < fms.length) {
      aiWorkbench3State.step4FmPointer[nodeId] = nextIdx;
    }
    renderWb3Step4MicroNav();
  } catch (err) {
    alert("JSON Parsing Error: " + err.message);
  }
}

function renderWb3Step4EffectsForFm(nodeId, fmIndex) {
  const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
  const fm = fms[fmIndex];
  const container = document.getElementById('wb3Step4EffectsListArea');
  if (!container) return;
  if (!fm || !fm.effectsList || fm.effectsList.length === 0) {
    container.innerHTML = '<div style="text-align:center; padding:10px; color:#64748b; font-size:11px;">No effects or parent failure linkages parsed for this FM yet.</div>';
    return;
  }

  const ctx = getActiveFmeaData();
  const node = (ctx && ctx.structure) ? getStructureNodeById(ctx.structure, nodeId) : null;
  const isRoot = (ctx && ctx.structure && node && node.id === ctx.structure.id);

  // Non-Root View: Show Linked N+1 Parent Failure Modes
  const isNonRootLinks = !isRoot || fm.effectsList.some(e => (e.category || '').includes('Parent'));
  if (isNonRootLinks) {
    container.innerHTML = `
      <div style="font-size:11px; font-weight:700; color:#f8fafc; margin-bottom:8px; display:flex; justify-content:space-between; align-items:center;">
        <div>
          <span>🔗 Linked N+1 Parent Failure Modes as Effects for: </span>
          <span style="color:#38bdf8;">${escapeHtml(fm.name.slice(0, 60))}</span>
        </div>
        <span style="background:#dc2626; color:#fff; padding:2px 8px; border-radius:4px; font-size:10px; font-weight:800;">
          Inherited Chain Sev: S=${fm.severity}
        </span>
      </div>
      <div style="display:flex; flex-direction:column; gap:6px; font-size:10.5px;">
        ${fm.effectsList.map(e => `
          <div style="background:#0f172a; padding:8px 10px; border-radius:5px; border:1px solid #3b82f6; display:flex; justify-content:space-between; align-items:center;">
            <div>
              <div style="font-weight:700; color:#e2e8f0; font-size:11px;">
                <span style="color:#38bdf8;">[N+1 FM]</span> ${escapeHtml(e.desc)}
              </div>
              ${e.parentFunction ? `<div style="font-size:10px; color:#94a3b8; margin-top:2px;">Parent Function: ${escapeHtml(e.parentFunction)}</div>` : ''}
              ${e.causalRationale ? `<div style="font-size:10px; color:#34d399; margin-top:2px;">Rationale: ${escapeHtml(e.causalRationale)}</div>` : ''}
            </div>
            <div style="text-align:right; margin-left:12px;">
              <span style="background:rgba(239,68,68,0.2); color:#f87171; border:1px solid rgba(239,68,68,0.4); padding:2px 6px; border-radius:4px; font-weight:800; font-size:10.5px;">
                S: ${e.severity}
              </span>
            </div>
          </div>
        `).join('')}
      </div>
    `;
    return;
  }

  // Root Element View: 3-Level Effects (End User, OEM, Component Plant)
  const euList = fm.effectsList.filter(e => (e.category || '').includes('End User'));
  const oemList = fm.effectsList.filter(e => (e.category || '').includes('OEM'));
  const plantList = fm.effectsList.filter(e => (e.category || '').includes('Component'));
  container.innerHTML = `
    <div style="font-size:11px; font-weight:700; color:#f8fafc; margin-bottom:6px; display:flex; justify-content:space-between; align-items:center;">
      <div>
        <span>✅ ${fm.effectsList.length} Systemic Effects parsed for: </span>
        <span style="color:#38bdf8;">${escapeHtml(fm.name.slice(0, 60))}</span>
      </div>
      <span style="background:#dc2626; color:#fff; padding:2px 8px; border-radius:4px; font-size:10px; font-weight:800;">
        Max Sev: S=${fm.severity}
      </span>
    </div>
    <div style="display:grid; grid-template-columns: repeat(3, 1fr); gap:8px; font-size:10.5px;">
      <div style="background:#0f172a; padding:6px; border-radius:4px; border:1px solid #3b82f6;">
        <span style="font-weight:700; color:#38bdf8;">👤 End User Level (${euList.length}):</span>
        ${euList.map(e => `<div style="color:#cbd5e1; margin-top:3px;">• ${escapeHtml(e.desc)} <strong style="color:#f87171;">(S:${e.severity})</strong>${e.existingLibraryId ? ' <span style="color:#34d399;">[Reused]</span>' : ' <span style="color:#38bdf8;">[New]</span>'}</div>`).join('')}
      </div>
      <div style="background:#0f172a; padding:6px; border-radius:4px; border:1px solid #f59e0b;">
        <span style="font-weight:700; color:#fbbf24;">🏭 OEM Plant (${oemList.length}):</span>
        ${oemList.map(e => `<div style="color:#cbd5e1; margin-top:3px;">• ${escapeHtml(e.desc)} <strong style="color:#fbbf24;">(S:${e.severity})</strong>${e.existingLibraryId ? ' <span style="color:#34d399;">[Reused]</span>' : ''}</div>`).join('')}
      </div>
      <div style="background:#0f172a; padding:6px; border-radius:4px; border:1px solid #10b981;">
        <span style="font-weight:700; color:#34d399;">📦 Component Plant (${plantList.length}):</span>
        ${plantList.map(e => `<div style="color:#cbd5e1; margin-top:3px;">• ${escapeHtml(e.desc)} <strong style="color:#34d399;">(S:${e.severity})</strong>${e.existingLibraryId ? ' <span style="color:#34d399;">[Reused]</span>' : ''}</div>`).join('')}
      </div>
    </div>
  `;
}

async function runWb3Step4AllApi(options = {}) {
  if (aiWorkbench3State.apiInProgress) {
    if (typeof showToast === 'function') showToast('⏳ API call is already running. Please wait.', 'warning');
    return;
  }
  const nodeId = aiWorkbench3State.currentNodeId;
  const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
  if (fms.length === 0) { alert("No failure modes to process."); return; }

  const resumePolicy = (options && options.resumePolicy) || aiWorkbench3State.resumePolicy || 'ungenerated';
  const statusEl = document.getElementById('wb3Step4ApiStatus');
  if (statusEl) { statusEl.style.display = 'block'; statusEl.color = '#38bdf8'; }

  const resumeFrom = (aiWorkbench3State.step4FmPointer[nodeId] || 0);
  const startIdx = (resumePolicy === 'all') ? 0 : ((resumeFrom >= fms.length) ? 0 : resumeFrom);
  if (startIdx > 0 && statusEl) {
    statusEl.textContent = `⏩ Resuming from FM ${startIdx + 1}/${fms.length}...`;
    statusEl.style.color = '#f59e0b';
  }

  const ctx = getActiveFmeaData();
  const node = (ctx && ctx.structure) ? getStructureNodeById(ctx.structure, nodeId) : null;
  const isRoot = (ctx && ctx.structure && node && node.id === ctx.structure.id);
  const parentNode = (ctx && ctx.structure && !isRoot) ? getParentStructureNode(ctx.structure, nodeId) : null;

  wb3SetApiLock(true);
  let failed = false;
  try {
  for (let i = startIdx; i < fms.length; i++) {
    aiWorkbench3State.step4FmPointer[nodeId] = i;
    const fm = fms[i];
    const alreadyHasEffects = Array.isArray(fm.effectsList) && fm.effectsList.length > 0;
    if (resumePolicy === 'ungenerated' && alreadyHasEffects) {
      if (statusEl) statusEl.textContent = `⏩ FM ${i + 1}/${fms.length}: "${fm.name.slice(0, 30)}" already has effects — skipping...`;
      renderWb3Step4MicroNav();
      continue;
    }
    if (statusEl) statusEl.textContent = `Processing FM ${i + 1}/${fms.length}: ${fms[i].name.slice(0, 50)}...`;
    renderWb3Step4MicroNav();

    const prompt = generateWb3Step4FmPromptText(nodeId, i, i === startIdx);
    const result = await executeWb3ApiQuery(prompt, 'wb3Step4ApiStatus', null);
    if (!result) {
      if (statusEl) { statusEl.textContent = `❌ Failed at FM ${i + 1}/${fms.length}: "${fms[i].name.slice(0, 60)}". Fix the issue and click Generate again to resume.`; statusEl.style.color = '#f87171'; }
      if (typeof showToast === 'function') showToast(`❌ Step 4 halted at FM ${i + 1}. Resolve and click Generate to resume.`, 'error');
      failed = true;
      break;
    }

    try {
      const raw = sanitizeJsonString(result);
      const parsed = JSON.parse(raw);
      const fm = fms[i];
      let effectsList = [];

      if (Array.isArray(parsed.linkedParentFailureModes) && parsed.linkedParentFailureModes.length > 0) {
        effectsList = parsed.linkedParentFailureModes.map((link, j) => {
          const pNodeId = parentNode ? parentNode.id : '';
          const chainSev = getUpstreamFailureChainSeverity(pNodeId, link.parentFmId) || parseInt(link.chainSeverity || link.severity, 10) || 5;
          return {
            tempId: link.parentFmId || `eff-link-${Date.now()}-${j + 1}`,
            category: 'N+1 Parent Failure Mode',
            desc: link.parentFmName || link.desc || link.name || 'Parent Failure Mode',
            severity: chainSev,
            existingLibraryId: link.parentFmId || '',
            parentFunction: link.parentFunction || '',
            causalRationale: link.causalRationale || ''
          };
        });
      } else if (Array.isArray(parsed.effects)) {
        effectsList = parsed.effects;
      } else if (Array.isArray(parsed)) {
        effectsList = parsed;
      }

      const prefix = `eff-wb3-${nodeId.slice(0, 4)}-${fm.tempId.replace(/[^a-zA-Z0-9]/g, '')}-`;
      fm.effectsList = effectsList.map((e, j) => {
        const pNodeId = parentNode ? parentNode.id : '';
        let sev = parseInt(e.severity, 10) || 5;
        if (e.category === 'N+1 Parent Failure Mode' || !isRoot) {
          const upstream = getUpstreamFailureChainSeverity(pNodeId, e.existingLibraryId || e.tempId);
          if (upstream > sev) sev = upstream;
        }
        return {
          tempId: e.tempId || `${prefix}${j + 1}`,
          category: e.category || (!isRoot ? 'N+1 Parent Failure Mode' : 'End User Level'),
          desc: e.desc || '',
          severity: sev,
          existingLibraryId: e.existingLibraryId || '',
          parentFunction: e.parentFunction || '',
          causalRationale: e.causalRationale || ''
        };
      });

      // Multi-Chain Severity: max of all linked chains
      const maxSev = Math.max(...fm.effectsList.map(e => e.severity), fm.severity || 1);
      fm.severity = maxSev;

      if (fm.effectsList.length > 0 && fm.effectsList[0].existingLibraryId) {
        fm.linkedHigherFailureId = fm.effectsList[0].existingLibraryId;
      }

      if (!aiWorkbench3State.updatedEffectsLibrary[nodeId]) aiWorkbench3State.updatedEffectsLibrary[nodeId] = [];
      const liveLib = aiWorkbench3State.updatedEffectsLibrary[nodeId];
      fm.effectsList.forEach(e => {
        if (e.existingLibraryId) return;
        const exists = liveLib.find(le => le.desc && e.desc && le.desc.toLowerCase() === e.desc.toLowerCase());
        if (!exists) liveLib.push({ id: e.tempId, category: e.category, desc: e.desc, severity: e.severity, existingLibraryId: '' });
      });
    } catch (err) {
      console.warn(`FM ${i + 1} parse error:`, err);
    }
  }

  if (!failed) {
    aiWorkbench3State.step4FmPointer[nodeId] = 0;
    if (statusEl) { statusEl.textContent = `✅ All ${fms.length} FMs effects done! Auto-advancing to Step 5...`; statusEl.style.color = '#34d399'; }
    renderWb3Step4MicroNav();
    if (typeof showToast === 'function') showToast(`✅ Step 4 complete! Auto-starting Step 5 Causes...`, 'success');
    // ── AUTO-ADVANCE TO STEP 5 ──
    setTimeout(() => { wb3SetApiLock(false); goToWb3Step(5); }, 800);
  }
  } finally {
    if (failed) wb3SetApiLock(false);
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// WB3 STEP 5: MICRO-STEP CAUSES (One FM at a Time)
// ══════════════════════════════════════════════════════════════════════════════
function renderWb3Step5MicroNav() {
  const nodeId = aiWorkbench3State.currentNodeId;
  const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
  const pointer = aiWorkbench3State.step5FmPointer[nodeId] || 0;
  const nav = document.getElementById('wb3Step5MicroNav');
  if (!nav) return;

  if (fms.length === 0) {
    nav.innerHTML = '<div style="text-align:center; padding:18px; color:#64748b; font-size:11px;">No failure modes yet. Complete Steps 3 & 4 first.</div>';
    return;
  }

  const fm = fms[pointer];
  const causes = aiWorkbench3State.nodeCauses[nodeId] || [];
  const fmCauses = causes.filter(c => c.failureTempId === (fm ? fm.tempId : ''));
  const allDone = fms.every(f => causes.some(c => c.failureTempId === f.tempId));

  nav.innerHTML = `
    <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:10px; padding:10px; background:#0f172a; border:1px solid #1e293b; border-radius:8px; margin-bottom:12px;">
      <div style="display:flex; align-items:center; gap:12px;">
        <button onclick="goToWb3Step5Fm(${pointer - 1})" ${pointer === 0 ? 'disabled' : ''} style="padding:4px 10px; background:#1e293b; border:1px solid #334155; border-radius:6px; color:#94a3b8; cursor:${pointer === 0 ? 'not-allowed' : 'pointer'}; font-size:11px;">◀ Prev FM</button>
        <div style="text-align:center;">
          <div style="font-size:12px; font-weight:800; color:#f59e0b;">Failure Mode ${pointer + 1} / ${fms.length}</div>
          <div style="font-size:10px; color:#64748b; margin-top:2px;">${escapeHtml(fm ? fm.name.slice(0, 80) + (fm.name.length > 80 ? '…' : '') : '')} ${fmCauses.length > 0 ? '<span style="color:#10b981;">✓ ' + fmCauses.length + ' causes</span>' : ''}</div>
        </div>
        <button onclick="goToWb3Step5Fm(${pointer + 1})" ${pointer >= fms.length - 1 ? 'disabled' : ''} style="padding:4px 10px; background:#1e293b; border:1px solid #334155; border-radius:6px; color:#94a3b8; cursor:${pointer >= fms.length - 1 ? 'not-allowed' : 'pointer'}; font-size:11px;">Next FM ▶</button>
      </div>
      <div style="display:flex; gap:8px; flex-wrap:wrap;">
        <button onclick="copyWb3Step5FmPrompt(${pointer})" style="padding:5px 12px; background:#f59e0b; border:none; border-radius:6px; color:#000; font-size:11px; font-weight:700; cursor:pointer;">📋 Copy Prompt for FM ${pointer + 1}</button>
        <button id="wb3Step5ApiAllBtn" onclick="runWb3Step5AllApi()" style="display:none; padding:5px 12px; background:#7c3aed; border:none; border-radius:6px; color:#fff; font-size:11px; font-weight:700; cursor:pointer;">⚡ Run All ${fms.length} FMs via API</button>
        ${allDone ? '<span style="color:#10b981; font-weight:700; font-size:11px;">✅ All FMs Done</span>' : ''}
      </div>
    </div>
    <div style="margin-bottom:8px;">
      <div style="display:flex; gap:6px; flex-wrap:wrap;">
        ${fms.map((f, i) => {
          const done = causes.some(c => c.failureTempId === f.tempId);
          return `<button onclick="goToWb3Step5Fm(${i})" style="padding:2px 8px; font-size:10px; border-radius:4px; border:1px solid ${i === pointer ? '#f59e0b' : (done ? '#10b981' : '#334155')}; background:${i === pointer ? '#1e293b' : (done ? '#064e3b' : '#0f172a')}; color:${i === pointer ? '#f59e0b' : (done ? '#10b981' : '#64748b')}; cursor:pointer;" title="${escapeHtml(f.name)}">${done ? '✓' : ''} ${i + 1}</button>`;
        }).join('')}
      </div>
    </div>
  `;

  const promptText = generateWb3Step5FmPromptText(nodeId, pointer);
  const previewTA = document.getElementById('wb3Step5FmPromptPreview');
  if (previewTA) previewTA.value = promptText;

  renderWb3CausesForFm(nodeId, pointer);

  if (aiWorkbench3State.executionMode === 'API') {
    const btn = document.getElementById('wb3Step5ApiAllBtn');
    if (btn) btn.style.display = 'inline-flex';
  }
}

function goToWb3Step5Fm(idx) {
  const nodeId = aiWorkbench3State.currentNodeId;
  const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
  if (idx < 0 || idx >= fms.length) return;
  aiWorkbench3State.step5FmPointer[nodeId] = idx;
  renderWb3Step5MicroNav();
}

function generateWb3Step5FmPromptText(nodeId, fmIndex, isFirstCall) {
  if (isFirstCall === undefined) isFirstCall = true;
  const ctx = getActiveFmeaData();
  let node = (ctx && ctx.structure) ? getStructureNodeById(ctx.structure, nodeId) : null;
  const userCtx = aiWorkbench3State.nodeContexts[nodeId] || {};
  if (!node) node = { id: nodeId, name: userCtx.itemName || 'Element Under Analysis' };
  const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
  const fm = fms[fmIndex];
  if (!fm) return '';

  const isCatalogue = !!userCtx.isCatalogueItem;
  const catalogueTag = isCatalogue ? ' [CATALOGUE SELECTION — NOT DESIGN RESPONSIBLE]' : '';

  // Live growing causes library (sent on every call — grows with each FM)
  const liveCauses = (aiWorkbench3State.updatedCausesLibrary && aiWorkbench3State.updatedCausesLibrary[nodeId])
    ? aiWorkbench3State.updatedCausesLibrary[nodeId]
    : ((fmeaData && fmeaData.libraries && fmeaData.libraries.causes)
        ? fmeaData.libraries.causes
        : ((ctx && ctx.libraries && ctx.libraries.causes) ? ctx.libraries.causes : []));
  const causesLibText = (liveCauses && liveCauses.length > 0)
    ? '\nCAUSES LIBRARY (reuse existingLibraryId if context matches):\n' +
      liveCauses.map(c => `[${c.id || c.tempId}] "${c.details || c.desc || ''}" | ${c.characteristics || ''} | ${c.spec || '____'}`).join('\n') + '\n'
    : '';

  const fmLine = `FM ${fmIndex + 1}/${fms.length}: [${fm.tempId}] "${fm.name}" | ${fm.failureType} | S${fm.severity}`;
  const matPart = userCtx.material ? ` | Mat: "${userCtx.material}"` : '';
  const elemLine = `ELEMENT: "${userCtx.itemName || node.name}" (${userCtx.itemType || 'Assembly'})${catalogueTag}${matPart}`;

  // ── CONTINUATION CALL ──
  if (!isFirstCall) {
    const catalogueContinuationRule = isCatalogue
      ? `STRICT RULE (CATALOGUE SELECTION): ONLY consider causes related to the SELECTION OF PRODUCT SPECIFICATION (example but not limited to ratings, load/temperature capacity, environmental fit, duty cycle). Do NOT consider internal component design/manufacturing defects.Keep all field values minimal (max 7 words).Keep all field values minimal (max 7 words)\n`
      : `Apply same rules as FM 1. STRICT RULE: Every failure cause MUST be expressed as a specific product or joint characteristic deficiency (example but not limited to material thickness, material specification, hardness, surface finish, tolerances, diameter, welding specs, position & orientation, bolt torque). NEVER write generic causes. Keep all field values minimal (max 7 words).\n`;

    return `DFMEA Step 5 Root Causes — continuation.
${elemLine}
${fmLine}
${causesLibText}
${catalogueContinuationRule}Output JSON only:
{ "failureTempId": "${fm.tempId}", "causes": [{ "tempId": "${Date.now()}-cause-1", "causeDetails": "<specific characteristic deficiency>", "characteristics": "<specific char>", "spec": "<spec >= ____>", "occurrence": 3, "detection": 2, "ap": "M", "existingLibraryId": "" }] }`;
  }

  // ── FIRST CALL — full prompt ──
  const gdtPart = userCtx.gdt ? ` | GDT: "${userCtx.gdt}"` : '';
  const envPart = userCtx.env ? ` | Env: "${userCtx.env}"` : '';
  const isAssy = (userCtx.itemType === 'Assembly' || userCtx.itemType === 'Mixed');
  const isComp = (userCtx.itemType === 'Component' || userCtx.itemType === 'Mixed');
  let jointHint = '';

  if (isCatalogue) {
    // Strict Catalogue / Off-the-Shelf Selection Rule
    jointHint = `\n\n════════════════════════════════════════════════════════════════════════════════\nCRITICAL RULE — CATALOGUE / OFF-THE-SHELF PART SELECTION (NOT DESIGN RESPONSIBLE):\nWe are selecting this element from a product catalogue (we are NOT design responsible for internal component design or manufacturing).\nYOU MUST ONLY CONSIDER CAUSES RELATED TO THE SELECTION OF PRODUCT SPECIFICATION:\n• Inadequate specification of load rating, torque capacity, or peak stress limit for operational demands\n• Incorrect operating temperature range specified for the operational thermal environment\n• Improper duty cycle, endurance rating, or fatigue life specification for customer usage profile\n• Inappropriate material grade, polymer compound, or coating specified for fluid/chemical/environmental exposure\n• Incorrect mounting dimensions, interface envelope, or tolerance specification selected from catalogue\n• Specification omission of required ingress protection (IP code), sealing, or corrosion resistance\nDO NOT hypothesize internal component manufacturing defects, internal metallurgy flaws, internal molding/tooling defects, or assembly defects internal to the catalogue part.\n════════════════════════════════════════════════════════════════════════════════\n`;
  } else {
    // Design Responsible Mode (full engineering design & joint causes)
    const itemType = userCtx.itemType || 'Assembly';
    const isAssyOnly = (itemType === 'Assembly');
    const isCompOnly = (itemType === 'Component');
    const isMixed = (itemType === 'Mixed');

    let jointSection = '';
    if (isAssyOnly || isMixed) {
      const selJoints = (userCtx.joints && userCtx.joints.length > 0) ? userCtx.joints : ['Welding', 'Nut-Bolt'];
      if (typeof buildWb3JointCharacteristicsPromptText === 'function') {
        jointSection = buildWb3JointCharacteristicsPromptText(selJoints);
      }
    }

    let compSection = '';
    let featuresSection = '';

    if (isCompOnly || isMixed) {
      let selCompTypes = [];
      let selCustomTypes = '';
      let selCompFeatures = [];
      let selCustomFeatures = '';

      if (isMixed) {
        if (Array.isArray(userCtx.subComponents) && userCtx.subComponents.length > 0) {
          const typesSet = new Set();
          const customTypesArr = [];
          const featsSet = new Set();
          const customFeatsArr = [];

          userCtx.subComponents.forEach(sc => {
            if (Array.isArray(sc.componentTypes) && sc.componentTypes.length > 0) {
              sc.componentTypes.forEach(t => typesSet.add(t));
            }
            if (sc.customTypes && typeof sc.customTypes === 'string') {
              customTypesArr.push(sc.customTypes);
            }
            if (Array.isArray(sc.componentFeatures) && sc.componentFeatures.length > 0) {
              sc.componentFeatures.forEach(f => featsSet.add(f));
            }
            if (sc.customFeatures && typeof sc.customFeatures === 'string') {
              customFeatsArr.push(sc.customFeatures);
            }
          });
          selCompTypes = Array.from(typesSet);
          selCustomTypes = customTypesArr.join(', ');
          selCompFeatures = Array.from(featsSet);
          selCustomFeatures = customFeatsArr.join(', ');
        }
      } else {
        // Pure Component mode: strictly read from userCtx (saved in Step 1) without unwanted auto-detect overwrite
        selCompTypes = Array.isArray(userCtx.componentTypes) ? [...userCtx.componentTypes] : [];
        selCustomTypes = userCtx.customComponentTypes || '';
        selCompFeatures = Array.isArray(userCtx.componentFeatures) ? [...userCtx.componentFeatures] : [];
        selCustomFeatures = userCtx.customComponentFeatures || '';
      }

      const activeChars = Array.isArray(userCtx.componentCharacteristics) && userCtx.componentCharacteristics.length > 0
        ? userCtx.componentCharacteristics
        : (window.wb3ComponentSelectedChars || []);
      if (activeChars.length > 0) {
        const charLines = activeChars.map(c => `  • [${c.category || 'Component'}] ${c.name}${c.spec ? ' (Specifications: ' + c.spec + ')' : ''}`).join('\n');
        compSection = `\nLINKED COMPONENT CHARACTERISTICS & SPECIFICATIONS (AIAG-VDA ROOT CAUSE DERIVATION):\n${charLines}\nDIRECTIVE: Formulate specific failure causes addressing deficiencies in the above measurable specifications.\n`;
      } else if (selCompTypes.length > 0 || selCustomTypes) {
        const compText = (typeof buildWb3ComponentCharacteristicsPromptText === 'function')
          ? buildWb3ComponentCharacteristicsPromptText(selCompTypes, selCustomTypes)
          : '';
        if (compText) {
          compSection = `\nComponent: derive from geometry (fillet, wall thickness), metallurgy, surface finish, and tolerances.${compText}`;
        }
      }

      if (selCompFeatures.length > 0 || selCustomFeatures) {
        const featText = (typeof buildWb3ComponentFeaturesPromptText === 'function')
          ? buildWb3ComponentFeaturesPromptText(selCompFeatures, selCustomFeatures)
          : '';
        if (featText) {
          featuresSection = featText;
        }
      }
    }

    let mixedConstituents = '';
    if (isMixed) {
      const comps = userCtx.subComponents || [];
      if (comps.length > 0) {
        mixedConstituents = '\nCONSTITUENT COMPONENTS (MIXED ARCHITECTURE):\n' +
          comps.map((c, i) => {
            const allTypes = [...(Array.isArray(c.componentTypes) ? c.componentTypes : [])];
            if (c.customTypes) c.customTypes.split(/[,;\n]/).forEach(t => { if (t.trim()) allTypes.push(t.trim()); });
            const allFeats = [...(Array.isArray(c.componentFeatures) ? c.componentFeatures : [])];
            if (c.customFeatures) c.customFeatures.split(/[,;\n]/).forEach(f => { if (f.trim()) allFeats.push(f.trim()); });
            const typesTag = allTypes.length > 0 ? ` [Types: ${allTypes.join(', ')}]` : '';
            const featsTag = allFeats.length > 0 ? ` [Features: ${allFeats.join(', ')}]` : '';
            return `  ${i + 1}. "${c.name}" (${c.partNumber || 'N/A'})${typesTag}${featsTag}: ${c.desc}${c.material ? ' | Mat: ' + c.material : ''}`;
          }).join('\n') +
          '\nDIRECTIVES FOR MIXED ELEMENT: Derive failure causes addressing BOTH joint connection characteristics (connection mechanics) AND individual constituent component characteristics & features strictly according to the constituent components listed above.\n';
      }
    }

    const characteristicRuleBanner = `\n\n════════════════════════════════════════════════════════════════════════════════\nSTRICT AIAG-VDA RULE — LOGICALLY RELEVANT CHARACTERISTIC CAUSES ONLY:\n1. Every Failure Cause (FC) MUST be formulated as a SPECIFIC CHARACTERISTIC SPECIFICATION DEFICIT chosen strictly from the applicable user-selected characteristics and features above.\n2. LOGICAL LINKAGE RULE: Link ONLY those characteristics and features that are logically, physically, and mechanistically relevant to the specific Failure Mode (FM), failure mechanism, and component function under consideration. NEVER force or fabricate illogical combinations.\n3. NO GENERIC TERMS: NEVER generate vague or generic causes (do NOT write "part wears out", "excessive vibration", "overheating", "high stress", or "environmental degradation").\n4. Every cause MUST pinpoint the exact engineering characteristic deficiency with its measurable specification (e.g. >= ____ or <= ____ or = ____ +/- ____).\n════════════════════════════════════════════════════════════════════════════════\n`;

    jointHint = `${jointSection}${mixedConstituents}${compSection}${featuresSection}${characteristicRuleBanner}`;

    
  }

  const causeRule1 = isCatalogue
    ? 'STRICT: ONLY consider causes related to selection of product specification — zero internal component design/manufacturing flaws.'
    : 'STRICT: ONLY specific product/joint characteristic specification deficiencies (material thickness, material spec, hardness, surface finish Ra, tolerances/clearance, diameter, welding specs, position & orientation, bolt torque) that are LOGICALLY and physically relevant to the failure mode — ZERO generic terms.';

  return `DFMEA Step 5 — Root Cause Analysis (AIAG-VDA 1st Ed.)
${elemLine}${gdtPart}${envPart}${jointHint}
CRITICAL INSTRUCTIONS FOR ROOT CAUSE DERIVATION:- DO NOT copy, limit yourself to, or rely on the illustrative examples shown in parentheses or past templates. - Dynamically derive all failure mechanisms, characteristics, and measurable specifications strictly from the unique combination of the element description, joint characteristics, constituent components, environment, and G&DT provided in THIS prompt.- Cover applicable domains (e.g., mechanical, structural, dimensional, wall thickness/stiffness, thermal, wear, or joint degradation) based purely on what physically applies to the input data. 
${fmLine}
${getWb3AnalysisModeDirectives(5)}
RULES: (1) ${causeRule1} (2) STRICT CHARACTERISTIC ONLY: Cause details MUST explicitly specify which product or joint characteristic is deficient. (3) One mechanism per entry — no clubbing. (4) Char + Spec with "____" — no invented numbers. (5) Assign O(1-10), D(1-10), AP(H/M/L). Keep all field values minimal.Keep minimal words within 7 words
${causesLibText}
Output JSON only:
{ "failureTempId": "${fm.tempId}", "causes": [{ "tempId": "${Date.now()}-cause-1", "causeDetails": "<specific characteristic deficiency>", "characteristics": "<specific product or joint char>", "spec": "<spec >= ____>", "occurrence": 3, "detection": 2, "ap": "M", "existingLibraryId": "" }] }`;
}


function copyWb3Step5FmPrompt(fmIndex) {
  const nodeId = aiWorkbench3State.currentNodeId;
  const prompt = generateWb3Step5FmPromptText(nodeId, fmIndex, true);
  if (!prompt) return;
  navigator.clipboard.writeText(prompt).then(() => {
    if (typeof showToast === 'function') showToast(`📋 Copied causes prompt for FM ${fmIndex + 1}!`, 'success');
  });
}

function parseWb3Step5FmJson(nodeId, fmIndex) {
  const input = document.getElementById('wb3Step5FmJsonInput');
  if (!input || !input.value.trim()) {
    alert("Please paste the causes JSON for this failure mode first.");
    return;
  }
  try {
    const raw = sanitizeJsonString(input.value);
    const parsed = JSON.parse(raw);
    const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
    const fm = fms[fmIndex];
    if (!fm) return;

    let causesList = [];
    if (Array.isArray(parsed.causes)) causesList = parsed.causes;
    else if (parsed.failureTempId && Array.isArray(parsed.causes)) causesList = parsed.causes;
    else if (Array.isArray(parsed)) causesList = parsed;

    if (causesList.length === 0) {
      alert("No causes found in JSON.");
      return;
    }

    if (!aiWorkbench3State.nodeCauses[nodeId]) aiWorkbench3State.nodeCauses[nodeId] = [];
    aiWorkbench3State.nodeCauses[nodeId] = aiWorkbench3State.nodeCauses[nodeId].filter(c => c.failureTempId !== fm.tempId);

    causesList.forEach((c, i) => {
      const causeObj = {
        tempId: c.tempId || c.id || `cause-wb3-${Date.now()}-${i + 1}`,
        failureTempId: fm.tempId,
        details: c.causeDetails || c.details || c.desc || 'Root cause mechanism',
        characteristics: c.characteristics || 'Design Characteristic',
        spec: c.spec || 'Spec >= ____',
        occurrence: parseInt(c.occurrence, 10) || 3,
        detection: parseInt(c.detection, 10) || 2,
        ap: c.ap || 'M',
        existingLibraryId: c.existingLibraryId || ''
      };
      aiWorkbench3State.nodeCauses[nodeId].push(causeObj);

      // Add to live causes library if not reused
      if (!causeObj.existingLibraryId) {
        if (!aiWorkbench3State.updatedCausesLibrary[nodeId]) aiWorkbench3State.updatedCausesLibrary[nodeId] = [];
        const liveCauses = aiWorkbench3State.updatedCausesLibrary[nodeId];
        const exists = liveCauses.find(lc => (lc.details || lc.desc) && causeObj.details && (lc.details || lc.desc).toLowerCase() === causeObj.details.toLowerCase());
        if (!exists) {
          liveCauses.push({
            id: causeObj.tempId,
            details: causeObj.details,
            characteristics: causeObj.characteristics,
            spec: causeObj.spec,
            occurrence: causeObj.occurrence,
            detection: causeObj.detection,
            ap: causeObj.ap,
            existingLibraryId: ''
          });
        }
      }
    });

    if (input) input.value = '';
    if (typeof showToast === 'function') showToast(`✅ FM ${fmIndex + 1}: Added ${causesList.length} causes!`, 'success');

    const nextIdx = fmIndex + 1;
    if (nextIdx < fms.length) aiWorkbench3State.step5FmPointer[nodeId] = nextIdx;
    renderWb3Step5MicroNav();
  } catch (err) {
    alert("JSON Parsing Error: " + err.message);
  }
}

function renderWb3CausesForFm(nodeId, fmIndex) {
  const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
  const fm = fms[fmIndex];
  const container = document.getElementById('wb3Step5CausesListArea');
  if (!container) return;
  const causes = (aiWorkbench3State.nodeCauses[nodeId] || []).filter(c => c.failureTempId === (fm ? fm.tempId : ''));
  if (causes.length === 0) {
    container.innerHTML = '<div style="text-align:center; padding:10px; color:#64748b; font-size:11px;">No causes parsed for this FM yet.</div>';
    return;
  }
  const apColors = { H: '#ef4444', M: '#f59e0b', L: '#10b981' };
  container.innerHTML = `
    <div style="font-size:11px; font-weight:700; color:#f8fafc; margin-bottom:6px;">✅ ${causes.length} causes for: <span style="color:#f59e0b;">${escapeHtml(fm ? fm.name.slice(0, 60) : '')}</span></div>
    ${causes.map(c => `
      <div style="background:#0f172a; border:1px solid #1e293b; border-radius:6px; padding:8px; font-size:10.5px; margin-bottom:6px;">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:3px;">
          <span style="color:#f59e0b; font-weight:700;">⚙️ ${escapeHtml(c.details)}</span>
          <div style="display:flex; gap:6px;">
            <span style="background:${apColors[c.ap] || '#334155'}; color:#fff; padding:1px 6px; border-radius:3px; font-size:9.5px;">AP: ${c.ap}</span>
            <span style="color:#94a3b8; font-size:10px;">O:${c.occurrence} D:${c.detection}</span>
          </div>
        </div>
        <div style="color:#64748b;"><em>Char:</em> ${escapeHtml(c.characteristics)} • <em>Spec:</em> ${escapeHtml(c.spec)}</div>
        ${c.existingLibraryId ? '<span style="color:#34d399; font-size:10px;">[Reused from library]</span>' : ''}
      </div>
    `).join('')}
  `;
}

async function runWb3Step5AllApi(options = {}) {
  if (aiWorkbench3State.apiInProgress) {
    if (typeof showToast === 'function') showToast('⏳ API call is already running. Please wait.', 'warning');
    return;
  }
  const nodeId = aiWorkbench3State.currentNodeId;
  const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
  if (fms.length === 0) { alert("No failure modes to process."); return; }

  const resumePolicy = (options && options.resumePolicy) || aiWorkbench3State.resumePolicy || 'ungenerated';
  const statusEl = document.getElementById('wb3Step5ApiStatus');
  if (statusEl) { statusEl.style.display = 'block'; statusEl.color = '#38bdf8'; }

  if (!aiWorkbench3State.nodeCauses[nodeId]) aiWorkbench3State.nodeCauses[nodeId] = [];

  const resumeFrom = (aiWorkbench3State.step5FmPointer[nodeId] || 0);
  const startIdx = (resumePolicy === 'all') ? 0 : ((resumeFrom >= fms.length) ? 0 : resumeFrom);
  if (startIdx > 0 && statusEl) {
    statusEl.textContent = `⏩ Resuming causes from FM ${startIdx + 1}/${fms.length}...`;
    statusEl.style.color = '#f59e0b';
  }

  wb3SetApiLock(true);
  let failed = false;
  try {
  for (let i = startIdx; i < fms.length; i++) {
    aiWorkbench3State.step5FmPointer[nodeId] = i;
    const fm = fms[i];
    const alreadyHasCauses = aiWorkbench3State.nodeCauses[nodeId]?.some(c => c.failureTempId === fm.tempId);
    if (resumePolicy === 'ungenerated' && alreadyHasCauses) {
      if (statusEl) statusEl.textContent = `⏩ FM ${i + 1}/${fms.length}: "${fm.name.slice(0, 30)}" already has causes — skipping...`;
      renderWb3Step5MicroNav();
      continue;
    }
    if (statusEl) statusEl.textContent = `Processing causes for FM ${i + 1}/${fms.length}...`;
    renderWb3Step5MicroNav();

    const prompt = generateWb3Step5FmPromptText(nodeId, i, i === startIdx);
    const result = await executeWb3ApiQuery(prompt, 'wb3Step5ApiStatus', null);
    if (!result) {
      if (statusEl) { statusEl.textContent = `❌ Failed at FM ${i + 1}/${fms.length}: "${fms[i].name.slice(0, 60)}". Fix the issue and click Generate again to resume.`; statusEl.style.color = '#f87171'; }
      if (typeof showToast === 'function') showToast(`❌ Step 5 halted at FM ${i + 1}. Resolve and click Generate to resume.`, 'error');
      failed = true;
      break;
    }

    try {
      const raw = sanitizeJsonString(result);
      const parsed = JSON.parse(raw);
      const fm = fms[i];
      let causesList = [];
      if (Array.isArray(parsed.causes)) causesList = parsed.causes;
      else if (Array.isArray(parsed)) causesList = parsed;

      aiWorkbench3State.nodeCauses[nodeId] = aiWorkbench3State.nodeCauses[nodeId].filter(c => c.failureTempId !== fm.tempId);
      if (!aiWorkbench3State.updatedCausesLibrary[nodeId]) aiWorkbench3State.updatedCausesLibrary[nodeId] = [];
      const liveCauses = aiWorkbench3State.updatedCausesLibrary[nodeId];

      causesList.forEach((c, j) => {
        const causeObj = {
          tempId: c.tempId || `cause-wb3-${Date.now()}-${j + 1}`,
          failureTempId: fm.tempId,
          details: c.causeDetails || c.details || c.desc || 'Root cause mechanism',
          characteristics: c.characteristics || 'Design Characteristic',
          spec: c.spec || 'Spec >= ____',
          occurrence: parseInt(c.occurrence, 10) || 3,
          detection: parseInt(c.detection, 10) || 2,
          ap: c.ap || 'M',
          existingLibraryId: c.existingLibraryId || ''
        };
        aiWorkbench3State.nodeCauses[nodeId].push(causeObj);

        if (!causeObj.existingLibraryId) {
          const exists = liveCauses.find(lc => (lc.details || lc.desc) && causeObj.details && (lc.details || lc.desc).toLowerCase() === causeObj.details.toLowerCase());
          if (!exists) {
            liveCauses.push({
              id: causeObj.tempId,
              details: causeObj.details,
              characteristics: causeObj.characteristics,
              spec: causeObj.spec,
              occurrence: causeObj.occurrence,
              detection: causeObj.detection,
              ap: causeObj.ap,
              existingLibraryId: ''
            });
          }
        }
      });
    } catch (err) {
      console.warn(`FM ${i + 1} causes parse error:`, err);
    }
  }

  if (!failed) {
    aiWorkbench3State.step5FmPointer[nodeId] = 0;
    if (statusEl) { statusEl.textContent = `✅ All ${fms.length} FMs causes done! Auto-advancing to Step 6...`; statusEl.style.color = '#34d399'; }
    renderWb3Step5MicroNav();
    if (typeof showToast === 'function') showToast(`✅ Step 5 complete! Auto-starting Step 6 Controls...`, 'success');
    // ── AUTO-ADVANCE TO STEP 6 (Only in standalone manual API click) ──
    if (!aiWorkbench3State.autoPilotRunning) {
      setTimeout(() => { wb3SetApiLock(false); goToWb3Step(6); }, 800);
    }
  }
  } finally {
    if (failed) wb3SetApiLock(false);
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// WB3 STEP 6: CONTROLS
// ══════════════════════════════════════════════════════════════════════════════

function ingestWb3UserControlsList(nodeId, controlsText) {
  if (!controlsText || !controlsText.trim()) return;
  const lines = controlsText.split('\n').map(l => l.trim()).filter(l => l);
  if (!aiWorkbench3State.nodeControls[nodeId]) aiWorkbench3State.nodeControls[nodeId] = {};
  const causes = aiWorkbench3State.nodeCauses[nodeId] || [];

  const prevControls = lines.filter(l => /^prev/i.test(l) || /^pc/i.test(l) || /^prevention/i.test(l));
  const detControls = lines.filter(l => /^det/i.test(l) || /^dc/i.test(l) || /^detection/i.test(l));
  const allControls = lines;

  causes.forEach(c => {
    aiWorkbench3State.nodeControls[nodeId][c.tempId] = {
      prevention: prevControls.length > 0 ? prevControls.join('; ') : allControls.slice(0, Math.ceil(allControls.length / 2)).join('; '),
      detection: detControls.length > 0 ? detControls.join('; ') : allControls.slice(Math.ceil(allControls.length / 2)).join('; '),
      prevList: prevControls.length > 0 ? prevControls : allControls.slice(0, Math.ceil(allControls.length / 2)),
      detList: detControls.length > 0 ? detControls : allControls.slice(Math.ceil(allControls.length / 2))
    };
  });
  renderWb3ControlsList();
  if (typeof showToast === 'function') showToast(`📋 Controls from Step 1 list assigned to ${causes.length} causes!`, 'success');
}

function renderWb3Step6MicroNav() {
  const nodeId = aiWorkbench3State.currentNodeId;
  const causes = aiWorkbench3State.nodeCauses[nodeId] || [];
  const pointer = aiWorkbench3State.step6FmPointer[nodeId] || 0;
  const nav = document.getElementById('wb3Step6MicroNav');
  if (!nav) return;

  if (causes.length === 0) {
    nav.innerHTML = '<div style="text-align:center; padding:18px; color:#64748b; font-size:11px;">No causes yet. Complete Step 5 first.</div>';
    return;
  }

  const cause = causes[pointer];
  const ctrlMap = aiWorkbench3State.nodeControls[nodeId] || {};
  const allDone = causes.every(c => !!ctrlMap[c.tempId]);
  const currentDone = !!ctrlMap[cause ? cause.tempId : ''];

  nav.innerHTML = `
    <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:10px; padding:10px; background:#0f172a; border:1px solid #1e293b; border-radius:8px; margin-bottom:12px;">
      <div style="display:flex; align-items:center; gap:12px;">
        <button onclick="goToWb3Step6Cause(${pointer - 1})" ${pointer === 0 ? 'disabled' : ''} style="padding:4px 10px; background:#1e293b; border:1px solid #334155; border-radius:6px; color:#94a3b8; font-size:11px; cursor:${pointer === 0 ? 'not-allowed' : 'pointer'};">◀ Prev</button>
        <div style="text-align:center;">
          <div style="font-size:12px; font-weight:800; color:#10b981;">Cause ${pointer + 1} / ${causes.length}</div>
          <div style="font-size:10px; color:#64748b; margin-top:2px;">${escapeHtml(cause ? cause.details.slice(0, 70) + (cause.details.length > 70 ? '…' : '') : '')} ${currentDone ? '<span style="color:#10b981;">✓ Done</span>' : ''}</div>
        </div>
        <button onclick="goToWb3Step6Cause(${pointer + 1})" ${pointer >= causes.length - 1 ? 'disabled' : ''} style="padding:4px 10px; background:#1e293b; border:1px solid #334155; border-radius:6px; color:#94a3b8; font-size:11px; cursor:${pointer >= causes.length - 1 ? 'not-allowed' : 'pointer'};">Next ▶</button>
      </div>
      <div style="display:flex; gap:8px;">
        <button onclick="copyWb3Step6CausePrompt(${pointer})" style="padding:5px 12px; background:#10b981; border:none; border-radius:6px; color:#000; font-size:11px; font-weight:700; cursor:pointer;">📋 Copy Prompt for Cause ${pointer + 1}</button>
        <button id="wb3Step6ApiAllBtn" onclick="runWb3Step6AllApi()" style="display:none; padding:5px 12px; background:#7c3aed; border:none; border-radius:6px; color:#fff; font-size:11px; font-weight:700; cursor:pointer;">⚡ Run All ${causes.length} Causes via API</button>
        ${allDone ? '<span style="color:#10b981; font-weight:700; font-size:11px;">✅ All Done</span>' : ''}
      </div>
    </div>
    <div style="margin-bottom:8px;">
      <div style="display:flex; gap:6px; flex-wrap:wrap;">
        ${causes.map((c, i) => {
          const done = !!ctrlMap[c.tempId];
          return `<button onclick="goToWb3Step6Cause(${i})" style="padding:2px 8px; font-size:10px; border-radius:4px; border:1px solid ${i === pointer ? '#10b981' : (done ? '#059669' : '#334155')}; background:${i === pointer ? '#1e293b' : (done ? '#064e3b' : '#0f172a')}; color:${i === pointer ? '#10b981' : (done ? '#10b981' : '#64748b')}; cursor:pointer;" title="${escapeHtml(c.details)}">${done ? '✓' : ''} ${i + 1}</button>`;
        }).join('')}
      </div>
    </div>
  `;

  const promptText = generateWb3Step6CausePromptText(nodeId, pointer);
  const previewTA = document.getElementById('wb3Step6CausePromptPreview');
  if (previewTA) previewTA.value = promptText;

  if (aiWorkbench3State.executionMode === 'API') {
    const btn = document.getElementById('wb3Step6ApiAllBtn');
    if (btn) btn.style.display = 'inline-flex';
  }
}

function goToWb3Step6Cause(idx) {
  const nodeId = aiWorkbench3State.currentNodeId;
  const causes = aiWorkbench3State.nodeCauses[nodeId] || [];
  if (idx < 0 || idx >= causes.length) return;
  aiWorkbench3State.step6FmPointer[nodeId] = idx;
  renderWb3Step6MicroNav();
}

function generateWb3Step6CausePromptText(nodeId, causeIndex, isFirstCall) {
  if (isFirstCall === undefined) isFirstCall = true;
  const ctx = getActiveFmeaData();
  const node = getStructureNodeById(ctx.structure, nodeId);
  if (!node) return '';
  const userCtx = aiWorkbench3State.nodeContexts[nodeId] || {};
  const isCatalogue = !!userCtx.isCatalogueItem;
  const catalogueTag = isCatalogue ? ' [CATALOGUE SELECTION — NOT DESIGN RESPONSIBLE]' : '';
  const causes = aiWorkbench3State.nodeCauses[nodeId] || [];
  const cause = causes[causeIndex];
  if (!cause) return '';
  const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
  const parentFm = fms.find(f => f.tempId === cause.failureTempId);

  const masterControls = (fmeaData && fmeaData.libraries && fmeaData.libraries.controls)
    ? fmeaData.libraries.controls
    : ((ctx.libraries && ctx.libraries.controls) ? ctx.libraries.controls : []);
  const ctrlLibText = masterControls.length > 0
    ? '\nCONTROLS LIBRARY (set existingLibraryId if context matches):\n' +
      masterControls.map(c => `[${c.id}] ${c.type}: "${c.desc}"`).join('\n') + '\n'
    : '';

  const causeLine = `Cause ${causeIndex + 1}/${causes.length}: [${cause.tempId}] | FM: "${parentFm ? parentFm.name : cause.failureTempId}" | Mechanism: "${cause.details}" | Char: "${cause.characteristics}" | Spec: "${cause.spec}"`;

  // ── CONTINUATION CALL ──
  if (!isFirstCall) {
    const catContRule = isCatalogue ? 'CATALOGUE CONTROLS: PC = specification review & sizing calculations; DC = catalogue specification tests & supplier certificate validation. ' : 'Apply same PC/DC rules as Cause 1. ';
    return `DFMEA Step 6 Controls — continuation.
${causeLine}
${ctrlLibText}
${catContRule}Keep desc minimal. Output JSON only:
{ "causeTempId": "${cause.tempId}", "preventionControls": [{ "desc": "<PC>", "existingLibraryId": "" }], "detectionControls": [{ "desc": "<DC>", "existingLibraryId": "" }] }`;
  }

  // ── FIRST CALL — full prompt ──
  const catControlsDirective = isCatalogue
    ? '\nCATALOGUE CONTROLS RULE: Since this element is selected from a catalogue (not design responsible), Prevention Controls (PC) must focus on specification verification (e.g. application sizing calculations, specification sheet review, supplier catalogue rating verification); Detection Controls (DC) must focus on catalogue specification validation (e.g. bench specification verification test, supplier test certificate review, vehicle integration testing).\n'
    : '';

  return `DFMEA Step 6 — Prevention & Detection Controls (AIAG-VDA 1st Ed.)
ELEMENT: "${node.name}"${catalogueTag}
${causeLine}
PC = design standards / FEA / calculations that prevent the cause during design.
DC = tests / inspection that detect the cause or failure before production release.
${catControlsDirective}${getWb3AnalysisModeDirectives(6)}
RULES: (1) Strict PC/DC separation — never merge. (2) Multiple controls per type allowed. (3) Real standards only — no invented test numbers. Keep desc minimal.
${ctrlLibText}
Output JSON only:
{ "causeTempId": "${cause.tempId}", "preventionControls": [{ "desc": "<PC>", "existingLibraryId": "" }], "detectionControls": [{ "desc": "<DC>", "existingLibraryId": "" }] }`;
}


function copyWb3Step6CausePrompt(causeIndex) {
  const nodeId = aiWorkbench3State.currentNodeId;
  const prompt = generateWb3Step6CausePromptText(nodeId, causeIndex, true);
  if (!prompt) return;
  navigator.clipboard.writeText(prompt).then(() => {
    if (typeof showToast === 'function') showToast(`📋 Copied controls prompt for Cause ${causeIndex + 1}!`, 'success');
  });
}

function parseWb3Step6CauseJson(nodeId, causeIndex) {
  const input = document.getElementById('wb3Step6CauseJsonInput');
  if (!input || !input.value.trim()) {
    alert("Please paste the controls JSON for this cause first.");
    return;
  }
  try {
    const raw = sanitizeJsonString(input.value);
    const parsed = JSON.parse(raw);
    const causes = aiWorkbench3State.nodeCauses[nodeId] || [];
    const cause = causes[causeIndex];
    if (!cause) return;

    let prevList = [];
    let detList = [];
    if (Array.isArray(parsed.preventionControls)) prevList = parsed.preventionControls.map(p => typeof p === 'string' ? p : (p.desc || p));
    if (Array.isArray(parsed.detectionControls)) detList = parsed.detectionControls.map(d => typeof d === 'string' ? d : (d.desc || d));

    if (!aiWorkbench3State.nodeControls[nodeId]) aiWorkbench3State.nodeControls[nodeId] = {};
    aiWorkbench3State.nodeControls[nodeId][cause.tempId] = {
      prevention: prevList.join('; ') || 'Standard design guideline',
      detection: detList.join('; ') || 'DVP&R bench test',
      prevList,
      detList
    };

    if (input) input.value = '';
    if (typeof showToast === 'function') showToast(`✅ Controls added for Cause ${causeIndex + 1}!`, 'success');

    const nextIdx = causeIndex + 1;
    if (nextIdx < causes.length) aiWorkbench3State.step6FmPointer[nodeId] = nextIdx;
    renderWb3Step6MicroNav();
    renderWb3ControlsList();
  } catch (err) {
    alert("JSON Parsing Error: " + err.message);
  }
}

function renderWb3ControlsList() {
  const nodeId = aiWorkbench3State.currentNodeId;
  const container = document.getElementById('wb3ControlsContainer');
  const countEl = document.getElementById('wb3ControlsCount');
  if (!container) return;
  const causes = aiWorkbench3State.nodeCauses[nodeId] || [];
  const ctrlMap = aiWorkbench3State.nodeControls[nodeId] || {};
  if (countEl) countEl.textContent = causes.length;
  if (causes.length === 0) {
    container.innerHTML = '<div style="text-align:center; padding:18px; color:#64748b; font-size:11px;">No causes to assign controls to. Complete Step 5 first.</div>';
    return;
  }
  container.innerHTML = causes.map(c => {
    const ctrls = ctrlMap[c.tempId] || { prevention: 'Not defined', detection: 'Not defined', prevList: [], detList: [] };
    const prevArr = (ctrls.prevList && ctrls.prevList.length > 0) ? ctrls.prevList : [ctrls.prevention];
    const detArr = (ctrls.detList && ctrls.detList.length > 0) ? ctrls.detList : [ctrls.detection];
    return `
      <div style="background:#020617; border:1px solid #1e293b; border-radius:6px; padding:10px; font-size:11px; margin-bottom:8px;">
        <div style="font-weight:700; color:#f8fafc; margin-bottom:6px;">🔩 Cause: <span style="color:#f59e0b;">${escapeHtml(c.details)}</span></div>
        <div style="display:grid; grid-template-columns: 1fr 1fr; gap:8px; font-size:10.5px;">
          <div style="background:#0f172a; padding:6px; border-radius:4px; border:1px solid #10b981;">
            <span style="font-weight:700; color:#10b981;">🛡️ Prevention Controls (${prevArr.length}):</span>
            ${prevArr.map(p => `<div style="color:#cbd5e1; margin-top:2px; line-height:1.2;">• ${escapeHtml(p)}</div>`).join('')}
          </div>
          <div style="background:#0f172a; padding:6px; border-radius:4px; border:1px solid #38bdf8;">
            <span style="font-weight:700; color:#38bdf8;">🔍 Detection Controls (${detArr.length}):</span>
            ${detArr.map(d => `<div style="color:#cbd5e1; margin-top:2px; line-height:1.2;">• ${escapeHtml(d)}</div>`).join('')}
          </div>
        </div>
      </div>
    `;
  }).join('');
}

async function runWb3Step6AllApi() {
  if (aiWorkbench3State.apiInProgress) {
    if (typeof showToast === 'function') showToast('⏳ API call is already running. Please wait.', 'warning');
    return;
  }
  const nodeId = aiWorkbench3State.currentNodeId;
  const causes = aiWorkbench3State.nodeCauses[nodeId] || [];
  if (causes.length === 0) { alert("No causes to process."); return; }

  if (!aiWorkbench3State.nodeControls[nodeId]) aiWorkbench3State.nodeControls[nodeId] = {};
  const statusEl = document.getElementById('wb3Step6ApiStatus');
  if (statusEl) { statusEl.style.display = 'block'; statusEl.style.color = '#38bdf8'; }

  const resumeFrom = (aiWorkbench3State.step6FmPointer[nodeId] || 0);
  const startIdx = (resumeFrom >= causes.length) ? 0 : resumeFrom;
  if (startIdx > 0 && statusEl) {
    statusEl.textContent = `⏩ Resuming controls from cause ${startIdx + 1}/${causes.length}...`;
    statusEl.style.color = '#f59e0b';
  }

  wb3SetApiLock(true);
  let failed = false;
  try {
  for (let i = startIdx; i < causes.length; i++) {
    aiWorkbench3State.step6FmPointer[nodeId] = i;
    if (statusEl) statusEl.textContent = `Processing controls for cause ${i + 1}/${causes.length}...`;
    const prompt = generateWb3Step6CausePromptText(nodeId, i, i === startIdx);
    const result = await executeWb3ApiQuery(prompt, 'wb3Step6ApiStatus', null);
    if (!result) {
      if (statusEl) { statusEl.textContent = `❌ Failed at cause ${i + 1}/${causes.length}. Fix the issue and click Generate again to resume.`; statusEl.style.color = '#f87171'; }
      if (typeof showToast === 'function') showToast(`❌ Step 6 halted at cause ${i + 1}. Resolve and click Generate to resume.`, 'error');
      failed = true;
      break;
    }
    try {
      const raw = sanitizeJsonString(result);
      const parsed = JSON.parse(raw);
      const cause = causes[i];
      const prevList = Array.isArray(parsed.preventionControls) ? parsed.preventionControls.map(p => typeof p === 'string' ? p : (p.desc || p)) : [];
      const detList = Array.isArray(parsed.detectionControls) ? parsed.detectionControls.map(d => typeof d === 'string' ? d : (d.desc || d)) : [];
      aiWorkbench3State.nodeControls[nodeId][cause.tempId] = {
        prevention: prevList.join('; '),
        detection: detList.join('; '),
        prevList,
        detList
      };
    } catch (err) {
      console.warn(`Cause ${i + 1} controls parse error:`, err);
    }
  }
  if (!failed) {
    aiWorkbench3State.step6FmPointer[nodeId] = 0;
    if (statusEl) { statusEl.textContent = `✅ All ${causes.length} causes controls done! Auto-advancing...`; statusEl.style.color = '#34d399'; }
    renderWb3Step6MicroNav();
    renderWb3ControlsList();
    if (typeof showToast === 'function') showToast(`✅ Step 6 complete! Auto-advancing to next step...`, 'success');
    // ── AUTO-ADVANCE TO STEP 7 or SKIP TO 8 ──
    const nextStep = aiWorkbench3State.requirementsNeeded ? 7 : 8;
    setTimeout(() => { wb3SetApiLock(false); goToWb3Step(nextStep); }, 800);
  }
  } finally {
    if (failed) wb3SetApiLock(false);
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// WB3 STEP 7: REQUIREMENTS
// ══════════════════════════════════════════════════════════════════════════════

function generateWb3Step7Prompt() {
  const ctx = getActiveFmeaData();
  const nodeId = aiWorkbench3State.currentNodeId;
  const node = getStructureNodeById(ctx.structure, nodeId);
  if (!node) return '';
  const userCtx = aiWorkbench3State.nodeContexts[nodeId] || {};
  const isCatalogue = !!userCtx.isCatalogueItem;
  const catalogueTag = isCatalogue ? ' [CATALOGUE SELECTION]' : '';
  const catalogueReqDirective = isCatalogue ? 'CATALOGUE SELECTION REQUIREMENTS DIRECTIVE: Formulate measurable requirements strictly based on catalogue product specification selection thresholds (e.g. required rated load >= ____, operating temperature rating >= ____, IP rating >= ____).\n' : '';
  const fns = aiWorkbench3State.nodeFunctions[nodeId] || [];
  const masterReqs = (fmeaData && fmeaData.libraries && fmeaData.libraries.requirements)
    ? fmeaData.libraries.requirements
    : ((ctx.libraries && ctx.libraries.requirements) ? ctx.libraries.requirements : []);
  const reqsLibText = masterReqs.length > 0
    ? '\nREQS LIBRARY (set existingLibraryId if context matches):\n' +
      masterReqs.map(r => `[${r.id}] "${r.desc || r.details || ''}" | ${r.spec || '____'}`).join('\n') + '\n'
    : '';

  const prompt = `DFMEA Step 7 — Performance Requirements (AIAG-VDA 1st Ed.)
ELEMENT: "${node.name}"${catalogueTag}
FUNCTIONS:
${JSON.stringify(fns.map(f => ({ tempId: f.tempId, name: f.name, type: f.type })), null, 2)}
${reqsLibText}
${catalogueReqDirective}RULES: (1) Reuse from library if context matches (set existingLibraryId). (2) Use "____" for unknowns — no invented numbers. (3) Link only physically necessary requirements per function.
Keep desc/spec values minimal. Output JSON only:
{
  "functionRequirements": [
    {
      "functionTempId": "${fns[0] ? fns[0].tempId : 'fn-temp-1'}",
      "requirements": [
        { "desc": "<requirement>", "spec": "<spec >= ____>", "existingLibraryId": "" }
      ]
    }
  ]
}`;

  const preview = document.getElementById('wb3Step7PromptPreview');
  if (preview) preview.value = prompt;
  return prompt;
}

function parseWb3Step7Json() {
  const input = document.getElementById('wb3Step7JsonResponseInput');
  if (!input || !input.value.trim()) {
    alert("Please paste the requirements JSON response first.");
    return;
  }
  try {
    const raw = sanitizeJsonString(input.value);
    const parsed = JSON.parse(raw);
    const nodeId = aiWorkbench3State.currentNodeId;
    const fnReqs = parsed.functionRequirements || (Array.isArray(parsed) ? parsed : []);
    aiWorkbench3State.nodeRequirements[nodeId] = [];
    fnReqs.forEach(fr => {
      (fr.requirements || [fr]).forEach(r => {
        aiWorkbench3State.nodeRequirements[nodeId].push({
          functionTempId: fr.functionTempId || fr.functionId || `fn-temp-${Date.now()}`,
          desc: r.desc || r.description || '',
          spec: r.spec || r.specification || '____',
          existingLibraryId: r.existingLibraryId || ''
        });
      });
    });
    renderWb3RequirementsList();
    if (typeof showToast === 'function') showToast(`📥 Loaded ${aiWorkbench3State.nodeRequirements[nodeId].length} requirements!`, 'success');
  } catch (err) {
    alert("JSON Parsing Error: " + err.message);
  }
}

function renderWb3RequirementsList() {
  const nodeId = aiWorkbench3State.currentNodeId;
  const container = document.getElementById('wb3RequirementsContainer');
  const countEl = document.getElementById('wb3RequirementsCount');
  if (!container) return;
  const reqs = aiWorkbench3State.nodeRequirements[nodeId] || [];
  if (countEl) countEl.textContent = reqs.length;
  if (reqs.length === 0) {
    container.innerHTML = '<div style="text-align:center; padding:18px; color:#64748b; font-size:11px;">No requirements yet.</div>';
    return;
  }
  container.innerHTML = reqs.map((r, idx) => `
    <div style="background:#020617; border:1px solid #1e293b; border-radius:6px; padding:8px; font-size:11px; margin-bottom:6px;">
      <div style="color:#a5f3fc; font-weight:700;">${escapeHtml(r.desc)}</div>
      <div style="color:#64748b; font-size:10.5px; margin-top:2px;"><em>Spec:</em> ${escapeHtml(r.spec)} ${r.existingLibraryId ? '<span style="color:#34d399;">[Reused]</span>' : ''}</div>
    </div>
  `).join('');
}

// ══════════════════════════════════════════════════════════════════════════════
// WB3 STEP 8: DASHBOARD, PACKAGE & INGEST
// ══════════════════════════════════════════════════════════════════════════════

function hasWb3NodeData(nodeId) {
  if (!nodeId) return false;
  const fns = (aiWorkbench3State.nodeFunctions && aiWorkbench3State.nodeFunctions[nodeId]) || [];
  const fms = (aiWorkbench3State.nodeFailures && aiWorkbench3State.nodeFailures[nodeId]) || [];
  const causes = (aiWorkbench3State.nodeCauses && aiWorkbench3State.nodeCauses[nodeId]) || [];
  const controls = (aiWorkbench3State.nodeControls && aiWorkbench3State.nodeControls[nodeId]) || {};
  const reqs = (aiWorkbench3State.nodeRequirements && aiWorkbench3State.nodeRequirements[nodeId]) || [];
  return fns.length > 0 || fms.length > 0 || causes.length > 0 || Object.keys(controls).length > 0 || reqs.length > 0;
}

function updateWb3Step8Dashboard() {
  const nodeId = aiWorkbench3State.currentNodeId;
  const ctx = getActiveFmeaData();
  const allNodes = getAllStructureNodesList();
  const activeNode = (ctx && ctx.structure) ? getStructureNodeById(ctx.structure, nodeId) : null;
  const activeNodeName = (activeNode && activeNode.name) || (aiWorkbench3State.nodeContexts[nodeId] && aiWorkbench3State.nodeContexts[nodeId].itemName) || nodeId || 'Current Element';

  const fns = aiWorkbench3State.nodeFunctions[nodeId] || [];
  const fms = aiWorkbench3State.nodeFailures[nodeId] || [];
  const causes = aiWorkbench3State.nodeCauses[nodeId] || [];
  const reqs = aiWorkbench3State.nodeRequirements[nodeId] || [];
  const ctrlMap = aiWorkbench3State.nodeControls[nodeId] || {};
  const totalEffects = fms.reduce((sum, fm) => sum + (fm.effectsList ? fm.effectsList.length : 0), 0);
  const totalControls = Object.keys(ctrlMap).length;

  const setEl = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
  setEl('wb3Kpi1', fns.length);
  setEl('wb3Kpi2', fms.length);
  setEl('wb3Kpi3', totalEffects);
  setEl('wb3Kpi4', causes.length);
  setEl('wb3Kpi5', totalControls);
  setEl('wb3Kpi6', reqs.length);

  const summary = document.getElementById('wb3Step8Summary');
  if (!summary) return;

  if (!aiWorkbench3State.ingestedNodes) aiWorkbench3State.ingestedNodes = new Set();
  const isCurrentIngested = aiWorkbench3State.ingestedNodes.has(nodeId);
  const hasCurrentData = hasWb3NodeData(nodeId);

  // Calculate totals across whole study in WB3
  let totalStudyFns = 0;
  let totalStudyFms = 0;
  let totalStudyEffects = 0;
  let totalStudyCauses = 0;
  let totalStudyControls = 0;
  let totalStudyReqs = 0;
  let totalNodesWithData = 0;
  let totalNodesIngested = 0;

  allNodes.forEach(item => {
    const nId = item.id;
    const nFns = aiWorkbench3State.nodeFunctions[nId] || [];
    const nFms = aiWorkbench3State.nodeFailures[nId] || [];
    const nCauses = aiWorkbench3State.nodeCauses[nId] || [];
    const nReqs = aiWorkbench3State.nodeRequirements[nId] || [];
    const nCtrlMap = aiWorkbench3State.nodeControls[nId] || {};
    const nEffects = nFms.reduce((sum, fm) => sum + (fm.effectsList ? fm.effectsList.length : 0), 0);
    const nCtrls = Object.keys(nCtrlMap).length;

    totalStudyFns += nFns.length;
    totalStudyFms += nFms.length;
    totalStudyEffects += nEffects;
    totalStudyCauses += nCauses.length;
    totalStudyControls += nCtrls;
    totalStudyReqs += nReqs.length;

    if (nFns.length > 0 || nFms.length > 0) totalNodesWithData++;
    if (aiWorkbench3State.ingestedNodes.has(nId)) totalNodesIngested++;
  });

  // Render elements matrix rows
  const rowsHtml = allNodes.map((item, idx) => {
    const nId = item.id;
    const depth = item.depth || 0;
    const isRoot = (depth === 0);
    const isActive = (nId === nodeId);
    const isIngested = aiWorkbench3State.ingestedNodes.has(nId);
    const nFns = aiWorkbench3State.nodeFunctions[nId] || [];
    const nFms = aiWorkbench3State.nodeFailures[nId] || [];
    const nCauses = aiWorkbench3State.nodeCauses[nId] || [];
    const nReqs = aiWorkbench3State.nodeRequirements[nId] || [];
    const nCtrlMap = aiWorkbench3State.nodeControls[nId] || {};
    const nEffects = nFms.reduce((sum, fm) => sum + (fm.effectsList ? fm.effectsList.length : 0), 0);
    const nCtrls = Object.keys(nCtrlMap).length;
    const nHasData = nFns.length > 0 || nFms.length > 0;
    const userCtx = aiWorkbench3State.nodeContexts[nId] || {};
    const itemType = userCtx.itemType || (isRoot ? 'System' : (depth === 1 ? 'Assembly' : 'Component'));

    const depthPrefix = depth === 0 ? '' : ('&nbsp;'.repeat(depth * 3) + '└─ ');
    const icon = depth === 0 ? '🏢' : (depth === 1 ? '📦' : '⚙️');

    let statusBadge = '';
    if (isIngested) {
      statusBadge = '<span style="background:#064e3b; color:#34d399; border:1px solid #059669; padding:2px 8px; border-radius:10px; font-size:10.5px; font-weight:700; white-space:nowrap;">✅ Ingested</span>';
    } else if (nHasData) {
      statusBadge = '<span style="background:#451a03; color:#fde68a; border:1px solid #d97706; padding:2px 8px; border-radius:10px; font-size:10.5px; font-weight:700; white-space:nowrap;">⚡ Ready</span>';
    } else {
      statusBadge = '<span style="background:#1e293b; color:#64748b; border:1px solid #334155; padding:2px 8px; border-radius:10px; font-size:10.5px; white-space:nowrap;">⚪ No Data</span>';
    }

    return `
      <tr style="border-bottom:1px solid #1e293b; ${isActive ? 'background:rgba(2,132,199,0.08);' : ''}">
        <td style="padding:8px 10px; text-align:center;">
          <input type="checkbox" class="wb3-ingest-select-node" data-node-id="${nId}" ${nHasData ? 'checked' : 'disabled'} style="accent-color:#10b981; cursor:pointer;" />
        </td>
        <td style="padding:8px 10px; font-size:11.5px; color:#f8fafc;">
          ${depthPrefix}<span style="margin-right:4px;">${icon}</span><strong style="${isActive ? 'color:#38bdf8;' : ''}">${escapeHtml(item.name || 'Element')}</strong>
          ${isActive ? '<span style="margin-left:6px; font-size:9px; background:#0284c7; color:#fff; padding:1px 5px; border-radius:3px; font-weight:700;">ACTIVE</span>' : ''}
        </td>
        <td style="padding:8px 10px; font-size:11px; color:#94a3b8;">${escapeHtml(itemType)}</td>
        <td style="padding:8px 10px; font-size:11.5px; text-align:center; font-weight:700; color:${nFns.length ? '#38bdf8' : '#475569'};
        ">${nFns.length}</td>
        <td style="padding:8px 10px; font-size:11.5px; text-align:center; font-weight:700; color:${nFms.length ? '#ef4444' : '#475569'};
        ">${nFms.length}</td>
        <td style="padding:8px 10px; font-size:11.5px; text-align:center; font-weight:700; color:${nEffects ? '#f59e0b' : '#475569'};
        ">${nEffects}</td>
        <td style="padding:8px 10px; font-size:11.5px; text-align:center; font-weight:700; color:${nCauses.length ? '#f59e0b' : '#475569'};
        ">${nCauses.length}</td>
        <td style="padding:8px 10px; font-size:11.5px; text-align:center; font-weight:700; color:${nCtrls ? '#10b981' : '#475569'};
        ">${nCtrls}</td>
        <td style="padding:8px 10px; font-size:11.5px; text-align:center; font-weight:700; color:${nReqs.length ? '#a5f3fc' : '#475569'};
        ">${nReqs.length}</td>
        <td style="padding:8px 10px; text-align:center;">${statusBadge}</td>
        <td style="padding:8px 10px; text-align:right; white-space:nowrap;">
          ${nHasData ? `
            <button type="button" class="btn btn-sm ${isIngested ? 'btn-secondary' : 'btn-green'}" onclick="ingestWb3ElementOneByOne('${nId}')"
              style="padding:3px 10px; font-size:11px; font-weight:700; margin-right:4px;" title="Insert only this element into FMEA database">
              ${isIngested ? '🔄 Re-insert' : '📥 Insert'}
            </button>
          ` : `
            <button type="button" class="btn btn-sm btn-secondary" onclick="switchWb3ActiveElement('${nId}');"
              style="padding:3px 8px; font-size:10.5px; color:#64748b; margin-right:4px;" title="Go to element setup">
              ○ Setup
            </button>
          `}
          ${!isActive ? `
            <button type="button" class="btn btn-sm btn-secondary" onclick="switchWb3ActiveElement('${nId}'); goToWb3Step(8);"
              style="padding:3px 8px; font-size:10.5px; color:#94a3b8;" title="Switch active selection to this element">
              👁️ Switch
            </button>
          ` : ''}
        </td>
      </tr>
    `;
  }).join('');

  summary.innerHTML = `
    <!-- Mode Selection Notice & Active Element Card -->
    <div style="background:#020617; border:1px solid #1e293b; border-radius:8px; padding:12px 16px; margin-bottom:14px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px;">
      <div>
        <div style="display:flex; align-items:center; gap:8px;">
          <span style="font-size:16px;">🎯</span>
          <span style="font-size:13px; font-weight:800; color:#f8fafc;">Active Element: <span style="color:#38bdf8;">${escapeHtml(activeNodeName)}</span></span>
          ${isCurrentIngested
            ? '<span style="background:#064e3b; color:#34d399; border:1px solid #059669; padding:2px 8px; border-radius:10px; font-size:10.5px; font-weight:700;">✅ Ingested</span>'
            : (hasCurrentData ? '<span style="background:#451a03; color:#fde68a; border:1px solid #d97706; padding:2px 8px; border-radius:10px; font-size:10.5px; font-weight:700;">⚡ Ready to Ingest</span>' : '<span style="background:#1e293b; color:#64748b; border:1px solid #334155; padding:2px 8px; border-radius:10px; font-size:10.5px;">⚪ No Data</span>')
          }
        </div>
        <div style="font-size:11px; color:#94a3b8; margin-top:3px;">
          Contains ${fns.length} Functions, ${fms.length} Failure Modes, ${totalEffects} Effects, ${causes.length} Causes, ${totalControls} Controls, ${reqs.length} Reqs.
        </div>
      </div>
      <div style="display:flex; align-items:center; gap:8px;">
        <button type="button" class="btn btn-primary btn-sm" onclick="ingestWb3CurrentElementIntoProject()" ${hasCurrentData ? '' : 'disabled'}
          style="padding:6px 14px; font-weight:700; font-size:11.5px; background:#0284c7; border-color:#0369a1; display:flex; align-items:center; gap:5px;"
          title="Insert data for only this active element into FMEA database">
          📥 ${isCurrentIngested ? 'Re-insert Current Element' : 'Insert Current Element Only'}
        </button>
      </div>
    </div>

    <!-- Structure Elements Ingestion Matrix Table -->
    <div style="background:#020617; border:1px solid #1e293b; border-radius:8px; overflow:hidden;">
      <div style="background:#0f172a; padding:10px 14px; border-bottom:1px solid #1e293b; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px;">
        <div>
          <div style="font-size:12.5px; font-weight:800; color:#f8fafc; display:flex; align-items:center; gap:6px;">
            <span>📋 Structure Elements Ingestion Matrix</span>
            <span style="font-size:10px; background:#1e293b; color:#94a3b8; padding:2px 6px; border-radius:4px; border:1px solid #334155;">${totalNodesIngested} / ${totalNodesWithData} Ingested</span>
          </div>
          <div style="font-size:10.5px; color:#94a3b8; margin-top:2px;">
            Insert elements <strong>one by one</strong> using the row buttons, or select multiple and <strong>insert at once</strong>.
          </div>
        </div>

        <!-- Ingestion Batch Toolbar -->
        <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
          <label style="display:inline-flex; align-items:center; gap:5px; font-size:11px; color:#cbd5e1; cursor:pointer; margin-right:4px;">
            <input type="checkbox" id="wb3CloseAfterIngestCheckbox" style="accent-color:#10b981; cursor:pointer;" />
            <span>Close workbench after insert</span>
          </label>
          <button type="button" class="btn btn-secondary btn-sm" onclick="ingestWb3SelectedElementsIntoProject()"
            style="padding:5px 12px; font-size:11px; font-weight:700;" title="Insert all checked elements">
            📥 Insert Selected
          </button>
          <button type="button" class="btn btn-green btn-sm" onclick="ingestWb3AllElementsIntoProject()"
            style="padding:5px 14px; font-size:11px; font-weight:800; display:flex; align-items:center; gap:5px;" title="Insert all elements across structure tree at once">
            🌐 Insert All at Once
          </button>
        </div>
      </div>

      <!-- Scrollable Matrix Table -->
      <div style="max-height:320px; overflow-y:auto;">
        <table style="width:100%; border-collapse:collapse; text-align:left;">
          <thead style="background:#090d16; position:sticky; top:0; z-index:2; border-bottom:1px solid #1e293b;">
            <tr style="font-size:10.5px; color:#94a3b8; text-transform:uppercase; letter-spacing:0.5px;">
              <th style="padding:7px 10px; text-align:center; width:36px;">
                <input type="checkbox" id="wb3MasterIngestCheckbox" checked onchange="toggleWb3IngestSelectAll(this)" style="accent-color:#10b981; cursor:pointer;" title="Select / Deselect All with Data" />
              </th>
              <th style="padding:7px 10px;">Structure Element</th>
              <th style="padding:7px 10px; width:80px;">Type</th>
              <th style="padding:7px 10px; text-align:center; width:45px;" title="Functions">Fns</th>
              <th style="padding:7px 10px; text-align:center; width:45px;" title="Failure Modes">FMs</th>
              <th style="padding:7px 10px; text-align:center; width:45px;" title="Total Effects">Eff</th>
              <th style="padding:7px 10px; text-align:center; width:45px;" title="Root Causes">Cau</th>
              <th style="padding:7px 10px; text-align:center; width:45px;" title="Controls Linked">Ctrl</th>
              <th style="padding:7px 10px; text-align:center; width:45px;" title="Requirements">Req</th>
              <th style="padding:7px 10px; text-align:center; width:85px;">Status</th>
              <th style="padding:7px 10px; text-align:right; width:130px;">Action</th>
            </tr>
          </thead>
          <tbody>
            ${rowsHtml}
          </tbody>
        </table>
      </div>
    </div>
  `;
}

function buildWb3SubfilePackage(targetNodeId = null) {
  const ctx = getActiveFmeaData();
  const nodeId = targetNodeId || aiWorkbench3State.currentNodeId;
  const node = getStructureNodeById(ctx.structure, nodeId);
  if (!node) return null;
  const isRoot = (node.id === ctx.structure.id);
  const parentNode = isRoot ? null : getParentStructureNode(ctx.structure, nodeId);
  const userCtx = aiWorkbench3State.nodeContexts[nodeId] || {};
  const tsPrefix = 'wb3-' + (nodeId ? String(nodeId).replace(/[^a-zA-Z0-9]/g, '').slice(-4) : 'nd') + '-' + Date.now().toString().slice(-4) + Math.floor(Math.random() * 89 + 10);

  const stateFns = aiWorkbench3State.nodeFunctions[nodeId] || [];
  const stateFms = aiWorkbench3State.nodeFailures[nodeId] || [];
  const stateCauses = aiWorkbench3State.nodeCauses[nodeId] || [];
  const stateControls = aiWorkbench3State.nodeControls[nodeId] || {};
  const stateReqs = aiWorkbench3State.nodeRequirements[nodeId] || [];

  const masterEffects = (fmeaData && fmeaData.libraries && fmeaData.libraries.effects) ? fmeaData.libraries.effects : ((ctx.libraries && ctx.libraries.effects) ? ctx.libraries.effects : []);
  const masterCauses = (fmeaData && fmeaData.libraries && fmeaData.libraries.causes) ? fmeaData.libraries.causes : ((ctx.libraries && ctx.libraries.causes) ? ctx.libraries.causes : []);
  const masterControls = (fmeaData && fmeaData.libraries && fmeaData.libraries.controls) ? fmeaData.libraries.controls : ((ctx.libraries && ctx.libraries.controls) ? ctx.libraries.controls : []);

  // ── 1. FUNCTIONS ──
  const functionNetworkLinks = [];
  const parentFnsInState = (parentNode && aiWorkbench3State.nodeFunctions[parentNode.id]) || [];

  const pkgFunctions = stateFns.map((fn, idx) => {
    const libFn = fn.existingLibraryId ? (ctx.libraries && ctx.libraries.functions ? ctx.libraries.functions.find(f => f.id === fn.existingLibraryId) : null) : null;
    const mappedFnId = libFn ? libFn.id : (`fn-${tsPrefix}-${idx + 1}`);

    const rawPids = Array.isArray(fn.parentFunctionIds) && fn.parentFunctionIds.length > 0
      ? fn.parentFunctionIds
      : (fn.parentFunctionId ? [fn.parentFunctionId] : []);

    const resolvedParentIds = [];
    rawPids.forEach(pId => {
      if (!pId || pId === 'parent-fn') return;
      const stateMatch = parentFnsInState.find(pf => pf.tempId === pId || pf.id === pId);
      const ctxMatch = (ctx.functions || []).find(cf => cf.id === pId || (parentNode && cf.structId === parentNode.id && cf.name === pId));
      const finalPId = stateMatch ? (stateMatch.existingLibraryId || stateMatch.id || stateMatch.tempId) : (ctxMatch ? ctxMatch.id : pId);
      if (finalPId && !resolvedParentIds.includes(finalPId)) {
        resolvedParentIds.push(finalPId);
        functionNetworkLinks.push({
          id: `fnlink-${tsPrefix}-${functionNetworkLinks.length + 1}`,
          sourceFuncId: mappedFnId,
          targetFuncId: finalPId,
          sourceStructId: nodeId,
          targetStructId: parentNode ? parentNode.id : null,
          type: 'FUNCTION_SUPPORT'
        });
      }
    });

    return {
      id: mappedFnId,
      structId: nodeId,
      name: fn.name,
      type: fn.type || 'Primary function',
      parentFunctionId: resolvedParentIds[0] || (parentNode ? 'parent-fn' : ''),
      parentFunctionIds: resolvedParentIds,
      existingLibraryId: fn.existingLibraryId || ''
    };
  });

  const fnIdMap = {};
  stateFns.forEach((fn, idx) => {
    fnIdMap[fn.tempId || fn.id] = pkgFunctions[idx].id;
  });

  // ── 2. FAILURE MODES ──
  const fmIdMap = {};
  stateFms.forEach((fm, idx) => {
    fmIdMap[fm.tempId || fm.id] = `fm-${tsPrefix}-${idx + 1}`;
  });

  // ── 3. EFFECTS (REUSED & N+1 PARENT FAILURE MODES FULLY LINKED) ──
  const localEffects = [];
  const failureModeEffects = {};
  const failureNetworkLinks = [];
  const effectTempIdToFinalId = {};
  let effCounter = 0;

  stateFms.forEach(fm => {
    const finalFmId = fmIdMap[fm.tempId || fm.id];
    failureModeEffects[finalFmId] = [];

    (fm.effectsList || []).forEach(e => {
      const normDesc = (e.desc || '').trim().toLowerCase();
      let assignedEffId = null;

      // A. If already mapped from an earlier effect in this session
      if (e.existingLibraryId && effectTempIdToFinalId[e.existingLibraryId]) {
        assignedEffId = effectTempIdToFinalId[e.existingLibraryId];
      }

      // B. If it's a Non-Root N+1 Parent Failure Mode Link
      if (!assignedEffId && (!isRoot && parentNode) && (e.category === 'N+1 Parent Failure Mode' || e.existingLibraryId)) {
        const parentFmId = e.existingLibraryId || e.tempId;
        assignedEffId = `eff-link-${tsPrefix}-${++effCounter}`;
        localEffects.push({
          id: assignedEffId,
          category: e.category || 'N+1 Parent Failure Mode',
          desc: e.desc || 'Parent Failure Mode',
          severity: parseInt(e.severity, 10) || 8,
          structId: parentNode.id,
          systemName: parentNode.name || '',
          functionName: e.parentFunction || '',
          parentFmId: parentFmId
        });

        // Add formal Failure Network Link for graph/catalog views
        failureNetworkLinks.push({
          sourceFmId: finalFmId,
          targetFmId: parentFmId,
          type: 'component_to_parent'
        });
      }

      // C. Direct match in masterEffects by ID
      if (!assignedEffId && e.existingLibraryId) {
        const directMatch = masterEffects.find(me => me.id === e.existingLibraryId);
        if (directMatch) {
          assignedEffId = directMatch.id;
          if (!localEffects.some(le => le.id === directMatch.id)) {
            localEffects.push(directMatch);
          }
        }
      }

      // D. Text match in masterEffects
      if (!assignedEffId && normDesc) {
        const textMatch = masterEffects.find(me => (me.desc || me.details || '').trim().toLowerCase() === normDesc);
        if (textMatch) {
          assignedEffId = textMatch.id;
          if (!localEffects.some(le => le.id === textMatch.id)) {
            localEffects.push(textMatch);
          }
        }
      }

      // E. Match localEffects already created in this subpackage
      if (!assignedEffId && normDesc) {
        const localMatch = localEffects.find(le => (le.desc || le.details || '').trim().toLowerCase() === normDesc);
        if (localMatch) {
          assignedEffId = localMatch.id;
        }
      }

      // F. Create new effect
      if (!assignedEffId) {
        assignedEffId = `eff-${tsPrefix}-${++effCounter}`;
        localEffects.push({
          id: assignedEffId,
          category: e.category || 'End User Level',
          desc: e.desc || 'System consequence',
          severity: parseInt(e.severity, 10) || 8,
          structId: nodeId,
          systemName: node.name || ''
        });
      }

      if (e.tempId) effectTempIdToFinalId[e.tempId] = assignedEffId;
      if (e.existingLibraryId) effectTempIdToFinalId[e.existingLibraryId] = assignedEffId;
      if (!failureModeEffects[finalFmId].includes(assignedEffId)) {
        failureModeEffects[finalFmId].push(assignedEffId);
      }
    });
  });

  // ── 4. CAUSES (REUSED CAUSES ACROSS FAILURE MODES FULLY LINKED) ──
  const localCauses = [];
  const failureModeCauses = {};
  const causeIdMap = {};
  const causeTempIdToFinalId = {};
  let causeCounter = 0;

  stateFms.forEach(fm => {
    const finalFmId = fmIdMap[fm.tempId || fm.id];
    failureModeCauses[finalFmId] = [];
    const fmCauses = stateCauses.filter(c => c.failureTempId === (fm.tempId || fm.id));

    fmCauses.forEach(c => {
      const normDetails = (c.details || c.causeDetails || c.desc || '').trim().toLowerCase();
      const normChar = (c.characteristics || '').trim().toLowerCase();
      let assignedCauseId = null;

      // A. Reused from an earlier cause in this session via tempId
      if (c.existingLibraryId && causeTempIdToFinalId[c.existingLibraryId]) {
        assignedCauseId = causeTempIdToFinalId[c.existingLibraryId];
      }

      // B. Direct match in masterCauses by ID
      if (!assignedCauseId && c.existingLibraryId) {
        const directMatch = masterCauses.find(mc => mc.id === c.existingLibraryId);
        if (directMatch) {
          assignedCauseId = directMatch.id;
          if (!localCauses.some(lc => lc.id === directMatch.id)) {
            localCauses.push(directMatch);
          }
        }
      }

      // C. Match in masterCauses by text
      if (!assignedCauseId && normDetails) {
        const textMatch = masterCauses.find(mc =>
          (mc.details || mc.desc || '').trim().toLowerCase() === normDetails &&
          (!normChar || (mc.characteristics || '').trim().toLowerCase() === normChar)
        );
        if (textMatch) {
          assignedCauseId = textMatch.id;
          if (!localCauses.some(lc => lc.id === textMatch.id)) {
            localCauses.push(textMatch);
          }
        }
      }

      // D. Match in localCauses already created in this element
      if (!assignedCauseId && normDetails) {
        const localMatch = localCauses.find(lc =>
          (lc.details || lc.desc || '').trim().toLowerCase() === normDetails &&
          (!normChar || (lc.characteristics || '').trim().toLowerCase() === normChar)
        );
        if (localMatch) {
          assignedCauseId = localMatch.id;
        }
      }

      // E. Create new cause
      if (!assignedCauseId) {
        assignedCauseId = `cause-${tsPrefix}-${++causeCounter}`;
        localCauses.push({
          id: assignedCauseId,
          details: c.details || c.causeDetails || c.desc || 'Root cause mechanism',
          desc: c.details || c.causeDetails || c.desc || 'Root cause mechanism',
          name: c.details || c.causeDetails || c.desc || 'Root cause mechanism',
          characteristics: c.characteristics || 'Design Characteristic',
          spec: c.spec || '____',
          occurrence: parseInt(c.occurrence, 10) || 3,
          detection: parseInt(c.detection, 10) || 2,
          ap: c.ap || 'M',
          structId: nodeId,
          systemElement: node.name,
          variants: ['ALL'],
          origin: 'DFMEA'
        });
      }

      causeIdMap[c.tempId || c.id] = assignedCauseId;
      if (c.tempId) causeTempIdToFinalId[c.tempId] = assignedCauseId;
      if (c.existingLibraryId) causeTempIdToFinalId[c.existingLibraryId] = assignedCauseId;

      if (!failureModeCauses[finalFmId].includes(assignedCauseId)) {
        failureModeCauses[finalFmId].push(assignedCauseId);
      }
    });
  });

  // ── 5. CONTROLS (FLAT ARRAY OF IDs IN causeControls) ──
  const localControls = [];
  const causeControls = {};
  let ctrlCounter = 0;

  stateCauses.forEach(c => {
    const assignedCauseId = causeIdMap[c.tempId || c.id];
    if (!assignedCauseId) return;

    // Check both stateControls[c.tempId] and stateControls[c.existingLibraryId]
    const ctrls = stateControls[c.tempId || c.id] || (c.existingLibraryId ? stateControls[c.existingLibraryId] : null);
    if (!ctrls) return;

    const ctrlList = causeControls[assignedCauseId] || [];

    const prevItems = (ctrls.prevList && ctrls.prevList.length > 0) ? ctrls.prevList : (ctrls.prevention ? [ctrls.prevention] : []);
    const detItems = (ctrls.detList && ctrls.detList.length > 0) ? ctrls.detList : (ctrls.detection ? [ctrls.detection] : []);

    prevItems.forEach(pItem => {
      const prevDesc = (typeof pItem === 'object' ? (pItem.desc || pItem.name || '') : String(pItem || '')).trim();
      if (!prevDesc) return;
      const pLibId = typeof pItem === 'object' ? pItem.existingLibraryId : '';

      let assignedPrevId = null;
      if (pLibId) {
        const directPrev = masterControls.find(mc => mc.id === pLibId && mc.type === 'Prevention');
        if (directPrev) assignedPrevId = directPrev.id;
      }
      if (!assignedPrevId) {
        const textPrev = masterControls.find(mc => mc.desc && mc.desc.trim().toLowerCase() === prevDesc.toLowerCase() && mc.type === 'Prevention');
        if (textPrev) assignedPrevId = textPrev.id;
      }
      if (!assignedPrevId) {
        const localPrev = localControls.find(lc => lc.desc && lc.desc.trim().toLowerCase() === prevDesc.toLowerCase() && lc.type === 'Prevention');
        if (localPrev) assignedPrevId = localPrev.id;
      }
      if (!assignedPrevId) {
        assignedPrevId = `ctrl-prev-${tsPrefix}-${++ctrlCounter}`;
        localControls.push({ id: assignedPrevId, desc: prevDesc, type: 'Prevention' });
      }

      if (!ctrlList.includes(assignedPrevId)) ctrlList.push(assignedPrevId);
    });

    detItems.forEach(dItem => {
      const detDesc = (typeof dItem === 'object' ? (dItem.desc || dItem.name || '') : String(dItem || '')).trim();
      if (!detDesc) return;
      const dLibId = typeof dItem === 'object' ? dItem.existingLibraryId : '';

      let assignedDetId = null;
      if (dLibId) {
        const directDet = masterControls.find(mc => mc.id === dLibId && mc.type === 'Detection');
        if (directDet) assignedDetId = directDet.id;
      }
      if (!assignedDetId) {
        const textDet = masterControls.find(mc => mc.desc && mc.desc.trim().toLowerCase() === detDesc.toLowerCase() && mc.type === 'Detection');
        if (textDet) assignedDetId = textDet.id;
      }
      if (!assignedDetId) {
        const localDet = localControls.find(lc => lc.desc && lc.desc.trim().toLowerCase() === detDesc.toLowerCase() && lc.type === 'Detection');
        if (localDet) assignedDetId = localDet.id;
      }
      if (!assignedDetId) {
        assignedDetId = `ctrl-det-${tsPrefix}-${++ctrlCounter}`;
        localControls.push({ id: assignedDetId, desc: detDesc, type: 'Detection' });
      }

      if (!ctrlList.includes(assignedDetId)) ctrlList.push(assignedDetId);
    });

    // CRITICAL: MUST BE FLAT ARRAY of control IDs for renderFMEATable
    causeControls[assignedCauseId] = ctrlList;
  });

  // ── 6. REQUIREMENTS ──
  const pkgRequirements = [];
  const reqIdMap = {};
  let reqCounter = 0;
  stateReqs.forEach(r => {
    const reqId = r.existingLibraryId || `req-${tsPrefix}-${++reqCounter}`;
    reqIdMap[r.functionTempId] = reqId;
    if (!r.existingLibraryId) pkgRequirements.push({ id: reqId, desc: r.desc, spec: r.spec, structId: nodeId });
  });

  // ── 7. FUNCTION LINES ──
  const pkgFunctionLines = stateFns.map((fn, idx) => {
    const fnId = pkgFunctions[idx] ? pkgFunctions[idx].id : `fn-${tsPrefix}-${idx + 1}`;
    const reqId = reqIdMap[fn.tempId] || null;
    const fmSubset = stateFms.filter(fm => fm.functionTempId === fn.tempId);
    const fmArray = fmSubset.map(fm => ({
      id: fmIdMap[fm.tempId || fm.id],
      name: fm.name,
      severity: fm.severity,
      occurrence: stateCauses.filter(c => c.failureTempId === fm.tempId).reduce((max, c) => Math.max(max, c.occurrence), 3),
      detection: stateCauses.filter(c => c.failureTempId === fm.tempId).reduce((max, c) => Math.max(max, c.detection), 2),
      rpn: fm.severity * stateCauses.filter(c => c.failureTempId === fm.tempId).reduce((max, c) => Math.max(max, c.occurrence), 3) * stateCauses.filter(c => c.failureTempId === fm.tempId).reduce((max, c) => Math.max(max, c.detection), 2),
      ap: stateCauses.filter(c => c.failureTempId === fm.tempId).map(c => c.ap)[0] || 'M'
    }));
    return {
      id: fnId,
      funcId: fnId,
      structId: nodeId,
      functionId: fnId,
      functionName: fn.name,
      functionType: fn.type || 'Primary function',
      reqId: reqId,
      requirementId: reqId,
      higherFunctionIds: pkgFunctions[idx] ? (pkgFunctions[idx].parentFunctionIds || []) : [],
      parentFunctionIds: pkgFunctions[idx] ? (pkgFunctions[idx].parentFunctionIds || []) : [],
      isConsidered: true,
      failureModes: fmArray
    };
  });

  return {
    packageMagic: "JOST_FMEA_SUBFILE_PKG_V1",
    projectName: `${node.name} DFMEA Subpackage (WB3)`,
    exportedAt: new Date().toISOString(),
    structure: [{
      id: node.id,
      name: node.name,
      type: isRoot ? 'System' : (userCtx.itemType || 'Component'),
      partNumber: node.partNo || node.partNumber || 'PN-001',
      description: node.desc || node.description || 'Automotive Element'
    }],
    variants: ["ALL"],
    functions: pkgFunctions,
    requirements: pkgRequirements,
    functionLines: pkgFunctionLines,
    libraries: {
      effects: localEffects,
      causes: localCauses,
      controls: localControls
    },
    failureModeEffects,
    failureModeCauses,
    causeControls,
    functionNetworkLinks,
    failureNetworkLinks
  };
}

function ingestWb3ElementOneByOne(nodeId, closeModal = false) {
  if (!nodeId) nodeId = aiWorkbench3State.currentNodeId;
  const ctx = getActiveFmeaData();
  const node = (ctx && ctx.structure) ? getStructureNodeById(ctx.structure, nodeId) : null;
  const nodeName = (node && node.name) || (aiWorkbench3State.nodeContexts[nodeId] && aiWorkbench3State.nodeContexts[nodeId].itemName) || nodeId;

  if (!hasWb3NodeData(nodeId)) {
    if (typeof showCustomAlert === 'function') {
      showCustomAlert(`No AI-generated data found for element "${nodeName}". Please generate functions and failure modes first.`, "Ingestion Warning", "warning");
    } else {
      alert(`No AI-generated data found for element "${nodeName}". Please generate functions and failure modes first.`);
    }
    return false;
  }

  const pkg = buildWb3SubfilePackage(nodeId);
  if (!pkg) {
    alert(`Could not build subpackage for element "${nodeName}".`);
    return false;
  }

  parseAndIngestWb2FullSubpackage(pkg);

  if (!aiWorkbench3State.ingestedNodes) aiWorkbench3State.ingestedNodes = new Set();
  aiWorkbench3State.ingestedNodes.add(nodeId);
  aiWorkbench3State.processedNodes.add(nodeId);

  renderWb3StructureNavBar();
  updateWb3Step8Dashboard();

  if (typeof showToast === 'function') {
    showToast(`📥 Ingested data for "${nodeName}" into FMEA database!`, "success");
  }

  const closeCheckbox = document.getElementById('wb3CloseAfterIngestCheckbox');
  if (closeModal || (closeCheckbox && closeCheckbox.checked)) {
    closeAiWorkbench3Modal();
  }
  return true;
}

function ingestWb3CurrentElementIntoProject(closeModal = false) {
  return ingestWb3ElementOneByOne(aiWorkbench3State.currentNodeId, closeModal);
}

function ingestWb3AllElementsIntoProject(closeModal = false) {
  const ctx = getActiveFmeaData();
  if (!ctx || !ctx.structure) {
    alert("No active FMEA study found.");
    return false;
  }

  const allNodes = getAllStructureNodesList();
  if (!allNodes || allNodes.length === 0) {
    alert("No structure tree elements found.");
    return false;
  }

  const nodesWithData = allNodes.filter(item => hasWb3NodeData(item.id));
  if (nodesWithData.length === 0) {
    if (typeof showCustomAlert === 'function') {
      showCustomAlert("No elements have generated data in AI Workbench 3 yet. Please generate functions and failure modes first before committing to FMEA database.", "No Data to Ingest", "info");
    } else {
      alert("No elements have generated data in AI Workbench 3 yet. Please generate functions and failure modes first.");
    }
    return false;
  }

  if (!aiWorkbench3State.ingestedNodes) aiWorkbench3State.ingestedNodes = new Set();

  let ingestedCount = 0;
  // Ingest in hierarchical pre-order (top-down)
  for (const item of nodesWithData) {
    const pkg = buildWb3SubfilePackage(item.id);
    if (pkg) {
      parseAndIngestWb2FullSubpackage(pkg, { skipRefresh: true });
      aiWorkbench3State.ingestedNodes.add(item.id);
      aiWorkbench3State.processedNodes.add(item.id);
      ingestedCount++;
    }
  }

  // Master refresh and auto-save after batch ingest
  if (typeof updateFmeaTable === 'function') updateFmeaTable();
  if (typeof renderFMEATable === 'function') renderFMEATable();
  if (typeof updateStructureTree === 'function') updateStructureTree();
  if (typeof refreshAllLibraries === 'function') refreshAllLibraries();
  if (typeof renderCausesLibraryList === 'function') renderCausesLibraryList();
  if (typeof performAutoSave === 'function') performAutoSave('AI Workbench 3 Ingest All');

  renderWb3StructureNavBar();
  updateWb3Step8Dashboard();

  if (typeof showToast === 'function') {
    showToast(`🎉 Ingested ${ingestedCount} element(s) into FMEA database successfully!`, "success");
  }

  const closeCheckbox = document.getElementById('wb3CloseAfterIngestCheckbox');
  if (closeModal || (closeCheckbox && closeCheckbox.checked)) {
    closeAiWorkbench3Modal();
  }
  return true;
}

function ingestWb3SelectedElementsIntoProject(closeModal = false) {
  const checkboxes = document.querySelectorAll('.wb3-ingest-select-node:checked');
  if (!checkboxes || checkboxes.length === 0) {
    if (typeof showToast === 'function') showToast("Please select at least one element to insert.", "warning");
    else alert("Please select at least one element to insert.");
    return false;
  }

  const selectedNodeIds = Array.from(checkboxes).map(cb => cb.dataset.nodeId);
  const allNodes = getAllStructureNodesList();
  // Filter nodes maintaining top-down hierarchical order
  const targetNodes = allNodes.filter(n => selectedNodeIds.includes(n.id) && hasWb3NodeData(n.id));

  if (targetNodes.length === 0) {
    if (typeof showToast === 'function') showToast("Selected elements have no AI-generated data to insert.", "warning");
    else alert("Selected elements have no AI-generated data to insert.");
    return false;
  }

  if (!aiWorkbench3State.ingestedNodes) aiWorkbench3State.ingestedNodes = new Set();

  let count = 0;
  for (const item of targetNodes) {
    const pkg = buildWb3SubfilePackage(item.id);
    if (pkg) {
      parseAndIngestWb2FullSubpackage(pkg, { skipRefresh: true });
      aiWorkbench3State.ingestedNodes.add(item.id);
      aiWorkbench3State.processedNodes.add(item.id);
      count++;
    }
  }

  // Master refresh and auto-save after batch ingest
  if (typeof updateFmeaTable === 'function') updateFmeaTable();
  if (typeof renderFMEATable === 'function') renderFMEATable();
  if (typeof updateStructureTree === 'function') updateStructureTree();
  if (typeof refreshAllLibraries === 'function') refreshAllLibraries();
  if (typeof renderCausesLibraryList === 'function') renderCausesLibraryList();
  if (typeof performAutoSave === 'function') performAutoSave('AI Workbench 3 Ingest Selected');

  renderWb3StructureNavBar();
  updateWb3Step8Dashboard();

  if (typeof showToast === 'function') {
    showToast(`📥 Ingested ${count} selected element(s) into FMEA database!`, "success");
  }

  const closeCheckbox = document.getElementById('wb3CloseAfterIngestCheckbox');
  if (closeModal || (closeCheckbox && closeCheckbox.checked)) {
    closeAiWorkbench3Modal();
  }
  return true;
}

function toggleWb3IngestSelectAll(masterCheckbox) {
  const isChecked = masterCheckbox ? masterCheckbox.checked : true;
  const checkboxes = document.querySelectorAll('.wb3-ingest-select-node:not(:disabled)');
  checkboxes.forEach(cb => { cb.checked = isChecked; });
}

function ingestWb3IntoProject() {
  const closeCheckbox = document.getElementById('wb3CloseAfterIngestCheckbox');
  const shouldClose = closeCheckbox ? closeCheckbox.checked : true;
  return ingestWb3CurrentElementIntoProject(shouldClose);
}

// ══════════════════════════════════════════════════════════════════════════════
// WB3 API ENGINE
// ══════════════════════════════════════════════════════════════════════════════

async function executeWb3ApiQuery(promptText, statusElId, buttonId) {
  const cfg = aiWorkbench3State.apiSettings;
  const statusEl = statusElId ? document.getElementById(statusElId) : null;
  const btn = buttonId ? document.getElementById(buttonId) : null;

  if (!cfg.apiKey && cfg.provider !== 'ollama') {
    alert("API Key is missing. Click 'API Config' to set your API Key.");
    return null;
  }
  if (statusEl) { statusEl.style.display = 'block'; statusEl.textContent = 'Querying AI model...'; statusEl.style.color = '#38bdf8'; }
  if (btn) btn.disabled = true;

  try {
    let resultText = '';
    const isResponsesApi = cfg.provider === 'openai_responses' || (cfg.endpoint && cfg.endpoint.includes('/responses'));
    const isNvidia = cfg.provider === 'nvidia' || (cfg.endpoint && cfg.endpoint.includes('nvidia.com'));

    let extraHeaders = {};
    if (cfg.customHeaders) {
      try { extraHeaders = typeof cfg.customHeaders === 'string' ? JSON.parse(cfg.customHeaders) : cfg.customHeaders; } catch(e) {}
    }
    let extraParams = {};
    if (cfg.customParams) {
      try { extraParams = typeof cfg.customParams === 'string' ? JSON.parse(cfg.customParams) : cfg.customParams; } catch(e) {}
    }

    if (isResponsesApi) {
      const resp = await fetch(cfg.endpoint, {
        method: 'POST',
        headers: Object.assign({ 'Content-Type': 'application/json', 'Authorization': `Bearer ${cfg.apiKey}` }, extraHeaders),
        body: JSON.stringify(Object.assign({ model: cfg.model, input: promptText, store: true }, extraParams))
      });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}: ${await resp.text()}`);
      const data = await resp.json();
      resultText = extractResponsesApiText(data);
    } else if (isNvidia) {
      const resp = await fetch(cfg.endpoint, {
        method: 'POST',
        headers: Object.assign({
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${cfg.apiKey}`,
          'Accept': 'application/json'
        }, extraHeaders),
        body: JSON.stringify(Object.assign({
          model: cfg.model || 'moonshotai/kimi-k3',
          messages: [{ role: 'user', content: promptText }],
          max_tokens: 16384,
          temperature: 1,
          reasoning_effort: 'max',
          seed: 0,
          stream: false
        }, extraParams))
      });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}: ${await resp.text()}`);
      const data = await resp.json();
      resultText = (data.choices && (data.choices[0]?.message?.content || data.choices[0]?.message?.reasoning_content || data.choices[0]?.delta?.content)) || '';
    } else if (cfg.provider === 'openai' || cfg.provider === 'azure' || cfg.provider === 'custom' || cfg.provider === 'openrouter' || cfg.provider === 'openrouter_free' || cfg.provider === 'groq' || cfg.provider === 'groq_free') {
      const resp = await fetch(cfg.endpoint, {
        method: 'POST',
        headers: Object.assign({ 'Content-Type': 'application/json', 'Authorization': `Bearer ${cfg.apiKey}` }, extraHeaders),
        body: JSON.stringify(Object.assign({
          model: cfg.model,
          messages: [{ role: 'user', content: promptText }],
          temperature: 0.2
        }, extraParams))
      });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}: ${await resp.text()}`);
      const data = await resp.json();
      resultText = data.choices && (data.choices[0]?.message?.content || data.choices[0]?.message?.reasoning_content);
    } else if (cfg.provider === 'gemini' || cfg.provider === 'gemini_free' || cfg.provider === 'google_gemini') {
      const url = cfg.endpoint.includes('key=') ? cfg.endpoint : `${cfg.endpoint}${cfg.endpoint.includes('?') ? '&' : '?'}key=${cfg.apiKey}`;
      const resp = await fetch(url, {
        method: 'POST',
        headers: Object.assign({ 'Content-Type': 'application/json', 'x-goog-api-key': cfg.apiKey }, extraHeaders),
        body: JSON.stringify(Object.assign({ contents: [{ parts: [{ text: promptText }] }] }, extraParams))
      });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}: ${await resp.text()}`);
      const data = await resp.json();
      if (data.candidates && data.candidates[0]?.content?.parts) {
        const parts = data.candidates[0].content.parts;
        const part = parts.find(p => p.text && !p.thought) || parts[parts.length - 1];
        resultText = part ? part.text : '';
      } else {
        resultText = '';
      }
    } else if (cfg.provider === 'ollama') {
      const resp = await fetch(cfg.endpoint, {
        method: 'POST',
        headers: Object.assign({ 'Content-Type': 'application/json' }, extraHeaders),
        body: JSON.stringify(Object.assign({ model: cfg.model, messages: [{ role: 'user', content: promptText }], stream: false }, extraParams))
      });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}: ${await resp.text()}`);
      const data = await resp.json();
      resultText = data.message?.content;
    }
    if (statusEl) { statusEl.textContent = '✅ Completed!'; statusEl.style.color = '#34d399'; }
    return resultText;
  } catch (err) {
    if (statusEl) { statusEl.textContent = `❌ Error: ${err.message}`; statusEl.style.color = '#f87171'; }
    return null;
  } finally {
    if (btn) btn.disabled = false;
  }
}

async function runWb3Step2Api() {
  if (aiWorkbench3State.apiInProgress) {
    if (typeof showToast === 'function') showToast('⏳ Another API call is still running. Please wait.', 'warning');
    return;
  }
  wb3SetApiLock(true);
  const statusEl = document.getElementById('wb3ApiStep2Status');
  try {
  const prompt = generateWb3Step2Prompt();
  const res = await executeWb3ApiQuery(prompt, 'wb3ApiStep2Status', 'wb3BtnRunApiStep2');
  if (!res) {
    if (statusEl) { statusEl.textContent = '❌ No response received from API.'; statusEl.style.color = '#f87171'; }
    wb3SetApiLock(false);
    return;
  }
  try {
    const raw = sanitizeJsonString(res);
    const parsed = JSON.parse(raw);
    const fns = parsed.functions || (Array.isArray(parsed) ? parsed : []);
    if (!Array.isArray(fns) || fns.length === 0) {
      if (statusEl) { statusEl.textContent = '❌ No functions found in API response. Check prompt/model.'; statusEl.style.color = '#f87171'; }
      console.warn('[WB3 Step2 API] Raw response:', res);
      return;
    }
    const nodeId = aiWorkbench3State.currentNodeId;
    aiWorkbench3State.nodeFunctions[nodeId] = fns.map((fn, idx) => ({
      tempId: fn.tempId || fn.id || `fn-temp-${idx + 1}`,
      name: fn.name || 'Unnamed Function',
      type: typeof normalizeWb2FunctionType === 'function' ? normalizeWb2FunctionType(fn.type) : (fn.type || 'Primary function'),
      parentFunctionId: fn.parentFunctionId || '',
      existingLibraryId: fn.existingLibraryId || ''
    }));
    // Also update the textarea for visibility
    const input = document.getElementById('wb3Step2JsonResponseInput');
    if (input) input.value = res;
    renderWb3FunctionsTable();
    if (statusEl) { statusEl.textContent = `✅ Parsed ${fns.length} functions successfully!`; statusEl.style.color = '#34d399'; }
    if (typeof showToast === 'function') showToast(`📥 Step 2: ${fns.length} functions loaded!`, 'success');
  } catch (err) {
    if (statusEl) { statusEl.textContent = `❌ Parse Error: ${err.message}`; statusEl.style.color = '#f87171'; }
    console.error('[WB3 Step2 API] Parse error:', err, '\nRaw:', res);
  }
  } finally {
    wb3SetApiLock(false);
  }
}

async function runWb3Step3Api() {
  if (aiWorkbench3State.apiInProgress) {
    if (typeof showToast === 'function') showToast('⏳ Another API call is still running. Please wait.', 'warning');
    return;
  }
  wb3SetApiLock(true);
  const statusEl = document.getElementById('wb3ApiStep3Status');
  try {
  const prompt = generateWb3Step3Prompt();
  const res = await executeWb3ApiQuery(prompt, 'wb3ApiStep3Status', 'wb3BtnRunApiStep3');
  if (!res) {
    if (statusEl) { statusEl.textContent = '❌ No response received from API.'; statusEl.style.color = '#f87171'; }
    wb3SetApiLock(false);
    return;
  }
  try {
    const raw = sanitizeJsonString(res);
    const parsed = JSON.parse(raw);
    let modes = parsed.failureModes || parsed.modes || parsed.data || (Array.isArray(parsed) ? parsed : []);
    if (!modes.length && parsed.failureModeEffects) modes = parsed.failureModeEffects;
    if (!Array.isArray(modes) || modes.length === 0) {
      if (statusEl) { statusEl.textContent = '❌ No failure modes found in API response.'; statusEl.style.color = '#f87171'; }
      console.warn('[WB3 Step3 API] Raw response:', res);
      return;
    }
    const nodeId = aiWorkbench3State.currentNodeId;
    aiWorkbench3State.nodeFailures[nodeId] = modes.map((fn, idx) => ({
      tempId: fn.tempId || fn.id || fn.failureId || `fm-${idx + 1}`,
      functionTempId: fn.functionTempId || fn.fnTempId || fn.functionId || '',
      name: fn.name || fn.failureName || fn.desc || `Failure Mode ${idx + 1}`,
      failureType: fn.failureType || fn.type || 'Loss of function',
      severity: parseInt(fn.severity || fn.sev || 8, 10) || 8,
      effectsList: fn.effectsList || [],
      effects: fn.effects || {},
      causesList: fn.causesList || []
    }));
    aiWorkbench3State.step4FmPointer[nodeId] = 0;
    aiWorkbench3State.step5FmPointer[nodeId] = 0;
    aiWorkbench3State.updatedEffectsLibrary[nodeId] = null;
    // Also update the textarea for visibility
    const input = document.getElementById('wb3Step3JsonResponseInput');
    if (input) input.value = res;
    renderWb3FailureModesList();
    if (statusEl) { statusEl.textContent = `✅ Parsed ${modes.length} failure modes! Auto-advancing to Step 4 Effects...`; statusEl.style.color = '#34d399'; }
    if (typeof showToast === 'function') showToast(`📥 Step 3: ${modes.length} FMs loaded! Starting Step 4 Effects...`, 'success');
    // ── AUTO-ADVANCE TO STEP 4 ──
    setTimeout(() => goToWb3Step(4), 800);
  } catch (err) {
    if (statusEl) { statusEl.textContent = `❌ Parse Error: ${err.message}`; statusEl.style.color = '#f87171'; }
    console.error('[WB3 Step3 API] Parse error:', err, '\nRaw:', res);
  }
  } finally {
    wb3SetApiLock(false);
  }
}

async function runWb3Step7Api() {
  if (aiWorkbench3State.apiInProgress) {
    if (typeof showToast === 'function') showToast('⏳ Another API call is still running. Please wait.', 'warning');
    return;
  }
  wb3SetApiLock(true);
  const statusEl = document.getElementById('wb3ApiStep7Status');
  try {
  const prompt = generateWb3Step7Prompt();
  const res = await executeWb3ApiQuery(prompt, 'wb3ApiStep7Status', 'wb3BtnRunApiStep7');
  if (!res) {
    if (statusEl) { statusEl.textContent = '❌ No response received from API.'; statusEl.style.color = '#f87171'; }
    wb3SetApiLock(false);
    return;
  }
  try {
    const raw = sanitizeJsonString(res);
    const parsed = JSON.parse(raw);
    const nodeId = aiWorkbench3State.currentNodeId;
    const fnReqs = parsed.functionRequirements || (Array.isArray(parsed) ? parsed : []);
    aiWorkbench3State.nodeRequirements[nodeId] = [];
    fnReqs.forEach(fr => {
      (fr.requirements || [fr]).forEach(r => {
        aiWorkbench3State.nodeRequirements[nodeId].push({
          functionTempId: fr.functionTempId || fr.functionId || `fn-temp-${Date.now()}`,
          desc: r.desc || r.description || '',
          spec: r.spec || r.specification || '____',
          existingLibraryId: r.existingLibraryId || ''
        });
      });
    });
    // Also update the textarea for visibility
    const input = document.getElementById('wb3Step7JsonResponseInput');
    if (input) input.value = res;
    renderWb3RequirementsList();
    const count = aiWorkbench3State.nodeRequirements[nodeId].length;
    if (statusEl) { statusEl.textContent = `✅ Parsed ${count} requirements! Auto-advancing to Step 8...`; statusEl.style.color = '#34d399'; }
    if (typeof showToast === 'function') showToast(`📥 Step 7: ${count} requirements loaded! Moving to Ingest...`, 'success');
    // ── AUTO-ADVANCE TO STEP 8 ──
    setTimeout(() => goToWb3Step(8, true), 800);
  } catch (err) {
    if (statusEl) { statusEl.textContent = `❌ Parse Error: ${err.message}`; statusEl.style.color = '#f87171'; }
    console.error('[WB3 Step7 API] Parse error:', err, '\nRaw:', res);
  }
  } finally {
    wb3SetApiLock(false);
  }
}

