function getWb3AiMode() {
  const el = document.getElementById('wb3AiModeSelect');
  if (el && el.value) return el.value;
  return (aiWorkbench3State && aiWorkbench3State.aiCompanionMode) || localStorage.getItem('wb3_ai_mode') || 'chatgpt';
}

function getWb3CompanionUrl(mode = null) {
  const m = mode || getWb3AiMode();
  if (m === 'gemini') return 'https://gemini.google.com/app';
  if (m === 'copilot') return 'https://copilot.microsoft.com';
  if (m === 'deepseek') return 'https://chat.deepseek.com';
  if (m === 'kimi') return 'https://kimi.ai';
  if (m === 'claude') return 'https://claude.ai';
  if (m === 'qwen') return 'https://chat.qwen.ai';
  return 'https://chatgpt.com';
}

function getWb3CompanionServiceName(mode = null) {
  const m = mode || getWb3AiMode();
  if (m === 'gemini') return 'Google Gemini';
  if (m === 'copilot') return 'Microsoft Copilot';
  if (m === 'deepseek') return 'DeepSeek';
  if (m === 'kimi') return 'Kimi / Kim';
  if (m === 'claude') return 'Claude';
  if (m === 'qwen') return 'Qwen (Tongyi)';
  if (m === 'api') return 'Direct API';
  return 'ChatGPT';
}

