function openAiStructureImportModal() {
  const modal = document.getElementById('aiStructureImportModal');
  if (!modal) return;
  modal.style.display = 'block';

  const roughInput = document.getElementById('aiStructRoughInput');
  if (roughInput && !roughInput.value.trim()) {
    setStructurePromptPreset('fifth_wheel');
  } else {
    updateAiStructureMasterPrompt();
  }
}

function setStructurePromptPreset(presetKey) {
  const roughInput = document.getElementById('aiStructRoughInput');
  if (roughInput) {
    roughInput.value = AI_STRUCTURE_PRESETS[presetKey] || '';
  }
  updateAiStructureMasterPrompt();
}

function buildAiStructureMasterPrompt(roughText) {
  const roughSection = (roughText && roughText.trim().length > 0)
    ? `[TARGET PRODUCT SYSTEM & COMPONENTS]:\n${roughText.trim()}\n`
    : `[TARGET PRODUCT SYSTEM]: (Derive a complete, realistic automotive sub-system with realistic component breakdown)\n`;

  return `You are a Principal Automotive Systems Engineer and DFMEA Master Specialist operating strictly per the AIAG-VDA 1st Edition FMEA Handbook.

TASK:
Perform DFMEA Step 2 (Structure Analysis) and create a comprehensive, highly realistic automotive System Hierarchy (System -> Sub-systems -> Components) for the following product:

${roughSection}
AIAG-VDA 1st EDITION STRUCTURE RULES:
1. THREE-LEVEL HIERARCHY:
   - Root Element (Level 1): The overall System / Top-Level Assembly (Type: "Assembly").
   - Sub-Systems (Level 2): Key mechanical, structural, or actuation sub-assemblies (Type: "Assembly").
   - Components (Level 3): Individual leaf parts, plates, housings, shafts, fasteners, and standard items (Type: "Component").

2. CATALOGUE PART CLASSIFICATION (CRITICAL FOR DFMEA):
   - For every component, determine whether it is:
     * DESIGN RESPONSIBLE (isCatalogueItem: false): Custom designed component where we control geometry, section thickness, metallurgy, heat treatment, and tolerances.
     * CATALOGUE / OFF-THE-SHELF PART (isCatalogueItem: true): Standard commercial item selected from a supplier catalogue (e.g., standard bearings, O-rings, rotary shaft seals, standard fasteners, hydraulic fittings, commercial compression springs, standard solenoids).

3. RICH ENGINEERING DESCRIPTIONS FOR WORKBENCH 3 EXECUTION:
   - Every single element (System, Sub-system, and Component) MUST have a rich, precise 2–3 sentence engineering description following this exact formula:
     [What it physically is] + [What it connects / interfaces to] + [Key operating loads, torques, forces, pressures, articulation] + [Operating environment & temperature limits].
   - Include realistic Part Numbers (e.g. JS-SYS-001, JS-SUB-101, JS-CMP-201, CAT-BRG-6208).
   - For components, specify:
     * material: Standard engineering alloy/grade & heat treatment (e.g. "Forged 42CrMo4 alloy steel, Q&T to 28-32 HRC, induction hardened 52-56 HRC", "S355J2 structural steel", "FKM Viton with carbon steel case").
     * gdt: Critical dimensions and GD&T tolerances (e.g. "Ø50.8 +0.05/-0.00 mm, surface finish Ra <= 0.8 um, runout <= 0.03 mm").
     * env: Operating environment boundaries (e.g. "-40°C to +85°C chassis ambient, de-icing salt spray ASTM B117, EP-2 lithium grease").
   - For assemblies, specify joints (e.g. ["Welding", "Nut-Bolt", "Press Fit"]).

4. OUTPUT FORMAT:
   - Output ONLY valid JSON starting with { and ending with }. No prose, markdown commentary, or explanations outside the JSON.

JSON SCHEMA:
{
  "projectName": "Name of Product System",
  "structure": {
    "id": "sys-1",
    "name": "Top Level System Name",
    "partNo": "PN-SYS-001",
    "type": "Assembly",
    "isCatalogueItem": false,
    "desc": "Rich 2-3 sentence engineering description following the formula...",
    "material": "Overall system materials",
    "gdt": "Overall envelope tolerances",
    "env": "System operating environment",
    "joints": ["Welding", "Nut-Bolt"],
    "children": [
      {
        "id": "sub-1",
        "name": "Sub-System Name",
        "partNo": "PN-SUB-101",
        "type": "Assembly",
        "isCatalogueItem": false,
        "desc": "Sub-system engineering description...",
        "joints": ["Welding", "Nut-Bolt"],
        "children": [
          {
            "id": "comp-1",
            "name": "Custom Component Name",
            "partNo": "PN-CMP-201",
            "type": "Component",
            "isCatalogueItem": false,
            "desc": "Rich 2-3 sentence engineering description...",
            "material": "Specific alloy & heat treatment",
            "gdt": "Specific critical dimensions & GD&T",
            "env": "Component operating environment"
          },
          {
            "id": "comp-2",
            "name": "Standard Catalogue Part Name",
            "partNo": "CAT-SEAL-80",
            "type": "Component",
            "isCatalogueItem": true,
            "desc": "Standard catalogue part description...",
            "material": "Catalogue material",
            "gdt": "Nominal catalogue dimensions",
            "env": "Catalogue operating environment"
          }
        ]
      }
    ]
  }
}`;
}

function updateAiStructureMasterPrompt() {
  const roughInput = document.getElementById('aiStructRoughInput');
  const promptDisplay = document.getElementById('aiStructMasterPromptDisplay');
  if (!promptDisplay) return;
  const prompt = buildAiStructureMasterPrompt(roughInput ? roughInput.value : '');
  promptDisplay.value = prompt;
}

function copyAiStructureMasterPrompt() {
  const promptDisplay = document.getElementById('aiStructMasterPromptDisplay');
  if (!promptDisplay || !promptDisplay.value) return;
  navigator.clipboard.writeText(promptDisplay.value).then(() => {
    if (typeof showToast === 'function') {
      showToast('📋 Master Structure Prompt copied! Paste into ChatGPT / Gemini / Claude to generate structure.', 'success');
    } else {
      alert('Master Structure Prompt copied to clipboard!');
    }
  });
}

async function runAiStructureDirectApi() {
  const promptDisplay = document.getElementById('aiStructMasterPromptDisplay');
  const statusBadge = document.getElementById('aiStructParseStatusBadge');
  const btn = document.getElementById('btnRunStructApi');
  if (!promptDisplay || !promptDisplay.value) return;

  if (typeof executeWb3ApiQuery !== 'function') {
    alert('Direct API client is not initialized.');
    return;
  }

  if (statusBadge) {
    statusBadge.textContent = '⏳ Querying AI API...';
    statusBadge.style.color = '#38bdf8';
  }
  if (btn) btn.disabled = true;

  try {
    const rawRes = await executeWb3ApiQuery(promptDisplay.value, null, 'btnRunStructApi');
    if (!rawRes) {
      if (statusBadge) { statusBadge.textContent = '❌ No API response received'; statusBadge.style.color = '#f87171'; }
      return;
    }
    const jsonInput = document.getElementById('aiStructJsonResponseInput');
    if (jsonInput) {
      jsonInput.value = rawRes;
    }
    previewAiStructureJson();
    if (typeof showToast === 'function') showToast('⚡ AI Structure generated successfully via API!', 'success');
  } catch (err) {
    if (statusBadge) { statusBadge.textContent = '❌ API Error: ' + err.message; statusBadge.style.color = '#f87171'; }
    alert('API Error: ' + err.message);
  } finally {
    if (btn) btn.disabled = false;
  }
}

function clearAiStructureJsonInput() {
  const jsonInput = document.getElementById('aiStructJsonResponseInput');
  if (jsonInput) jsonInput.value = '';
  parsedAiStructureCache = null;
  const statusBadge = document.getElementById('aiStructParseStatusBadge');
  if (statusBadge) { statusBadge.textContent = 'Cleared'; statusBadge.style.color = '#94a3b8'; }
  const preview = document.getElementById('aiStructPreviewContainer');
  if (preview) preview.innerHTML = '<div style="text-align:center; color:#64748b; font-size:11px; padding:30px 10px; font-style:italic;">Paste AI JSON above and click \'Validate &amp; Preview\' to see the full hierarchy breakdown with catalogue flags and rich descriptions.</div>';
  const ingestBtn = document.getElementById('btnIngestAiStructure');
  if (ingestBtn) { ingestBtn.disabled = true; ingestBtn.style.opacity = '0.5'; ingestBtn.style.cursor = 'not-allowed'; }
}

