// WB3 COMPONENT & MIXED CONSTITUENT CHARACTERISTICS (TYPE ➔ SUBTYPE) CONTROLLERS
// ══════════════════════════════════════════════════════════════════════════

window.wb3ComponentSelectedChars = window.wb3ComponentSelectedChars || [];
window.wb3ActiveComponentCategory = window.wb3ActiveComponentCategory || 'ALL';

function normalizeCharacteristicsInput(input) {
  if (!input) return [];
  const rawList = Array.isArray(input) ? input : [input];
  const results = [];
  
  rawList.forEach(item => {
    if (!item) return;
    if (typeof item === 'object' && item.name) {
      results.push({
        category: item.category || findCategoryForSubtypeName(item.name) || '⚙️ Mechanical & Structural',
        name: String(item.name).trim(),
        spec: item.spec || findSpecForSubtypeName(item.name) || ''
      });
    } else if (typeof item === 'string' && item.trim()) {
      item.split(/[,;\n]/).forEach(token => {
        const trimmed = token.trim();
        if (trimmed) {
          results.push({
            category: findCategoryForSubtypeName(trimmed) || '⚙️ Mechanical & Structural',
            name: trimmed,
            spec: findSpecForSubtypeName(trimmed) || ''
          });
        }
      });
    }
  });

  // Deduplicate by name
  const seen = new Set();
  return results.filter(r => {
    const k = r.name.toLowerCase();
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

function findCategoryForSubtypeName(name) {
  const lower = name.toLowerCase();
  for (const cat of MASTER_COMPONENT_CHARACTERISTICS_DATA) {
    for (const it of cat.items) {
      if (it.name.toLowerCase() === lower || lower.includes(it.name.toLowerCase()) || it.name.toLowerCase().includes(lower)) {
        return cat.category;
      }
    }
  }
  return null;
}

function findSpecForSubtypeName(name) {
  const lower = name.toLowerCase();
  for (const cat of MASTER_COMPONENT_CHARACTERISTICS_DATA) {
    for (const it of cat.items) {
      if (it.name.toLowerCase() === lower) {
        return it.spec;
      }
    }
  }
  return '';
}

// --- A. WB3 Step 1 Pure Component Element Selector ---
function initWb3ComponentCharacteristicsSelector(initialChars = []) {
  window.wb3ComponentSelectedChars = normalizeCharacteristicsInput(initialChars);
  window.wb3ActiveComponentCategory = 'ALL';
  renderWb3ComponentCategoryTabs();
  renderWb3ComponentSelectedCharsBadges();
  renderWb3ComponentSubtypesGrid();
}

function renderWb3ComponentCategoryTabs() {
  const container = document.getElementById('wb3CompCategoryTabs');
  if (!container) return;

  const current = window.wb3ActiveComponentCategory || 'ALL';
  let html = `<button type="button" class="wb3-type-btn ${current === 'ALL' ? 'active' : ''}" onclick="setWb3ComponentCategory('ALL')">🌟 All Categories</button>`;

  MASTER_COMPONENT_CHARACTERISTICS_DATA.forEach(cat => {
    const isActive = (cat.category === current);
    html += `<button type="button" class="wb3-type-btn ${isActive ? 'active' : ''}" onclick="setWb3ComponentCategory('${escapeHtml(cat.category)}')">${escapeHtml(cat.category)}</button>`;
  });

  container.innerHTML = html;
}

function setWb3ComponentCategory(catName) {
  window.wb3ActiveComponentCategory = catName;
  renderWb3ComponentCategoryTabs();
  renderWb3ComponentSubtypesGrid();
}

function renderWb3ComponentSelectedCharsBadges() {
  const container = document.getElementById('wb3CompSelectedCharsContainer');
  const badgeEl = document.getElementById('wb3CompSelectedCountBadge');
  const selected = window.wb3ComponentSelectedChars || [];

  if (badgeEl) {
    badgeEl.textContent = `${selected.length} Linked`;
  }

  if (!container) return;

  if (selected.length === 0) {
    container.innerHTML = '<span style="font-size:9.5px; color:#64748b; font-style:italic;">No characteristics linked yet. Select category then subtype below.</span>';
    return;
  }

  container.innerHTML = selected.map((item, idx) => {
    const icon = (item.category && item.category.split(' ')[0]) || '🏷️';
    const tooltip = item.spec ? `${item.category}\nSpec: ${item.spec}` : item.category;
    return `
      <span class="wb3-linked-badge" title="${escapeHtml(tooltip)}">
        <span>${icon}</span>
        <span>${escapeHtml(item.name)}</span>
        <span class="remove-btn" onclick="removeWb3ComponentSubtype(${idx})" title="Unlink characteristic">✕</span>
      </span>
    `;
  }).join('');
}

function removeWb3ComponentSubtype(idx) {
  if (window.wb3ComponentSelectedChars && window.wb3ComponentSelectedChars[idx]) {
    window.wb3ComponentSelectedChars.splice(idx, 1);
    renderWb3ComponentSelectedCharsBadges();
    renderWb3ComponentSubtypesGrid();
  }
}

function renderWb3ComponentSubtypesGrid() {
  const container = document.getElementById('wb3CompSubtypeGrid');
  if (!container) return;

  const currentCat = window.wb3ActiveComponentCategory || 'ALL';
  const searchInput = document.getElementById('wb3CompSubtypeSearchInput');
  const term = (searchInput ? searchInput.value : '').toLowerCase().trim();

  let candidateItems = [];
  MASTER_COMPONENT_CHARACTERISTICS_DATA.forEach(cat => {
    if (currentCat === 'ALL' || cat.category === currentCat) {
      cat.items.forEach(it => {
        candidateItems.push({
          category: cat.category,
          name: it.name,
          spec: it.spec
        });
      });
    }
  });

  if (term) {
    candidateItems = candidateItems.filter(it => 
      it.name.toLowerCase().includes(term) ||
      it.category.toLowerCase().includes(term) ||
      (it.spec && it.spec.toLowerCase().includes(term))
    );
  }

  if (candidateItems.length === 0) {
    container.innerHTML = '<div style="grid-column: 1 / -1; font-size:10px; color:#64748b; text-align:center; padding:8px;">No matching component subtypes found.</div>';
    return;
  }

  const selectedNames = new Set((window.wb3ComponentSelectedChars || []).map(s => s.name.toLowerCase()));

  container.innerHTML = candidateItems.map(it => {
    const isSelected = selectedNames.has(it.name.toLowerCase());
    const icon = it.category.split(' ')[0] || '';
    const safeCat = it.category.replace(/'/g, "\'");
    const safeName = it.name.replace(/'/g, "\'");
    const safeSpec = (it.spec || '').replace(/'/g, "\'");
    return `
      <div class="wb3-subtype-chip ${isSelected ? 'selected' : ''}" 
           title="${escapeHtml(it.category + ': ' + it.spec)}"
           onclick="toggleWb3ComponentSubtype('${safeCat}', '${safeName}', '${safeSpec}')">
        <span>${icon} ${escapeHtml(it.name)}</span>
        <span style="font-size:10px; font-weight:bold; color:${isSelected ? '#10b981' : '#475569'};">${isSelected ? '✓' : '+'}</span>
      </div>
    `;
  }).join('');
}

function toggleWb3ComponentSubtype(category, name, spec) {
  if (!window.wb3ComponentSelectedChars) window.wb3ComponentSelectedChars = [];
  const lower = name.toLowerCase();
  const existingIdx = window.wb3ComponentSelectedChars.findIndex(it => it.name.toLowerCase() === lower);

  if (existingIdx >= 0) {
    window.wb3ComponentSelectedChars.splice(existingIdx, 1);
  } else {
    window.wb3ComponentSelectedChars.push({ category, name, spec });
  }

  renderWb3ComponentSelectedCharsBadges();
  renderWb3ComponentSubtypesGrid();
}

function addWb3CompCustomSubtype() {
  const input = document.getElementById('wb3CompCustomSubtypeInput');
  if (!input || !input.value.trim()) return;

  const raw = input.value.trim();
  const cat = (window.wb3ActiveComponentCategory && window.wb3ActiveComponentCategory !== 'ALL')
    ? window.wb3ActiveComponentCategory
    : '⚙️ Mechanical & Structural';

  raw.split(/[,;\n]/).forEach(token => {
    const trimmed = token.trim();
    if (trimmed) {
      toggleWb3ComponentSubtype(cat, trimmed, 'Custom characteristic specification');
    }
  });

  input.value = '';
}

function clearWb3ComponentCharacteristics() {
  window.wb3ComponentSelectedChars = [];
  renderWb3ComponentSelectedCharsBadges();
  renderWb3ComponentSubtypesGrid();
}


